window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[2]=[{"i":10357,"n":"גאבורין, אהרן מבייקי","k":"אדמור מבייקי","dt":"תרסב","b":"אדמור בבייקי-ליד סלונים. בנו מרדכי בעל \"אילת השחר\"."},{"i":10358,"n":"גאבורין, מרדכי","f":"אהרן מבייקי וסלונים","k":"בעל אילת השחר","bt":"תרלב","bp":"סלונים","b":"תלמיד ישיבת וולוזין, בקי בשפות וחשבון. עסק במסחר. חיבר \"אילת השחר\" וארשא תרנד."},{"i":10359,"n":"גאביזון - משפחה","b":"משפחה בספרד. בזמן פרעות קנא ברחו מסביליה לגרנדה, ואח\"כ כשסרבו להמיר דתם ונהרגו מהם כ-200 נפשות, ניצלו רק שני האחים ר יעקב ור אברהם בני רי יוסף, ומהם המשפחה שנפוצה בארצות הים התיכון. מהם בתלמסאן, מהם באלגיר, צפת, מצרים ועוד."},{"i":10360,"n":"גאביש, אברהם","b":"תלמיד ר נסים חיים שלום מרגונטו."},{"i":10361,"n":"גאביש, יהודה מאזמיר","b":"גזבר \"חברת יתומות\" של קהלת פורטוגל באזמיר-תמח."},{"i":10362,"n":"גאביש, יצחק מאזמיר","dt":"תקיג - א אד\"א","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'."},{"i":10363,"n":"גאביש, שלמה מאזמיר","b":"גביר באזמיר-תפו הקדיש ביכ\"נ וחצר ובתים לקהלה, בנו - הגביר דניאל שיקם אותו לאחר שנשרף."},{"i":10364,"n":"גאביש, שלמה מאזמיר וירושלים","dt":"תקג","dp":"ירושלים?","b":"מחכמי אזמיר, ירושלים, נספד ב\"שארית יעקב\"-תקד. נספד ע\"י ר יעקב אלגזי בירושלים."},{"i":10365,"n":"גאגין, אברהם חיים מירקאדו מי-ם","f":"משה","k":"אג\"ן - מנחה טהורה","r":"הרב אג\"ן","bt":"תקמז","bp":"קושטא","dt":"תרח - ח-כ אייר","dp":"ירושלים","b":"עלה לירושלים עם אביו בנערותו. חתן בזיוו\"ש של ר' אברהם שלום שרעבי. בשנת תרב התמנה לראשון לציון - היה החכם באשי הרשמי הראשון המוכר ע\"י השלטון. מספריו: \"מנחה טהורה\" שלוניקי תקפה, \"חוקי חיים\" ירושלים תרג, \"מנחה טהורה\", \"סביב לאהל\" ירושלים תרמו, דרשות חיים מירושלים וכן מאמרים וחוברות. בניו - ר שלום חי גאגין, ר יצחק. חתנו - ר יעקב פינצי ור דוד יהודה שאקו. מכתב ממנו וחבריו כנגד אספת הריפורמים בברונשויג בתוך \"שומר ציון הנאמן\" - אלטונא תרו-תרטז.","bk":[["חוקי חיים","מפרשי רמב\"ם"],["מנחה טהורה [עמ\"ס מנחות] (אג\"ן)",""],["חוקי חיים – שו\"ת וחידושים",""],["חיים מירושלים - דרוש",""],["מנחה טהורה – מנחות",""],["סביב לאוהל – אוהל מועד",""]]},{"i":10366,"n":"גאגין, אברהם מירושלים","f":"שלום משה חי=שמ\"ח","bt":"תרמה ?","bp":"ירושלים","dt":"תרעח - י כסלו","dp":"ירושלים","b":"הקים בית דפוס בירושלים עם אחיו ר יצחק ועם ר חזקיה שבתי ור נחמן בטיטו."},{"i":10367,"n":"גאגין, אברהם משלוניקי","dt":"שב - אחרי","dp":"שלוניקי","b":"רופא בשלוניקי, אולי הוא שהיה מראשי קהלת ליסבון-שך."},{"i":10368,"n":"גאגין, אברהם משלוניקי","dt":"תקך","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר במגפה-תקך."},{"i":10369,"n":"גאגין, דוד חי מירושלים","b":"מחכמי ירושלים, בשליחות בצפון אפריקה, שהה בפאריס-תרכה."},{"i":10370,"n":"גאגין, דניאל משלוניקי","dt":"שלג - יא תמוז","dp":"שלוניקי","b":"רופא בשלוניקי, מקהלת איבורה. נספד ע\"י ר שלמה הלוי ב\"דברי שלמה\"."},{"i":10371,"n":"גאגין, חיים ממרוקו וספרד","k":"בעל עץ חיים","bt":"רטו - רי","bp":"פאס","dt":"רצה-שה","dp":"פאס-מרוקו","b":"אבי משפחת גאגין מירושלים. ברח מפאס במאורעות-רכה, למד אצל ר' יצחק אבוהב ור יוסף עוזיאל, אב\"ד בפאס, תמך בעמדת מסורת צפון אפריקה, לבין גולי ספרד בנושא בדיקת הטריפות."},{"i":10372,"n":"גאגין, חיים משלוניקי","f":"ידידיה","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ."},{"i":10373,"n":"גאגין, ידידיה משלוניקי","dt":"תלח","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":10374,"n":"גאגין, יצחק מירושלים","f":"אברהם חיים","k":"הו\"ל אהל מועד","bp":"ירושלים","b":"מחכמי ירושלים, הו\"ל \"אהל מועד\"."},{"i":10375,"n":"גאגין, משה מקושטא","dt":"תקסח - ב תשרי","dp":"ירושלים","b":"מחכמי קושטא, חתן ר דוד מאגר בעל חסדי דוד. בנו - ר אברהם חיים-אג\"ן, עלה לירושלים. שליח צבור מפורסם."},{"i":10376,"n":"גאגין, משה מקושטא - א","b":"מחכמי שלוניקי, עבר לקושטא-שנות ה-ת'."},{"i":10377,"n":"גאגין, רפאל חזקיהו","f":"שלום משה חי","k":"בעל מכסה לאהל","bt":"תרי-ך","bp":"ירושלים","dt":"תרפד - כט כסלו","dp":"ירושלים","b":"מחכמי ירושלים, בעל ספריה גדולה ובית דפוס. למד אצל אביו ובישיבות ירושלים, חבר בית דינו של ר יוסף בורלא. כתב הערות לספר \"אהל מועד\" לר שמואל גירונדי בשם \"מכסה לאהל\" ירושלים תרמו."},{"i":10378,"n":"גאגין, שלום משה חי מירושלים","f":"אברהם חיים -אג\"ן","k":"שמ\"ח - בעל ישמח לב","bt":"תקצג","bp":"ירושלים","dt":"תרמג - יב אב","dp":"ירושלים","b":"מחכמי ירושלים, נכד ר רפאל אברהם שלום שרעבי (נכד הרש\"ש). תלמיד ר ידידיה רפאל אבולעפיה (=היר\"א). חתנו של הראשון לציון ר חיים נסים אבולעפיה, בשנת תרכב בשליחות בצפון אפריקה, מראשי \"בית אל\" ובהמשך ראש הישיבה, לאחר פטירת ר ידידיה אבולעפיה. בשנת תרלא בשליחות באיטליה. חיבר גם \"ישמח משה\" ירושלים תרלח, ועוד.","bk":[["ישמח לב [שו\"ת] (הרב שמ\"ח)",""]]},{"i":10379,"n":"גאגין, שם טוב מירושלים","f":"יצחק בן שמ\"ח","k":"בעל כתר שם טוב","bt":"תרמה","bp":"ירושלים","dt":"תשיד","b":"תלמיד ב\"דורש ציון\", ור יעקב אלפייה. רב בקהיר-תרעג ודיין בעדת האשכנזים, סירב להצעת ר חיים נחום לרבנות בגדד, רב קהילת הספרדים במנצסטר ודיין בקהלה, רב העדה הפורטוגזית בלונדון, וראש ישיבת \"אהל משה ויהודית\" ברמסגאט, סגן ועד הרבנים באנגליה וראש ישיבת \"עץ חיים\" בלונדון-תרצג. פרסם מאמרים ב\"החבצלת\", ובעתוני היהודים באנגליה. חיבר גם רשמי מסע בספרד וצרפת בכת\"י, ועוד. מפסקיו בספרי חכמי דורו ובהם \"מפי אהרן\" לר בכור אהרן אלחדף, ועוד.","bk":[["כתר שם טוב",""]]},{"i":10380,"n":"גאדל","b":"רב באדנבורג-שנת ר'"},{"i":10381,"n":"גאדל","b":"רב בסעטשין-תק\"מ"},{"i":10382,"n":"גאדל","b":"רב בפאטשא-תקע\"ב"},{"i":10383,"n":"ג'אהון, אברהם משלוניקי","b":"מדפיס בדפוס חיים אברהם בן שבתי נחמה וסעדי הלוי-תקנח."},{"i":10384,"n":"גאווקיל, משה מירושלים","b":"רב בירושלים. נזכר ב\"גט פשוט\"."},{"i":10385,"n":"גאוורין, דובער","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":10386,"n":"ג'אוי, דוד","dp":"ירושלים","b":"מקובל, דיין בגאבס, סוסא(תונס)-תרמ\"ח, עלה לא\"י"},{"i":10387,"n":"ג'אוי, שמעון מתונס","b":"רב בתונס - סוף שנות ה-תר'. הגיה את \"תנובות שדי\" לר דוד קטורזא, ור ישועה אלמליח."},{"i":10388,"n":"גאון, אברהם מספרד","f":"יהושע בן שאול","b":"אביו של ר שם טוב בעל \"מגדל עוז\" על הרמב\"ם."},{"i":10389,"n":"גאון, דוד מבוסניה וירושלים","f":"יצחק","bt":"תריט","bp":"טראבניק-ליד סרייבו","b":"תלמיד ר משה פינצי בסרייבו. רב בטראבניק, עלה לירושלים-תרפ והיה מחכמי ישיבת \"בית אל\", דרשן בישיבת \"חמד בחורים\" בראשות ר יעקב חי בורלא, מחכמי \"פורת יוסף\". בנו - מ.ד. גאון מחבר הספר."},{"i":10390,"n":"גאון, דניאל ממצרים","b":"מרבני מצרים, דיין עם ר' משה פארדו-תרפ\"ו"},{"i":10391,"n":"גאון, חיים מירושלים","b":"מחכמי ונציה?, עלה לירושלים-שמ. אחיו - ר יצחק מירושלים."},{"i":10392,"n":"גאון, יום טוב משלוניקי","f":"שמואל","dt":"שנח - י סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":10393,"n":"גאון, יוסף","b":"נספד ב\"עולת שבת\"."},{"i":10394,"n":"גאון, יוסף מפורטוגל ושלוניקי","b":"מאנוסי פורטוגל, הגיע לשלוניקי - שנות ה-ש'."},{"i":10395,"n":"גאון, יוסף משלוניקי","dt":"תח","dp":"שלוניקי","b":"מחכמי שלוניקי-סוף שנות ה-ש'. נספה במגפה הגדולה בשלוניקי-תח."},{"i":10396,"n":"גאון, יצחק מונציה וירושלים","dt":"תיב - אחרי","dp":"ירושלים","b":"מחכמי ונציה, עלה לירושלים-שעז והיה לו ישיבה בביתו ללימוד קבלה יחד עם ר יעקב צמח, ובין החכמים נמנו ר יצחק צמח, ר דוד קונפורטי, ר עזריה זאבי. מחכמי ירושלים, ר דוד קונפורטי למד בישיבתו. מוזכר ב\"חרבות ירושלים\" כאחד האסורים בפרעות אבן פארוך. בנו - ר שמואל. אחיו - ר חיים מירושלים."},{"i":10397,"n":"גאון, נחום","f":"נתן נטע","b":"רב בנארינסק-ת\"ס"},{"i":10398,"n":"ג'און, שבתי","b":"רב ראשי במונסור(יוגוסלביה)"},{"i":10399,"n":"גאון, שלמה מקושטא","b":"דיין בקושטא-תקעו, אצל ר יעקב הלוי."},{"i":10400,"n":"גאון, שם טוב גאון מטולידו","f":"אברהם גאון","k":"בעל כתר שם טוב","bt":"מז","bp":"סגוביא-ספרד","dt":"ק (1340)","dp":"צפת","b":"תלמיד הרשב\"א ור יצחק בן טודרוס החסיד. מחכמי סגוביא, ברצלונה, טולידו, סופר סת\"ם ומעטר. עלה לצפת-לפני שנת עה, ועמד בראש הקהלה עם ר שלמה עמנואל ור פרץ, אחר זמן חזר לספרד ושם סיים את ספרו מגדל עז על הרמב\"ם. חיבר גם \"בדי הארון ומגדל חננאל\" - הספר הקבלי הראשון שחובר בצפת."},{"i":10401,"n":"גאון, שמואל","f":"שמואל גאון","b":"מגדולי שאלוניקי-ת\"ר"},{"i":10402,"n":"גאון, שמואל משלוניקי - מהרש\"ו","f":"יצחק","k":"בעל משפטים ישרים","bt":"שס-שע","bp":"שלוניקי","dt":"תכז - ב-כ חשון","dp":"שלוניקי","b":"תלמיד ר יעקב הכהן - תלמידו של ר שבתי יונה משלוניקי. דיין בשלוניקי, רב הכולל על מקום ר יעקב די בוטון הזקן. מתלמידיו - גיסו ר יצחק פאייס (ואייס) אשכנזי-השליח מארץ ישראל, ר דוד יונה, ר יהודה די ליאון, ר מיכאל הכהן בעל \"מורה צדק\", ר מאיר אליאש, וחתנו ר חנניה טאיטצאק. חיבר חיבור על חו\"מ ונדפס תשובות ממנו עם תשובות ר שלמה ן חסון בשם \"משפטים ישרים\". מתורתו ותשובותיו בספרי חכמי דורו ותלמידיו. השתתף ב\"תשובה הגדולה\"-תכו של שבתי צבי."},{"i":10403,"n":"גאונים, רי\"ף, אשכול וראב\"ד. ראה נספח ז","bt":"ד'תתצ-ה","bk":[["חכמי פרובינציא",""]]},{"i":10404,"n":"גאזל, יהודה רפאל חיים הלוי","dt":"תקמד - ה ניסן","dp":"ירושלים","b":"מחכמי ישיבת \"יפאר ענוים\" בירושלים-תקיח, חתם עם רבני ירושלים-תקלז על כתב שליחות רי\"א ן שאנג'י. כתב פירוש על הרמב\"ם ושו\"ת"},{"i":10405,"n":"גאזל, שמואל ממצרים","b":"מדפיס במצרים-תק אצל אברהם יתום."},{"i":10406,"n":"ג'אחון, אברהם משלוניקי","b":"מדפיס בדפוס סעדי הלוי אשכנזי-תקסו."},{"i":10407,"n":"ג'אחון, יוסף משלוניקי","b":"מורה לעברית בבית הספר האיטלקי בשלוניקי-תרכד. בנו - סאלבטאור ג'אחון."},{"i":10408,"n":"ג'אחון, סאלוואדור משלוניקי","b":"מראשי קהלת שלוניקי-תרפא."},{"i":10409,"n":"ג'אין, שבתי יוסף","bt":"תרמג","bp":"פליוונה","b":"תלמיד ר חיים פאניג'ל, ר נסים שמואל הלוי מהמושבה הרטוב, ר אהרן בוטון מירושלים, תלמיד ביהמ\"ד לרבנים בסופיה בניהולו של ר מרדכי גרינוולד, ביהמ\"ד לרבנים בקושטא. פעיל ציוני, נואם, דרשן ומורה בניש-סרביה, עבר לטרבניק-בוסניה, סרייבו, רב הקהלה הספרדית בבואנוס איירס, בוקרשט. חיבר מחזות ובהם \"בר כוכבא\","},{"i":10410,"n":"גאכס, יוסף משאראי","b":"דיין בשאראי אצל ר שם טוב בן יצחק צבי."},{"i":10411,"n":"גאלוב, דב בר ממאהלין","b":"רב במאהלין-פלך צרניגוב-תרע. חתנו - ר יוסף רוזין מסיסלוביץ."},{"i":10412,"n":"גאלוב, יעקב מנימאיון","f":"דובער","bt":"תריב","b":"רב בנימאיון-פלך וילנא-תרמג, ובבירשטאן-עיר הקיט הסמוכה."},{"i":10413,"n":"גאלוב, שניאור פיבוש מדרעוונא","f":"יצחק","bt":"תרטו","b":"ר\"מ בישיבת סלובודקא-תרמב, רב בדרוונה(=דרעוונא)-פלך קובנא-תרמו."},{"i":10414,"n":"גאלייגו, יוסף מוידין","b":"דיין בוידין-שנות ה-ש'."},{"i":10415,"n":"גאלייגו, יוסף משלוניקי","b":"מגדולי חכמי שאלוניקי-ש\"צ"},{"i":10416,"n":"גאלימדו, אליהו מקושטא","b":"רב בקושטא-שנות ה-ת'."},{"i":10417,"n":"גאלימידי, אליה מקושטא - ב","dt":"תקפב - כז תמוז","b":"דיין, מחכמי קושטא"},{"i":10418,"n":"גאלימידי, אליהו מקושטא וליפנטו","k":"בעל מחזור רומני","dt":"שמב - אחרי","b":"מראשי קהלת קושטא חדש-רן-ש לעדת הרומנים (שקדמו ליוצאי ספרד ודברו יוונית), עם ר אליהו לקו, רב בליפאנטו. נזכר בספרי חכמי דורו ובהם הרא\"ם. חתם-שכט (ואולי רב אחר בעל אותו השם) על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא. הו\"ל מחזור רומניה עם הערות - קושטא שמב."},{"i":10419,"n":"גאלימידי, אליעזר מתונס וירושלי","bp":"תונס","dt":"תקסא - לפני","dp":"תונס","b":"מחכמי תונס, עלה לירושלים, בשנים תקסד תקסו שליח ירושלים בצפון אפריקה, ונהרג בכפר בתונס, והספידו ר עזריאל אלחייך בספרו \"חיים וחסד\"."},{"i":10420,"n":"גאלימידי, אלעזר מקושטא","b":"ראש קהלת הרומנים בקושטא-שפב על מקום ר גבריאל בן אליה."},{"i":10421,"n":"גאלימידי, יוסף משלוניקי","b":"שליח ציבור בשלוניקי, והורד מתפקידו-שנות ה-ת'."},{"i":10422,"n":"גאלין, אהרן מקידאן","dt":"תשא - ה אלול","b":"מו\"צ בקידאן"},{"i":10423,"n":"גאלין, דוד ליב מבוצאץ","b":"דיין בבוצאץ-תרף אצל ר שרגא פיבל ויליג, עם ר אריה ליב גלנצר."},{"i":10424,"n":"גאליפוליטי, שבתי מברוסה","k":"בעל ישמח משה","b":"רב בברוסה - שנות ה-תר'. קיבל הסכמה מר נסים יעקב בכ\"ר דוד מקושטא."},{"i":10425,"n":"גאליקו, אברהם","k":"ראה: יגל-גלי","b":"פילוסוף ומקובל במונציליצי(איטליה)"},{"i":10426,"n":"גאלסטר, יצחק משעווער","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":10427,"n":"ג'אמי, אשר","b":"מחכמי תונס"},{"i":10428,"n":"ג'אמי, רפאל מתונס","dt":"תרצז - כג שבט","b":"מגדולי המקובלים בתונס. מתלמידיו ר מצליח מאזוז. נזכר אצל ר כלפון הכהן מג'רבא בעל \"דרש משה\"."},{"i":10429,"n":"ג'אמע ן, שמואל","k":"בעל אגור","b":"מדקדק,פייטן,מגדולי עיר קאבס בתוניס-ד'תת\"ק"},{"i":10430,"n":"גאנאשוילי, יצחק מקילאש-גרוזיה","f":"משה","dp":"ירושלים","b":"רב בקילאש-פלך כותאס-גרוזיה, עלה לירושלים בסוף ימיו. מתלמידיו - ר מיכאל אלאשוילי בעל \"זבח ומנחה\"."},{"i":10431,"n":"גאנגילה, יצחק משלוניקי","dt":"שח","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי הוא שהעיד בפני ריב\"ל."},{"i":10432,"n":"גאנה-שווילי, יצחק","b":"רב בקולאש(גרוזיה)-תרכ\"ה,עלה לא\"י"},{"i":10433,"n":"גאני, אברהם משלוניקי","b":"רופא בשלוניקי-שנות ה-ש'. נזכר בשו\"ת מהריב\"ל."},{"i":10434,"n":"גאני, מאיר מיוון","dt":"תרצא - כ ניסן","dp":"ירושלים","b":"עלה לירושלים-תרן. מחכמי ירושלים, ועסקן בעדה הספרדית."},{"i":10435,"n":"גאנסו, אברהם מברוסה","b":"רב בברוסה-תו."},{"i":10436,"n":"גאנסו, יוסף מפירוייה וברוסה","k":"בעל ספר פזמונים","dt":"ת'","dp":"ירושלים","b":"פייטן, משורר, מרביץ תורה בברוסה(=ברושה), גליפולי, רב בפירוייה, עלה לירושלים. חיבר ספר פזמונים בצורת שירי ר ישראל נגארה. מתלמידיו - ר שלמה אלגזי."},{"i":10437,"n":"גאסטיל, אברהם מירושלים","f":"שמואל","b":"סופר סתם מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":10438,"n":"גאסטער, משה מלונדון","f":"אברהם","bt":"תרטז","bp":"בוקרשט","b":"תלמיד ביהמ\"ד לרבנים בברסלוי. פרופסור באוניברסיטת בוקרשט, גורש והגיע לאנגליה. פרופסור באוכספורד ורב הכולל לקהילות הספרדים בלונדון-תרמז. הו\"ל כת\"י עתיקים עם הערות וביאורים ובהם \"דברי הימים לירחמיאל\", \"ספר יהושע של השומרונים\"."},{"i":10439,"n":"גאפורט, משה משלוניקי","b":"מחכמי שלוניקי-ש'."},{"i":10440,"n":"ג'אפרוט, יצחק מקושטא","b":"מחכמי קושטא, עלה לירושלים, שו\"ב בירושלים-שנד."},{"i":10441,"n":"גאקון, יוסף מתירייא","b":"רב בתירייא - בדור שלאחר הגירוש. בספר \"שורש ישי\" מזכיר פירושו על רות, וב\"מנות הלוי\" מוזכר פירושו על אסתר."},{"i":10442,"n":"גאר, יוסף מאוטיאן","f":"דוד","k":"בעל אומקום פון דער י","bt":"1908","bp":"קובנא","b":"עתונאי וסופר. מורה באוטיאן. תלמיד באוניברסיטת קובנא. ניצל מהשואה ואחריה הגיע לגרמניה-1945, ארה\"ב-1948. חוקר ב\"יווא\" בניו יורק ופרסם ביבליוגרפיות על השואה. חיבר \"אומקום פון דער יידישער קובנא\" מינכן 1948, ועוד."},{"i":10443,"n":"גאר, יצחק מירושלים","dt":"תרע","b":"רב בבירז,רוקשיק,עלה לא\"י-תרס\"ז,ר\"מ בחברון,ירושלים"},{"i":10444,"n":"גאר, צבי מריגא","dt":"תשג","b":"רב בריגא"},{"i":10445,"n":"גארסון, יהודה משלוניקי","b":"דיין בשלוניקי-שיט."},{"i":10446,"n":"גארסון, משה יהודה משלוניקי","dt":"שלד - אחרי","b":"רב בשלוניקי בעיקר בק\"ק פולייא. נספד ע\"י ר סעדיה לונגו."},{"i":10447,"n":"גארסון, משה משלוניקי","b":"דיין בזמן מהר\"י טיטאצק המזכירו בספרו."},{"i":10448,"n":"גארסון, משה משלוניקי","dt":"שפא - טז תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":10449,"n":"גארסיאה, דוד משלוניקי","b":"מחכמי שלוניקי-תק'."},{"i":10450,"n":"גארפיל, מרדכי מביאליסטוק","k":"בעל יגיעות מרדכי","b":"רב בביאליסטוק, ניו יורק. חיבר \"יגיעות מרדכי\" פיעטרקוב תרסז."},{"i":10451,"n":"גאשלאר, נפתלי הירש מהלברשטט","f":"יעקב","k":"בעל מרומי שדה","b":"נכד הש\"ך. חיבר \"מרומי שדה\" - אמשטרדם תקיב, \"מאמר אפשרות הטבעית\"."},{"i":10452,"n":"גאשקו, יצחק ממונשטיר","b":"רב במונשטיר-שמח."},{"i":10453,"n":"גבאי איזידורו, אברהם מספרד","k":"בעל יד אברהם","dt":"תקטו","dp":"לונדון","b":"מאנוסי ספרד, נמלט ללונדון, עבר לאמסטרדם, הרב של סורינם, ברבדוס, חזר ללונדון. חיבר \"יד אברהם\" אמשטרדם תקיח."},{"i":10454,"n":"גבאי, אברהם","dt":"תרח","dp":"ירושלים","b":"נספד בספר אם הבנים ח\"ב פנחס דרוש א"},{"i":10455,"n":"גבאי, אברהם דב מוארקלאן","f":"משה מבוברויסק","k":"בעל חדושי הראדב\"ם","bt":"תר","bp":"בוברויסק","b":"מצאצאי בעל \"תולעת יעקב\". תלמיד ר יחיאל מיכל אפשטין מנוברדוק. חתן ר נחום בן הלל אימיאנסון מרעזיצא. רב בוורקלן(=וארקלאן)-פלך ויטבסק. נסמך מאת: הנצי\"ב, ר אליהו גולדברג מבוברויסק, האחים ר זליג ציוני מדלוצין ור יצחק ציוני מדרעזיצא. בנו - ר אפרים מריגא, חתנו - ר ראובן לוין מדוינסק ואנטאליפט-פלך קובנא. חיבר \"חדושי הראדב\"ם\" על הש\"ס - בכת\"י."},{"i":10456,"n":"גבאי, אברהם מאזמיר","f":"ידידיה מליוורנו","k":"כף נחת","b":"גביר באזמיר. הקים בית דפוס בשלוניקי ולפי רוזניס באזמיר."},{"i":10457,"n":"גבאי, אברהם מאלגיר","bt":"קן - בערך","dt":"רך - בערך","b":"רב באלגיר. נזכר בשו\"ת התשב\"ץ - \"לר חיים אל מלילי על יד ר אברהם גבאי\"."},{"i":10458,"n":"גבאי, אברהם מירושלים","dt":"תרנג","dp":"ירושלים","b":"עלה מאזמיר לירושלים. עליו בספר יפה ללב ח\"ב דרוש ה"},{"i":10459,"n":"גבאי, אברהם מקושטא","dt":"תרה - כו שבט","dp":"קושטא","b":"רב בקושטא, חתם-תקפז עם ר אליהו צבי, ר משה פריסקו ור שמואל חיים."},{"i":10460,"n":"גבאי, אפרים מבאלבירעשא וריגא","f":"אברהם דב","b":"רב ודרשן בבלבירישוק על מקום ר צבי הירש כהנא בעל \"לקוטי רצב\"א ור שמואל מאיר אש על מקומו אחריו, מו\"צ בריגא."},{"i":10461,"n":"גבאי, בן ציון","b":"רב בחברון"},{"i":10462,"n":"גבאי, בנימין מספרד ופאס-מרוקו","f":"יוסף","b":"רב בפאס, חתם על תקנות גולי ספרד בפאס-רנד."},{"i":10463,"n":"גבאי, וולף","f":"ליפמן גבאי","b":"רב בלובלין"},{"i":10464,"n":"גבאי, חיים","k":"בעל פסח לה'","b":"חיבר \"פסח לה'\" על הגדה של פסח"},{"i":10465,"n":"גבאי, חיים דוד מחברון","f":"יהודה","k":"בעל מזכיר לדוד","b":"מחכמי חברון, בשליחות בצפון אפריקה-תפה, חיבר \"מזכיר לדוד\" בכתב יד בדרך שליחותו."},{"i":10466,"n":"גבאי, ידידיה מאזמיר - הנכד","f":"אברהם בן ידידיה","b":"מדפיס באזמיר על מקום אביו."},{"i":10467,"n":"גבאי, ידידיה מליוורנו ואזמיר","f":"יצחק - כף נחת","b":"מדפיס בליוורנו ואזמיר?. בנו - ר אברהם - מדפיס באזמיר."},{"i":10468,"n":"גבאי, יוסף ממצרים","b":"רב במצרים, ביקר בירושלים-רפז והיה אצל הרלב\"ח, ובדמשק - בענין משפט הקדושין של הבחורה אורדואנה ממצרים והמחלוקת בין חכמי מצרים וא\"י בענין."},{"i":10469,"n":"גבאי, יוסף מפאס - א","f":"בנימין?","dt":"שלו - אחרי","b":"מחכמי פאס-שך. מחכמי התקנות."},{"i":10470,"n":"גבאי, יוסף מצפרו-מרוקו - ב","dt":"תקט - לפני","b":"תלמיד ר משה בן חמו. מקובל, מו\"ץ בצפרו-מרוקו עם ר יחיא באנון, ר יוסף עטייה, ר ישועה בן חמו. חתם על פס\"ד-תצא. בנו - ר מאיר."},{"i":10471,"n":"גבאי, יוסף משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":10472,"n":"גבאי, יוסף שפרוט מאמשטרדם","b":"משורר מחכמי אמשטרדם-שנות ה-תק', ממונה על כשרות הגבינות באמשטרדם, ושאל את ר דוד מילדולה בענין זה."},{"i":10473,"n":"גבאי, יחזקאל מקושטא","bp":"בגדד","b":"גביר בבגדד, קושטא-תקסח, סייע רבות ליהודים. יחד עם ישעיה אג'ימאן."},{"i":10474,"n":"גבאי, יחזקאל מקושטא","b":"נכד הגביר ר יחזקאל מבגדד וקושטא. מיסד \"ג'ורנאל ישראלית\"-תרך, מזכיר הקהלה, משכיל. בנו - יצחק."},{"i":10475,"n":"גבאי, יעקב מקושטא","f":"שלמה","b":"חתן ר שלמה פרנקו - המדפיס בקושטא, ומדפיס על מקומו אחריו יחד עם גיסו אברהם פרנקו."},{"i":10476,"n":"גבאי, יצחק מפאס","f":"שלמה","k":"בעל כף נחת","b":"ממשפחה מיוצאי ספרד, מחכמי פאס(=אספי)-מרוקו - שנות ה-ר'-ש', עבר לאיטליה. בנו - ר ידידיה מדפיס בליוורנו, ונכדו ר אברהם - מדפיס באזמיר."},{"i":10477,"n":"גבאי, יצחק מקושטא","k":"בעל פירוש המשנה","b":"רב בקושטא, בזמן ר משה שלטון. חיבר פירוש למשנה ונדפס בקושטא תט."},{"i":10478,"n":"גבאי, יצחק עובדיה מבבל","k":"בעל פחד יצחק","b":"מחכמי בבל בתחילת המאה ה-19. חיבר \"ויעתר יצחק\", \"ויזרע יצחק\" - בכת\"י."},{"i":10479,"n":"גבאי, ליפמן","f":"מהר\"ם מלובלין","b":"מחכמי לובלין-שנת ת'"},{"i":10480,"n":"גבאי, מאיר מונציה","k":"בעל מראות אלקים","b":"מחכמי ויניציאה-תקפ. חיבר \"מראות אלוקים\" ונציה."},{"i":10481,"n":"גבאי, מאיר מספרד","f":"יחזקאל","k":"בעל עבודת הקדש","bt":"רמ","bp":"ספרד","b":"מקובל ממגורשי ספרד, והגיע למצרים ואולי גם לצפת. נחשב לאחד מגדולי המקובלים, והמהר\"ל והשל\"ה מביאים ממנו ומתסמכים עליו בספריהם. חיבר גם \"תולעת יעקב\", \"דרך אמונה\". חתנו - ר שניאור פלקון - סייע בידו בהדפסה."},{"i":10482,"n":"גבאי, מאיר מצפרו-מרוקו","f":"יוסף","b":"מו\"ץ בצפרו-מרוקו - שנות ה-ת'-תק'."},{"i":10483,"n":"גבאי, מאיר מתירייא","b":"רב בתירייא - בדור שלאחר הגירוש."},{"i":10484,"n":"גבאי, משה יעקב","b":"תלמיד ר חיים פלאג'י המזכירו בספרו. חתן ר ישראל פרחי-תקפא. הגיה \"נוה צדק\" לר אברהם הלוי, והוסיף הערות."},{"i":10485,"n":"גבאי, משה מספרד ואלגיר","f":"שם טוב","bt":"קי - בערך","dt":"רג","b":"רב בקלעת איוב ליד גיסו ר יונה חותן הרשב\"ץ, עבר לטירול-ספרד, רב בטרואל-ספרד, מקורב למלך חואן הראשון מאורגון ומינהו לשו\"ב ודיין במיורקה לפני קמז, בזמן פרעות קנא ברח לצפון אפריקה וכיהן כרב בהוניין-ליד תלמסאן - שהיתה עיר נמל חשובה, עם קהלה יהודית מורכבת, עסק בעניני ספרד בחצר מלך מרוקו-קנד. חברו של הריב\"ש שעמו התיעץ הרבה, קרובו של הרשב\"ץ-שהיה נשוי לאחייניתו-בת אחותו, ואף ישב עמו בדין כדיין. מגדולי הדרשנים. נזכר בשו\"ת הריב\"ש. חיבר פירוש על רש\"י לתורה."},{"i":10486,"n":"גבאי, משה מפטרץ","f":"יוסף","b":"רב בפטרץ-שנות ה-ש' לצד ר צדיק פירמון."},{"i":10487,"n":"גבאי, נסים מקושטא","bt":"תפ","b":"תלמיד ר אברהם מיוחס, ממונה על איסור והיתר בקושטא-תקכט (יחד עם ר יהודה בן אברהם מיוחס), מכתב ממנו לחיד\"א-תקמז. חיבר \"פאת נגד\" - שלוניקי ובסופו \"דרך נגד\"."},{"i":10488,"n":"גבאי, נתן מחברון","b":"רב בחברון-תקכג. חתם על כתב שליחות ר רחמים בג'איו ור יצחק זאבי."},{"i":10489,"n":"גבאי, עמנואל מקושטא","b":"מחכמי קושטא-תעז. חיבר שיטה על כמה מסכתות ומביא חדושים ששמע מפיהם של ר מאיר יצחק בעל \"אור יקרות\", ר משה הכהן בעל \"כהונת עולם\" ור יהודה רוזניס בעל \"משנה למלך\". בקובץ \"זכור לאברהם\" תשן, נדפס מעט מחדושיו."},{"i":10490,"n":"גבאי, ראובן שלום ישועה מבגדד","dt":"תרלו - לפני","b":"מתורתו ב\"נופת צופים\" לר שלמה תווינא."},{"i":10491,"n":"גבאי, שבתי מקושטא","f":"אברהם","dt":"תקל - לפני","b":"דיין בקושטא-תפ. נזכר על מצבת אסתר בת אאע\"ה מבית החכם שבתי גבאי - וכנראה היתה שפחה אצלו ונתגיירה."},{"i":10492,"n":"גבאי, שלום","k":"בעל אשירה לה'"},{"i":10493,"n":"גבאי, שלמה מקושטא","b":"נזכר ב\"אזני יהושע\" ו\"בית ישראל\" לר יהושע בנבנישתי."},{"i":10494,"n":"גבאי, שלמה מקושטא","f":"יעקב","b":"מדפיס בקושטא על מקום אביו, אצל דודו אברהם פרנקו."},{"i":10495,"n":"גבאי, שם טוב ממרוקו וירושלים","f":"יעקב","k":"בעל טוב וחסד","bp":"מרוקו או ירושלים","b":"מחכמי סאלי-מרוקו. מתלמידי ר חיים בן עטר, ועלה אתו לירושלים, היה מחכמי ירושלים. חיבר \"טוב וחסד\" בכתב יד. היה מראשי ישיבת גדולת מרדכי שיסד הגביר ר מרדכי טאלון-תאלק יחד עם ר יונה נבון, היה גם בישיבת כנסת ישראל שיסד ר חיים ן עטר בעל אור החיים."},{"i":10496,"n":"גבאי, שמואל (נסים) מקושטא","k":"בעל פאת נגב","dt":"תקנז - לפני","b":"תלמיד ר אברהם מיוחס. רב בקושטא, ממונה איסור והיתר-תקכט, דיין עם ר חיים מטלון ור יעקב ישראל אשכנזי. עלה לירושלים. חיבר גם \"דרך הנגב\"."},{"i":10497,"n":"גבאי, שמואל מפאס","b":"דיין בפאס."},{"i":10498,"n":"גבאיש, מנחם ציון","f":"זלמן גבאש","k":"בעל נחמת ציון","dt":"תלט - יא אייר","dp":"אלטונא","b":"תלמיד ר משה ר מנדלש מקראקא. רב בוידיסלב-תכב, דיין בקראקא, עבר לאשכנז וכיהן כרב ומו\"ץ, ראב\"ד באה\"ו-תלב בזמן ר הלל אשכנזי בעל \"בית הלל\". ר מנחם מנדל בעל \"צמח צדק\" כינהו \"אחד מגדולי הדור\"."},{"i":10499,"n":"ג'באלי, יצחק מטריפולי","f":"עטייה","bt":"תס","dt":"תקל - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":10500,"n":"ג'באלי, ישעיה מטריפולי","bt":"תם","dt":"תקי - בערך","b":"מחכמי טריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":10501,"n":"ג'באלי, עטייה מטריפולי","bt":"תל","dt":"תק - בערך","b":"מחכמי טריפולי (מכונה החכם השלם). חתם בפנקס בי\"ד טריפולי."},{"i":10502,"n":"גבאש, זלמן","b":"רב-שנת ת'"},{"i":10503,"n":"גבורין, שלמה","bt":"תרמג","dt":"תרצ - יב אדר","b":"מרביץ תורה,ר\"מ במאלטש-תרס\"ח,מינסק-תרע\"ד"},{"i":10504,"n":"גביו, אשר","k":"בעל ספר הפרדס","b":"מגדולי הפוסקים הראשונים,מחכמי צרפת במנטשון-ק'"},{"i":10505,"n":"גביזון, אברהם יעקב"},{"i":10506,"n":"גביזון, אברהם מאלגיר - ב","f":"יעקב","dt":"שפ - אחרי","b":"רב ורופא בתלמסאן, אלגיר. חתם על שטר-שמז. נזכר ב\"זרע אנשים\". הזהיר מלימוד קבלה ללא הכנה טובה בתורת הנגלה."},{"i":10507,"n":"גביזון, אברהם מטיטואן-מרוקו","b":"מחכמי טיטואן-מרוקו, חתם על פס\"ד-תקכו עם ר מימון אדהאן."},{"i":10508,"n":"גביזון, אברהם מטריפולי","bt":"תקך","dt":"תקף - בערך","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":10509,"n":"גביזון, אברהם מספרד ואלגיר","f":"יוסף","dt":"רסו","b":"ממגורשי ספרד, התישב בתלמסאן-רנב והיה בין מקבלי פניהם של ר יעקב בירב ור יעקב קינו כשהגיעו אח\"כ לתלמסאן, וחיבר שירים על כך - ב\"עומר השכחה\". חתנו - ר יוסף הכהן מפאס. לפי \"מלכי רבנן\" ישב בטיטואן או טנג'יר שבמרוקו"},{"i":10510,"n":"גביזון, אברהם מספרד ותלמסאן","f":"יעקב","k":"בעל עמר השכחה","bt":"רפ","dt":"שלג-ט","dp":"תלמאסן","b":"תלמיד ר שמואל אנזמול. רב ומקובל, רופא-ש', בלשן ומשורר ממגורשי ספרד מגרנדה, רב בתלמסאן עבר לאלגיר-שלד בהזמנת המלך לשמש כרופאו. חיבר \"עומר השכחה\". בנו ר יעקב בעל \"לקט השכחה\" ו\"דרך השכל\" (ר יעקב בירב שיבח את הספר)."},{"i":10511,"n":"גביזון, אברהם מתונס","b":"מחכמי תונס-תרמ\"א"},{"i":10512,"n":"גביזון, אליהו מתונס","dt":"תקן","b":"מדייני תונס-תקמ\"ו"},{"i":10513,"n":"גביזון, יוסף מטיטואן-מרוקו","b":"מחכמי טיטואן, חתם על שטר-תסב עם ר משה ן עזרא."},{"i":10514,"n":"גביזון, יעקב חי מטריפולי","bt":"תרנה","bp":"בנגזי-לוב","dt":"תשכו","b":"תלמיד ישיבת ר ציון ביתאן בטריפולי. דיין בטריפולי-תרצז על מקום ר יוסף יונה שהתפטר. רב ראשי בלוב-תשח, עלה לארץ-תשיא וכהן כרב בתל אביב. מתלמידיו: ר כמוס עגיב, ר פריג'א זוארץ, ר פריג'א טייאר."},{"i":10515,"n":"גביזון, יעקב מספרד ואלגיר","f":"יוסף","k":"בעל דרך השכל","dt":"רפא - אחרי","b":"הגיע מספרד והתישב בתלמסאן. לפי מלכי רבנן התישב בטיטואן או בטנג'יר. אחיו של ר אברהם ואביו של ר אברהם בעל \"עומר השכחה\". חיבר דרך השכל - להגן על מורה נבוכים - כתה\"י הגיע לפולין ואבד בזמן השואה."},{"i":10516,"n":"גביזון, מאיר ממצרים","bt":"שה או שטו","bp":"צפת","dt":"שפא - אחרי","b":"הגיע מאלגיר, תלמיד ישיבות צפת, ויתכן שהיה תלמיד ר משה קסטילץ. עבר לאלכסנדריה-שמג עם אחיו דוד, רב בקהיר ור\"מ בישיבת ר חיים כפוסי. התפרנס ממסחר - ישב בבית הסוהר בגלל עלילה וניצל. היה נחשב למיקל בפסקיו ולכן נקרא בפי רבני מצרים \"בי דינא שריא\"."},{"i":10517,"n":"גביזון, משה מאלגיר","f":"יעקב","dt":"תנח","dp":"אלגיר","b":"נכד ר אברהם בעל \"עומר השכחה\", הגיה את ספר זקנו, והוסיף חדושים ממנו, ובנו - ר אברהם הו\"ל את הספר. (לדעת ר יוסף בן נאיים ב\"מלכי רבנן\" היה רב בטיטואן או טנג'יר). בכת\"י מספר על גזירת השמד הנקרא \"גזירת הרון\" בפאס."},{"i":10518,"n":"גביזון, נחמיה מטיטואן-מרוקו","k":"בעל נאות השלום","b":"מחכמי טיטואן בשנות ה-תק."},{"i":10519,"n":"גביזון, שלמה ממצרים","dt":"שסח - לפני","b":"רב בקהיר-שס, אסר לגייר קראים בניגוד לדעת הרדב\"ז. נזכר בספר הדרשות של ר חיים חבריא."},{"i":10520,"n":"גבירול ן, שלמה","f":"יהודה מקורדובה","k":"אבן גבירול","bt":"ד'תשפא (1021)","bp":"מלגה","dt":"ד'תתי או תתל","dp":"כבול בא\"י או ספרד","b":"עבר ממאלגה, לסרגוסה (=סרקסטה), קורדובה, מגדולי משוררי ספרד, חוקר, מדקדק, פילוסוף בסרקוסטה, יתכן ועלה לא\"י. חיבר \"אזהרות\", \"תקון מדות הנפש\" ועוד. מקורב לגביר יקותיאל ן חסאן שהוצא להורג-ד'תשצט."},{"i":10521,"n":"גבירול ן, שלמה משלוניקי","dt":"שמו","b":"תלמיד הרשד\"ם. משורר מחכמי שלוניקי."},{"i":10522,"n":"גבירול ן, שלמה משלוניקי - ב","dt":"שעז - יד אלול","dp":"שלוניקי","b":"מהרוגי דולייא."},{"i":10523,"n":"גבירץ, אברהם יוסף מפודגורזע","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":10524,"n":"גבירץ, יונה מוינה","f":"יקותיאל דב מטעט","bp":"טעט","dt":"תשכו - כט סיון","dp":"בני ברק","b":"תלמיד הדעת סופר, ור שמואל דוד הלוי אונגר מנייטרא. חתן ר יצחק זיינבל מקעזמארק. ניצל מהשואה ואחריה אב\"ד באלאטאן-פירעד, פרשבורג-תשו, וינה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":10525,"n":"גבירץ, יקותיאל דב מטעט","f":"משה מקאצקא","bp":"קאצקא","dt":"תשד - כג סיון","dp":"אושוויץ","b":"תלמיד השב\"ס,ור חזקיה פיבל פלויט משוראן, ור נפתלי סופר מפעטשי-נידארף. חתן ר יהושע גולדשטין מסערדאוהל. שו\"ב בנעדיעד-תרנו, טעט-תרס. נספה בשואה."},{"i":10526,"n":"גבירץ, מרדכי","b":"בהיותו בחור פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":10527,"n":"גבירץ, מרדכי מטעט","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא, \"הנשר\" - טירנוי תרצג-תשד."},{"i":10528,"n":"גבירץ, משה מקאצקא","b":"שו\"ב בקאצקא. בנו ר יקותיאל דב שו\"ב בנעדיעש ובטעט."},{"i":10529,"n":"גבירץ, שמואל חנוך הניך מדמביץ","k":"חנוך שטמלר-גבירץ","dt":"תקפז - בערך","b":"רב בדמביץ-תקף, ובנו ר אליהו ישב על מקומו אחריו. (חתם בשם חנוך ולא שמואל)."},{"i":10530,"n":"גבירץ-שטמלר, אליהו מדמביץ","f":"שמואל חנוך מדמביץ","b":"רב בדמביץ על מקום אביו-תקפז בערך."},{"i":10531,"n":"גבירצמן, ישראל מגורליץ","f":"אברהם","b":"חסיד צאנז. חתן ר אידאלע גניווישער. תלמיד האדמור ר שלמה מבובוב."},{"i":10532,"n":"גבירצמן, משה יצחק מפשוורסק","f":"נפתלי אלימלך","k":"אדמור מפשוורסק","bt":"תרמב","bp":"שינאווא-גליציה","dt":"תשלז - י תשרי","dp":"הולנד","b":"מצאצאי ר אלימלך אלבוים נכד הנועם אלימלך. תלמיד דודו ה\"דברי יחזקאל\" משינאווא, ומקורב לאדמור מבלז. רב בפשוורסק. ניצל מהשואה וגלה בסיביר, אחרי השואה הגיע לפריס, אנטורפן-תשטז ונהג שם כאדמור בהוראת האדמור מב לז. ביקר באמריקה-תשיט, וחזר עוד כמה ;פעמים. חתנו ר יעקב לייזר מיאשליסק על מוקמו אחריו. הביא בשם רבו ה\"דברי יחזקאל\" כי נשיא ארה\"ב לינקולן - נהרג כעונש שעבר על הקללה \"ארור כנען\" בזה ששחרר את העבדים, ור משה יצחק אמר אותו הדבר על הנשיא ג'ון קנדי בתשכד. חיבר \"אבות על בנים\" אנטורפן תשנח. בנו ר יוסף חיים חתן ר חיים שטינמץ - נספה בשואה. לתולדותיו ב\"רעה אבן ישראל\"-תשמט."},{"i":10533,"n":"גבירר, משלם מאברטין","f":"אריה","bt":"תקפו","bp":"אברטין","dt":"תרלד","b":"רבה הראשון של גורא-הומורא. אחותו נקראה - שרה הצדקת שטרק."},{"i":10534,"n":"גבל, יעקב יחיאל מגרוסורדין","f":"ישראל גרשון מפאפי","bt":"תרטו","bp":"פאפי","dt":"תרעח - ו אלול","dp":"גרוסורדין","b":"תלמיד השב\"ס, ור עזריאל הילדסהימר. חתן ר פרץ בלוי מבודפשט. מנהל בתי הספר היהודים באונגואר, בגרוסורדין-תרמב ויו\"ר חברת ש\"ס בגרוסורדין."},{"i":10535,"n":"גבל, משה איסר מברזוב","dt":"תרמג","b":"אב\"ד ברזוב. חסיד סדיגורא."},{"i":10536,"n":"גבל, מתתיהו מרעדים","b":"רב ברעדים-תרסד. חתם על ספר \"כוס ישועות\"."},{"i":10537,"n":"גבל, שלום מברזוב","f":"משה איסר","bt":"תרכב","dt":"תרפה","b":"אב\"ד ברזוב(=ברעזיב)-תרמג על מקום אביו. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אחיאסף\" - סטריזוב תרפט."},{"i":10538,"n":"גבל, שמואל חיים מטלומטש","b":"רב בטלומטש. תלמיד מהר\"י שמלקיס שהשיב לו ב\"בית יצחק\"."},{"i":10539,"n":"גבל, שמעון מברזוב","f":"ישראל איסר","k":"בעל כלי גולה","bp":"צשינוב","b":"תלמיד זקנו ר שלום מברזוב. חתן רז\"ו ניסנבוים מדרוהוביטש. אב\"ד ברעזוב על מקום זקנו. ניצל מהשואה, ואחריה הגיע לניו יורק וכיהן שם כרב. חיבר \"כלי גולה וסופרי שמעון\" ירושלים תשן."},{"i":10540,"n":"גבל, שמעון מקוביץ ונ\"י","k":"בעל כלי גולה","b":"רב בקטוביץ, ניו יורק-תשג."},{"i":10541,"n":"ג'בלי, אברהם מטריפולי","f":"עטייה","bt":"תן","dt":"תקך - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":10542,"n":"ג'בלי, שלמה מתימן - א","b":"מחכמי דו אלגבלה-תימן, עבר למצרים, ונזכר בתשובת הרמבם, אודות מעשה שהיה שביזה את הדרשן בבית הכנסת והובא הענין בפני הרמבם."},{"i":10543,"n":"ג'בלי, שלמה מתימן - ב","b":"רב בג'בלה-תימן בתחילת המאה ה-20. עזר לשליח העדה האשכנזית בירושלים - ר חיים צבי פרידמן-תרס ולשליח הגט - ר יוסף מדמוני-חאפדי, כאשר הגיעו למקומו."},{"i":10544,"n":"גברא, יצחק מתימן","f":"יצחק","bt":"תרל","bp":"סוד - תימן","dt":"תשיא","dp":"עג'ור","b":"רב בסוד-תימן, ובנו ר דוד על מקומו בחייו עד תשח (עליית תימן). עלה לארץ עם משפחתו והתישב במעברת עג'ור (ליד בית שמש)."},{"i":10545,"n":"גברונסקי, ברוך בנדט","f":"ישכר בר משואקשנה","k":"בעל אוצר לשון המקרא","bt":"1912","bp":"שוואקשנה","dp":"מוסקבה","b":"אביו היה רבה של שואקשנה. גביר, עסקן ותלמיד חכם. חתן הגביר קלונימוס זאב ויסוצקי ועבר אליו למוסקבה. חיבר \"אוצר לשון המקרא והתלמוד\" ונדפס אחר פטירתו בעריכת \"רב צעיר\". אלמנתו מרים (בתו של ויסוצקי) ייסדה את קבוץ פוניבז לזכר בעלה בעצתו של ר ירוחם יהודה ויסברים ממוסקבה."},{"i":10546,"n":"גברונסקי, ישכר בער (רבינוביץ)","f":"אליעזר מזגער","bt":"תקעה","bp":"זאגר-ליטא","dt":"תרך - כח שבט","b":"רב בבוקין, פופיליאן, שוואקשנה(=שוועקאשנא)-פלך קובנא, שוקיאן. בניו: ר אבא משה רבינוביץ מפופיליאן, ר שמואל יעקב רבינוביץ על מקומו אחריו, ר ברוך בנדט ממוסקבה בעל אוצר לשון המקרא, ר יהודה ליב מדוינסק, ר ישכר בר מארה\"ב (נולד אחר פטירת אביו ונקרא ע\"ש)."},{"i":10547,"n":"גברט (גלברד),אברהם חיים מגלינא","b":"דיין בגלינה-תרמד."},{"i":10548,"n":"גבריאל אברהם","dt":"תקמג - ח אדר","b":"רב בפינטשוב"},{"i":10549,"n":"גבריאל חייא מצפת","k":"בעל סדר זמנים","b":"מחכמי צפת, בשליחות באיטליה בשנת תלד יחד עם ר יוסף ריקיטי. חיבר \"סדר זמנים\" לוח לשלושים שנה (תלה-תסה) ונציה תלה, בשנת תעח הסכים על ספר \"הון עשיר\" לר עמנואל חי ריקי, חתם בין השנים תמו - תעג על אגרות שליחות."},{"i":10550,"n":"גבריאל טשאק מטשאקווא-צפת","b":"תלמיד ר אלימלך מליזנסק, ואחיו ר משולם זוסיא מאניפולי, ור פנחס מקוריץ. עלה לארץ והתשיב בצפת. מנכדיו ר משה חר\"ג (=חתן רבי גרשון) בצפת."},{"i":10551,"n":"גבריאל יעקב מאונסדורף","b":"מגיד באונסדורף-תקלג. רב בטאקאי. נספד ב\"מלאה קטורת\" לר זוסמן סופר מפאקש."},{"i":10552,"n":"גבריאל יעקב סאנדיץ מטוקאי","dt":"תרכח - כח אב","b":"רב באונסדורף, טוקאי(=טאקאי) - כ-50 שנה."},{"i":10553,"n":"גבריאל יצחק","b":"רב-שנת תק\"ע"},{"i":10554,"n":"גבריאל מאוסטרהא וזיטומיר","f":"דוד","b":"דיין באוסטרהא אצל ר חיים רפפורט בעל \"מים חיים\", דיין ומו\"צ בזיטומיר. הסכים על \"סדר עבודה ומורה דרך\" יחד עם ר חיים רפפרוט - סלאויטא תקצו."},{"i":10555,"n":"גבריאל מברסלוי ולברטוב","b":"רב בלברטוב(=לוורטוב), ראב\"ד בברסלוי-תקמ. קרובו וחברו של בעל הנודע ביהודה המזכירו בספרו.(לפי אוצר הרבנים בנו - ר יצחק איזיק לנדא מלברטוב)."},{"i":10556,"n":"גבריאל מדמשק","b":"מחכמי דמשק,רב בקהילת אבוקיר(מצרים),רב בברוסה(=ברושה)-ש\"כ"},{"i":10557,"n":"גבריאל ממגלניצא","dt":"תריח - ט אב","b":"דיין בוורשה"},{"i":10558,"n":"גבריאל ממצרים ותורכיה","f":"אליהו","b":"תלמיד הרדב\"ז במצרים, רב באבוקיר-מצרים, ברוסה-שך על מקום ר יום טוב ן ארוליא, ראש העדה הרומנית בקושטא-שן על מקום ר יהושע קנדיוטי ור אליעזר גאלמידי על מקומו אחריו. חתם-שכט על מכתב הרבנים לטובת דון יוסף נשיא. מתורתו בספרי רבו-הרדב\"ז, ור יוסף קארו."},{"i":10559,"n":"גבריאל מסוכוסטוב","f":"נפתלי הירץ","bp":"סטנוב","b":"רב בסוכוסטוב (ליד קופישיניץ). חבוריו אבדו בשריפה בסטנוב. נכדו רא\"ל בלחובר מזסלב הדפיס מתורתו בספרו \"שם אריה\" - תרלד."},{"i":10560,"n":"גבריאל מצפת","f":"אליהו","b":"מגדולי חכמי צפת-ש\"כ"},{"i":10561,"n":"גבריאל מקראקא","dt":"תקסה - ה חשון","b":"דיין בקרקא"},{"i":10562,"n":"גבריאל נושא חן","b":"חסיד חב\"ד. לתולדותיו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":10563,"n":"גבריאל עמנואל משלוניקי","dt":"תקלח","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":10564,"n":"גבריאל שבתי יהושע","b":"מגדולי חכמי שלוניקי"},{"i":10565,"n":"גבריאל, אברהם","b":"מחכמי צפת, נסמך ע\"י ר' יעקב בירב-שנ\"ט"},{"i":10566,"n":"גבריאל, יעקב מבגדד","f":"אלישע","k":"בעל חנוכת הבית","dt":"תרלו - ב תמוז","b":"רב בבגדאד, חיבר \"חנוכת הבית\""},{"i":10567,"n":"גבריאלוביץ, ישראל מהמבורג","f":"גבריאל יצחק","bt":"תקע","dt":"תרמז - ה טבת","dp":"אהרנסבורג-ליד המבורג","b":"תלמיד ר עקיבא איגר, ר אברהם אבוש ורעשנער מצערקוב. מו\"צ בוויטקווא, מחכמי הקלויז של ר יחיאל ואליך בהמבורג-תרלב, ודיין אצל ר אשר שטרן."},{"i":10568,"n":"גברילוביץ, אריה ליב מירושלים","f":"אליעזר דן","bp":"ירושלים","dt":"תרעד - יד שבט","dp":"ירושלים"},{"i":10569,"n":"גברילוביץ, גבריאל מירושלים","f":"אריה ליב","bp":"ירושלים","b":"תלמיד ישיבת עץ חיים בירושלים."},{"i":10570,"n":"גברין, אלחנן אליעזר","bt":"תרכב","b":"רב בקרדיף-תרנ\"ח,דובלין"},{"i":10571,"n":"גברין, שרגא פיבל מחווידאן","dt":"תשג","b":"רבה האחרון של כוויידן(=חווידאן)-תרצה. נספה בשואה. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":10572,"n":"גג’ אליהו בן יוסף","bt":"1830","dt":"ה'תרסד 1904","bk":[["חסד ואמת",""],["סדר הגדה של פסח עם פירוש הרב אליהו גג’",""]]},{"i":10573,"n":"גג', חיים דוד","k":"בעל חיים לישראל","b":"מחכמי תונס,דיין,מרביץ תורה בנגלה ונסתר,חיבר \"חיים לישראל\""},{"i":10574,"n":"ג'ג, יהודה","k":"בעל נחל יהודה","dt":"תרנ - כ סיון","b":"מקובל,מחכמי תונס,חיבר \"נחל יהודה\""},{"i":10575,"n":"ג'ג, מרדכי מתונס","b":"תלמיד ר יעקב פיתוסי בעל \"ירך יעקבק\". דיין בתונס-תקצב, ונזכר ב\"מעשה ב\"ד\"."},{"i":10576,"n":"גג', שלמה","b":"נזכר-תרל ב\"זרעו של אברהם\" לר אברהם חג'אג', על פסק דין ששלחו לר נתן בורג'ל הראב\"ד בתונס."},{"i":10577,"n":"גד","f":"יואל","b":"רב-שנת תק\"י"},{"i":10578,"n":"גד - חתן הט\"ז","k":"חתן הט\"ז","b":"רב-שנת תמ. בנו ר יואל משברשין בעל \"חדושי הלכות\"."},{"i":10579,"n":"גד אשטרוק","f":"יעקב","k":"בעל דיני ממונות על","b":"חיבר - דיני ממונות על מלאכת המספר - בכת\"י (אצל המשכיל יוא\"ל מפדובה)."},{"i":10580,"n":"גד בן יעקב אבינו, קבור בעבר הירדן","dt":"י חשון"},{"i":10581,"n":"גד מטרניגרד","b":"רב בטרניגרד"},{"i":10582,"n":"גד משה","f":"יואל משברשין","b":"רב-שנת תס. בנו ר יואל מפרג."},{"i":10583,"n":"גדאמסי, משה מלוב","b":"רב בגאדאמס-לוב (במדבר פזאן) בתקופת הגאונים."},{"i":10584,"n":"גדול, שלמה מחרסון וירושלים","b":"רב בוורניאן, חרסון, עלה לירושלים וכיהן כמו\"צ בירושלים."},{"i":10585,"n":"גדולי המחברים - רמב\"ם","bt":"גדולי המפרשים - ראב\"ד","dt":"גדולי הדורות - השלמה","bk":[["מאירי – כללים ללשונותיו",""]]},{"i":10586,"n":"גדולת מרדכי - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה בידי הגביר ר מרדכי תאלוק."},{"i":10587,"n":"גדיליה, אברהם מחברון - הנכד","f":"יוסף","bp":"חברון?","dt":"תקלז - לפני","dp":"חברון","b":"רב בחברון. נכדו של אברהם בן שמואל גדיליא, בשליחות בשנים תפז תצא, ולאחר מכן בשנת תקד לאירופה, באמשטרדם היה בקשר עם ר דוד מילדולה, (מופיע בספרו של מילדולה (דברי דוד) חתום על תקנת הקהל בקרפנטרץ.. הסכים על ספר \"שער יוסף\" לחיד\"א, וחתם על איגרת השליחות של החיד\"א בשנת תקיג. אולי הוא שהיה ראש ישיבה בונציה-תקח. חתם-תקכג על כתב שליחות ר אשר קוריאט."},{"i":10588,"n":"גדיליה, אברהם מירושלים - הזקן","f":"שמואל","k":"בעל ברית אברהם","bt":"שן","bp":"ירושלים?","dt":"תלב - אייר","b":"רב בחברון, ירושלים תי. התגורר גם בליוורנו-תח. תשובה אליו ב\"דבר שמואל\". חיבר פירוש לילקוט שמעוני בשם \"ברית אברהם\" עם הקדמה מהרמ\"ז - ונציה. בשליחות באיטליה-תי ופגש שם את ר משה זכות שחיבר שיר לכבודו. בניו - ר יעקב, ר יוסף - שניהם נהרגו-תמה בידי ערבים, נכדו - ר אברהם גדיליא מחברון."},{"i":10589,"n":"גדיליה, אברהם מצפת וטבריה","b":"מחכמי צפת וטבריה בזמן המבי\"ט, אחיו - ר יוסף משה - נזכרו בספרו של המבי\"ט על משפט ירושה שהיה להם."},{"i":10590,"n":"גדיליה, אליהו מחברון","f":"נחמיה","b":"מחכמי חברון, בשנת תקכג חתם על אגרת שליחות של ר רחמים באג'יו ור יצחק זאבי, היה שליח חברון באירופה, בתקלח פגש את החידא בטורינו, בתקמה היה בטיקטין בליטא ונרשם שם בפנקס הקהל"},{"i":10591,"n":"גדיליה, חיים מלונדון","f":"יהודה","bt":"תקעה","dt":"תרסה - כב תשרי","dp":"לונדון","b":"בן אחותו של סיר משה מונטיפיורי. פעל למען יהודי מרוקו-תרכד ו-תרמח."},{"i":10592,"n":"גדיליה, חיים שמעון מאזמיר וחבר","b":"מחכמי אזמיר, חברון, בשנת תקנח חתם על אגרת שליחות ר אברהם רוביו ור מיכאל הכהן. בשנת תקסג בשליחות בטריפולי ובשנת תקעה בשליחות במרוקו."},{"i":10593,"n":"גדיליה, יהודה מליסבון וקושטא","b":"מדפיס בליסבון אצל ר אליעזר טולדנו, יסד את הדפוס הראשון בשלוניקי. לדעת טולדנו-נר המערב היה גם בפאס והדפיס שם \"אבודרהם\"."},{"i":10594,"n":"גדיליה, יהודה משלוניקי וקושטא","f":"משה","k":"בעל מסורת תלמוד ירוש","b":"מחכמי שלוניקי-שפ, חיבר הגהות למדרש רבה ו\"מסורת תלמוד ירושלמי\" - מפתח לתלמוד ירושלמי. יסד את הדפוס הראשון בשלוניקי-שעה אצל ר אליעזר טולדנו."},{"i":10595,"n":"גדיליה, יוסף מחברון","f":"אברהם","dt":"תסה","dp":"ליד עזה","b":"מחכמי חברון, מתשובותיו בספר \"כרם שלמה\" לר שלמה אמריליו משלוניקי. בשנת תסה בשליחות ובחזרתו נרצח יחד עם אחיו ר יעקב בין עזה לחברון."},{"i":10596,"n":"גדיליה, יוסף משה מצפת וטבריה","b":"מחכמי צפת וטבריה בזמן המבי\"ט, אחיו - ר אברהם - נזכרו בספרו של המבי\"ט על משפט ירושה שהיה להם."},{"i":10597,"n":"גדיליה, יצחק מחברון","b":"מחכמי חברון, בשנת תקכה בשליחות בתורכיה."},{"i":10598,"n":"גדיליה, מאיר מחברון","b":"מחכמי חברון, רבו של ר חיים יצחק קאריגל, בשנת תקיח בשליחות בצפון אפריקה, בתונס פגש את ר מרדכי ברוך קרבליו שמביא מדבריו בספרו \"תועפות ראם\". בשנת תקי חתם על קבלת כספים מר יהודה אסיאו."},{"i":10599,"n":"גדיליה, משה מטבריה","f":"יוסף","b":"מחכמי טבריה, נזכר בשות המביט. לדעת יערי זהה עם ר משה שחתם על כתב שליחות ר אברהם בן יצחק אשכנזי שנשלח מטעם טבריה לתימן בשנת שלט."},{"i":10600,"n":"גדיליה, משה משלוניקי","f":"יהודה","k":"בעל מסורת התלמוד הבב","b":"מחכמי שלוניקי, קושטא."},{"i":10601,"n":"גדיליה, נחמיה רחמים מחברון","f":"אברהם מחברון","b":"מחכמי חברון, וראש הרבנים-תקמג על מקום ר מרדכי רוביו, בשנת תקמא חתם על כתב שליחות ר שמואל הכהן. ישנה חתימה משנת תקצה ותקצט על כתב שליחות ותקנה בחברון ואולי הוא אותו אדם שהאריך ימים."},{"i":10602,"n":"גדיליה, שמואל","b":"מגדולי חכמי ירושלים-ש\"פ"},{"i":10603,"n":"גדליה","f":"משה","k":"בעל מעשי ה'","b":"חיבר \"מעשי ה'\" לקורות בני ישראל בשלשה חלקים - המבורג תקסח."},{"i":10604,"n":"גדליה","f":"אליעזר","k":"בעל עמודי גברא","b":"חיבר \"עמודי גברא\", ובסופו דיני מעשר עני לבנו - ברין תקעז."},{"i":10605,"n":"גדליה אביש מדילוטין","b":"פרנס בדילוטין"},{"i":10606,"n":"גדליה הכהן מגאנידז","f":"פנחס ליב הכהן","b":"רב בגאנידז(=נאנידז)."},{"i":10607,"n":"גדליה הלוי","k":"בעל דרוש המלאכים","dt":"שע - אחרי","b":"גיסו של ר חיים ויטל, תלמיד האר\"י מן הכת הראשונה, בספר \"שבחי האריזל\" סיפורים רבים מפיו. ר גדליה סידר את \"דרוש המלאכים\" כפי שקיבל מהארי עם הגהות ר יעקב צמח, בשנת שסא חתם בשות מהרי\"ט."},{"i":10608,"n":"גדליה הלוי מקנישא","b":"רב בפאסטא,קנישא-תק\"פ"},{"i":10609,"n":"גדליה זוסיא מפלוישט","f":"אליעזר","b":"דיין בפלוישט, חתם-תרח עם ר דוד מודיל."},{"i":10610,"n":"גדליה יהודה מסמיאטיץ וירושלים","k":"בעל שאלו שלום י-ם","b":"עלה מעיר סמיאטיץ-פלך גרודנא בשיירת ר יהודה החסיד עם אחיו ר משה, הגיע לירושלים-תסא, רבני ירושלים חשדו בהם כשבתאים ושלחו שליח מיוחד לועד ארבע ארצות וביקשום לעזור ולגרש את העולים, אז נשלח ר גדליה לאירופה לנסות ולהסיר מעליהם את חשד השבתאות. בדרכו חיבר ספר \"שאלו שלום ירושלים\" ברלין תעו - אודות עליית ר יהודה החסיד ותיאור המקומות הקדושים בארץ."},{"i":10611,"n":"גדליה יונה מירושלים","dp":"ירושלים","b":"חתן ר דוד צבי מקרמניץ. עלה לירושלים לפני תרל."},{"i":10612,"n":"גדליה מאויבן","b":"דומ\"צ באויבן-ש\"י"},{"i":10613,"n":"גדליה מאוסטרופולי וליניץ","f":"יצחק מפולנאה","k":"בעל תשואות חן","bt":"תצח","dt":"תקמה - כט כסלו","b":"פגש את הבעש\"ט בילדותו. תלמיד ר אריה ליב מוכיח מפולנאה. בזיוו\"ש חתן ר משה טשארטאריער-אחיו של ר צבי מקמינקא. רב באוסטרופול, מירופול(=מריאפולי), ליניץ. אבי שושלת סוקוליבקה. גיסו של ר משה שפירא מסלאויטא (נשואים לאחיות). (אצל אלפסי תאריך פטירתו - תקסד)."},{"i":10614,"n":"גדליה מבדינגהיים","k":"ר' גדליה מרוטנברג","b":"תלמיד בעל \"שאגת אריה\". רב בבדינגהיים-תקצט."},{"i":10615,"n":"גדליה מדנמרק. ברון","bp":"קופנהגן","b":"נכד ר גדליה אב\"ד קופנהגן. כלכלן מפורסם ונציג בית רוטשילד בדנמרק. בעל תואר בארון מאת מלך דנמרק."},{"i":10616,"n":"גדליה מזולקווא","f":"בנימין זאב וולף","dt":"תקלז - כג חשון","dp":"זולקוא","b":"נכד ר יעקב מדובנא? (ראה ר בנימין זאב וולף מזולקוא בן יעקב מדובנא), חתן ר פנחס הורביץ בעל ההפלאה (ולדעת אחרים מחותן - ובנו ר אברהם חיים הוא שהיה החתן). רב בזולקווא. חתם-תקיא על החרום בזולקוא יחד עם ר נפתלי הרץ הורביץ מזולקוא, הסכים על האלשיך - זולקוא תקכה עם ר אברהם מרדכי מזולקוא, ועוד. תלמיד המגיד ממזריטש, ר יונתן איבשיץ פנה אליו לעזרה בזמן המחלוקת כנגדו. בנו ר אברהם חיים מזלוטשוב."},{"i":10617,"n":"גדליה מזליחוב","dt":"תקעז","b":"רב בזליחוב-תקס. תלמיד חבר למגיד מקוזניץ. נחשב מאוד בדורו."},{"i":10618,"n":"גדליה מלומבלא","f":"מאיר - מהר\"ם מלובלין","b":"רב בלומבלא-שעז. הו\"ל תשובות אביו עם הקדמה ממנו."},{"i":10619,"n":"גדליה ממאהלוב-ליטא","f":"צבי","dt":"תקעט - ח אב","dp":"אוסטרהא","b":"דרשן מליטא שהגיע לאוסטרהא ונפטר שם."},{"i":10620,"n":"גדליה ממיץ","b":"רב במיץ-תק\"ע"},{"i":10621,"n":"גדליה מפרשבורג","f":"צבי","dt":"תקיב-ג -כג תמוז","dp":"פרשבורג","b":"גביר אמיד ודיין בפרשבורג."},{"i":10622,"n":"גדליה מקראקא","f":"אשר מקראקא-עמק הברכה","k":"אבי המהר\"ם מלובלין","b":"רב בקראקא-שכ."},{"i":10623,"n":"גדליה משה הלוי מיאנוב","f":"צבי הירש","k":"בעל חמד משה","b":"רב ביאנוב-תקך, לאשיץ."},{"i":10624,"n":"גדליה משוטלסדורף","b":"רב בשוטלסדורף-תק\"פ"},{"i":10625,"n":"גדליה סגל מוילנא","b":"גביר מחכמי וילנא. חתנו - ר נחמן כץ. נזכרו-תקיא בכתב המינוי של ר שמואל בן אביגדור כרבה של וילנא שלא יערערו על המינוי של ר שמואל. (כמו לר מאיר גינצבורג מויזון)"},{"i":10626,"n":"גדליה סופר מטיסמניץ","b":"תשובה אליו \"ארץ צבי\"."},{"i":10627,"n":"גדליה, יהודה מלונדריש(=לונדון)","b":"יסד ישיבה בירושלים \"בית גדליה\"."},{"i":10628,"n":"גדליה, יעקב ממראקש","b":"מו\"ץ במראקש, היה גם בראבאט או בסאלי, מו\"ץ באגאדיר-מרוקו, וחתם שם על פס\"ד-תצה יחד עם ר משה בן לחזאן. חברו של ר שלם בוזגלו בעל \"מקדש מלך\" והזכירו בספרו."},{"i":10629,"n":"גדלס, מנחם מנדל מפרשבורג","dt":"תקצט - כט תשרי","dp":"פרשבורג","b":"בן למשפחת נדלס מפרג. מחכמי פרשבורג."},{"i":10630,"n":"ג'ו ן, מרדכי מטנג'יר - הנכד","dt":"תרעז - כו טבת","b":"רב בטנג'יר-מרוקו במשך 61 שנה. חיבר דרשות בכת\"י. נזכר ב\"ישא איש\" לר יעקב שאול אלישר."},{"i":10631,"n":"ג'ו ן, מרדכי ממרוקו - הזקן","bp":"טיטואן","b":"רב בטאנכיר(=טנג'יר). זקנו של ר מרדכי השני."},{"i":10632,"n":"ג'ו ן, משה מטנג'יר","b":"תלמיד ר אברהם טולידנו. רב בטאנכיר(=טנג'יר). נזכר ב\"ויאמר יצחק\", חתם עם ר יצחק ן ואליד ור יום טוב הלוי-תקצה."},{"i":10633,"n":"ג'ו ן, ראובן מטנג'יר","b":"רב בטנכיר(=טנג'יר). נזכר בשו\"ת \"ויאמר יצחק\"."},{"i":10634,"n":"גואיטה סויסי, רחמים מטריפולי","bt":"תקי","dt":"תקף - בערך","b":"סופר קהלת טריפולי, חתם בפנקס בי\"ד טריפולי."},{"i":10635,"n":"גואיטה, אליהו מלוב","f":"שלמה","bt":"תקל","dt":"תר - בערך","b":"רב ומשורר בג'ריאן-לוב. חיבר קובץ פיוטים בכת\"י - והיה בידי נחום סלוש."},{"i":10636,"n":"גואיטה, חואתו מטריפולי","dt":"תרעח","dp":"טריפולי","b":"תלמיד ר ציון ביתאן. רב בטריפולי-לוב. נזכר ב\"אשכבתא דרבנן\" לקהלת טריפולי."},{"i":10637,"n":"גואיטה, יצחק מטריפולי-איטליה","f":"פריג'א","k":"בעל שדה יצחק","bt":"תקלז","bp":"אג'בל-לוב וי\"א איטליה","dt":"תריז - שבט","dp":"טבריה","b":"משפחה ממגורשי ספרד-מהעיר גואטו, תלמיד ר משה לחמייש, ור יצחק ואתורי. עבר מלוב לליוורנו-תקנח, התעשר ועבר לטריאסט. היה גביר ואיש חסד בעיקר לשלוחי ארץ ישראל וכן סייע בהדפסת ספרי קדמונים וחכמי דורו. סייע בשיקום צפת אחרי הרעש-תקצז והקים שם בית מדרש וכן בטבריה החזיק בית מדרש בשם \"פחד יצחק\" ושיקם בית מדרש עתיק הנקרא \"בי כנישתא רבא דטבריה\" - \"בית יעקב\" . עלה לארץ בזקנותו והתישב בצפת. חיבר \"שדה יצחק\" ליוורנו תרו, בשנת תריג הוציא לאור ר אהרן לוצטו בטריאסט ספר \"ויסתבל החגב\" - השגות על הספר \"שדה יצחק\" לר יצחק גואטה."},{"i":10638,"n":"גואיטה, נסים מטריפולי","f":"יצחק","bt":"תקך","dt":"תקץ - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":10639,"n":"גואיטה, נתן מלוב","bt":"תרי","dt":"תרף - בערך","b":"רב ומשורר ביפרן-לוב."},{"i":10640,"n":"גואיטה, פרג'ללה מלוב","bt":"תרס","dt":"תשל - בערך","dp":"ישראל","b":"רב ביפרן-לוב, עלה לארץ וכיהן כרב במושב עוזה."},{"i":10641,"n":"גואיטה, ציון מלוב","k":"ר ציון מחלולה","bt":"תר","dt":"תרע - בערך","b":"רב ומלמד תשב\"ר בלוב. חיבר פיוטים."},{"i":10642,"n":"גואיטה, רפאל מתונס","k":"בעל ערוגות הבשם","b":"רב בסוסא-תונס. מתלמידיו ר יצחק נאג'ר. תרגם תהלים לערבית בשם \"ערוגות הבושם\"."},{"i":10643,"n":"גואיטה, שלום מטריפולי","dt":"תרסח","dp":"טריפולי","b":"רב ודיין בטריפולי. מתורתו ב\"באר לחי\" לר חי מימון - ליוורנו תרמח, וב\"מעטה תהלה\" לר יעקב רקח - ליוורנו תרי, הניח חדושי תורה בכת\"י. נזכר אצל יהודי לוב בתפילת יוה\"כ, עם שמות הרבנים הקדומים. לתולדותיו בכתב העת \"אגרת\" תל אביב תשיח."},{"i":10644,"n":"גואלטיל, חייא משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. מהרוגי דולייא."},{"i":10645,"n":"גואלטיל, ישראל משלוניקי","dt":"שה - טו תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":10646,"n":"גואקיל, אברהם","b":"מתלמידי האר\"י"},{"i":10647,"n":"גואקיל, אליהו מקושטא","b":"מחכמי קושטא-תפ בערך."},{"i":10648,"n":"גואקיל, ידידיה משה מירושלים","b":"מחכמי ירושלים, הסכים-תקיג על \"אדמת קדש\". (ראה גם: עובדיה משה גואקיל)."},{"i":10649,"n":"גואקיל, יעקב מטבריה","b":"מחכמי טבריה, חתם על מכתב הקהלה בשנת תקמה ותקסה."},{"i":10650,"n":"גואקיל, יצחק מקושטא","k":"בעל ספר הצרוף","b":"מחכמי קושטא. חיבר ספר הצירוף - קושטא שכח."},{"i":10651,"n":"גואקיל, משה מירושלים - א","b":"מחכמי ירושלים-שנות ה-ת'. חתם עם מהר\"ם ן חביב ב\"זרע אנשים\", ונזכר בספרו \"גט פשוט\"."},{"i":10652,"n":"גואקיל, עובדיה משה מירושלים","f":"שמואל","k":"בעל אורים ותומים","bt":"תנח","dt":"תקל","dp":"ירושלים","b":"מחכמי ירושלים מבית המדרש \"בית יעקב\", בשנת תצז חתם על תקנת העזבונות. חיבר \"אורים ותומים\" שלוניקי תקטז."},{"i":10653,"n":"גואקיל, שמואל מחברון - א","f":"משה","b":"מחכמי חברון, בשנת תסב בשליחות באלגיר ונשדד בדרכו ואיבד כתב שליחותו ואז העידו חכמי אלגיר שראו את כתב השליחות לפני שנשדד. מתורתו ב\"מראה עינים\" לר אליעזר בהלול ממכנאס. יתכן והוא חתם בטיטואן על אישור פסק דין- בשנת ותה\"י לי ליצירה."},{"i":10654,"n":"גוארטיל, אליהו משלוניקי","dt":"שצד-ה-ז - פסח","dp":"שלוניקי","b":"תלמיד ר חיים שבתי, ר\"מ בשלוניקי, מתלמידיו: ר משה ן יעיש, ר ברכיה רוסו, ר יוסף הלוי, ר דוד יצחקי."},{"i":10655,"n":"גואשוש, מסעוד מצליח מדרעא","b":"מקובל וחוזה עתידות בדרעא-מרוקו-שנות ה-ש'."},{"i":10656,"n":"גוגל, שלמה דוד ממאקווא","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":10657,"n":"גוגנהיים, אברהם מאה\"ו","f":"יוסף","dt":"תקכו - כח אב","dp":"אה\"ו","b":"מחכמי אה\"ו. מצאצאי ר שמואל אופנהיים מוינה. גיסו של השתדלן ר יהודה ליב זינצהיים. עמד לצדו של ר יונתן איבשיץ בזמן המחלוקת, והיה מחותמי האגרת לרבני פולין בזכותו של ר יונתן. חתנו - משה מנדלסון."},{"i":10658,"n":"גוגנהיים, יעקב מבטהינגן","b":"חתם-תעב על בעלות על הספר 'שפע טל'."},{"i":10659,"n":"גוגנהיימר, הרב מקאלין","b":"רב בקאלין. הספיד את הכת\"ס בהלוייה."},{"i":10660,"n":"גוגנהיימר, יוסף מאלזס","dt":"תקף - אחרי","b":"רב באלזס, דיין במיץ-תקסח. הסכים על \"קרית חנה\" - תקמה, \"מאורי אור\" - תקן."},{"i":10661,"n":"גוגנהיימר, יוסף מבוהמיה","bt":"תקצג","dt":"תרנו","b":"חתן הרש\"ר הירש מפפד\"מ. רב בקהלות בהונגריה, גרמניה, קאלין-בוהמיה."},{"i":10662,"n":"גודמן, יצחק מארה\"ב (או אנגליה)"},{"i":10663,"n":"גודמן, ישראל","bt":"תרלד","dt":"תרעב - כב טבת","b":"רב בגורג'י-סיטי,בורלינגטון"},{"i":10664,"n":"גודמן, עזריאל זליג מארה\"ב","f":"אהרן מאיר","bt":"תרע","bp":"טימקוביץ-פלך מינסק","b":"תלמיד ישיבות רבי יצחק אלחנן אצל ר שלמה פוליצוק, חברון, קמניץ, מיר. נסמך מאת: ר ברוך בר ליבוביץ, ר אליעזר יהודה פינקל, ר יעקב שפירא מוולוזין, ר יהודה ליב פיין מסלונים, ר דוד רווינסקי מקרלין, ר אהרן ולקין מפינסק, ר שמחה זליג מבריסק, ר ראובן בורשטין מקמניץ. חתן ר אברהם יצחק קרדאן. רב באירי-ארה\"ב-תרצב, רידינג, קהלת \"בני ציון\" בשיקגו, \"בית ישראל אחי יבנה\"-תשה. פרסם מאמרים ב\"הפרדס\", חיבר חדושים בכת\"י. חבר אגודת הרבנים באמריקה."},{"i":10665,"n":"גודשטדט, שלמה זלמן","k":"בעל אמרי שלמה","bt":"1808","bp":"קאלואריה-ליטא","dt":"1868","b":"תלמיד ישיבות וילנא וולוזין. עבר ללונדון ופריס. חיבר גם \"דברי שלמה\"."},{"i":10666,"n":"גוהמי, שלמה מתימן","b":"דיין בחוגריה-תימן לפני תשח."},{"i":10667,"n":"גווירה, מנחם מוירונה","b":"רב בוירונה-תקכז."},{"i":10668,"n":"גוורטין, יצחק","dt":"תשג","b":"רב בקריזבורג"},{"i":10669,"n":"גוזובסקי, שמואל יחזקאל מקראקא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":10670,"n":"גוזז, יעקב מקושטא","b":"דיין בקושטא-תקף עם ר אברהם יהודה שלום, ור נסים חיים ביסודו."},{"i":10671,"n":"גוזי ן, משה ממרוקו ואלגיר","bt":"תקי","bp":"מרוקו","dt":"תקף","b":"הגיע מאוג'דא-מרוקו, רב בתלמסאן."},{"i":10672,"n":"גוזיק, יוסף יצחק מדוקלא","k":"הו\"ל אהל תורה","b":"הו\"ל ירחון \"אהל תורה\" ובו מתורתו. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":10673,"n":"גוזיק, מנחם יהודה מארה\"ב","k":"בעל נחמת יהודה","b":"רב במקובה-תרנד, רב בארה\"ב-תרצה. מכונה \"מאקובר רב\"."},{"i":10674,"n":"גוזיקוב, מיכאל יוסף","b":"כנר יהודי שניגן בחצרות מלכי אירופה, ושמר על יהדותו על זקנו ופיאותיו. לתולדותיו \"המנגן המופלא\" תל אביב תשז מאת דב סדן."},{"i":10675,"n":"גוזלאן, מסעוד מאלגיר","f":"יוסף","k":"בעל סמדר","bt":"תקץ","dt":"תרס","b":"תלמיד ר דוד מועטי. רב בקצמטינא, ועסק לפרנסתו במסחר. מרבני הדור החדש ברוח הקונסיסטואר. חיבר ספר \"סמדר\" - פירוש על הרא\"ם, עם קונטרס \"פרחה הגפן\"."},{"i":10676,"n":"גוזלאן, שלמה מאלגיר","f":"מרדכי","bt":"תק","dt":"תקע - בערך","dp":"מרוקו","b":"רב ומשורר באלגיר, ובמרוקו."},{"i":10677,"n":"גוזנסקי, שמואל","k":"בעל \"מכתב לתעמלנים","bt":"1867","bp":"וילנא","dt":"1938 - אחרי","dp":"סיביר","b":"פעיל בבונד, עבר לביאליסטוק. נאסר והוגלה ליקוטסק. חיבר חוברות ובהם \"דין ויושר\", \"די שכירות\", ועוד. השתתף בהוצאת כתבי לנין באידיש. נאסר ב-1936 ולא נודעו עקבותיו. ?? לא באוצר ??"},{"i":10678,"n":"גוזר, ישראל מירושלים","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":10679,"n":"גוט, אברהם מדוברומיל","b":"מחכמי דוברומיל. חותנו של ר יוסף פינלש מלברג."},{"i":10680,"n":"גוט, יעקב מטירנוי","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":10681,"n":"גוטבלאט, אברהם צבי מארה\"ב","f":"פנחס אריה","bp":"וארשא","b":"תלמיד ר ליבל חריף, ר יהושע יעקב הכהן. נסמך מאת: ר נתן נטע הכהן מקאליבל, ר יחיאל משה סאנאלוביץ ממלאווא. היגר לניו יורק-תרע ונסמך מאת רשא\"ה יפה, רש\"צ ויין. רב ודרשן בניו יורק."},{"i":10682,"n":"גוטה, בנימין ברוך מסטמר ונ\"י","f":"אברהם יהושע השל","k":"בעל שיטה מקובצת חדש","bt":"תרטז","bp":"סטמר","dt":"תרצה-ח -יד אלול","dp":"ניו יורק","b":"תלמיד מהר\"ם שיק, ר שמעלקא קליין מסעליש, הכת\"ס, ר מאיר פערלס מקראלי - וכתב הקדמה לספרי רבו, ר אהרן דוד דייטש מיארמוט בעל \"גורן דוד\", ועוד. חתן ר טוביה הלוי רוט. עבר לארה\"ב-תרס, וכיהן כרב ק\"ק צ'נסטחוב - חתם סופר בניו יורק. נשיא כולל אמריקה וממיסדי המזרחי בארה\"ב. חבר ועד הנשיאות של ישיבת ר יצחק אלחנן, והיה מעורב במחלוקת על דרכה של הישיבה והתפטר. תשובה ממנו ב\"אוצר נחמד\". הסכים על כמה ספרים ובהם \"שאלו שלום ירושלים\" כנגד הציונות-תרעח. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח, \"המגיד\" - סטמר תרפח-תרצט."},{"i":10683,"n":"גוטה, זרחיה משה מקושטא ומצרים","f":"שניאור או אברהם","k":"בעל זרח יעקב","bp":"קושטא","dt":"תח","dp":"מצרים - ירושלים","b":"מחכמי קושטא, תלמיד ר יחיאל באסאן ור יוסף מטרני, עלה לירושלים ואחר כך לחברון, הגיע למצרים סמוך לשנת ת-תה, ולמד בישיבת ר אברהם סכנדרי. חיבר \"זרח יעקב\", ועוד בכתב יד. נפטר צעיר במצרים ונקבר בת\"י בארץ ישראל. מתלמידיו - ר\"י שאראף. בניו - ר נתן גוטה יצא לונציה להדפיס ספר אביו ולא הסתייע, ר משה, נכדו (בן בתו) ר שמואל ן חביב. אחיו - ר יצחק. מתלמידיו - ר יהודה שראף."},{"i":10684,"n":"גוטה, יצחק מקושטא","f":"אברהם","b":"מחכמי קושטא-שנות ה-ש'-ת'. אחיו - ר זרחיה. בנו - ר נתן מונציה."},{"i":10685,"n":"גוטה, נתן מקושטא וגליפולי","f":"זרחיה","b":"מחכמי קושטא, רב בגאליפולי-תי. נזכר ב\"פני משה\" לר משה בנבנישתי. אחיו - ר משה. גיסו - ר שלמה בן בנימין הלוי מירושלים. (היו שני חכמים בשם זה - בני דודים - ואולי יש בלבול ביניהם)."},{"i":10686,"n":"גוטה, נתן מקושטא ירושלים ונציה","f":"יצחק","dp":"מצרים","b":"מחכמי ירושלים, גיסו של ר מאיר פאפירש ודודו של ר משה בן חביב, מתלמידי מהרי\"ט, והו\"ל את ספר תשובותיו בונציה, והיה מגיה בבית הדפוס שם, בשנת תיז חתם על אגרת בענין עשרת השבטים, בשנת תיט בשליחות בהמבורג, לאחר שנת תך עבר למצרים ונמנה בין חכמי מצרים שחתמו נגד שבתי צבי. (היו שני חכמים בשם זה - בני דודים - ואולי יש בלבול ביניהם)."},{"i":10687,"n":"גוטהיינר, אריה ליב","b":"פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":10688,"n":"גוטויזנא, אליעזר גוטמן מקיעלץ","bt":"תרי","b":"מו\"צ בזוואלין-פלך ראדום-תרמב. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":10689,"n":"גוטויליג, פנחס מקנטשונה","bp":"פשמישל","dt":"תש..","b":"תלמיד ישיבת \"משיב נפש\" בפשמישל. רב בקנטשונה. נספה בשואה."},{"i":10690,"n":"גוטוין, שמואל מצאנז","k":"הו\"ל הפרדס","bt":"תרעג","dt":"תשג","b":"חתן דודו ר שלמה ביגלאייזן. מדפיס בצאנז חדש. הוציא לאור קובץ \"הפרדס\" - צאנז תרצא."},{"i":10691,"n":"גוטוין-גולד,יעקב יצחק מסטריזוב","dt":"תרעד","b":"בנו של הרב מסטריזוב. בנו ר גד אשר היה חסיד בקורטשין וספרו עליו שהיה לו גילוי אליהו. גבאי צדקה לכולל ירושלים."},{"i":10692,"n":"גוטוירט, אברהם מרדכי מזאטור","f":"צבי הירש","bt":"תר","dt":"תרע","b":"רב באושפצין (אושביץ), אב\"ד זאטור(זאטוב)-תרמב, בנו ר צבי הירש מילא את מקומו בחייו."},{"i":10693,"n":"גוטוירט, אליהו יהודה מלבוב","f":"אליעזר","k":"בעל ציון לנפש חיה","bt":"תרן","bp":"לבוב","dt":"תרצג","b":"חתנו של ר יהודה אייכנשטין. בתרסט ביקר עם אביו בירושלים והוזמן לדרוש שם, בהמשך התכתב עם גדולי ירושלים וביניהם הרב חיים ברלין. חיבר \"ציון לנפש חיה\" למברג תרפו. מעורכי \"במחז\"ה\". ?? לא באוצר ??"},{"i":10694,"n":"גוטוירט, אליעזר ליזר ממושיצסק","f":"משה רפאל","bt":"תקל","dt":"תקף","b":"מחכמי מושציסק. נכד ר יהודה ליב מירושלים."},{"i":10695,"n":"גוטוירט, טוביה מטרנוב","f":"יקותיאל צבי זלמן","bt":"תרל","bp":"טרנוב","dt":"תשיג","dp":"אנטורפן","b":"חסיד בלז וצאנז. חתן ר אברהם אבוש רינהולד מטורנא - שהביא ממנו בספרו \"חדושי אבר\"ח. עבר לאנטורפן."},{"i":10696,"n":"גוטוירט, יחיאל אהרן מזאטור","f":"צבי הירש","bt":"תרן","dt":"תשג","b":"רבה של זאטור, על מקום אביו."},{"i":10697,"n":"גוטוירט, יחיאל מריגליץ","f":"יקותיאל צבי זלמן","k":"בעל כתבי רבי יחיאל","dt":"תשכב","b":"גר בקשנוב, טרנוב. עבר לאנטורפן-תרעא. התכתב עם הרוגצ'ובר. ניצל מהשואה. חיבר \"כתבי רבי יחיאל\" - שו\"ת שבינו לרוגצ'ובר - בני ברק תשסב."},{"i":10698,"n":"גוטוירט, יעקב מדוקלא","f":"אליעזר ליזר","bt":"תקס","dt":"תרח","b":"מגדולי תלמידי ה\"חוות דעת\". אב\"ד דוקלא."},{"i":10699,"n":"גוטוירט, יעקב מטרנוב","b":"דיין בטרנוב, דיין בקולבסוב-תרפ."},{"i":10700,"n":"גוטוירט, יקותיאל צבי זלמן","f":"קלונימוס קלמן","bt":"תרי","dt":"תרץ - בערך","b":"חסיד בלוזוב. חתן ר נחום צבי סגל טנצר אב\"ד ריגליץ. אב\"ד בריגליץ-תרסד על מקום חותנו, עבר לטורנא."},{"i":10701,"n":"גוטוירט, ישראל מבואנוס איירס","f":"אליהו יהודה מלמברג","k":"בעל תולדות היהודים","dt":"תשנח","b":"ניצל מהשואה. עבר לבואנוס איירס-תשיא. כיהן שם כנשיא אגודת ישראל. פרסם בעתוני אידיש. חיבר \"תולדות היהודים בספרד\" בספרדית."},{"i":10702,"n":"גוטוירט, מרדכי מאיר מבובוב","dt":"תרפז - בערך","b":"דיין בבובוב-תרנט. חתן אחות תלמידו ר אלתר יחיאל נבנצל."},{"i":10703,"n":"גוטוירט, משה ישראל מוינה","f":"מרדכי רפאל","bt":"תרמז","dt":"תרצה","dp":"וינה"},{"i":10704,"n":"גוטוירט, משה מבובוב","b":"יסד בימ\"ד בבובוב."},{"i":10705,"n":"גוטוירט, משה רפאל מבובוב","b":"רב בבובוב על מקום חותנו ר יעקב."},{"i":10706,"n":"גוטוירט, נחום צבי מאנטורפן","f":"יחיאל","bt":"תרעז","bp":"הולנד","dt":"תשס","b":"תלמיד ישיבת היידה-תרצב, טלז-תרצו, קובנא. בזמן השואה היה באינדונזיה ועסק בהצלה יחד עם ידידו הקונסול ההולנדי - דרך האי קורסאו. חתן ר פנחס מינץ מקובנא. עבר לאנטורפן-תשיב."},{"i":10707,"n":"גוטוירט, צבי הירש מזאטור","f":"אברהם מרדכי","bt":"תרכו","dt":"תרסה","b":"נכד ר ליב יוניבה - חתן הט\"ז. חתן ר פנחס פכטר מדמביץ. רב באושפיצין, אב\"ד זאטור-תרסו על מקום אביו עוד בחייו. נסמך מאת: ר ישעיה שיינפרוכט מיעכוב, ר יחזקאל מרדומסק. חתניו: ר ברוך מאיר בנט, ר משה יוסף זאלץ."},{"i":10708,"n":"גוטוירט, קלונימוס קלמן מפריז","f":"יחיאל","bt":"תרעח","dt":"תשמח","b":"חתן ר שלמה דרייפוס. עסקן באגו\"י בפריז."},{"i":10709,"n":"גוטוירט, קלונימוס קלמן מקראקא","f":"צבי הירש","bt":"תקפז","dt":"תרסב","b":"דיין בקראקא-תרם אצל ר שמעון סופר. הניח כתבים שלא נדפסו."},{"i":10710,"n":"גוטוירט, שאול מדוברומיל","b":"דיין בדוברומיל. החליף שות עם הרב צווייג בענין אם מותר לאשה ללמד תורה לילדות בביתה."},{"i":10711,"n":"גוטימה, אליהו מדולינא","b":"דיין בדולינה-תרמב - תרנד."},{"i":10712,"n":"גוטלובר, אברהם בר","k":"בעל זכרונות ומסעות","bt":"1810","dt":"1899","b":"משכיל, בעברו חסיד חב\"ד."},{"i":10713,"n":"גוטליב משוואבן","f":"יעקב","b":"מחכמי שוואבן. צירף חתימתו לר יצחק איזיק גינצבורג במחלוקת ר שמעון גינצבורג עם ר נתן שאטן."},{"i":10714,"n":"גוטליב, אברהם ישכר מוולברום","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":10715,"n":"גוטליב, אברהם מארה\"ב","dt":"תרנד","dp":"שיקגו?","b":"אדריכל בשיקגו. נשיא ביהכ\"נ \"ציון\" בשיקגו."},{"i":10716,"n":"גוטליב, אהרן אורי מקאליש","f":"גדליה גוטליב מלאדמיר","k":"אדמור מסמבור קאליש","bp":"סמבור","dt":"תשב - אב","b":"מצאצאי ר שלמה הלוי מקרלין. חתן דודו ר שלום מסטרי (סמבור). אדמור בקלוש. נספה בשואה."},{"i":10717,"n":"גוטליב, אהרן אריה מרוזדול","bt":"תקפב","bp":"רוזדול","dt":"תרמב","b":"תלמיד ר יהודה צבי איכנשטין ומהרי\"א מזידיטשוב שציוהו לנהוג אדמורות. אחיו של ר משה."},{"i":10718,"n":"גוטליב, אהרן מדברצין","b":"מחכמי דברצין-תרלז. אביו של ר שמואל מפאפא."},{"i":10719,"n":"גוטליב, אליעזר יצחק ממונטריאול","b":"ר\"מ בישיבת קלעצק. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":10720,"n":"גוטליב, אלתר דוד","b":"תשובה אליו ב\"מנחת שי\"."},{"i":10721,"n":"גוטליב, אריה ליב מזביא","b":"אב\"ד זביא ופוטר בגלל התנגדותו לציונות, על מקומו הרב פישר מזורובנא איש המזרחי. חתנו של בעל \"פתחא זוטא\" ומתורתו בספר חותנו."},{"i":10722,"n":"גוטליב, אריה ליב מרוה-רוסקה","f":"נח אברהם","bt":"תרע","dt":"תשב","b":"אביו היה מנהל בבלז ומייצגה אצל השלטונות. מחכמי רוה-רוסקה. נסמך בגיל 18 מה\"מחזה אברהם\". נספה בשואה. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":10723,"n":"גוטליב, גדליה מבוריסלב","f":"מנחם נחום הלוי","k":"אדמור","b":"רב בבוריסלב-תרפט."},{"i":10724,"n":"גוטליב, גדליה מלודמיר","b":"רב בלאדמיר-תר\"ל"},{"i":10725,"n":"גוטליב, גדליה מסמבור וארה\"ב","f":"נחום מלודמיר","k":"אדמור מסמבור-טשרנובי","b":"מצאצאי ר שלמה הלוי מקרלין. חתן ר אורי מסמבור. אדמור מטשרנוביל בסמבור. היגר לארה\"ב-תרצג. בנו ר נפתלי מבואנוס איירס, וחתנו ר מנחם ישראל ארליך."},{"i":10726,"n":"גוטליב, דב בריש משינאווא","f":"יעקב","k":"בעל יד הקטנה","bt":"תק","dt":"תקנו - כג אב","b":"מחכמי שיניבה. חיבר \"יד הקטנה\" למברג תקס. (באוצר הרבנים תאריך הפטירה תרה)","bk":[["חיי עולם - מוסר",""],["יד הקטנה (מנחת עני) - תרי\"ג מצוות על דרך הרמב\"ם",""]]},{"i":10727,"n":"גוטליב, זאב וולף מוינה ואנגליה","f":"משה יהודה אריה","k":"בעל מימי קדם","bt":"תרע","bp":"פלצה-מלה (גליציה)","dt":"תשמג","b":"חתן ר אהרן אריה ליב רוזן. רב בוינה-תרצב. עבר לאנגליה-תרצח. רב בגלזגו-תשי ורב ראשי בסקוטלנד. עלה לירושלים-תשלז. חיבר \"מימי קדם\" לונדון תשח. ?? לא באוצר ??"},{"i":10728,"n":"גוטליב, חיים יוסף מסטרפקוב","f":"יהודה אריה ליב","k":"בעל טיב גיטין וקדושי","r":"אב\"ד סטרופקוב","bt":"תתקן","bp":"טסא-בערצל","dt":"תרכז - ד אד\"ב","dp":"טיסניץ","b":"תלמיד ר יצחק איזיק מקאליב, ר נפתלי צבי מרופשיץ, והדברי חיים מצאנז. חתן ר מאיר ליכטשין מטרצל, ובזיוו\"ש חתן ר חיים יוסף ברוקשטין מפיסטין. רב בטרצל-תקפג, סטרופקוב-תרא. (לפי אלפסי נפטר ב-טבת). ישיבה על שמו בירושלים - \"רבנו חיים יוסף\" בראשות ר שלמה גוטליב ור שלמה אהרן פולנסקי. מתורתו ב\"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף.","bk":[["טיב גיטין וקידושין – חי' גפ\"ת על סדר נשים",""]]},{"i":10729,"n":"גוטליב, חיים מרדכי יעקב ממישקו","f":"אברהם","k":"בעל יגל יעקב","bt":"תרלו","dt":"תרצו - ח תמוז","dp":"מישקולץ","b":"תלמיד דודו ר יואל צבי רוט בעל \"בית היוצר\", ובעל \"ערוגת הבשם\" בחוסט. חתן הגביר ר מאיר צבי סגל ממיידאן-מארמרוש, ועבר לשם. חסיד האדמור ר יוסף מאיר וויס מספיקנא ובנו ר יצחק. דיין בבורשה-תרסג, אויברווישווה-תרסט, כפר ריזאווליה-מארמרוש-תרפג, על מקום ר יצחק מנחם קיזלניק ור משה קיזלניק על מקומו אחריו, רב במישקולץ, ובנו ר יהודה על מקומו אחריו.","bk":[["יגל יעקב [עה\"ת",""],["שו\"ת]",""],["יגל יעקב \\ יג\"ל יעקב – שו\"ת ודרשות",""]]},{"i":10730,"n":"גוטליב, ידידיה","k":"בעל אהבת השם","dt":"תה","b":"דרשן בלבוב"},{"i":10731,"n":"גוטליב, יהודה מארה\"ב","f":"חיים מרדכי יעקב","dt":"תשלד - ניסן","b":"דומ\"צ ורב במשקולץ,עבר לארה\"ב-תש\"ח"},{"i":10732,"n":"גוטליב, יהושע מהאלמין","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":10733,"n":"גוטליב, יהושע מקוסוב","f":"ישראל","k":"בעל פניני יהושע","bt":"תרעא","bp":"קוסוב","dt":"תשנז","b":"הקים סניף בני עקיבא בקוסוב. עלה לארץ-תרצה, והתישב במנחמיה ובעמק החולה. ממיסדי נחלים-תשט. ממנהלי הישיבות בשילה ועטרת כהנים. חיבר \"פניני יהושע\", \"צו את יהושע\" ועוד."},{"i":10734,"n":"גוטליב, יואל מגלנטא","dt":"תקנב - ו אדר","b":"רב בגלנטא-תקלה ור ליב טעלטש על מקומו אחריו."},{"i":10735,"n":"גוטליב, יוסף אליעזר מזולקוא","b":"דיין בזולקווא עם ר יוסף יוזפא סגל שטרן אצל ר יעקב אורנשטין. הסכים על \"תקפו כהן\" לבעל הש\"ך, ועל זהר חדש - זולקוא תקסז."},{"i":10736,"n":"גוטליב, יועץ משה מהמבורג","f":"משה","bt":"תקעה","bp":"ברגנדורף","dt":"תרלג - יט טבת","dp":"המבורג","b":"תלמיד ר אברהם ברנדס, הרב בערנייס בהמבורג. חתן הדיין ר זלמן וינהיים. מגיד הח\"ק, דיין בהמבורג לצד ר איזיק מעץ, מחכמי הקלויז על מקום ר מרדכי מיכאל יפה."},{"i":10737,"n":"גוטליב, יחיאל מגריבוב","f":"יהושע","bt":"תרעב","bp":"גריבוב","dt":"תשנה","b":"חסיד צאנז. ר\"מ בישיבה בעירו. ניצל מהשואה, רב בוידען-גרמניה. עלה לארץ-תשט, והיה מזכיר אגו\"י בפתח תקוה."},{"i":10738,"n":"גוטליב, יעקב מביהאר","f":"עוזר מהעדילא-מאדע","dt":"תריג - כה אדר","dp":"ביהאר-נאדי","b":"תלמיד החת\"ס, ובעל ישמח משה. חתן ר צבי דייטש משאראש-פאטאק. רב בטאקייא, שאראש-פאטאק, חוסט-תקפט, ביהאר-נאדי-באיאים - תרה. חתנו - ר יואל צבי רוט על מקומו אחריו בחוסט. ליקוטים מתורתו בספר \"בית יעקב\" ירושלים תשסב."},{"i":10739,"n":"גוטליב, יעקב מחוסט ובאייים","dt":"תרך","b":"רב בחוסט, אייאם(=נאגי-באיום)-תרה ור יצחק איזיק פרידמן על מקומו אחריו."},{"i":10740,"n":"גוטליב, יעקב מליטא","f":"צבי הירש","bt":"1911","bp":"קובנא","dt":"1945","dp":"מאיר-רוסיה","b":"משורר וסופר. גדל במשפחה חסידית בקובנא. תלמיד ישיבות ליטא. פרסם שירים ומאמרים בכתבי עת שונים בנושא טבע נוף והעיירה ליטאית - צפה את החורבן העומד לבוא חיבר \"גאלד און בלוט\" קובנא 1931, ועוד. אחיו של נח יצחק."},{"i":10741,"n":"גוטליב, יעקב מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":10742,"n":"גוטליב, יצחק אלחנן מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":10743,"n":"גוטליב, יצחק מבואנוס איירס","f":"שמעון מהאלמין","k":"בעל ילקוט ש\"י","b":"חתן ר שלום לנדא מלעגענע-מיהאי. במלחמת העולם ה-I איבד את בנו ר שמואל יעקב שנלקח מהישיבה לצבא. ואחריה עבר לארגנטינה, וכיהן כרב בבואנוס איירס."},{"i":10744,"n":"גוטליב, ישראל מבוליחוב","b":"מחכמי בוליחוב. רב בטשרנוביץ, עבר ללמברג. תשובה אליו בדב\"ח."},{"i":10745,"n":"גוטליב, לוי יצחק","b":"חתן ר נחמיה בידרמן מללוב."},{"i":10746,"n":"גוטליב, מאיר מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":10747,"n":"גוטליב, מרדכי יעקב","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":10748,"n":"גוטליב, מרדכי מניו יורק","f":"שלום מסטרי","k":"אדמור מסמבור בנ\"י","b":"מצאצאי ר שלמה הלוי מקרלין."},{"i":10749,"n":"גוטליב, מרדכי מסמבור","f":"גדליה מסמבור","b":"מצאצאי ר שלמה הלוי מקרלין. חתן ר ישכר דב מחודרוב (זידיטשוב). היגר לניו יורק."},{"i":10750,"n":"גוטליב, משה מליבטשוב","b":"מקובל. דודו של רח\"ה מאלסק. חיבר ספרי קבלה שחלקם נגנזו. נזכר בשו\"ת \"השיב משה\"."},{"i":10751,"n":"גוטליב, משה מסטניסלב","f":"גדליה מלודמיר","k":"אדמור מסטניסלב","bp":"סמבור","dt":"תשג - יג אד\"א","dp":"דרוהוביטש","b":"אדמור בסטניסלב. מצאצאי ר שלמה הלוי מקרלין. חתן דודו ר יהודה צבי מסמבור. נספה בשואה."},{"i":10752,"n":"גוטליב, משה שמעון","b":"פרסם מאמרים ב\"הכרם\" - וארשא תרפז."},{"i":10753,"n":"גוטליב, נח אברהם","b":"תשובה אליו במהרש\"ם."},{"i":10754,"n":"גוטליב, נח יצחק","f":"צבי הירש","k":"בעל בלויע גנאד","bt":"1903","bp":"קובנא","dt":"1967","dp":"מונטריאול","b":"תלמיד ישיבות ליטא. פעיל ב\"החלוץ\". חיבר שירים ומאמרים בעתונות היהודים בליטא וארצות נוספות. היגר לקנדה-1930. חיבר גם \"גאנג\" קובנא 1929, ועוד."},{"i":10755,"n":"גוטליב, פסח מנמירוב","f":"מאיר","k":"בעל חדושי מהר\"פ","bt":"תק","dt":"תקעז","b":"רב בנמירוב. חיבר \"חידושי מהר\"פ\""},{"i":10756,"n":"גוטליב, צבי אריה מסטניסלב","f":"יוסף","k":"בעל רזא דחכמתא","b":"מחכמי סטניסלב. עלה לחברון. חיבר \"רזא דחכמתא-סוד חכמים\" למברג תרן. ?? באוצר בעילום שם ??"},{"i":10757,"n":"גוטליב, צבי הרש מסטמר","b":"חתנו - ר משה אליעזר קרויס מלונדון."},{"i":10758,"n":"גוטליב, שלום מנשה","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר.","bk":[["משנת שלום","מסכת בבא מציעא"]]},{"i":10759,"n":"גוטליב, שלום מסטרי","f":"אורי אהרן מקאלוש","k":"אדמור מסמבור בנ\"י","b":"מצאצאי ר שלמה הלוי מקרלין."},{"i":10760,"n":"גוטליב, שלמה זלקא","f":"חיים יוסף-טיב גיטין","bt":"תקעו","bp":"טארצאל","dt":"תרלז - ג שבט","b":"רב באינטרדאם-גליל נאסוד."},{"i":10761,"n":"גוטליב, שלמה מירושלים","b":"ר\"מ בישיבת \"רבנו חיים יוסף\" בירושלים. מעורכי \"תורת בית הוראה\" - ירושלים תשג."},{"i":10762,"n":"גוטליב, שמואל מפאפא","f":"אהרן מדברצין","k":"בעל ויהי בנסוע","bt":"תרלז-תרם","bp":"דברצין","dt":"תרפט - כו חשון","dp":"פאפא","b":"תלמיד השב\"ס, ור מנחם ברודא מקאליב ועוד. חתן ר יוסף שלמה רייניץ ממישקולץ. רב בשבעש-תרסב, טאלטשווא-תרסט על מקום ר אברהם יצחק גליק, פאפא-תרפז על מקום ר משה אריה רוט, וחתנו ר יעקב הברפלד על מקומו אחריו. בזמנו פרשו החסידים מהקהילה ומינו לרב את ר יעקב יחזקיה גרינוולד. חיבר \"שמואל ברמה\", \"שמואל במצפה\"-בכת\"י. ?? לא באוצר ??"},{"i":10763,"n":"גוטליב, שמעון מהאלמין","dt":"תרסו - טז אדר","b":"דיין בהאלמין. נספד ב\"ערוגת הבשם\", נזכר ב\"יד יצחק\", \"לבושי מרדכי\". שאלה ממנו לר שמואל דוד יונגרייז."},{"i":10764,"n":"גוטליב, שמעון ממיטאוי","b":"מחכמי מיטאוי-תקפג בזמן ר ישראל פרידמן."},{"i":10765,"n":"גוטמכר צבי בן אליהו","bt":"1818","dt":"ה'תרל 1870","bk":[["נחלת צבי",""],["נחלת צבי (קן מפורשת)",""]]},{"i":10766,"n":"גוטמכר, אליהו מגריידיץ","f":"שלמה","k":"בעל צפנת פענח","r":"רב בפעלשען ואח\"כ בגריידיץ שבפרוסיה","bt":"תקנו","dt":"תרלה - כד תשרי","b":"תלמיד ר עקיבא איגר, עסק בקבלה והתקרב לחסידות. ,רב בפלשן-תקפב, גריידיץ-תקצט והחל לנהוג כאדמור ואף האדמור ר יהודה אריה ליב מגור ביקש ממנו ברכה, כונה הצדיק מגריידיץ-\"דער גריידיצער צדיק\". פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב. מאמר ממנו ב\"סיני\" - ירושלים תרצז, \"תבונה\" - ממל-קניגסברג תרכא.","bk":[["צפנות פענח",""],["הגהות רא\"ג –",""],["חידושי ר' אליהו גוטמכר",""],["סוכת שלום",""],["חידושי רבי אליהו גוטמכר",""],["מכתב מאליהו",""],["סוכת שלום - מכתב מאליהו",""],["צפנח פענח",""],["קן מפורשת - מסכת קנים",""],["שלום בפמליא של מעלה",""]],"e":"תקנ\"ו-תרל\"ה"},{"i":10767,"n":"גוטמכר, צבי הירש","dt":"תרלא - כד חשון","b":"רב בפלעטשין"},{"i":10768,"n":"גוטמן שתדלן מלובלין","b":"מחכמי לובלין. מחברי הח\"ק-תקמב."},{"i":10769,"n":"גוטמן, אברהם יוסף מגרישינא","f":"משה","bt":"תרל","b":"תלמיד ישיבת טלז. רב בנעטשייבקה, גרשינה-פלך יקטרינסלב. חיבר ספר דרוש וחדושי תורה - בכת\"י."},{"i":10770,"n":"גוטמן, אברהם מירושלים","b":"מנהל כולל אונגרן בירושלים-תרלו."},{"i":10771,"n":"גוטמן, אברהם מנחם מנדל מסעליש","dt":"תשג","dp":"סעליש","b":"תלמיד השב\"ס. חתן ר אברהם קליין ראש הקהלה בסעליש ועבר לשם. ראש הקהלה בסעליש-תרנא על מקום חותנו."},{"i":10772,"n":"גוטמן, אברהם שמואל מבודפשט","b":"דיין בבודפשט, חתם-תשיא עם ר עמרם יונגרייז."},{"i":10773,"n":"גוטמן, אהרן מוורנה","b":"גביר תלמיד חכם. פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":10774,"n":"גוטמן, אליעזר מקלם","bt":"תקלב-תקם","dt":"תקצא - ו ניסן","b":"אביו - רב בליסינקי-פלך קיוב נהרג עק\"ה בידי ההידמאקים, והמשפחה עברה לליטא והתישבה בפלונגיאן. תלמיד ישיבות שאוולי ווילנא. רבה הראשון של קלם-תקע בהמלצת ר צבי הירש ברוידא. בנו - ר ראובן צבי ונכדו - ר יחיאל מיכל האוושא מקלם. (תאריך פטירתו במקום אחר - ל ניסן תקפט)."},{"i":10775,"n":"גוטמן, אריה צבי מירושלים","b":"תלמיד ישיבת \"עץ חיים\" בירושלים. נספד ב\"קול תורה\" - ירושלים תרץ."},{"i":10776,"n":"גוטמן, גרשון ליב מקובנא","f":"שלום","k":"העילוי מז'ידיק","bt":"תרלב","bp":"ז'ידיק","dt":"תשג","dp":"קובנה","b":"תלמיד ישיבות סלובודקה, וולוזין, וקלם וכונה \"העילוי מז'ידיק\". דיין בקובנה, ור\"מ בישיבת ר הירשל בסלובודקה, וממייסדי \"בית המוסר\" בקובנה. ייסד מטבח ציבורי כשר עבור החיילים היהודים שחנו בקובנה."},{"i":10777,"n":"גוטמן, דב בר","b":"רב בסדילקוב-תר\"ל. חתנו - ר שלום יוסף מקרוסנא."},{"i":10778,"n":"גוטמן, דוד מפרעשוב","dt":"תשג","b":"רב בפרעשוב"},{"i":10779,"n":"גוטמן, וולף משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":10780,"n":"גוטמן, טוביה","f":"צבי הירש פדר","k":"בעל להט החרב","bp":"פשעדבורג","b":"חיבר השגות לבאורי אהרן וולפסון ועל \"ויעתק יצחק\" לסטאנוב בשם \"להט החרב\", \"קול מחצצים\" כנגד תרגום סטאנוב לספר משלי - ונגנז, ועוד. חיבר שירים ובהם \"הצלחת אלכסנדר\" על מלחמת נפוליאון. מכתב ממנו מברדיטשוב אל ר יעקב שמואל ביק ב\"כרם חמד\"."},{"i":10781,"n":"גוטמן, טוביה מריגליץ","f":"ראה גם: רפפורט","k":"אדמור מריגליץ","b":"תלמיד החוזה מלובלין. אב\"ד ואדמור בריגליץ ונודע כפועל ישועות. בנו ר אברהם אבא על מקומו כרב בריגליץ, וחתנו ר נחום צבי הורביץ על מקומו כאדמור. (ראה גם: רפפורט, טוביה)"},{"i":10782,"n":"גוטמן, יהודה מברזן","b":"תשובה אליו - חסל\"א-תרט."},{"i":10783,"n":"גוטמן, יהושע מרואן-צרפת","dt":"תשלב","b":"מחשובי רבני צרפת,רב ברואן"},{"i":10784,"n":"גוטמן, יחיאל מיכל מבודפשט","k":"בעל האנציקלופדיה התל","b":"רבה האחרון של הקהילה הניאולוגית בצ'ונגראד-1903, מלמד תלמוד בביהמ\"ד לרבנים בבודפשט, בביהמ\"ד לרבנים בברסלאו-1921, באוניברסיטה העברית בירושלים - שנה אחת, וחזר לבודפשט. חיבר\"היהדות וסביבתה\", האנציקלופדיה התלמודית - (יצא לאור 4 כרכים על האות א בלבד)."},{"i":10785,"n":"גוטמן, יחיאל מיכל מניאובה","b":"פרסם מאמרים ב\"יבנה\" - לבוב תרפט."},{"i":10786,"n":"גוטמן, יעקב מטורנא","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":10787,"n":"גוטמן, יצחק אלקנה מיברוב","b":"תשובה אליו - \"דבר משה\"-תריא. (אולי אחיו של ר מרדכי אברהם)."},{"i":10788,"n":"גוטמן, יצחק מסמולביץ","b":"גביר בסמולוביץ. חתן הגביר ר דב בער סוטין מסמאלוביץ. בחרו בר אברהם דב שפירא-חתן הגדול ממינסק לרב בסמאלוביץ על מקום גיסו ר אליעזר רבינוביץ שעבר למינסק."},{"i":10789,"n":"גוטמן, ישראל","f":"דוב בער גוטמן","bt":"תרטז","dt":"תרצו - ח אדר","b":"רב בקמניץ-פודולסק,ברוקלין"},{"i":10790,"n":"גוטמן, ישראל מיאסי","f":"אריה ליב מסדילקוב","k":"בעל בית ישראל","b":"רב ביאסי-תרל."},{"i":10791,"n":"גוטמן, ליפא","dt":"תשג","b":"רב בנאהילבסקי"},{"i":10792,"n":"גוטמן, מרדכי","dt":"תרנח","b":"רב בטערעבעש"},{"i":10793,"n":"גוטמן, משה מבריסק","bt":"תרכו","dt":"תרצג","b":"רב באורלא, דיין בבריסק-תרנו אצל ר חיים סולוביציק, ומנהל מטעמו את הועד לעזרת ישיבת \"תורת חיים\" בירושלים."},{"i":10794,"n":"גוטמן, משה מליטא","bt":"1883","bp":"ואפר-פלך קובנא","dt":"1939","b":"תלמיד ישיבות וילקומיר, קובנא, ווילנא. הצטרף ל\"פועלי ציון\"-1902. ציר בועידת הקהילות בקובנא-1909. ציר בועידת יט\"א בענין אנגולה. נאסר פעמים רבות. חבר בפרלמנט של קרנסקי. חבר ועד הקהילה במינסק, והיה בין החותמים אודות אוטונומיה ליהודי רוסיה הלבנה-1918. התצטרף לקומוניסטים, נאסר-1937 והוצא להורג-1939."},{"i":10795,"n":"גוטמן, משה מפרשבורג","b":"תלמיד ישיבת פרשבורג, מראשי התנועה הציונית בהונגריה, ואחר כך בצכוסלובקיה. נספה בשואה."},{"i":10796,"n":"גוטמן, מתתיהו יחזקאל מליאובה","f":"שלום או משה מיאסי","k":"בעל זרע קדש","bt":"תרנא","dt":"תשלו - י כסלו","b":"רב בליאובה, בוהוש, יאסי, ניצל מהשואה וברח לקזחסטן, חזר לרומניה-תשו, עלה לארץ-תשח וכיהן כרב בגבעת עליה-יפו. פרסם מאמרים ב\"אפריון\" - בודפשט תרפד, \"קבוצי אפרים\" - יאסי-בוקרשט תרעד."},{"i":10797,"n":"גוטמן, נחום מיאסי","b":"פרסם מאמרים ב\"יבנה\" - לבוב תרפט."},{"i":10798,"n":"גוטמן, נחום ממונקטש","k":"אדמור ממונקטש","dt":"תש..","b":"אדמור במונקטש. נספה בשואה."},{"i":10799,"n":"גוטמן, נפתלי חיים מסטריזוב","f":"יצחק פרעמישלר","k":"בעל תולדות נח","bt":"תקסז","dt":"תרט - אייר","b":"תלמיד מובהק לר יעקב יולס בעל \"מלא הרועים\". תלמיד ר אשר ישעיה מרופשיץ, ר צבי הירש מרימנוב. רב בסטריזוב. חיבר \"תולדות נח\" פשמישל תרפט."},{"i":10800,"n":"גוטמן, נפתלי משה מטרנוב","b":"תשובה אליו - \"מחנה חיים\"."},{"i":10801,"n":"גוטמן, צבי","k":"בעל כרם צבי","bt":"תרנג","dt":"תשלג - יט אב","b":"רב פעלים,רב בקודיאקט-תרע\"ג,בוקרשט-תר\"פ,עלה לתל אביב-תשכ\"א"},{"i":10802,"n":"גוטמן, צבי הירש","b":"רב בנירבאטור-תר\"ס"},{"i":10803,"n":"גוטמן, צבי הירש","dt":"תשג","b":"מרביץ תורה בברנוביץ"},{"i":10804,"n":"גוטמן, צבי מליסינקי","b":"רב בליסינקי-פלך קיוב, ונהרג עק\"ה בידי ההידמאקים, ומשפחתו עברה לליטא והתישבה בפלונגיאן. בנו ר אליעזר היה רבה הראשון של קלם."},{"i":10805,"n":"גוטמן, שלום מיאסי","f":"ישראל","k":"בעל בית ישראל","bt":"תרכז","dt":"תרפט","b":"מצאצאי ר לוי יצחק מברדיטשוב. נסמך מאת: מהרש\"ם מברעזן, ר יהודה ליב לנדא בעל \"יד יהודה\", ר אברהם בנימין קלוגר מברודי. רב ביאסי-תרנד. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. חיבר גם \"תפארת בית לוי - לתולדות ר לוי יצחק מברדיטשוב (שהיה מצאצאיו), ועוד."},{"i":10806,"n":"גוטמן, שמואל ברוך מגרוסורדין","f":"שלמה יעקב","bt":"תריט","dt":"תרצא - יג כסלו","dp":"גרוסורדין","b":"תלמיד השב\"ס. ראש השוחטים בגרוסורדין."},{"i":10807,"n":"גוטמן, שמואל מפרשבורג","b":"ממנהיגי היהדות החרדית בפרשבורג, יחד עם גיסיו ר משה בטלהיים, ור וולף פפנהיים (שהיו נשואים לאחיות והתעשרו כאשר גיסם-אחי נשותיהם המומר מוינה הוריש להם את כל רכושו העצום), תרמו לקהלה בזמן החת\"ס. היה חשוך ילדים ועמד בראש אגודה לטיפול ביתומים-תקצד. חתם על צוואת ר דניאל פרוסטיץ-תרו."},{"i":10808,"n":"גוטמן, שמעיה מדיוסג","b":"תלמיד ר משה הירש פוקס מגרוסורדין. שו\"ב ורב בדיוסג-ליד גרוסורדין."},{"i":10809,"n":"גוטמן, שמשון מהוסיאטין","dt":"תש..","b":"רב בהוסיטאין. נספה בשואה. (ראה גם: גוטסמן שמשון מסניאטין)."},{"i":10810,"n":"גוטמן-יסני, רוזה","f":"אליהו","k":"בעל פאר גאר נאענטסטע","bt":"1903","bp":"קובנא","b":"משוררת. עברה לברלין-1921, פאריס, ספרד. ארה\"ב-1939. חיברה גם \"לידער\" ניו יורק 1947. ?? לא באוצר ??"},{"i":10811,"n":"גוטמן-רפפורט, טוביה הכהן מקילץ","f":"ראה: רפפורט, טוביה","dt":"תרסב - כז שבט","b":"תלמיד ר מנחם מנדל מקוצק. רבה הראשון של קילץ."},{"i":10812,"n":"גוטנטאג, ש\"י מסוכוצין","b":"פרסם מאמרים ב\"הלבנון\" - סטמר תרפח."},{"i":10813,"n":"גוטניק, מרדכי זאב","bt":"תרנח","dt":"תרצב - יט כסלו","b":"רב בהכנ\"ס חב\"ד בלונדון"},{"i":10814,"n":"גוטנפלאן, אברהם מטיניע","f":"אהרן מבעלעד","k":"בעל באר אברהם","bt":"תרן","dt":"תשיא - כח אב","dp":"ירושלים","b":"תלמיד הדעת סופר, ור ישעיה זילברשטין מוויצען. חתן ר מאיר רייכהרט מקאטה-תרעג ועבר לשם. רב בפרוינקירכן, רב בטיניע(=טונאג)-תרפז. ניצל מהשואה ואחריה רב בבודפשט, מונקטש. עלה לירושלים-תשז וכיהן כרב במוסררה. חיבר \"נחלת ישעיהו\" ועוד. (במורשת רבני הונגריה נרשם - נספה בשואה)."},{"i":10815,"n":"גוטנפלאן, אהרן מבעלעד","b":"שו\"ב בבעלעד. אביו של ר אברהם מטיניע."},{"i":10816,"n":"גוטסדינר, אברהם מחירוב (עובדיה","f":"גבריאל","k":"בעל כתבים נבחרים","bt":"תרנג","bp":"חירוב","dt":"תשא","b":"עמד בראש תנועת בני עקיבא ותנועות ציוניות דתיות נוספות. עמד בראש בתי ספר עבריים ובתרפח מנהל רשת החינוך יבנה. בשנת תרצד עלה לארץ ושינה שם משפחתו לעובדיה. חיבר \"כתבים נבחרים\" ירושלים תשב, חוברת \"דברות הרמבם\" תל אביב תרצה, \"אייגענע וועגן\" וארשא תרצד. ?? לא באוצר ??"},{"i":10817,"n":"גוטסדינר, גבריאל מחירוב","b":"רב בחירוב-תרנג. חתן ר אברהם דומיניץ אב\"ד רעדים."},{"i":10818,"n":"גוטסדינר, חיים גרשון כץ","b":"רב בטאליא"},{"i":10819,"n":"גוטסדינר, ש' אליעזר כץ","b":"רב בטיסאלוק-תר\"ל"},{"i":10820,"n":"גוטסמן, אברהם","dt":"תקעד - יט טבת","b":"רב במונקאטש"},{"i":10821,"n":"גוטסמן, אברהם","b":"פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":10822,"n":"גוטסמן, אברהם יהושע השל מסטני","f":"נפתלי משלם פיביש","k":"אדמור מלשקוביץ סטניס","bt":"תרמה-ח","bp":"לשקוביץ","dt":"תשג - חשון","dp":"דרוהוביטש","b":"חתן נכדת ר שלום יולס מסטרי (סמבור). נסמך מאת בעל \"עצי בשמים\". אדמור מלשקוביץ בסטניסלב, דרוהוביטש. נספה בשואה."},{"i":10823,"n":"גוטסמן, אברהם יוסף יוסקא מיאס","f":"מאיר הלוי מיאס","k":"אדמור מיאס בבוקרשט","bt":"תרלז","bp":"אוזריאן","dt":"תשח - י אדר","b":"נכד ר אהרן ליב מלשקביץ. תלמיד דודו זקנו - ר בנימין וולף מאוזיראן, חתן רבו ר פנחס לנדמן אב\"ד קרילוב. רב ואדמור בבראילוב-תרסב, אדמור מיאסי בבוקרשט-תרעו, עבר לארה\"ב-תרפב וכיהן כאדמור מאזיראן בניו יורק. חיבר \"אמונה שלמה\" ניו יורק תרפד. בניו - ר צבי, הצייר ר בנימין זאב וולף אדמור מיאס מברוקלין. חתנו ר אברהם בנימין ביניש אוירבך מירושלים."},{"i":10824,"n":"גוטסמן, אברהם יעקב","f":"מרדכי לטניר מדרוהובי","b":"בן האדמור מדרוהוביטש-בעל מאמר מרדכי."},{"i":10825,"n":"גוטסמן, אהרן אריה ליב מגלינא","dt":"תש..","b":"חתן ר חיים גרינברג האדמור מגלינה. היה רבה האחרון של גלינה. נספה בשואה."},{"i":10826,"n":"גוטסמן, אהרן אריה ליב מלשקוביץ","f":"יוסף יוסקא מלשקוביץ","k":"אדמור מלשקוביץ","bt":"תקץ","dt":"תרנה - כז אייר","b":"חתן ר יצחק צבי מצנחם מלשנוב. אדמור זבאריז בלשקוביץ."},{"i":10827,"n":"גוטסמן, אליהו מדולינא","b":"חתן האדמור ר ישכר בר איכנשטין מדולינא, רב בדולינא-תרלח."},{"i":10828,"n":"גוטסמן, אלתר מלשקוביץ","f":"יוסף יוסקא מלשקוביץ","k":"אדמור מלשקוביץ","dt":"תש..","b":"אדמור בלשקוביץ על מקום אביו. נספה בשואה."},{"i":10829,"n":"גוטסמן, אריה ליב מבורשצוב","b":"אב\"ד בורשצוב."},{"i":10830,"n":"גוטסמן, אריה ליב מלוביטש","b":"רב בלוביטש-תרנו, בנו ר אברהם מנדל על מקומו אחריו. מחותמי כרוז הפרדות מהכופרים-תרמא."},{"i":10831,"n":"גוטסמן, אריה ליב מלשקוביץ","f":"יוסף יוסקא","k":"אדמור מלשקוביץ","bt":"תקץ","dt":"תרנה","b":"תלמיד הדע\"ק. האדמור מלשקוביץ על מקום אביו. הכין לדפוס ספר זקנו - רמ\"פ הלר מזבריז - \"יושר דברי אמת\" - לא נדפס."},{"i":10832,"n":"גוטסמן, בנימין זאב וולף","f":"יצחק מנחם אורבוך","bt":"תקפה","dt":"תרנט","b":"(אביו ר יצחק מנחם ולא ר שמשון!). חתן ר נחמן מסקלט. מחכמי וצדיקי אוזיראן, סירב להתפרנס מרבנות והיה סופר סת\"ם."},{"i":10833,"n":"גוטסמן, בצלאל מיריטשוב","b":"חסיד בלז. חתן ר שמואל אב\"ד יריטשוב. אב\"ד יריטשוב-תרפב על מקום חותנו. אחריו כיהן בנו ר חיים. חתנו - ר שמואל באב\"ד אב\"ד דנציג."},{"i":10834,"n":"גוטסמן, חיים מיריטשוב","f":"בצלאל מיריטשוב","b":"רב ביריטשוב-תרץ על מקום אביו, והיה אחרון בשושלת רבנים בת כמאתיים שנה. תלמיד בישיבת \"הלכתא כנחמני\" של חסידי ברסלב בלודז. חתן ר שמחה דרזנר מלמברג. נספה בשואה."},{"i":10835,"n":"גוטסמן, חיים מנאדי-לעטא","dt":"תרעט - ט תמוז","b":"חתן ר יעקב צבי קלטמן מויטעש. רב בלעטא."},{"i":10836,"n":"גוטסמן, יהושע חיים מוולדזירז","b":"במנויי \"צפנת פענח\"- למברג תרן."},{"i":10837,"n":"גוטסמן, יוסף יוסקא מלשקוביץ","f":"שמשון הלר מאוזיראן","bt":"תקס","dt":"תריח - כ טבת","b":"חתן ר מאיר מפרמישלן. רב ואדמור בלשקוביץ. בנו ר אהרן אריה ליב מילא את מקומו אחריו."},{"i":10838,"n":"גוטסמן, יוסף יוסקא מלשקוביץ","f":"אהרן אריה ליב מלשקוב","k":"אדמור מלשקוביץ","bt":"תריב","dt":"תרצג - ז סיון","dp":"זלישטשיק","b":"חתן דודו או אחיו ר משולם פיבש. רב ואדמור בלשקוביץ על מקום אביו. עבר לצאנז ואחר כך לזלישטשיק. הניח חדושים בכת\"י."},{"i":10839,"n":"גוטסמן, יעקב","dt":"תשג","b":"רב בזאסטוונע"},{"i":10840,"n":"גוטסמן, ישראל בר מדרוהוביטש","f":"יוכל מוורצקי","bt":"תקם","dt":"תקף","b":"רב בדרוהוביטש, מתלמידיו הקרובים של החוזה מלובלין."},{"i":10841,"n":"גוטסמן, ישראל זאב משניפישוק","b":"חתן ר מאיר בסין משניפישוק. רב בשניפישוק על מקום חותנו."},{"i":10842,"n":"גוטסמן, מאיר מאוסטר-נוביסליץ","f":"שמשון הלוי מבלשביץ","bt":"תרלה","b":"אב\"ד אוסטר-נוביסליץ(=נאוי-סעליץ)-תרנז. חתן ר מנחם מנדל מזבלטוב (קוסוב)."},{"i":10843,"n":"גוטסמן, מאיר מלשקוביץ ויאס","f":"אהרן אריה ליב מלשקוב","k":"אדמור מיאסי","bt":"תרי","bp":"לשקוביץ","dt":"תרעב-ז - ו אלול","b":"חתן ר משולם פיבש מאוזיראן-מצאצאי ר ברוך ממזבוז' ובזיוו\"ש חתן ר פנחס מניגרעשט בן ר מתתיהו יחזקאל.. רב ואדמור ביאסי-תרסב, אוזראן, זינקוב, פראיזנא, סיאטין. ממשתתפי ועדה לחדושי הסמיכה-תרעד."},{"i":10844,"n":"גוטסמן, מאיר מנובוסליץ","f":"שמשון מבלשביץ","dt":"תרצז","b":"גיסו של ר ישראל ברגר מבוקרשט. רב בנוביסליץ (ליד טשרנוביץ). חסר בויאן. רב בוינה."},{"i":10845,"n":"גוטסמן, מנחם מנדל מלוביטש","f":"ליב","b":"רב בלוביטש-תרנז על מקום אביו."},{"i":10846,"n":"גוטסמן, מנחם מניס מסוקולוב","f":"אלעזר ישראל מרוזדול","b":"רב בסוקולוב."},{"i":10847,"n":"גוטסמן, משה מאיר","dt":"תשד","b":"רב בוואלוץ"},{"i":10848,"n":"גוטסמן, משה צבי מנאדי-לעטא","f":"חיים מנאדי-לעטא","dt":"תשד - ה סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר. רב בנאדי-לעטא על מקום אביו-תרצז. נספה בשואה."},{"i":10849,"n":"גוטסמן, נפתלי משלם פיבוש מסניא","f":"אהרן אריה ליב מלשקוב","k":"אדמור מלשקוביץ סניאט","bt":"תריד","dt":"תרעג - ג אד\"א","b":"חתן ר ישראל רחל'ס מזינקוב (שושלת אפטא). אדמור מלשקוביץ בסניאטין-תרנה."},{"i":10850,"n":"גוטסמן, נפתלי משלם פיבוש מסניא"},{"i":10851,"n":"גוטסמן, שמואל מלשקוביץ-יריטשוב","f":"יוסף יוסקא מלשקוביץ","k":"אדמור מלשקוביץ-יריטש","bt":"תרסב","bp":"לשקוביץ","dt":"תשל","b":"דור חמישי לבעש\"ט. חתן ר חיים יוסף טייטלבוים בן ר יעקב יוקל מוואלווא (שושלת אוהל). רב ואדמור מלשקוביץ ביריטשוב-תרצג על מקום אביו. בשנת תש נמלט לני יורק ועמד שם בראש קהילה. בשנת תשכב ביקש להקים קהלה בארץ ולא עלה בידו."},{"i":10852,"n":"גוטסמן, שמשון אפרים מסניאטין","f":"נפתלי משלם פיבוש","k":"אדמור מלשקוביץ","bt":"תרם","dt":"תשד - ט תשרי","b":"חתן ר אליעזר זאב מרילוס מבוצאץ. רב ואדמור מלשקוביץ בסניאטין-תרף על מקום אביו. נספה בשואה. חבר אגודת הרבנים לחדוש הסמיכה-תרעד."},{"i":10853,"n":"גוטסמן, שמשון מבלשביץ","f":"אהרן אריה ליב מלשקוב","k":"אדמור מבלשביץ","bt":"תרטז","bp":"לשקוביץ","dt":"תרעו","b":"רב ואדמור בבלשביץ-תרע. מחותן עם האדמור ר נחום מסמבור. בנו ר מאיר מאוסטר-נוביסליץ."},{"i":10854,"n":"גוטעגעלד, זאב","b":"מראשי אגודת ישראל בפולין, ממנהלי ישיבת חכמי לובלין."},{"i":10855,"n":"גוטפריד, מרדכי","f":"ישראל לנדא","bt":"תרמד","bp":"אוהנוב-ליד לבוב","dt":"תשכג","b":"משורר, פרסם מאמרים וזכרונות. עלה לארץ-תרצו והתישב בתל אביב."},{"i":10856,"n":"גוטפריד, עזריאל מלבוב","f":"ברוך","k":"בעל חושבנא בעלמא","bt":"תרך","dt":"תרע","b":"מחכמי אוהנוב ואחר כך למברג. חיבר \"חושבנא בעלמא\" פרמישלא תרנז, ועוד. ?? לא באוצר ??"},{"i":10857,"n":"גוטפריד, צבי הירש מפרמישלא","f":"מנחם","k":"הירש אסתר יענטיס","bt":"תרך","dt":"תרעה","b":"חסיד בלז. מחכמי פרמישלא. חיבר \"פני צבי\" פרמישלא תרע, ועוד."},{"i":10858,"n":"גוטפריד, ראובן מירושלים","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":10859,"n":"גוטפרשטין, יוסף מליטא וצרפת","f":"אנשל","bt":"1903","bp":"פראן-ליטא","b":"תלמיד ישיבות ליטא. הסמינר היהודי למורים בקובנא. פרסם שירים ב\"וויספע\". נסע לגרמניה-1923, צרפת-1926 והיה פעיל בפדרציה של האגונים היהודיים בפאריס. ניצל מהשואה ואחריה חזר לפאריס. תרגום לצרפתית פרקים מה\"זהר\" ומ\"ספר היצירה\". חיבר חיבור על פולקלור יהודי ליטא - חלקו פורסם בספר \"יהדות ליטא\"."},{"i":10860,"n":"גוטקובסקי, יעקב","k":"בעל קול יעקב","bt":"1870","dt":"תשו - ג שבט","b":"מו\"צ בקלווריה-תרנ\"ו,ר\"מ בלודז-תרנ\"ח,רב בתל אביב-תרצ\"ז","bk":[["קול יעקב",""]]},{"i":10861,"n":"גוטקובסקי, יצחק אריה","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":10862,"n":"גוטר, אברהם","b":"מחכמי טבריה, חתם בשנת תקמו על כתב שליחות שם."},{"i":10863,"n":"גוטרמן, אהרן מנחם מנדל מרדזימי","f":"שלמה יהושע דוד","k":"אדמור מרדזימין","bt":"תרך","dt":"תרצד - ח אדר","b":"חתן ר יצחק יעקב רבינוביץ מביאלא (שושלת פשיסחא), ובזיוו\"ש חתן ר יעקב משה ספרין מקומרנא. תלמיד ר אברהם מסוכטשוב, ור שניאור זלמן מקאפוסט. רב ואדמור ברדזימין והקים שם ישיבה \"ארחות חיים\". ביקר בארץ-תרפט ויזם הקמת מחיצת הפרדה בכותל בין גברים לנשים. סייע בהקמת העיר בני ברק. רב בנאשלעסק-תרץ והעביר לשם את הישיבה. נפטר ללא ילדים. הניח כ-100 חבורים בכת\"י. בני אחותו ר יעקב אריה מורגנשטרן מוישקוב, ואחיו ר אברהם פנחס משדליץ על מקומו אחריו כאדמורים. חיבר \"צמח מנחם\", \"קונטרס חינוך הבנים\", ועוד. מתולדותיו ב\"תועפות ראם\"."},{"i":10864,"n":"גוטרמן, אלחנן צבי מסקרנטון","dt":"תשכז - ד חשון","b":"רב בסקרנטון-ארה\"ב, הריסבורג. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":10865,"n":"גוטרמן, ברוך מטשיטשילניק","f":"שלמה מטשיטשילניק","k":"אדמור מטשיטשילניק","dt":"תשיא - כט כסלו","dp":"טשיטשילניק","b":"חתן הרב מלכוביץ, ובזיוו\"ש חתן ר אליעזר ריזל מסטנוביץ. אדמור בטשיטשילניק כל ימיו."},{"i":10866,"n":"גוטרמן, ברוך מסאווראן","f":"שלמה מסאווראן","k":"אדמור מסאווראן","b":"חתן ר דוד מזבלטוב (קוסוב). אדמור בסאווראן על מקום אביו."},{"i":10867,"n":"גוטרמן, דוד מסאווראן","f":"שלמה מסאווראן","k":"אדמור מסאווראן","dt":"תרעג - ז חשון","b":"חתן ר מנחם נחום מטשרנוביל-לויאב, ובזיוו\"ש חתן ר שמעון שלמה מבענדר. אדמור בסאווראן(=סברן) על מקום אחיו ר ברוך."},{"i":10868,"n":"גוטרמן, יהודה ירחמיאל","f":"לוי יצחק מסירטשין","dt":"תש..","b":"חתן דודו ר פנחס אליהו מייזלש מוירשוב. נספה בשואה."},{"i":10869,"n":"גוטרמן, יהושע השל מדרוהוביטש","b":"רב בדרוהוביטש. נספה בשואה."},{"i":10870,"n":"גוטרמן, יעקב אריה מרדזימין","f":"שלמה","k":"אדמור מרדזימין","bt":"תקנב","dt":"תרלז - יח תמוז","b":"חתן הגביר ר בעריש מריטשוואהל. מתלמידי המגיד ממזריטש, ואחריו ר שמחה בונם מפשיסחא, ובנו ר אברהם משה ור יצחק מווארקי. רב בריטשוואהל, רדזימין ואדמור שם-תרח לאחר פטירת רבו האדמור מווארקי. מפורסם במופתיו. חיבר \"ביכורי אביב\", \"דברי אביב\". מתורתו ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":10871,"n":"גוטרמן, ישראל מברשד","f":"שלמה מטשיטשילניק","k":"אדמור מברשד","bt":"תרמח","dt":"תרעח - טו שבט","b":"חתן דודו ר נח השני מלכוביץ. אדמור בחיי אביו."},{"i":10872,"n":"גוטרמן, לוי יצחק מסירטשין","f":"ישראל מרדזימין","k":"אדמור מרדזימין בסירט","dt":"תרסה - כג טבת","dp":"וארשא","b":"נכד ר יעקב אריה האדמור מרדזימין. בזיוו\"ש חתן ר חיים שניאור זלמן מליאדי, ועבר לשם. אדמור בליאדי אחר פטירת חותנו, אדמור בסורוצינה(=סירטשין)-תרמ, וארשא."},{"i":10873,"n":"גוטרמן, מנחם מנדל","dt":"תרצה","b":"אדמו\"ר מרדזימין"},{"i":10874,"n":"גוטרמן, מרדכי מטשיטשילניק","f":"שלמה","bt":"תרמב","dt":"תשו - ו ניסן","dp":"אלמא אטא-קזכסטן","b":"חתן דודו ר נחמיה מקוידנוב ברנוביץ (לכוביץ). ברח מהפוגרום בטשיטשילניק-תרפא ועבר לריבניצא, ומשם הוגלה ע\"י הקומוניסטים לאלמא אטא. בנו ר יוחנן מירושלים."},{"i":10875,"n":"גוטרמן, משה","f":"שלמה מטשיטשילניק","dt":"תרעג - ז אב","b":"חתן ר ישראל ואליס-נכד הבעשט. בנו ר אברהם דוד - בבאר שבע."},{"i":10876,"n":"גוטרמן, משה מטשישילניק","f":"שלמה מסאווראן","k":"אדמור מטשיטשילניק","bt":"תקצז","dt":"תרלא - כא חשון","b":"חתן ר יוחנן מרחמיסטריבקא (טשרנוביל). אלמנתו שיינא רייזא עלתה לצפת-תרס, והקימה בימ\"ד ע\"ש בעלה."},{"i":10877,"n":"גוטרמן, משה מקיוב","f":"דוד מסאווראן","dt":"תרפג - א ניסן","dp":"קיוב","b":"חתן ר מרדכי דב מהורנסטיפל (אניפולי). ראב\"ד בקיוב."},{"i":10878,"n":"גוטרמן, משה צבי מסאווראן","f":"שמעון שלמה","k":"אדמור מסאווראן","bt":"תקלה","dt":"תקצז-תרה-כה טבת","dp":"טשיטשילניק","b":"מצאצאי השר ר שמשון ורטהימר מוינה. תלמיד ר לוי יצחק מברדיטשוב ור ברוך ממזבוז. בזיוו\"ש חתן ר דוד מסטעפין. רב בסאווראן על מקום אביו, ברדיטשוב, אומאן, קישינוב, טשיטשילניק. נשיא א\"י ל\"כולל ווהלין\". היה במחלוקת עם חסידי ברסלב. מתורתו ב\"לקוטי שושנים השלם\". מתורתו ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":10879,"n":"גוטרמן, שלמה יהושע דוד מרדזימי","f":"יעקב אריה מרדזימין","k":"אדמור מרדזימין","dt":"תרסג - טו שבט","b":"רב ואדמו\"ר ברדזימין-תרל, ונשיא קופת ר מאיר בעל הנס לכולל פולין. מתורתו בספרי בנו."},{"i":10880,"n":"גוטרמן, שלמה מטשיטשילניק","f":"משה מסאווראן","k":"אדמור מטשיטשילניק","bt":"תריח","dt":"תרף - יא כסלו","b":"נכד ר יוחנן מרחמיסטריבקא. חתן דודו ר מרדכי מאליק, ובזיוו\"ש חתן ר ברוך מרדכי מקוידנוב (לכוביץ). זקנו האדמור מרחמיסטריבקא הכתריו כאדמור. מבניו ר אהרן, ר משה."},{"i":10881,"n":"גוטרמן, שלמה שמעון מסאווראן","f":"משה צבי","k":"אדמור מסאוורן בטשיטש","dt":"תרח - ח תמוז","dp":"כפר ליבעצוק-טשיטשילניק","b":"חתן ר אברהם מסקווירא-נכד הבעשט. אדמור בטשיטשילניק על מקום אביו. מתורתו ב\"לקוטי שושנים השלם\". בניו: ר משה, ר דוד."},{"i":10882,"n":"גוטשטין, דוד צבי מירושלים","b":"מראשי חסידי קרלין בירושלים-תשה."},{"i":10883,"n":"גוטשטין, יצחק","dt":"תרעח","b":"רב בקוזיגלוב"},{"i":10884,"n":"גוטשטין, לוי אברהם מבלשביץ","b":"מחכמי בלשקביץ. תשובות אליו ב\"בית יצחק\", \"שמן הראש\"."},{"i":10885,"n":"גוטשטין, לוי יצחק","f":"דוד","b":"תשובה אליו \"בית יצחק\"-תרלד. (אולי הוא אחיו של ר זאב יהודה מבלשביץ)."},{"i":10886,"n":"גוטשטין, מאיר מבלשביץ","f":"זאב יהודה","bt":"תקץ","bp":"הליטש","dt":"תרעה","b":"רב בהליטש, בלשביץ-תרטו כששים שנה, בנו ר נפתלי על מקומו אחריו ומכר את הרבנות לגיסו ר שלום הלוי קנר. השאיר כתבים שאבדו."},{"i":10887,"n":"גוטשטין, נפתלי מבלשביץ","f":"מאיר מבלשביץ","bt":"תרלה","dt":"תרפא","dp":"ניו יורק","b":"חסיד צורטוקב וזידיטשוב. חתן ר יצחק ישכר טויבש אב\"ד אטיניא. רבה של בלשביץ על מקום אביו, אטיניא-תרעא על מקום חותנו. רב הפליטים בגייע שבמעהרין. היגר לניו יורק-תרפא והיה רבם של אנשי קהילת בלשביץ שם."},{"i":10888,"n":"גוטשכטר, חיים יהושע","bt":"תרכ","dt":"תשב - יג ניסן","b":"רב בוועד הרבנים בוורשה"},{"i":10889,"n":"גוטשל, אשר (משה) אנשיל מרדושי","f":"ראובן","k":"אדמור מרדושיץ לודז","b":"חתן ר הלל מרדושיץ. אב\"ד וואנחצק, אדמור בלודז-תרסא כמנהג אדמורי רדושיץ - שנהגו להרבות בסיגופים ותעניות וטבילות. בנו ר יחזקאל מזרנוב-נספה בשואה."},{"i":10890,"n":"גוטשל, בנימין מרדושיץ","f":"אשר אנשל מרדושיץ לוד","k":"אדמור מרדושיץ","dt":"תש..","b":"חתן ר אלתר מאיר דוד רוטנברג האדמור מואלברום. אדמור ברדושיץ. יודע נגן ומלחין. בנו ר משה יוסף נפטר בצעירותו-ד תמוז תרפז."},{"i":10891,"n":"גוטשל, יוסף ברוך מלודז","f":"אשר אנשל מרדושיץ לוד","dt":"תש..","dp":"גיטו לודז","b":"בן האדמור מרדושיץ בלודז. למדן, יודע נגן, התפרסם ביפי תוארו. נספה בשואה."},{"i":10892,"n":"גוטשל, יחזקאל מזרנוב","f":"אשר אנשיל מרדושיץ","bt":"תרכד","dt":"תש..","b":"נכד ר הלל בן יצחק האדמור מרדושיץ. רב בזרנוב(=זארנוב)-פלך ראדום-תרס. נספה בשואה."},{"i":10893,"n":"גוטשלט, בנימין","dt":"תשג","b":"רב בראדושיץ"},{"i":10894,"n":"ג'ויא - משפחה","b":"מקור שם המשפחה - ג'ויא הוא שם אישה ונזכר ב\"גט פשוט\"."},{"i":10895,"n":"ג'ויא ן, יוסף משלוניקי וירושלי","k":"בעל טל אורות","dt":"תקכח - ג אב","dp":"ירושלים","b":"מחכמי שלוניקי, ירושלים, ונקרא על שם אמו שגדלתו. חתם על ספר \"שער המים\". חיבר \"טל אורות\" שלוניקי תקכה. בשנת תקב בשליחות עם ר יום טוב מאמאן.","bk":[["טל אורות",""]]},{"i":10896,"n":"ג'ויא ן, שלמה מאזמיר","b":"חתם-תרלו ב\"עיני כל חי\" לר חיים פלאג'י, עם חכמים נוספים."},{"i":10897,"n":"גויא, אריה ליב מברנוביץ","dt":"תשג","b":"ר\"מ בברנוביץ"},{"i":10898,"n":"גויוזו, אבטליון מצפת","k":"בעל דיני שחיטה ובדיק","b":"מחכמי צפת, בשליחות בבגדד-תעט. חיבר ספר בדיני שחיטה ובדיקה - בכתב יד."},{"i":10899,"n":"גויוזו, חיים משלוניקי","b":"רב בשלוניקי. הספידו ב\"באר לחי רואי\"."},{"i":10900,"n":"גויוזו, חיים מתתיה מצפת ושלוני","dt":"תפא","dp":"שלוניקי","b":"מחכמי צפת, בשליחות בתורכיה-תעה נשא ונתן בשלוניקי עם ר חיים אמריליו, יתכן שהוא מצאצאי ר יעקב גויוזו מצפת."},{"i":10901,"n":"גויוזו, יעקב מצפת","dt":"שסה","b":"מחכמי צפת, בן זמנו של ר יוסף סמברי הכותב עליו בספרו. ר משה ירושלמי מספר עליו ספורים מופלאים בספרו \"ידי משה\", וכן ר דוד קונפורטי."},{"i":10902,"n":"גויוזו, מנחם מצפת","b":"מחכמי צפת-תנז, בזמן ר אבטליון גויוזו, ר חיים מתתיהו גויוזו ור שמעון גויוזו. כנראה מצאצאי ר יעקב גויוזו."},{"i":10903,"n":"גויוזו, שמעון משלוניקי וצפת","b":"יתכן שהוא נכד ר יעקב גויוזו המקובל הנזיר. מחכמי שלוניקי, עלה לצפת-תמה, רבה של צפת על מקום ר יצחק שלום. בשליחות במצרים-תלו וחזר לצפת, בשנת תמז חתם על הסכמה ל\"שער אפרים\" לר אפרים הכהן. באותו הזמן חיו בצפת עוד ממשפחת גויוזו - ר אבטליון, ר מנחם ור חיים מתתיהו. חתם-תפא על כתב שליחות ר משה ישראל מרודוס."},{"i":10904,"n":"גויטיין, אליהו מנחם מהעדיעס","f":"צבי הרש מהעדיעס","bt":"תקצז-ח","dt":"תרסב -כג-ד אלול","dp":"העדיעס","b":"נכד ר בנימין גויטין בעל \"כסף נבחר\". תלמיד הכת\"ס, ור יוחנן הלוי שפיץ מטאב ור אברהם פופר מטאב. חתן ר ירחמיאל דב בריש בנט מליפטא. רב בהעדיעס(=הוג'אס)-תרך על מקום אביו, בנו ר יוסף שלמה על מקומו אחריו. בנו גם - ר יחזקאל, ר צבי הירש מקופנהגן. מתורתו ב\"זכרון אבות\". פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":10905,"n":"גויטיין, ברוך בנדט (בנדיקט)","k":"בעל כסף נבחר","dt":"תקצ","b":"תלמיד ישיבת ר\"מ מינץ בברודי. רב בהעדיעס(=הוג'אס)-מחוז טולנא ובנו ר צבי הירש על מקומו אחריו. נכדו - ר אליהו מנחם מהעדיעס."},{"i":10906,"n":"גויטיין, גרשון מפרשבורג","f":"יוסף שלמה מהעדיעס","bt":"תרסה","bp":"העדיעס","dt":"תש..","b":"תלמיד הדעת סופר. חתן לבית שנפלד מפריישטט. רב בפרשבורג, בזמן השואה ארגן שיעורי תורה בחברה \"אהבת עולם\" שיסד. נספה בשואה."},{"i":10907,"n":"גויטיין, יוסף שלמה מהעדיעס","f":"אליהו מנחם מהעדיעס","k":"הו\"ל ידי משה","bt":"תרלט-ם","bp":"העדיעס","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר גרשון הלוי ליטש-רוזנבוים מטאליא. רבה האחרון של העדיעס-תרסג על מקום אביו. תומך בציונות. נספה בשואה. בתמיכת הרבנים לבית גויטיין היתה הקהלה מקורבת לציונות ורוב הנוער נתארגן בתנועת אגודת ישראל או המזרחי. חתנו ר אברהם אליעזר אקשטין רב בהעדיעס."},{"i":10908,"n":"גויטיין, יחזקאל ממרינבאד","f":"אליהו מנחם מהעדיעס","bt":"תרכד","b":"תלמיד ר אברהם קרפלס בעל \"אהל אברהם\", ר מאיר פערלס, ביהמ\"ד לרבנים בברלין, בעל תואר ד\"ר. רב במרינבאד-בוהמיה-תרנב, בורגקונשטט(=בירנקונדשטט)-תרנז."},{"i":10909,"n":"גויטיין, צבי הירש מהעדיאס-הזקן","f":"ברוך בנדט מהעדיעס","k":"בעל ידי משה","dt":"תריט","b":"רב בהעדיעס-תקצו על מקום אביו, ובנו ר אליהו מנחם על מקומו אחריו."},{"i":10910,"n":"גויטיין, צבי הירש מקופנהגן-הנכ","f":"אליהו מנחם מהעדיעס","bt":"תרלה","b":"תלמיד ביהמ\"ד לרבנים בברלין. רב בקופנהגן-תרנח."},{"i":10911,"n":"גוייא, יהודה ליב מברנוביץ","b":"מאמר ממנו ב\"תורה אור\" - שנחאי תשו."},{"i":10912,"n":"גוילי, יהושע מטריפולי","f":"יוסף","bt":"שף","dt":"תס - בערך","b":"רב ודיין בטריפולי, כנראה אב\"ד-תכט, חתם ראשון על תעודה בבי\"ד טריפולי - בענין אברהם קרדוזו מכת ש\"ץ. עליו בכתב העת \"עאדא\"-23."},{"i":10913,"n":"גוילי, יעקב מצפת","b":"רב בצפת-שס בזמן המבי\"ט. נזכר ב\"קורא הדורות\"."},{"i":10914,"n":"גויסון, דוד משלוניקי","b":"שליח קהלת שלוניקי-של בערך - לאיסוף כספים לפדיון יהודים מארץ ישראל שנשבו."},{"i":10915,"n":"גוכברג, שמואל מויסאקי-רודע","f":"יוסף","bt":"תרלז","b":"רב בניישטט-סורווינט(=ולאדיסלאווא)-תרס, ויסאקי-רודע-פלך סובאלק, קוזלובה-רודע-פלך סובאלק."},{"i":10916,"n":"גולד, אברהם מארה\"ב","b":"סופר בניו יורק, חיבר \"תולדות ישראל לילדים\" עם מנחם תומרוב."},{"i":10917,"n":"גולד, אברהם מרדכי"},{"i":10918,"n":"גולד, דוד שאול מרזפניק","f":"חיים גולדברג מגורליץ","b":"רב ברזפניק, חתנו ר אהרן יוסף טמפלר על מקומו אחריו. חסיד הדב\"ח (חתם למענו-תרכט). מתלמידיו ר\"ש אנגל."},{"i":10919,"n":"גולד, זאב וולף מארה\"ב","f":"יעקב מאיר קרבצנסקי","k":"בעל ניבי זהב","bt":"תרמט","dt":"תשטז - כז ניסן","b":"נכד-אבי אמו הגביר ר יהושע מנחם גולדואסר משצוצין (וכנראה - מכאן שמו - גולד). דרשן,רב פעלים לישוב א\"י,רב ביוטיקה,שיקאגו-תרס\"ז,קליפורניה,ברוקלין,עלה לירושלים-תרפ\"ד"},{"i":10920,"n":"גולד, חיים מקרקא","bp":"גורליץ","dt":"תרסו","dp":"קראקא","b":"דיין בקראקא-תרסג."},{"i":10921,"n":"גולד, יחיאל מיכל","b":"פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה, \"הנשר\" - טירנוי תרצג-תשד."},{"i":10922,"n":"גולד, יחיאל מיכל הכהן מקורשאן","b":"רב בקורשאן-ליטא-תרלד."},{"i":10923,"n":"גולד, יעקב מדרוהוביטש","f":"שמואל משה","bp":"דרוהוביטש","dt":"תשסא","b":"חסיד בלז. חתן ר אברהם יוסף יהודה נייפלד מקשנוב. ניצל מהשואה. עבר לניו יורק והיה תעשיין בבל-הרבר."},{"i":10924,"n":"גולד, מנחם מניס מטרנופול","b":"דיין ומגיד מישרים בטרנופול. נשלח ע\"י הגביר ר יעקב דוד ברייטמן מטרנופול לבדוק את המהר\"ם שפירא מלובלין בטרם היה לחתנו. תשובה אליו ב\"אור המאיר\"."},{"i":10925,"n":"גולד, משה מרדומישל","k":"בעל דער תהלים זאגער","b":"עסקן צא\"י בגליציה. פרסם מאמרים באידיש בעתונים. נספה בשואה. חיבר \"דער תהלים זאגער\" ניו יורק תשטו."},{"i":10926,"n":"גולד, צבי","b":"תשובה אליו מרבו - \"בנין צבי\"-תרצג."},{"i":10927,"n":"גולד, שמואל משה","f":"יעקב מדרוהוביטש","b":"חסיד בלז המסייע למוסדות החסידות. חתן ר אברהם קרויס. חיבר (לשמחת ילדיו) \"גדא טבא\" ניו יורק תשמט, \"קול רנה\" תשנא ועוד."},{"i":10928,"n":"גולד-הלפרין, יעקב שלמה","b":"חתם כגולד למרות ששמו הלפרין. אב\"ד פרמישלן-תרלא. תשובה אליו ב\"בית יצחק\"."},{"i":10929,"n":"גולדבוים, אביגדור מטיסמניץ","b":"רב בטיסמניץ-תרל. תשובה אליו ב\"בית שלמה\"."},{"i":10930,"n":"גולדבוים, יהושע מאיר מלמברג","f":"יוסף וולף מטרניגרד","b":"חתן ר משה שאול יעקב וואהל מלמברג. גביר בלמברג, ומחותן עם הגבירים ר בערקי מורא ור סנדר מנדל ביק מברודי."},{"i":10931,"n":"גולדבוים, שלום צבי מיאנובצה","f":"אהרן מרדכי","k":"בעל ברכת שלום","bt":"תרכז","b":"נכד ר אפרים רוקח מרדזוויל. חתן ר חיים גדליה רבינוביץ מביחוב. רב ביאנובצה-פלום ראדום-תרנה, גלוסק-פלך לובלין, גראבוביץ(=גראבאוויץ)-פלך לובלין. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":10932,"n":"גולדבוים, שמואל אלעזר מדוקלא","f":"יצחק צבי","bt":"תרל","dt":"תרצה","b":"חתן ר שלום שכנא ויינברגר. רב בדוקלא וגבאי ארץ ישראל."},{"i":10933,"n":"גולדבלום, אבא מארה\"ב","b":"עסקן ציבור בשיקגו, ונשיא אגודת הקהלות החרדיות בשיקגו."},{"i":10934,"n":"גולדבלום, ישראל איסר מליטא ובר","k":"יאפ\"ז","bt":"1864","bp":"וילנא","dt":"1925","b":"ביבליוגרף. עבר לברלין והיה חוקר כתב יד עבריים עתיקים בספריות אירופה. פרסם מאמרים בחתימת יאפ\"ז (ישראל איסר פרח זהב). חיבר \"מאמר ביקורת ספרים\" פאריס תרמו, \"מגנזי ישראל בפאריס\", ועוד."},{"i":10935,"n":"גולדבלט, אהרן","f":"ראובן","k":"בעל ווארצלען","bt":"1897","bp":"קובנא","b":"תלמיד ישיבות ליטא. גלה עם הוריו לקרים-במלחה\"ע ה-I. פרסם שירים בכתבי עת ובהם \"וויספע\". היגר לצרפת-1929. ?? לא באוצר ??"},{"i":10936,"n":"גולדברג חיים","bt":"1890","dt":"ה'תשג 1943","bk":[["די פיער קשיות",""],["דער גרינער יום טוב",""]]},{"i":10937,"n":"גולדברג נתן","bt":"1821","dt":"ה'תרסט 1909","bk":[["מאורות נתן",""]]},{"i":10938,"n":"גולדברג, א' יעקב שלום","dt":"תשג","b":"רב בסטאצק"},{"i":10939,"n":"גולדברג, אברהם הלל","dt":"כז ניסן תשנ\"ד","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא.","bk":[["הארץ ומצוותיה",""]]},{"i":10940,"n":"גולדברג, אברהם יהושע מאיכנהויז","k":"בעל מקור הברכות","b":"תלמיד הסבא מקלם. רב באייכנהויזן-מורביה."},{"i":10941,"n":"גולדברג, אברהם יעקב","b":"הביא לדפוס - מגילת יוחסין וסדר הדורות של תלמידי הבעשט - למברג תרם."},{"i":10942,"n":"גולדברג, אברהם מארה\"ב","f":"נחום","b":"סופר ועסקן ציוני בארה\"ב."},{"i":10943,"n":"גולדברג, אברהם נפתלי","b":"פרסם מאמרים ב\"הלפיד\" - וארשא תרצז, \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":10944,"n":"גולדברג, אברהם פנחס מרומנובה","f":"חיים","bt":"תרה","b":"מחכמי סעלץ וממקורבי ר ירחם יהודה פרלמן \"הגדול ממינסק\" בסעלץ. רב ברומאנאווא(=רומנובה)-פלך מינסק-תרמ. חתנו - ר יוסף דב קוזאק מזאסלאוו."},{"i":10945,"n":"גולדברג, אברהם שלום מזליחוב","f":"יהושע אשר דוד מזליחו","k":"אדמור מזליחוב","dt":"תשב - סוכות","b":"נכד ר משה אליקים בריעה מזליחוב. אדמור בזליחוב על מקום אביו. נספה בשואה."},{"i":10946,"n":"גולדברג, אליהו מאיר ממדיניץ","b":"רבה של מדיניץ לפני השואה."},{"i":10947,"n":"גולדברג, אליהו מבוברויסק","b":"רב בבוברויסק-תר-תרמ. בנו - ר עקיבא ממיר."},{"i":10948,"n":"גולדברג, אליהו מקובנא וירושלים","f":"שמואל","k":"בעל משפט וצדקה","bp":"קובנא","b":"מחכמי קובנא, עלה לירושלים-תרמז."},{"i":10949,"n":"גולדברג, אלימלך מבייטש","b":"רבה הראשון של בייטש ומארגן הקהלה. חתן ר ישראל וגשל מליזנסק."},{"i":10950,"n":"גולדברג, אלימלך מריקי","f":"יהושע גולדברג","dt":"תשב - חהמ סוכות","b":"רב בריקי"},{"i":10951,"n":"גולדברג, אליעזר חיים מסטאצק","f":"ישראל חיים מסטאצק","k":"אדמור מסטאצק","dt":"תשג","b":"נכד ר משה אליקים בריעה מזליחוב. רב ואדמור בסטאצק על מקום אביו. נספה בשואה."},{"i":10952,"n":"גולדברג, אליעזר ליפמן ממינסק","b":"גביר מחכמי מינסק בזמן כהונת \"הגדול ממינסק\"."},{"i":10953,"n":"גולדברג, אליעזר מרוזאליה","dt":"תשב","b":"רבה האחרון של ראזליע(=רוזאליה)-ליטא. נספה בשואה."},{"i":10954,"n":"גולדברג, אליקים מקלם וארה\"ב","bp":"קלם","b":"עלה לארץ ושימש כרופא, עבר לארה\"ב וכיהן כרב."},{"i":10955,"n":"גולדברג, אלתר שלום אלימלך מטור","f":"נפתלי צבי -קול נפתלי","k":"בעל עבודת הלוים","bt":"תרכז","bp":"טרנוב","dt":"תרצח","b":"חתן הגביר ר שלמה זלמן שטינהורן. הקים ישיבה בפאביאניץ. חסיד רדומסק. משנת תרפב רב הקהלה שם.חיבר \"עבודת הלוים\" לודז תרצד."},{"i":10956,"n":"גולדברג, אריה ליב צבי מטוראוו","f":"שלמה","bt":"תריח","b":"נכד ר שמואל דוד מסמחולעויטש, ונכד-אבי אמו ר מנחם אליעזר בעל \"יעיר קינו\". רב בטוראוו-פלך מינסק-תרנא. נסמך מאת: ר יוסף מסלונים, ור שמחה הורביץ מלאחוביץ."},{"i":10957,"n":"גולדברג, בנימין","b":"פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":10958,"n":"גולדברג, גבריאל מפשמישל","f":"אהרן","b":"שו\"ב בפשמישל ממקורבי ר דוד מדינוב."},{"i":10959,"n":"גולדברג, דב בער","k":"הו\"ל יסוד עולם","bt":"תקסא","bp":"חלובנא-ליד רוצקי-פלך סובל","dt":"תרמד - יג אייר","dp":"פאריס","b":"אסף ספרים עתיקים והו\"ל ספרים רבים, ובהם \"יסוד עולם\" לר יצחק הישראלי - ברלין תרה, יחד עם חברו ר דוד קסל. פרסם מאמרים בכתבי עת ובהם \"הכרמל\", \"המגיד\", \"הלבנון\"."},{"i":10960,"n":"גולדברג, דב בער (מאיר) מגלינא","f":"יעקב","bt":"תרלו","bp":"גלינא","dt":"תרעא","b":"רב בגלינא-תרסח, השתתף בקובץ \"אהל מועד\"-חרסא בשם ר ברל מפרמישלא. נפטר ללא ילדים."},{"i":10961,"n":"גולדברג, דובער ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":10962,"n":"גולדברג, דוד","dt":"תשד","b":"רב בטשעטשעוויץ"},{"i":10963,"n":"גולדברג, דוד מקרוק","dt":"תשא","b":"חתן ר חיים מאיר פלדברג מקרוק, רבה האחרון של קרוק-מחוז קידאן על מקום חותנו. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":10964,"n":"גולדברג, זלמן מקריפטש","b":"אב\"ד קריפטש-תרפט"},{"i":10965,"n":"גולדברג, חיים אורי מרישא","b":"רבו של ר שלמה ליב מטיטשין. נזכר בכמה מספרי החסידות."},{"i":10966,"n":"גולדברג, חיים מגורליץ","f":"נתן שפירא","dt":"תרלא","b":"שינה שמו משפירא בגלל הצבא. בעל אחוזת רייכוולד שליד גורליץ - ונקרא על שמה רייכוולדר. ראב\"ד גורליץ, בנו ר דוד שאול גולד אב\"ד רזפניק. חסיד רופשיץ וצאנז."},{"i":10967,"n":"גולדברג, חיים מסטרי","b":"תשובה אליו - \"שארית יעקב\"-תקצא."},{"i":10968,"n":"גולדברג, חיים משה מבריגל","b":"מחכמי בריגל-תרנח, השתתף ב\"אהל מועד\"."},{"i":10969,"n":"גולדברג, טוביה","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":10970,"n":"גולדברג, יהודה אליקים מארה\"ב","f":"יעקב","k":"בעל כוחא דהתירא","bt":"תרטו","bp":"קלם","b":"תלמיד ישיבת קלם בעצת ר ישראל סלנטר, ישיבת ריטובה. נבחר לרב באלקסוט-פרבר קובנא אך סירב ולמד רפואה בקניגסברג - שם ישב באותו הזמן ר ישראל סלנטר שחיבבו וקרא לו בשם \"ר גציל חריף\", סיים לימודיו בברלין והיידלברג. נשלח ע\"י הברון רוטשילד לפקח על הרופאים בארץ, התישב בזכרון יעקב ועסק גם בשיעורי דת ופעילות למען הדת - הסתכסך עקב כך עם פקידי הברון והיגר לניו יורק-תרמה. ר יעקב יוסף - רבה של ניו יורק קירבהו ושתפו בפעולותיו בענין חנוך כשרות ועוד. ממיסדי \"עדת ישראל\" בניו יורק. יסד את ביהכ\"נ \"חובבי תורה\" בניו יורק וכיהן בו כרב. פרסם מאמרים בכתב עת תורנים."},{"i":10971,"n":"גולדברג, יהודה אריה מלודז","b":"פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז, \"פרח הלבנון\" - וארשא תרעח."},{"i":10972,"n":"גולדברג, יהודה אריה משנדישוב","b":"רב בשנדישוב."},{"i":10973,"n":"גולדברג, יהודה ליב מסיקס","dt":"תשד","b":"דומ\"צ בסיקס"},{"i":10974,"n":"גולדברג, יהושע אשר דוד מזליחוב","f":"משה אליקים בריעה","k":"אדמור מזליחוב","dt":"כב תשרי","b":"רב בזליחוב. חתנו ר אברהם שלום מסאבקוב."},{"i":10975,"n":"גולדברג, יהושע זרח מנאנאש","dt":"תשד","b":"רב בנאנאש"},{"i":10976,"n":"גולדברג, יונה מגלינא","b":"תלמיד ר אריה ליב הורביץ מסטרי שהזכירו ב\"הרי בשמים\"-תרם."},{"i":10977,"n":"גולדברג, יוסף אלעזר","bt":"תרלט","dt":"תרצה - ז אלול","b":"רב בצרניקוב,חבר וועד הרבנים בוורשה"},{"i":10978,"n":"גולדברג, יוסף משה מפאליענע","dt":"תשג","b":"רב בפאליענע"},{"i":10979,"n":"גולדברג, יחיאל מיכל מראדום","b":"פרסם מאמרים ב\"שערי חכמה\" - אוזרוב תרפד."},{"i":10980,"n":"גולדברג, יחיאל מקורווא","f":"אליעזר","bt":"תקפט","b":"רב בינובצה-תרל, קוריווא(=קורווא)-פלך לובלין-תרלט, דאלהא."},{"i":10981,"n":"גולדברג, יעקב מלסקרוב","f":"יהושע אשר דוד מזליחו","k":"אדמור מלסקרוב-זליחוב","dt":"תשב","b":"נכד ר משה אליקים בריעה מזליחוב. נספה בשואה."},{"i":10982,"n":"גולדברג, יעקב משה מברלין","f":"יצחק מקלעצק","k":"הו\"ל ספר המנהיג","bt":"תקנה","dt":"תרכח - כה חשון","dp":"ברלין","b":"תלמיד החת\"ס. רב בביאליסטוק-תקעה, מעלוקקען, קניגסברג-תקץ, מחכמי ביהמ\"ד של ר יחיאל ואליך בהמבורג-תקצו, ברלין-תרא. עורך \"תוספות רבי עקיבא איגר\". בניו: ר נחמן אברהם - הו\"ל ספרים רבים בברלין והיה חתנו של ר בנימין בנו של ר עקיבא איגר."},{"i":10983,"n":"גולדברג, יצחק ליב","f":"אלכסנדר","bt":"1860","bp":"שאקי-ליטא","dt":"1935","dp":"שוייץ - תל אביב","b":"יסד בוילנא את אגודת \"אוהבי ציון\". ציר בקונגרסים הציוניים. מתרומתו רכשה הקק\"ל אדמה במקומות שונים."},{"i":10984,"n":"גולדברג, יצחק מלומזה ומינסק","f":"ישראל יהודה","k":"בעל רחובות הנהר-יצחק","bt":"תרו","bp":"סעלץ-ליטא","dt":"תרע","dp":"ירושלים","b":"מחכמי ליטא, בשנת תרמח רב בלומזה ואחר כך במינסק, עלה לירושלים. חיבר \"רחובות הנהר\" ירושלים תרצא. ?? לא באוצר ??"},{"i":10985,"n":"גולדברג, יצחק ממינסק","k":"בעל רחובות יצחק","b":"מחכמי סעלץ - ונקרא עם חברו ר חיים בן חנניה בשם \"חריפי דפומפודיתא\" - ממקורבי הגדול ממינסק בשבתו שם, רב שכונת \"רחוב שדה\" במינסק ודיין אצל הגדול ממינסק, עלה לארץ. בתו מרת מנוחה ולירו הו\"ל את ספרו \"רחובות יצחק\" עם תולדותיו - תרצא."},{"i":10986,"n":"גולדברג, יצחק מקלעצק","b":"חתן ר יעקב משה מסלוצק. רב בקלעצק-תרי. בנו - ר חיים דב אדלמן מפטריקוב."},{"i":10987,"n":"גולדברג, יצחק שלמה","f":"ישראל חיים מסטאצק","b":"חתן ר חיים שמואל מחנטשין (לובלין)."},{"i":10988,"n":"גולדברג, ישעיה מלודז","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":10989,"n":"גולדברג, ישראל חיים מסטאצק","f":"משה אליקים בריעה","bt":"תריד","dt":"תרפד - ד אלול","b":"תלמיד ר יצחק מנסכיז, ור אברהם מטריסק. רב בזליחוב, מודזיץ, סטאצק."},{"i":10990,"n":"גולדברג, ישראל משה ממיהראד","f":"מרדכי","bt":"תריח","b":"רב במיהאראד-פלך חרסון-תרמז."},{"i":10991,"n":"גולדברג, לאה","k":"בעל טבעות עשן","bt":"1911","bp":"קובנא","dp":"ירושלים","b":"משוררת וסופרת. עלה לארץ-1935, מרצה לספרות באוניברסיטה. חברה גם \"שבולת ירוקת העין\" 1940, ועוד."},{"i":10992,"n":"גולדברג, מאיר יצחק","f":"ישראל","bt":"תרלא","bp":"שאט-פלך קובנא","b":"תלמידי ישיבת סלובודקא, תלמיד ר יצחק יעקב רבינוביץ מפוניבז. חתן ר יהושע זליג משטקלישוק. רב באוסטרובה-פלך מוהילוב-תרנט, ויטבסק-תרסז. נסמך מאת: ר משה דנישבסקי מסלובודקה, ר צבי הירש רבינוביץ מקובנא, ר מאיר שמחה הכהן מדוינסק, ר יוסף רוזין-הרוגצובר."},{"i":10993,"n":"גולדברג, מאיר ממדניץ","b":"תשובה אליו - מהרש\"ם-תרסט."},{"i":10994,"n":"גולדברג, מיכאל מראדום","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":10995,"n":"גולדברג, מרדכי מנחם מלודז","b":"ר\"מ בלודז. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":10996,"n":"גולדברג, משה אליקים בריעה","f":"יצחק שלמה מזליחוב","k":"אדמור מזליחוב","bt":"תקצב","dt":"תרסב-ג -כג תשרי","b":"חתן ר יהושע אשר מפוריסוב (פשיסחא). אדמור בזליחוב."},{"i":10997,"n":"גולדברג, משה מזליחוב","b":"עושה חסד,רב בזליחוב"},{"i":10998,"n":"גולדברג, משה מקולבסוב","f":"שלום מקולבסוב","b":"דיין בקולבסוב על מקום אביו."},{"i":10999,"n":"גולדברג, נחמן אברהם","f":"יעקב משה מברלין","b":"חתן ר בנימין וולף בן ר עקיבא איגר. מחכמי הקלויז של ר יחיאל ואליך בהמבורג ור פיבש הכהן מביאליסטוק על מקומו אחריו, מגיה בדפוס את המשניות והש\"ס, הו\"ל משניות עם פירוש חותנו זקנו ר עקיבא איגר והיה מחלוקת מצדו על מדפיסים בוארשא שהדפיסו ללא רשותו וגדולי הדור פסקו לטובתו-תרכא."},{"i":11000,"n":"גולדברג, נפתלי משעלץ","k":"אדמור משילץ-קול נפתל","r":"אדמו\"ר משילץ","dt":"תרסז - יח טבת","b":"נכד הנועם אלימלך. חתן ר משה רוקח האדמור מקארוב. רב ואדמור בשעלץ (ליד וארשא), בנו ר אלתר שלום אלימלך על מקומו כאדמור מפשעביעק. חיבר \"קול נפתלי\" וארשא תרצב.","bk":[["קול נפתלי – עה\"ת",""]]},{"i":11001,"n":"גולדברג, נפתלי צבי סגל מטורנא","f":"חיים הלוי","k":"בעל בית לוי","bt":"תקצב","dt":"תרסא","b":"חתן ר פסח יהודה הכהן ראב\"ד טרנוב. רב בטרנוב-תרמה על מקום חותנו. חיבר \"בית לוי\" פרמישלא תרלח."},{"i":11002,"n":"גולדברג, נתן נטע מקשאנוב","bt":"תרכה","dt":"תשב","b":"רב בקשאנוב, תלמידו של ה\"אבני נזר\". חסיד רדומסק. נספה בשואה."},{"i":11003,"n":"גולדברג, נתן סגל מלימנוב","f":"חיים","k":"בעל מאורות נתן","bt":"תקפא","bp":"גורליץ","dt":"תרסא-ט - א אב","b":"חסיד צאנז. רב בלימנוב-תרל שעל יד צאנז והקים שם ישיבה כששים שנה. חתנו ר חיים יצחק ירוחם מילא את מקומו אחריו. חיבר \"מאורות נתן\" ניו יורק תשד. מתלמידיו ר שלמה מבובוב, ר\"מ מברדיוב ועוד. ?? לא באוצר ??"},{"i":11004,"n":"גולדברג, צבי זאב מארה\"ב","k":"בעל כרם צבי","b":"רב בארה\"ב-תרפא."},{"i":11005,"n":"גולדברג, קלמן אברהם מארה\"ב","b":"רב קהלת עדת ישראל בניו יורק-תשד."},{"i":11006,"n":"גולדברג, שלום מקולבסוב","b":"רב בקולבסוב-תרלה. בנו ר משה מילא את מקומו אחריו."},{"i":11007,"n":"גולדברג, שלמה מיעלקמין","b":"חתן ר יוסף יוסקא אב\"ד פודקמין בעל \"אוהל יוסף\". אב\"ד ילקמין, עבר לבוצאץ."},{"i":11008,"n":"גולדברג, שלמה ממינסק","b":"גביר במינסק, פעל לטובת בית החולים במינסק."},{"i":11009,"n":"גולדברג, שמואל דוד מסמחוולביטש","b":"מו\"צ במסחלעוויטש-פלך מינסק-תקף."},{"i":11010,"n":"גולדברג, שמואל זנויל מבייטש","f":"אלימלך","b":"מחכמי בייטש, עסק בפירוש והערות על הירושלמי, וקטע מהם נדפס ב\"המאור\" - ברלין תרצג. ניהלו משא ומתן עם דפוס ראם בוילנא על הדפסת החדושים בירושלמי שלהם - אך לא יצא לפועל."},{"i":11011,"n":"גולדברג, שמחה מלימנוב","f":"נתן מלימנוב","b":"חתן ר אליהו רוזנר."},{"i":11012,"n":"גולדברג, שמעון","f":"אברהם יצחק","bt":"1873","bp":"קיבארט-ליטא","dt":"1940","dp":"תל אביב","b":"חובב ציון בליטא. מזכירו של ר שמואל מוהליבר, השתתף בועידות ציוניות וחבר \"בני משה\", עלה לארץ-1925, ממיסדי איגוד יוצאי ליטא בארץ ונשיאו - קיבל אות כבוד מטעם ממשלת ליטא על פעילותו למען יוצאי ליטא בארץ-1937."},{"i":11013,"n":"גולדברג, שמעון ממליץ","f":"אברהם חיים","k":"חתם \"שימן\" = שמעון","bt":"תרמה","bp":"צוזמיר","b":"חתן ר מרדכי זילבר ממליץ ועבר לשם. שימש כבוחן ליח\"ל בגליציה עבור מהר\"ם שפירא. חיבר \"מקור חכמה\" מונקטש תרסז."},{"i":11014,"n":"גולדברגר, אברהם גרשון מבאטורקז","f":"בנימין מבאטורקעז","bt":"תרלא","bp":"באטורקעז","dt":"תרנח - ט תמוז","dp":"גיסען","b":"תלמיד השב\"ס, ור דוד ניימן מפרשבורג ובנו ר משה מזשאמבאקרעט. נפטר בבחרותו."},{"i":11015,"n":"גולדברגר, בנימין יוסף","b":"תלמיד ישיבת פאקש. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":11016,"n":"גולדברגר, בנימין מבאטורקעז","f":"מנשה מסערדאוהל","b":"מחכמי באטורקעז. בנו - ר ישראל רב באויהל."},{"i":11017,"n":"גולדברגר, ברוך מגרוסורדין","f":"מנשה מסטרופקוב","dt":"תרעה - יז אלול","dp":"גרוסורדין","b":"חתן דודו ר זאב וולף גולדברגר מהוניאד ועבר לשם, מחכמי פיר-ליד טשאנד, עבר לגרוסורדין."},{"i":11018,"n":"גולדברגר, ברוך מנאנאש","f":"זאב וולף מרצפרט","b":"חתן ר מיכאל גליקליך מנאנאש. תלמיד ר חיים מצאנז. בנו ר זאב האדמור מהוניא. (אולי הוא שמופיע אצל ברוין ושבנו היה ר יצחק נאנאשער)."},{"i":11019,"n":"גולדברגר, גרשון אברהם מברעצל","f":"יוזפא","bt":"תרל","dt":"תרצו - כד ניסן","b":"נכד \"אך פרי תבואה\". רב בבערצעל-תרנד. מתורתו במאספים, ובספרי חכמי דורו."},{"i":11020,"n":"גולדברגר, דוד מטירנא","f":"מנשה מסערדאוהל","b":"רב בטירנא."},{"i":11021,"n":"גולדברגר, זאב וולף מהוניאד","f":"ברוך מהאידו נאנאש","bt":"תריב","dt":"תרעא - כא אב","b":"חסיד צאנז ושינאווא. חתן ר אברהם ישכר דב לייטאג (ליכטיג) מהוניאד, רב בהוניאד על מקום חותנו, ואדמור לחסידים, וחתנו ר ישראל פרוינד היה מועמד לרבנות (והיה מחלוקת עם ר צבי קינסטליכר שקיבלה במקומו)."},{"i":11022,"n":"גולדברגר, זאב וולף מראצפרט","dt":"תרי - יג סיון","b":"חתן ר יהודה ליב-רבה הראשון של קלינורדין. תלמיד ר יצחק איזיק מקאליב. עלה לצפת בסוף ימיו. בניו: ר ברוך מנאנאש, ר נפתלי צבי, ור יצחק."},{"i":11023,"n":"גולדברגר, טוביה מקליש וירושלים","b":"דיין בקליש, עלה לירושלים וכיהן כדיין. בשליחות בהונגריה."},{"i":11024,"n":"גולדברגר, ישראל איזידור מטאטא","bt":"1876","dt":"תשד","b":"רב בקהילה הניאולוגית באויהל-1903, טאטא. חוקר הפילוסופיה היהודית, המדרש, וחוקר תולדות יהדות הונגריה. חיבר מאמרים רבים בנושאים אלה, ובהם לתולדות יהודי טאטא טו וארוש, ותולדות יהודי זמפלן. נספה בשואה."},{"i":11025,"n":"גולדברגר, ישראל מפרשבורג","f":"קלונימוס קלמן מיאקא","bt":"תרמב","bp":"יאקא","dt":"תש.. ט חשון","b":"תלמיד השב\"ס, הדעת סופר, ור יהודה גרינולד מסטמר. חתן ר יוסף דב בר מוינה. מחכמי פרשבורג. נספה בשואה."},{"i":11026,"n":"גולדברגר, ליב מנ\"י","b":"פרסם מאמרים ב\"הלבנון\" - סטמר תרפח."},{"i":11027,"n":"גולדברגר, ליב מפרשבורג","b":"מלמד בחברה \"מחזיקי הדת\" - פרשבורג - אחרי תרנא."},{"i":11028,"n":"גולדברגר, מאיר זאב מפלעדיהאזא","k":"בעל אמרי המז\"ג","b":"רב בפעלעדיהאזא, ארה\"ב. חיבר \"אמרי המז\"ג\" נ\"י תשכד."},{"i":11029,"n":"גולדברגר, מיכאל ממעזא-טור","f":"מנשה","k":"בעל דרשות וחדושי רמג","bt":"תקפט","bp":"סערדאוהל","dt":"תרסב - ט תשרי","dp":"מעזא-טור","b":"מצאצאי ר מיכאל זלצר הראשון. תלמיד הכת\"ס, ור יהודה אסאד ור ישראל לנדברג מגרוסורדין. חתן ר נתן ויינר מסערדאוהל ועבר לשם. רב במעזא-טור-תרכז. ?? לא באוצר ??"},{"i":11030,"n":"גולדברגר, מנשה מסערדאוהל","b":"חתן ר מיכאל הכהן זלצר מפרשבורג. בניו - ר דוד מטירנא, ר בנימין מבאטורקעז, ר מיכאל ממעזא-טור."},{"i":11031,"n":"גולדברגר, נתן יוסף מליסקא וירו","f":"יעקב","bp":"הונגריה","dt":"תרם - יז טבת","dp":"ירושלים","b":"מחכמי ירושלים, עלה מליסקא (הונגריה) לירושלים, היה דיין וגבאי ישיבת \"עץ חיים\", בשנים תרכב - תרלג חתם על תעודות שונות בעניני צבור."},{"i":11032,"n":"גולדברגר, פנחס אשר ממעדיער","k":"בעל מנחת אשר","b":"חתן ר שמעון הכהן שאטין ממעדיער. רב במעדיער-תרצח על מקום חותנו, ניצל מהשואה ועבר לניו יורק. ?? לא באוצר ??"},{"i":11033,"n":"גולדברגר, צבי זאב וולף מברגסא","f":"שלמה מבערגסאז","k":"בעל אלף זעירא","bp":"ברגסאס","dt":"תשד","b":"תלמיד השב\"ס, ור חנניה יו\"ט ליפא טיטלבוים מסיגט. חתן ר דוד וייס מבילקא - ירושלים. רב בבילקא-תרסט, מו\"צ ומגיד בביהמ\"ד חסידים בברגסאס. נספה בשואה."},{"i":11034,"n":"גולדברגר, קלונימוס קלמן מיאקא","f":"אשר זליג מיאקא","k":"בעל דבר אמת","bt":"תרכו או תריח","bp":"יאקא","dt":"תשג","b":"תלמיד השב\"ס, ור מיכאל הופמן מסערדאוהל ור שמואל ארנפלד ממטרסדורף. חתן ר ישראל הכהן. מראשי הקהלה ביאקא, פרשבורג-תרצב. נספה בשואה. ?? לא באוצר ??"},{"i":11035,"n":"גולדגלנץ, יצחק נתן מטרנוב","b":"תשובה אליו - סת\"ם."},{"i":11036,"n":"גולדגעבער, יעקב מלאניאל","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":11037,"n":"גולדהאר, יצחק","b":"פרסם מאמרים ב\"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":11038,"n":"גולדהבר, ישראל מטבריה","bt":"תרמ","dt":"תשכא","b":"רב של חסידי קרלין בטבריה"},{"i":11039,"n":"גולדהירש, ישראל אברהם","f":"שמואל מרדכי הכהן","b":"רב בויניובטשיק. חתן ר מיכל אריה שו\"ב מיזלוביץ."},{"i":11040,"n":"גולדהמר, בנימין וולף מגווזדיץ","b":"רב בגוודיץ. מחותן עם \"הנחל אשכול\" ונתן לו הסכמה-תקסז."},{"i":11041,"n":"גולדהמר, צבי הירש מדוקלא","b":"גביר בדוקלא. גיסו של ר יעקב - חותנו של ר חיים יעקב שטוריס מדוקלא - שהתברך ע\"י הבעשט שכל צדיקי הדור יהיו קרוביו."},{"i":11042,"n":"גולדווסר, יהושע מנחם משצוצין","b":"גביר תלמיד חכם בשצוצין-פלך לומזה-תרל. חתנו - ר יעקב מאיר קרבצינסקי מקאפוליא. ונכדו - ר זאב וולף גולד משיקגו."},{"i":11043,"n":"גולדווסר, יוסף סגל מטרנוב","dt":"תרפב","b":"חתן ר ישראל דב בריש הלוי גלס מטשבין. חסיד שיניבה ובובוב."},{"i":11044,"n":"גולדווסר, יעקב מטשבין","k":"בעל חדושי יעקב","bt":"תרע","b":"תלמיד ישיבת טשבין, מחשובי חסידי בובוב. תלמיד ר שבתי רפפורט מקראקא. חתן ר בצלאל שטרן מלימנוב ועבר לשם. נספה בשואה. חיבר \"חדושי יעקב\" ניו יורק תשמז (נדפסו ע\"י אחיו)."},{"i":11045,"n":"גולדווסר, משה מקאשי","b":"מראשי קהלת קאשוי, חתם-תרלג על כתב מינוי ר משה יונגרייז."},{"i":11046,"n":"גולדווסר, פנחס","bp":"גליציה","dt":"תשמד","b":"למד בישיבה בקראקא. עלה לירושלים-תרצו. בוגר סמינר ליפשיץ. חתן אחיו יעקב (שנפל במלחמה בתש\"ח). השאיר חבורים ביהדות ובליטורגיה."},{"i":11047,"n":"גולדווסר, צבי הירש מקראקא","b":"רב בקראקא-תרך."},{"i":11048,"n":"גולדזול, אהרן מטבריה","b":"דיין בטבריה, חתם-תשו עם הראב\"ד ר אשר זאב ורנר ועם הדיין ר חיים סמאג'ה."},{"i":11049,"n":"גולדין, אברהם מרדכי","bt":"תרלב","dt":"תרצח - ב שבט","b":"רב ביפו-תרס\"ח,אודיסה-תר\"ע,תל אביב-תרפ\"ה"},{"i":11050,"n":"גולדין, אהרן מארה\"ב","f":"ישראל מארה\"ב","b":"תלמיד ישיבות טלז, סלובודקה, ישיבת ר יצחק אלחנן בניו יורק. רב בפאטאקעט-רוד איילנד."},{"i":11051,"n":"גולדין, חיים מבוסטון","f":"ישראל מארה\"ב","b":"תלמיד ישיבות טלז, סלובודקה, ישיבת ר יצחק אלחנן בניו יורק. רב בבוסטון."},{"i":11052,"n":"גולדין, יהודה ליב מזורובנה","f":"משה מלמברג","k":"בעל שבט מיהודה","b":"חתן ר דב בר מבוליחוב. רב בזורובנא(=זורוונא, זיראווני), סקאלי(=סקוליע)-תקם, בנו ר משה בעל הלכה למשה על מקומו אחריו. חיבר \"שבט מיהודה\" זולקוא תקסב."},{"i":11053,"n":"גולדין, יוסף משאקי","f":"ישראל מארה\"ב","dt":"תשג","b":"רב בוישיי, רבה האחרון של שאקי. נספה בשואה."},{"i":11054,"n":"גולדין, ישראל מליטא וארה\"ב","f":"יצחק","bt":"תרלד","bp":"לונא-פלך הורדנא","dt":"תשיא - א תשרי","b":"תלמיד ישיבות איישישוק, ראדין, זאלודק-ליד וילנא, אצל ר משה צבי הירש וולברינסקי מסקידל, נסמך ממנו ומאת: ר מרדכי בריף מלונא, ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא, ר אליהו חיים מייזל מלודז, ר אלכסנדר משה לפידות מראסיין. חתן ר צבי הירש דירקטור מסטיסלוב(=אמצילסב)-פלך מוהילוב. רב בסקידל, לונא, לאפי-פלך לומזה-תרנט, סערהיי(=סארהייא)-פלך סובאלק, היגר לארה\"ב וכיהן כרב ברוצ'סטר(ארה\"ב)-תרצט. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. בנו - ר יוסף משאקי-פלך קובנא, ר חיים מבוסטון, ר אהרן מפאטאקעט-רוד איילנד. אחיינו (בן אחותו) - ר יחזקאל אברמסקי בעל \"חזון יחזקאל\"."},{"i":11055,"n":"גולדין, משה מלבוב","k":"בעל פני משה","dt":"תקך - בערך","dp":"לבוב","b":"רב בטומשוב, למברג-תקח. גיסו ר יעקב הלפרין מטרמבובלה על מקומו אחריו. בנו ר יהודה ליב אב\"ד זורובנא וסקאלי. חיבר \"פני משה\" - בכת\"י. נכד(-אבי אמו) ר משה משינאווא. חתן-בנו של בעל הט\"ז. אב\"ד טומשוב, מגיד ומו\"צ בלבוב ואחיו ר יעקב מטרמבובלה על מקומו אחריו. חתם-תקח בפנקס קהלת לבוב. בנו - ר יהודה ליב מסקאלי בעל \"שבט מיהודה\" ונכדו ר משה בעל \"פני משה\"."},{"i":11056,"n":"גולדין, עזרא","f":"יואל משאץ","k":"בעל אם ובת","bt":"1868","bp":"וילנא","dt":"1915","dp":"וארשא","b":"סופר עברי. חיבר גם \"שכול ואלמן\" וארשא תרנג, \"למקום תורה\", ועוד. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":11057,"n":"גולדיץ, יצחק ממנצסטר","bt":"תרע","bp":"גליציה","b":"עבר לאנגליה בילדותו. תלמיד ישיבת מנצסטר. רב במנצסטר."},{"i":11058,"n":"גולדמינצר, יוסף מראווה","f":"חיים רוטקוף","b":"תלמיד הרד\"כ (דוד רפפורט). חתן ר יהושע פרישרמן מטומשוב, רב בטומשוב. עבר לארה\"ב והתישב בסקווירא. בנו ר זאב נחום ראש הכולל שם."},{"i":11059,"n":"גולדמן, אברהם מזוויהל","f":"מרדכי מזוויהל","k":"אדמור מזוויהל","b":"חתן ר מרדכי שטרנברג מבני ברק. אדמור מזוויהל בירושלים, ובנו ר גדליה משה בראש מוסדות החסידות."},{"i":11060,"n":"גולדמן, אהרן הלוי מארגנטינה","bt":"תריד","dt":"תרצב","b":"הרב הראשון בארגנטינה, רב במושבה \"קרית משה\" - מוזסויל - המושבה הראשונה בארגנטינה. עמד בקשרים עם גדולי דורו באירופה."},{"i":11061,"n":"גולדמן, אשר מירושלים","f":"יעקב","b":"עלה לירושלים-לפני תרטז, מחכמי ירושלים, בשליחות בתורכיה ונהרג בשליחותו בידי שודדים. בנו - ר יעקב והו\"ל ספר \"בני אשר\" לזכר אביו. חתם-תריט עם ר ליבוש בר\"מ מסטאנוב על שטר צוואת ר ברוך ארבאנד מאדעס."},{"i":11062,"n":"גולדמן, בנימין משה מירוסלב","dt":"תרצ..","b":"דיין בירוסלב-תרנז בזמן ר שמואל ולדברג. בנו ר דוד יצחק מילא מקומו אחריו."},{"i":11063,"n":"גולדמן, גדליה משה מזוויהל","f":"שלמה גולדמן","bt":"תרמז","dt":"תשט - כד חשון","b":"חתן ר דוד שלמה מקוברין. רב בזוויהל. נשלח לסיביר ע\"י הקומוניסטים. עלה לארץ וכיהן כאדמור מזוויהל בירושלים.","bk":[["רבי גדליה משה (זועהיל)",""]]},{"i":11064,"n":"גולדמן, דוד מקילץ","k":"אדמור מקילץ","dt":"תרפד - טז חשון","b":"חתן ר אברהם מאיר מביאלוברזיג-בן האדמור מפרגא. בצעירותו היה בעל אחוזה. אדמור בחמלניק לחלק מחסידי אלכסנדר לאחר פטירת האדמור ר יחיאל מאלכסנדר, אדמור בקילץ."},{"i":11065,"n":"גולדמן, חנניה יו\"ט ליפא מנ\"י","f":"יוסף מנייפעסט","k":"בעל הגהות לש\"ס","b":"רב בנייפעסט-תרצח על מקום אביו, ניצל מהשואה ואחריה היגר לארה\"ב וכיהן כרב בניו יורק. חיבר הגהות לש\"ס - ניו יורק תשיט. עורך \"המטיף\" סטמר תרצב. פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":11066,"n":"גולדמן, יהודה דוד מארה\"ב","f":"אליהו בן יוסף בן יצח","bt":"תרנג","bp":"דרוהיטשן-פלך גרודנא","b":"תלמיד ישיבות לודמיר, לומזה, בריסק אצל ר שמחה זליג, לידא אצל ר יעקב יצחק ריינס ור שלמה פוליצו'ק, סלובודקה אצל ר ברוך בר ליבוביץ, ר איצל מפוניבז, וולוזין. חתן - ר מרדכי זונדל רובינשטין בעל \"איש יהודי\". רב בדראהיטשען על מקום זקנו - ר יוסף המכונה \"חומסקער עילוי\", היגר לארה\"ב-תרפא וכיהן כרב קהלת \"בית אברהם\" בשיקגו, קהלת \"בית ישראל\" אנשי יאנובה. פרסם מאמרים שונים. חבר אגודת הרבנים באמריקה, ותנועת המזרחי, מנהל ומזכיר קרן ההצלה (בזמן השואה)."},{"i":11067,"n":"גולדמן, יום טוב ליפמן","dt":"תשד","b":"דומ\"צ בצלם"},{"i":11068,"n":"גולדמן, יוסף מנייפעסט","dt":"תרצח","b":"רב בנייפעסט(=אוי-פשט)-תרע כ-28 שנה, הקים ישיבה והקפיד על אופי אורטודוכסי בקהילה. היה כפוף בהוראה לרבני צעהלים ובוניהאד(=באניהאד)."},{"i":11069,"n":"גולדמן, יוסף נחמיה מקיבארטי","f":"צבי הירש","bt":"תרכז","b":"מו\"צ בקיבארטי-פלך סובאלק-תרס."},{"i":11070,"n":"גולדמן, יחיאל מיכל מזוויהל","f":"מרדכי או משה מזוויהל","bt":"תקמח","dt":"תרטז - יב תשרי","b":"נכד המגיד מזלוטשוב. חתן ר ישראל חיים מלודמיר (ריזין). רב בנאווגרודולינסק(=זעוויהל)-תרע. חתניו: ר יעקב ישראל קארף מזוויהל, ר פנסח רוקח מנאוודיע."},{"i":11071,"n":"גולדמן, יחיאל מרישא","b":"תשובה אליו - \"תפארת יוסף\"."},{"i":11072,"n":"גולדמן, יעקב מברלין","f":"פנחס אליעזר","dp":"לודז","b":"גביר בברלין, חסיד האדמור מטורנא. צוואתו נדפסה אחר פטירתו - לודז תרפה."},{"i":11073,"n":"גולדמן, יעקב מירושלים","f":"אשר","k":"בעל בני אשר","bt":"תרסז","bp":"ירושלים","b":"עסקן צבור, ממיסדי ביה\"ח שער ציון. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט. חיבר גם \"פרט ועוללות\"."},{"i":11074,"n":"גולדמן, יצחק","f":"מאיר","k":"בעל הפחד בלילות","bt":"1839","bp":"פלך וילנא","dt":"1905","b":"תלמיד ישיבות מינסק, וולוזין. סופר ומשורר עברי. עבר לוילנא והיה מקורב לאד\"ם הכהן. חיבר גם \"שנים קדמוניות\" וילנא תרלט, ועוד."},{"i":11075,"n":"גולדמן, יצחק","b":"חתן ר שלמה גולדמן האדמור מזוויהל."},{"i":11076,"n":"גולדמן, יצחק איזיק גרשון מליסא","b":"דיין בליסא-תקע בזמן ר יעקב בעל הנתיבות. חתם עם ר יהודה ליב קלישר מליסא."},{"i":11077,"n":"גולדמן, יצחק מבארנסוואלד","b":"תלמיד הכת\"ס, ור חזקיה פיבל פלויט משוראן. רב בארנסוואלד-תרכו."},{"i":11078,"n":"גולדמן, יצחק צבי מדוקלא","k":"הו\"ל דברי שאול","b":"ההדיר ספר \"דברי שאול\" לר שאול מלוטינבך - קראקא תרסה."},{"i":11079,"n":"גולדמן, ישעיה מקילץ","f":"דוד מקילץ","k":"אדמור מקילץ","b":"רב בבוסק. אדמור בקילץ-תרפד על מקום אביו."},{"i":11080,"n":"גולדמן, ישעיה צבי מפרשבורג","bt":"תרד","dt":"תרפז - ייט אד\"א","dp":"פרשבורג","b":"תלמיד הכת\"ס. חתן ר אריה יהודה ליב מפעזינג. מחכמי פרשבורג."},{"i":11081,"n":"גולדמן, ישראל מסטמר וגרוסורדין","f":"אהרן יצחק","k":"בעל כנסת ישראל","bp":"גרוסורדין","dt":"תשג - טו אד\"א","b":"תלמיד ר בנימין זאב מנדלבוים בסטמר, ור חיים צבי וינקלר מראצפרט. רב בסטמר-תרנט, גרוסורדין-תרע (לפי אוצר הרבנים). פרסם מאמר על חנוכה ב\"אללגעמיינע יידישע צייטונג\"-תרסא. נספה בשואה."},{"i":11082,"n":"גולדמן, ישראל פיליפובר מרומשיש","b":"רב ברומשישוק אחרי ר אהרן שמידט."},{"i":11083,"n":"גולדמן, מאיר מוילנא","f":"שמואל","dt":"תרנד - א תמוז","dp":"וילנא","b":"מחכמי וילנא. התוכח עם חכמי הקראים ובראשם אב\"ן רש\"ף בנוגע לפרשנות התנ\"ך. בקי בחכמות התכונה והרפואה. חיבר חידות ופרסם ב\"הצפירה\" תרנב \"תן חלק לשבעה וגם לשמנה\". הניח כתובים ושירים בכת\"י. מחותן עם בנו של ר מנשה מאיליא בעל \"אלפי מנשה\"."},{"i":11084,"n":"גולדמן, מרדכי מזוויהל - א","f":"יחיאל מיכל מזוויהל","k":"אדמור מזוויהל","bt":"תקעח","dt":"תרסא - יד תשרי","b":"אדמו\"ר מזעוויהל-תרל. חתן ר שלמה מגראנוב-חתן ר יצחק יעקב מגראנוב."},{"i":11085,"n":"גולדמן, מרדכי מזוויהל - ב","f":"גדליה משה מזוויהל","k":"אדמור מזוויהל","bt":"תרסו-ע","dt":"תשמא - כח שבט","b":"חתן דודו ר שמואל מרדכי מנסכיז-סטביחוב. חיבר \"יקרא דמלכא\", \"מרדכי בשער המלך\". אדמור מזוויהל-תשט."},{"i":11086,"n":"גולדמן, מרדכי מלודז","b":"מו\"צ בלודז-תר\"ע"},{"i":11087,"n":"גולדמן, משה מאיר מלימנוב","b":"רב בלימנוב. נכד ר משה דרשן. תשובה אליו לקראקא-תרנו."},{"i":11088,"n":"גולדמן, משה מירושלים","f":"אשר","bt":"תרכא","bp":"שדליץ","dt":"תרצג - ח טבת","dp":"ירושלים","b":"חתן נכדת ר קלמן שדליצר. מקורב לאדמור מגור \"שפת אמת\". עלה לארץ-תרנא ועסק בפעילות צבורית. נספד בידי הרב קוק."},{"i":11089,"n":"גולדמן, מתתיהו מרופשיץ","b":"דיין ברופשיץ-תרנג. תשובה אליו לקורטשין-תרסג ב\"פרי השדה\"."},{"i":11090,"n":"גולדמן, נחום","f":"שלמה צבי","bt":"1894","bp":"וישניאוה-פלך וילנא","b":"נשיא ההסתדרות הציונית. יו\"ר כינוס הקונגרס היהודי העולמי-1936, השתתף בהו\"ל האנציקלופדיה \"אשכול\" בברלין-1932, עבר לארה\"ב-1940 והיה נשיא הקונגרס היהודי העולמי."},{"i":11091,"n":"גולדמן, פנחס שלום מזלין","dt":"תרמז","b":"רב בזלין והתפרנס ממסחר. סירב להצעת רבנות מלמברג על מקום השו\"מ. בזיוו\"ש חתן ראנ\"ה ינר מקראקא."},{"i":11092,"n":"גולדמן, פסח","dt":"תשג","b":"רב בבאלניק"},{"i":11093,"n":"גולדמן, צבי אריה","f":"חיים שכנא","k":"בעל חשבון פרטי המצות","dt":"תרעו","dp":"ירושלים","b":"עלה ממזריטש לירושלים והיה מחכמי \"בית אל\". חיבר \"חשבון פרטי המצוות\" ירושלים תרסד, ועוד."},{"i":11094,"n":"גולדמן, שלמה ליב מירושלים","f":"אשר מירושלים","bt":"תריט","bp":"ירושלים","dt":"תרעט - יא תמוז","dp":"סידני","b":"תלמיד ישיבת עץ חיים בירושלים."},{"i":11095,"n":"גולדמן, שלמה מזוויהל","f":"מרדכי מזוויהל","k":"אדמור מזוויהל","r":"האדמו\"ר מזוועהיל","bt":"תרכט","dt":"תשה - כו אייר","b":"חתן ר אלתר בן ציון מדוידהורדוק והקים שם ישיבה. עלה לירושלים-תרפה וכיהן כאדמור מזוויהל בירושלים. מתורתו ב\"צדיק יסוד עולם\".","bk":[["יסוד צדיק – עה\"ת",""]]},{"i":11096,"n":"גולדמן, שלמה צבי - שלמון","k":"שלמון","bt":"1862","bp":"זאלודק-פלך וילנא","dt":"1933","b":"תלמיד ישיבות ראדין, איישישוק. סופר ועסקן ציוני. חיבר ספר משלים בכינוי \"שלמון\". אביו של נחום גולדמן."},{"i":11097,"n":"גולדמן, שמואל זאב מגרוסורדין","f":"ישראל מגרוסורדין","k":"בעל נדחי ישראל","b":"חתן ר משה קליין מראטע וגרוסורדין. רב בגרוסורדין על מקום חותנו. נספה בשואה. חיבר גם \"שלשלת הזהב\", \"כנסת ישראל\". פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"קבוצי בחורים\" - מארגרטן תרצג."},{"i":11098,"n":"גולדמן, שמואל מלמברג","b":"תלמיד רי\"ש נתנזון שהשיב לו בספריו-תרטו."},{"i":11099,"n":"גולדמן, שמחה ראובן מקעסטהאל","b":"מראשי קהלת קעסטהאל-סלובקיה-תר בערך, חתם עם ר יצחק שפיץ ור מנדל דוקס."},{"i":11100,"n":"גולדמן, שמעון מירושלים","b":"חתן המקובל ר שמעון צבי הורביץ מירושלים. הקים לזכר חותנו את ישיבת \"זכרון שמעון\" יחד עם המקובל ר שלום נג'אר."},{"i":11101,"n":"גולדמן-פריד, יצחק זאב ממזלבריץ","dt":"תשד","b":"רב במעזאלבריץ"},{"i":11102,"n":"גולדמרק, שמחה ראובן מקעסטהאלי","b":"מראשי קהלת קעסטהאלי-מורביה-תקפח. חתם על כתב מינוי ר שעפטיל הלוי לרב העיר."},{"i":11103,"n":"גולדנבך, שלום מטשרנוליצה","b":"בנו של אב\"ד טשרנוליצה. תשובה אליו - \"דבר משה\"."},{"i":11104,"n":"גולדנברג, חיים יהודה מסאוויליו","f":"שלום - דברי שלום","dt":"תשד","b":"רב בסוואליווע על מקום אביו. נספה בשואה."},{"i":11105,"n":"גולדנברג, משה מאיר מטשירטש","b":"רב בטשירטש-תר\"נ"},{"i":11106,"n":"גולדנברג, שלום","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":11107,"n":"גולדנברג, שלום מסואליווע","k":"בעל דברי שלום","bt":"תרלב","dt":"תרעח - טו אב","b":"תלמיד ר מנחם א\"ש באונגוואר. חתן ר מרדכי גוטמן מטאקע-טערעבעץ. (או חתן ר יצחק וייס בעל דברי יצחק). רב בסוואליווע(=סוועליעווע), וראש ישיבה. בנו - ר חיים יהודה ליב על מקומו אחריו. חתנו - ר יוסף אפשטין סייע בהדפסת ספרו \"דברי שלום\"."},{"i":11108,"n":"גולדנהורן, אביגדור מניו יורק","f":"לייביש הלוי גולדנהור","bt":"תרלט","dt":"תשו - כ אדר","b":"רב בברונקס"},{"i":11109,"n":"גולדנהורן, לייביש הלוי מפולנאה","b":"רב בפולנאה-תר\"מ"},{"i":11110,"n":"גולדנסון, אברהם מארה\"ב","bt":"תרל","dt":"תרצא - כא שבט","b":"רב ברוסיה, קהלת שערי תורה\" בשיקגו, סט' לואיס. חיבר את תולדות חייו של ר יצחק דובער חאנעס בסוף ספרו \"ספר המילים\"."},{"i":11111,"n":"גולדנסון, שמואל צבי מארה\"ב","bt":"1878","bp":"קאלואריה-ליטא","b":"רב רפורמי. תלמיד היברו יוניון קולג'. רב בלקסינגטון, פיטסבורג, ניו יורק ב\"טמפל עמנואל\". נשיא הועידה המרכזית של רבני אמריקה."},{"i":11112,"n":"גולדנפלד, נחמן מטורדה","b":"ראש ישיבה לבחורים מחוננים בכפר עגערבעג'-ליד טורדה(=טורדא). נזכר ב\"תורת יקותיאל\"."},{"i":11113,"n":"גולדנר, יהושע הלל מקלויזנבורג","k":"בעל ללמוד וללמד","b":"מלמד בקלויזנבורג. נספה בשואה."},{"i":11114,"n":"גולדנר, יעקב","b":"תשובה אליו - מהר\"י הכהן."},{"i":11115,"n":"גולדנשטיין, פנחס דב מבאחציסארי","b":"שו\"ב בבאחציסארי."},{"i":11116,"n":"גולדס, אברהם מקראקא","f":"אשר","dt":"תקפה","b":"נכד ר יצחק אב\"ד טיסמניץ. דיין בקראקא."},{"i":11117,"n":"גולדס, צבי מסניאטין","b":"תשובה אליו - \"כוכב מיעקב\". ממנויי \"ארץ החיים\"-תרסד."},{"i":11118,"n":"גולדפאדן, אברהם מניו יורק","k":"בעל ציצים ופרחים","bt":"תרה","bp":"קונסטנטין ישן-וואהלין","b":"תלמיד ביהמ\"ד לרבנים בזיטומיר, מורה בסימפערפול, אודסה, לבוב והו\"ל \"ישראליק\", טשרנוביץ והו\"ל \"איזראעליטישעס פאלקס בלאטט\", יאסי והקים תיאטרון יהודי, היגר לארה\"ב והו\"ל \"יידישע איללוסטרירטע צייטונג\", חזר לאירופה ל-10 שנים וחזר לארה\"ב-1903. חיבר גם \"דאס יודעלע\", \"בר כוכבא\", ועוד."},{"i":11119,"n":"גולדפדן אברהם","bt":"1840","dt":"ה'תרסח 1908","bk":[["ציצים ופרחים",""]]},{"i":11120,"n":"גולדפוגל, הנרי מניו יורק","bt":"1856","bp":"ניו יורק","b":"שופט בניו יורק, חבר קונגרס. פעיל בענינים יהודיים באמריקה."},{"i":11121,"n":"גולדפיין, אבא דוד","f":"יהודה","bt":"תרלח","bp":"רדייק-ליטא","dt":"תרצד","dp":"מוסקבה","b":"תלמיד ישיבות וולוזין, וסלובודקה. חתן ר יוסף רוזין הרוגצ'ובר. רב בדוינסק, מוסקבה. מתשובותיו ב\"חות דעת\" לר צבי מקובסקי. חיבר קונטרס על החליצה.","bk":[["זכר דוד - חליצה (נדפס בתוך ספר צפנת פענח חלק א' לחותנו - כן נדפס בסוף החלק של מתנות עניים קונטרס אחרון ממנו)",""],["פתח בית דוד - רמב\"ם (כת\"י)",""]]},{"i":11122,"n":"גולדפישר, יוסף מריישא","b":"מחכמי רישא. מתורתו ב\"דובב מישרים\"-תשא. נספה בשואה."},{"i":11123,"n":"גולדפלד, ישראל יחיאל מבנדין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":11124,"n":"גולדפלד, ישראל יחיאל מבנדין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":11125,"n":"גולדפלד, מיכל","b":"נכד ר חיים משה גינצבורג. ממשתתפי \"אהל מועד\"-תרנט."},{"i":11126,"n":"גולדפרב, אברהם מארה\"ב","b":"רופא בארה\"ב, ראש אגודת הרופאים."},{"i":11127,"n":"גולדפרב, דוד שלמה","k":"בעל רמזים וזרמים","bp":"גליציה","b":"עבר לניו יורק. תלמיד ישיבת ר יצחק אלחנן. רב בצרלסטון, לונג ביץ. עלה לירושלים. פרסם מאמרים בכתב עת שונים. חיבר \"רמזים וזרמים עה\"ת\" ניו יורק תשכא."},{"i":11128,"n":"גולדפרב, יוסף מוארשא","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":11129,"n":"גולדצויג, אלישע צבי מקוסוב","f":"חיים","bt":"תר","dt":"תרע","dp":"צפת?","b":"נכד האדמור ר אברהם ליב-נכדו של ר יעקב קופל חסיד - תלמיד הבעש\"ט. עלה לצפת. עסק רבות בצדקה."},{"i":11130,"n":"גולדצויג, חיים מקוסוב","f":"אלישע צבי","bt":"תרך","bp":"קוסוב","dt":"תרצו","dp":"צפת","b":"עלה עם אביו לצפת. חתן ר זידא מרדכי יהודה ליב מצפת בנו של הצדיק ר גרשון פלאך מקוסוב. בנו - ר יהודה בן ציון ממונטריאול."},{"i":11131,"n":"גולדצויג, יהודה בן ציון ממונט","f":"חיים בן אלישע צבי","bp":"קוסוב","dt":"תשכו - כה שבט","b":"תלמיד ישיבות לומזה, \"מרכז הרב\" בירושלים, ישיבת הרידב\"ז וחת\"ס בצפת, ר שלמה אליעזר אלפנדרי בצפת. נסמך מאת: ר יוסף הלפרין, ר זושא פרידמן, הרב קוק, ר שמחה בונם ורנר, ר\"נ אתרוג מצפת, ר חיים צבי רובינשטין משיקגו. דיין באדעס, בצפת אצל ר\"נ אתרוג, רב במונטריאול. חיבר ספרים - בכת\"י. חבר אגודת הרבנים באמריקה."},{"i":11132,"n":"גולדצויג, יעקב מחיפה","k":"הו\"ל אגרת לקץ הימין","b":"רב בחיפה. הו\"ל \"אגרת לקץ הימין\" לר חיים ויטאל - מנצסטר תרנו."},{"i":11133,"n":"גולדצויג, משה גרשון מארה\"ב","f":"חיים בן אלישע צבי","bt":"תרנט-ס","bp":"צפת","dt":"תשכו - ב אייר","b":"תלמיד הרידב\"ז בצפת, ישיבת חת\"ס בצפת, ישיבת נוברדוק. נסמך מאת: ר שמואל צינדר מצפת, ר אהרן משה קיסעלאוו מבאריסוב-פלך מינסק, ר שמואל לוין מאמסק. חתן ר מרדכי אהרן מאנעש הרישנזון ממוהילוב, ובזיוו\"ש חתן ר צבי אריה טערען משיקגו. רב בחרבין-סין, חיילאר-סיביר, פולארדי-סיביר, ציציקאר-סיביר, היגר לארה\"ב וכיהן כרב קהלת \"בני יעקב אנשי קובנא\" בשיקגו-תרפה, קהלת לאהישין דלובישוב, \"עטרת ישראל\", אנשי וארשא, \"תפארת משה\". פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":11134,"n":"גולדציהר, אהרן יום טוב ליפמן","f":"שרגא פייש מקיצע","bt":"תקעא","dt":"תרלד","b":"תלמיד החת\"ס. חתן ר יצחק ברגר. מחכמי שטוהל-וויסנבורג. בנו הפרופ' יצחק יהודה ליב גולדציהר בבודפשט."},{"i":11135,"n":"גולדציהר, יצחק מבודפשט","b":"פרופ' לפילוסופיה דתית בביהמ\"ד לרבנים בבודפשט. מזרחן מפורסם."},{"i":11136,"n":"גולדציהר, מאיר הירש מלאשנץ","b":"רב בלאשנץ-הונגריה-תרטו."},{"i":11137,"n":"גולדקורן, שמחה פישל מפרושביץ","b":"תשובה אליו - מהרש\"ם-תרסח. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":11138,"n":"גולדרט, ישכר דוב","f":"מרדכי גולדרט","k":"בעל מנחת יששכר","b":"רב בקיעלץ-תר\"מ"},{"i":11139,"n":"גולדרט, מרדכי","b":"ראב\"ד בקיעלץ-תר\"כ"},{"i":11140,"n":"גולדרט, שלמה מקיעלץ","b":"רב בקיעלץ-פולין. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":11141,"n":"גולדריך, יהושע אלכסנדר מאלטשטט","f":"שאול","k":"בעל ישועות ישראל","bt":"תקפה","b":"רב באלטשטט. חסיד קומורנא. חיבר \"ישועות ישראל\" פרמישלא תרמז."},{"i":11142,"n":"גולדשטוף, יוסף הלל מקראקא","b":"רב בית מדרש בקראקא-תרפח."},{"i":11143,"n":"גולדשטוף, שלמה זלמן","dt":"תרכו - ז טבת","b":"מחכמי קרקא"},{"i":11144,"n":"גולדשטוף, שלמה זלמן מקראקא","f":"ר\"ש","k":"בעל קורות העולם","bt":"תקן","dt":"תרכו","b":"חתן ה\"ברוך טעם\", מחכמי קראקא והיה מראשי הקהילה. חיבר \"קורות העולם\" וינה תריח, \"מגילת דמשק\" וינה תרכה, ועוד."},{"i":11145,"n":"גולדשטוף, שלמה זלמן מקראקא","f":"חיים יהודה","bt":"תרס","bp":"קראקא","dt":"תשם","b":"תלמיד ר יהודה מאיר לוין. חתן רד\"ב וינפלד מטשבין. ניצל מהשואה. עלה לארץ-תשב. עזר לחותנו בניהול ישיבת טשבין בירושלים."},{"i":11146,"n":"גולדשטוף, שלמה זלמן מקראקא","f":"יחזקאל פיבל"},{"i":11147,"n":"גולדשטט, יהושע השל","dt":"תרלב - כו ניסן","b":"דומ\"צ בוורשה"},{"i":11148,"n":"גולדשטין, אברהם יוסף","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":11149,"n":"גולדשטין, אהרן מפרשבורג","b":"מג\"מ בפרשבורג בחברה \"אגודת רעים\"-נוסדה תרסד."},{"i":11150,"n":"גולדשטין, בנימין","bt":"תשא","b":"רב בניישטט,פוניבאז"},{"i":11151,"n":"גולדשטין, גרשון מפרשבורג","b":"מג\"מ ומחברי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג."},{"i":11152,"n":"גולדשטין, דובער מחאלוי","bp":"בוברויסק","b":"נתייתם מאביו בצעירותו, והגביר ר חיים בועז רבינוביץ טיפל בו ושלחו ללמוד בוולוזין. רב בחאלוי-פלך מינסק-תרנח. נסמך מאת ר רפאל שפירא מוולוזין."},{"i":11153,"n":"גולדשטין, דוד מבודפשט","f":"שאול ממילדוי","b":"רב בבודפשט. חתנו - ר יצחק צבי פנט מבודפשט - דטרויט, ור בנימין זאב פישר מבודפשט."},{"i":11154,"n":"גולדשטין, דוד מפרשבורג","f":"בצלאל צורף מפרשבורג","k":"בעל קול אנחתי","b":"תלמיד החת\"ס. מחכמי פרשבורג, בודפשט. חיבר \"קול אנחתי\" - הספד על החת\"ס."},{"i":11155,"n":"גולדשטין, חיים","b":"תשובה אליו בשו\"מ."},{"i":11156,"n":"גולדשטין, חיים מטשעהרין","f":"נחמן מטשעהרין","bt":"תרכד","b":"רב בטשערין(=טשעהרין)-תרנד על מקום אביו."},{"i":11157,"n":"גולדשטין, חיים מפקיטילב","f":"שלמה","bt":"תרה","b":"רב בפאקיטילעב(=פאקיטיליוו)-פלך קיוב-תרכט. נסמך מאת: ר דוד שור מטולנא. בנו - ר פנחס אלימלך עוזר לצדו ברבנות."},{"i":11158,"n":"גולדשטין, יהודה מסאבינוב","f":"יהושע מסערדאוהל","bt":"תרלז","dt":"תרצג - טז ניסן","dp":"סאבינוב","b":"נכד ר יהודה אסאד. תלמיד הכת\"ס, ור ישעיה פירסט מוינה. חתן ר משה סופר מטיסא-פירעד. רב בקאדלבורג-תרס, סאבינוב(=קיש-סעבען)-תרסה ובנו ר יעקב שלום על מקומו אחריו. הו\"ל \"דברי מהרי\"א לתורה\" לזקנו ר יהודה אסאד."},{"i":11159,"n":"גולדשטין, יהודה שרגא","b":"חיבר מחזה באידיש על ישו הנוצרי על פי המסורת היהודית - הונגריה או טרנסילבניה סוף המאה ה-19."},{"i":11160,"n":"גולדשטין, יהושע מסערדאוהל","f":"עזרא צורף מסערדאוהל","b":"חתן ר אהרן שמואל אסאד מסערדאוהל. בניו - ר יהודה מאבינוב, ר עזרא מנחם מבאלטן-פירעד, וחתנו - ר יקותיאל דב מטעט."},{"i":11161,"n":"גולדשטין, יו\"ט מסערדאוהל","f":"יהושע מסערדאוהל","b":"חתן ר אהרן שמואל אסאד מסערדאוהל."},{"i":11162,"n":"גולדשטין, יעקב שלום מסאבינוב","f":"יהודה מסאבינוב","bt":"תרע","dt":"תש..","dp":"טרבלינקה","b":"תלמיד הדעת סופר. ור שמואל דוד אונגר מנייטרא. חתן ר אשר אנשל יהודה מילר מפעטרזשען. רב בסאבינוב(=קיש-סעבען)-תרצג. נספה בשואה. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":11163,"n":"גולדשטין, יעקב שלום מסעבען","dt":"תש","b":"תלמיד ר שמואל דוד אונגר בטירנוי. רב בסעבען. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא, \"משא ומתן\" - טירנוי תרצא."},{"i":11164,"n":"גולדשטין, יעקב שמשון","bt":"תרכא","dt":"תרפז - יח סיון","b":"רב בטורגאל-תרמ\"ה"},{"i":11165,"n":"גולדשטין, יצחק מברזנה","b":"רב בברזנה. פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":11166,"n":"גולדשטין, יצחק מנאהטשוב","b":"מחכמי נאהטשוב (גליל יברוב) - תשובה אליו \"בינת הלב\"-תרצז."},{"i":11167,"n":"גולדשטין, יקותיאל מזאגר ישן","b":"רב ודיין בזאגר ישן. עק\"ה."},{"i":11168,"n":"גולדשטין, ישכר דב בר מפרשבורג","b":"חתן ר שמעון צבי הרש מפרשבורג."},{"i":11169,"n":"גולדשטין, ישכר דב מירושלים","f":"מנחם אהרן מפרשבורג","k":"בעל אהל ישכר","r":"רב חוג חתם סופר, וראש ישיבת שומרי החומות","bt":"תרעה","dt":"תשמח - ח סיון","dp":"ירושלים","b":"תלמיד הדעת סופר ועוד. עלה לירושלים וכיהן כרב חוג חתם סופר בירושלים וראש ישיבות כולל שומרי החומות, חתנו ר נפתלי הירצקא פרנקל על מקומו אחריו בירושלים.","bk":[["אהל יששכר - שו\"ת",""],["ליקוטי הערות - שו\"ת חתם סופר",""],["ליקוטי הערות - שו\"ת חתם סופר, אהל יששכר - שו\"ת",""]]},{"i":11170,"n":"גולדשטין, ישכר דב מפרשבורג","b":"מלמד בביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה."},{"i":11171,"n":"גולדשטין, ישעיה מהעדילא","f":"עזרא צורף","b":"תלמיד הכת\"ס. חתן ר מאיר זאב וולף רוט מהעדילא מאדע, ועבר לשם-תרנא. (לפי אוצר הרבנים ישב בסרדאהעלי)."},{"i":11172,"n":"גולדשטין, ישראל מסמאטריטש","bt":"תרכה","b":"רב בסמאטריטש-פודוליה-תרס."},{"i":11173,"n":"גולדשטין, מנחם אהרן מפרשבורג","f":"משה שרגא מפרשבורג","b":"מחכמי פרשבורג. אביו של ר ישכר דב גולדשטין - רב בירושלים."},{"i":11174,"n":"גולדשטין, מנחם מנדל מנירדהאז","b":"רב ומגיד בשארוואר, עבר לנידרהאז."},{"i":11175,"n":"גולדשטין, משה ממונקטש","b":"יד ימינו של האדמור ר חיים אליעזר ממונקטש-תרץ, מנהל הישיבה והמוסדות."},{"i":11176,"n":"גולדשטין, משה מקאשוי","b":"מחכמי קאשוי. חתן ר אברהם יעקב ראזע מקאשוי. חתניו - ר יצחק קלנר מניר-באטור, ר נתן פרנקפורטר ור יצחק רוזנברג משאלגא-טאריאן."},{"i":11177,"n":"גולדשטין, משה מתל אביב","b":"תלמיד בישיבת פרשבורג בזמן מלחה\"ע ה-I. מיסד חברה \"דרכי אמונה\" לשילוב תורה ומלאכה בפרשבורג-תרפג, עלה לארץ וכיהן כגבאי בביהכ\"נ הגדול בתל אביב."},{"i":11178,"n":"גולדשטין, משה שרגא מפרשבורג","f":"ישכר דב מפרשבורג","bt":"תרמא","bp":"פרשבורג","dt":"תשד - ג חשון","dp":"בירקנאו","b":"תלמיד השב\"ס. חתן ר עקיבא יוסף לעהמן מפרשבורג, ובזיוו\"ש חתן ר יוסף טסלר (פערענץ) מטיסא-אוילאק. רב בפרשבורג-תרסז, בריסל, וחזר לפרשבורג וכיהן כרב חברת מחזיקי הדת. נספה בשואה."},{"i":11179,"n":"גולדשטין, נחמן מטשעהרין","f":"צבי אריה","k":"בעל לשון חסידים","bt":"תקפה","dt":"תרנד - יג אד\"ב","b":"נכד ר אהרן אב\"ד ברסלב. חתן ר יצחק מטשערוויץ-תלמיד ר נחמן מברסלב, ובזיוו\"ש חתן ר יואל לדיזינסקי מקרימנטשוק. חסיד ברסלב, תלמיד ר נתן מנמירוב. רב בטשעהרין ובנו ר חיים על מקומו אחריו. ביקר בארץ-תרכט. חיבר גם \"דרך חסידים\", \"פרפראות לחכמה\", \"ירח האיתנים\", ועוד. חתנו ר נפתלי הירץ בן ר שכנא בן ר נתן מנמירוב."},{"i":11180,"n":"גולדשטין, עזרא מנחם מבאלאטן","f":"יהושע מסערדאוהל","dt":"תשב - כא טבת","dp":"באלאטן-פירעד","b":"תלמיד הדעת סופר. רב בבאלטן-פירעד-תרעג."},{"i":11181,"n":"גולדשטין, פנחס אלימלך מפאקיטיל","f":"חיים מפאקיטיליוו","b":"רב בפאקיטיליוו-פלך קיוב לצד אביו."},{"i":11182,"n":"גולדשטין, צבי הרש מאויהל","f":"דוד מבודפשט","b":"חתנו - ר שמואל שמלקא שיק מגירבא פינצעהעל."},{"i":11183,"n":"גולדשטין, רפאל מניו יורק","k":"אדמור תולדות יצחק ני","b":"חתן ר מאיר בן ר דוד יצחק איזיק מסקוליא. רב ואדמור \"תולדות יצחק\"-סקוליא בניו יורק."},{"i":11184,"n":"גולדשטין, שלמה","b":"רב-שנת תר\"ל"},{"i":11185,"n":"גולדשטין, שמואל אהרן מניו זילנ","bt":"תריג","bp":"לונדון","b":"תלמיד ביהמ\"ד לרבנים בלונדון. רב בטואמבה-אוסטרליה, מייטלנד-אוסטרליה, אוקלנד-ניו זילנד-תרמ."},{"i":11186,"n":"גולדשטין, שמעון צבי מנינקירכן","f":"משה שרגא מפרשבורג","b":"אב\"ד ניינקירכן (אוסטריה)."},{"i":11187,"n":"גולדשטין, שמשון זליג מקעמעטשע","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":11188,"n":"גולדשטין-צורף, עזרא מסערדאוהל","f":"יוסף צורף","k":"בעל זכרון טוב","r":"ראב\"ד סערדלי","bt":"תקסב","bp":"סערדאוהל","dt":"תרם - ב חשון","dp":"סערדאוהל","b":"תלמיד החת\"ס, ור ברוך פרנקל-תאומים מלייפניק, ור צבי הרש הלר מאויבן. חתן ר משה פשקוב ממעדיער ועבר לשם-תקץ, רב בסערדאוהל.","bk":[["זכרון טוב - דרושים",""],["טופסי גיטין - כתובות וגיטין (כת\"י)",""],["טופסי גיטין - כתובות וגיטין (כת\"י), זכרון טוב - דרושים",""]]},{"i":11189,"n":"גולדשטין-רומרובסקי, ח","dt":"תשב","b":"ר\"מ בנוברדוק,רב בסוכוצין-תרצ\"ח"},{"i":11190,"n":"גולדשטיקר, אשר זליג הכהן מברלי","f":"יצחק מלייפניק","dt":"תקד - ה שבט","b":"חתן ר טוביה ממשפחת גולדשטיקר (על שעסקו ברקמת פרוכות) - ומכאן שמו. מתושבי העללא, פרנס בברלין ומראשי הקהילה-תפט, והיה מראשי התומכים בר משה בן אהרן מלבוב-רבה של ברלין - כנגד סיעת המתנגדים לו. סייע בהדפסת ספר קרובו ר יוסף בן בנימין זאב וולף אפשטין מקוניץ שהדפיס \"אגרת המוסר\" לר שלמה אלעמי, ו\"דת נשים\" לר משה ניגרין. בנו - ר אהרן כץ ונכדו ר דוד גולדשטיקר, חתנו - ר פיבש בן אלעזר חלפן מפפד\"א."},{"i":11191,"n":"גולדשטרן, נפתלי הרץ הכהן","f":"אשר זונדל","k":"בעל שבר פושעים","bt":"תקעא","bp":"למברג","dt":"תרמג","b":"השתתף במחלוקת צאנז וסדיגורא לטובת צאנז ופרסם חוברות בעילום שמו ובהם \"שבר פושעים\" למברג תרכט, ועוד. ?? לא באוצר ??"},{"i":11192,"n":"גולדשיידר, דניאל מוארשא","b":"תלמיד ישיבת \"בית שמואל\" בוארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":11193,"n":"גולדשלג, אברהם מסכטשין ומישניץ","f":"ברוך ירוחם","bt":"תרכח","b":"רב בסכטשין(=סאכאטשין)-פלך וארשא-תרמח, מישניץ(=מישעניץ)-פלך לומזה-תרנו."},{"i":11194,"n":"גולדשלג, אברהם מפיאנטקי","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":11195,"n":"גולדשלג, יהושע השל דוד מפשייטש","f":"יעקב חיים זליג מלובר","b":"נכד ר יחיאל מיכל משעפס בעל \"אמרי אמת\". חתן ר חיים לרמן האדמור מויסקוט וקרשנוביץ. רב בפשייטש-תרע, שרפץ, גיטו וארשא."},{"i":11196,"n":"גולדשלג, יחזקאל מוישיי","dt":"תש..","b":"רבה האחרון של וישיי-ליטא. נספה בשואה."},{"i":11197,"n":"גולדשלג, יחיאל מיכל משעפס","f":"אברהם","k":"בעל ספר המאורות","r":"תלמיד הרה\"ק מקאצק","bt":"תקצא","dt":"תרעח - כא שבט","b":"מצאצאי בעל הש\"ך. תלמיד ר ישראל יהושע מקוטנא בעל \"ישועות ישראל\", ר מנחם מנדל מקוצק, הרי\"מ מגור-ונסמך ממנו, ומאת: ר חיים דוידזון מוארשא. רב בקיקל(=קיקאל)-פלך פלאצ-תרח, (שרנצק(=שנרצקי), פודמביץ(=פודמניצא), אוסטרלנקא, שעפס-פלך פלאצק-תרכה. חיבר גם ביאור לתהלים \"ירושלים\", ועוד. בנו - ר יעקב חיים זליג מטשערוינסק. חיבר ספרים רבים. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב.","bk":[["אמרי אמת",""]]},{"i":11198,"n":"גולדשלג, יעקב","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":11199,"n":"גולדשלג, יעקב חיים זליג","f":"יחיאל מיכל משעפס","k":"בעל ירח למועדים","bt":"תריג","dt":"תרפו - כח אב","b":"מצאצאי הש\"ך, הט\"ז ור השל מקראקא. רב בטשרווינסק-תרלו, לוברנץ, מו\"צ בוארשא-תרן וראש קיבוץ לומדי תורה בשם \"בית המדרש לרבנים\" ובו עשרה אברכים. חיבר גם \"מרום הרים\", ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב. נסמך מאת: ר אליהו חיים מייזל מלודז, ר יחיאל מאיר האדמור מגוסטינין, ר\"ש זאנויל קלעפיש מוארשא. בנו - ר יהושע השל מפשייטש."},{"i":11200,"n":"גולדשמיד, אברהם","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":11201,"n":"גולדשמיד, אליעזר לזרוס","bt":"1871","bp":"פולנגיאן","dt":"1950","dp":"לונדון","b":"תלמיד ישיבת סלובודקה. למד באוניברסיטת ברלין ושטרסבורג. התגורר בגרמניה. חוקר ומתרגם התלמוד. תרגם את התלמוד לגרמנית-1930, תרגם את הקוראן לגרמנית. הו\"ל כתבי יד עתיקים מספריית המבורג, ניצל מהשואה ועבר ללונדון."},{"i":11202,"n":"גולדשמיד, אליעזר מסלובודקה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה. הו\"ל \"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":11203,"n":"גולדשמיד, בנימין וולף אברהם","f":"זוסמן סגל","dt":"תקצא - יד אייר","dp":"אלטונא","b":"בעל תוקע ובעל קורא מחכמי אלטונא."},{"i":11204,"n":"גולדשמיד, בנימין מאנגליה","f":"אהרן","bt":"תקיג","dt":"תקסח","dp":"לונדון","b":"הגיע עם אביו לאנגליה-תקכה. גביר עשיר, בעל אוצר ספרים גדול, מקורב לשלטון. הקים בית כנסת בביתו, יסד חברת עבור ר דוד לעווי להוצאת ספריו. אחיו אברהם סייע לצדו."},{"i":11205,"n":"גולדשמיד, הרמן מפפד\"מ","bt":"1802","bp":"פפד\"מ","dt":"1866","dp":"פונטגבלא-צרפת","b":"למד ציור במינכן, צייר בפאריס, אסטרונום וגילה כוכב בשם \"לוטעציא\", \"פאנאפא\". חיבר ספר מדע."},{"i":11206,"n":"גולדשמיד, יהודה","bt":"תרכז","dt":"תרצה","b":"רב במיסליץ-תרנ\"ב,פרוסניץ-תרנ\"ז"},{"i":11207,"n":"גולדשמיד, יהודה ליב מירושלים","bp":"אמשטרדם","b":"מחכמי ירושלים-תרטו, ראש כולל הו\"ד - יחד עם ר יהוסף שוורץ. בנו - ר משה יצחק מירושלים, חתנו - ר יעקב יוסף גולדשמיד."},{"i":11208,"n":"גולדשמיד, יוהנגע","f":"שוואב","k":"בעל רבקה ואמאליא","bt":"1806","b":"למדה אצל החכם ד\"ר אדוארד קלייא. אישה מלומדת בהמבורג ויסדה מוסדות חנוך. נשואה למוריץ גולדשמיד. חיברה \"מוטערפריידען אונד מוטער ליידען (שמחות האם וצרותיה) - בענין חנוך, פרסמה מאמרים. יסדה חברה \"אראבעל\" בהמבורג."},{"i":11209,"n":"גולדשמיד, יצחק משה מפפד\"מ","b":"ייצג את הקהילה במשפט כנגד יורשי אייזנמנגר-תקא (שפרסם ספר אנטישמי שהפצתו נאסרה)."},{"i":11210,"n":"גולדשמיד, ירחמיאל מוינהאראד","f":"ישראל דב מאליזבטגרד","b":"רב בווינאהאראד-תר\"ע"},{"i":11211,"n":"גולדשמיד, ישעיה מדוינסק ותל אב","bp":"דוינסק","b":"עלה לארץ וכיהן כדיין בתל אביב. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":11212,"n":"גולדשמיד, משה הלוי מאמשטרדם","f":"יונתן","b":"מראשי פקידים ואמרכלים באמשטרדם-תרלח, עם ר יהודה אריה לעהרן."},{"i":11213,"n":"גולדשמיד, משה יצחק מירושלים","f":"יהודה ליב מירושלים","b":"מחכמי ירושלים. מבוני שכונת \"בתי מחסה\" בירושלים."},{"i":11214,"n":"גולדשמיד, משה מקאמין-קאשריסק","f":"שמואל","bt":"תרלב","b":"תלמיד ר נח שחור מביאלא. חתן ר פנחס שיק מקוברין. מו\"צ בקוברין אצל חותנו, רב בקאמין-קאשירסק-ווהלין-תרנז."},{"i":11215,"n":"גולדשמיד, נתן מאמשטרדם","b":"שו\"ב באמשטרדם, כתב-תרמד פסקי דינים והוראות בעניני שחיטה באמשטרדם."},{"i":11216,"n":"גולדשמיד, פסח מאלטונא","f":"בנימין וולף","bt":"תקנט","bp":"אלטונא","dt":"תרלד - ט אייר","dp":"אלטונא","b":"תלמיד ר אברהם קראנאך. מחכמי הקלויז באלטונא על מקום ר מנחם מ ן, ובקלויז של ר אברהם זומביל."},{"i":11217,"n":"גולדשמיד, צבי מירושלים","f":"יעקב יוסף","b":"מורה בביה\"ס עזרה בירושלים, בעל בית מלון בירושלים."},{"i":11218,"n":"גולדשמיד, שמואל מנאסאווקא","f":"ישראל דב מאליזבטגרד","bt":"תרמא","b":"חתן ר דב זאב קוזווניקוב מיקטרינסלב, ומו\"צ לצד וממלא מקום חותנו ביקטרניסלב-תרסג, רב בנאסאווקה-פלך צרניגוב-תרסה. נסמך מאת: ר חיים ברלין, ר בנימין זקהיים מיקטרינסלב, ר צבי דב חן מצרניגוב, ר זאב מרחמיסטריבקא. אחיושל ר ירחמיאל מוינהאראד."},{"i":11219,"n":"גולדשמיד, שמשון מהמבורג","f":"יונתן משה","dt":"תקפג - טז כסלו","dp":"אלטונא","b":"חתן ר שמעון ניישטטל מפרג (ממשפחת ר זרח אידליץ ניישטטל מפרג). פרנס קהלת המבורג."},{"i":11220,"n":"גולדשנידר, יהודה מקראקא","f":"אברהם","bt":"תרט","b":"דיין בקראקא."},{"i":11221,"n":"גולוב, נחום מטולנא","f":"יוסף","bt":"תרכט","b":"רב ברמגרודוק-מחוז ברדיטשוב, טולנא-פלך קיוב."},{"i":11222,"n":"גולובנציץ, יצחק","b":"רב-שנת תר\"ל"},{"i":11223,"n":"גולובנציץ, שלמה חיים ממאהילנא","f":"יצחק","bt":"תרכט","dt":"תרצט","dp":"ירושלים","b":"ר\"מ במינסק-תרנד, מאהילנא(=מוהילוב?)-פלך מינסק-תרסה. עלה לירושלים-תרצב."},{"i":11224,"n":"גולומב, ד. מהול-אנגליה","b":"פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח."},{"i":11225,"n":"גולומב, יהודה מתתיהו מלודז","b":"פרסם מאמרים ב\"התפוח\" - בנדין תרפח."},{"i":11226,"n":"גולומב, צבי ניסן","f":"אליהו","k":"בעל למנצח בנגינות","bt":"1853","bp":"פודזאלוה-ליטא","dt":"1934","dp":"וילנא","b":"תלמידישיבת וילקומיר. מגיה בדפוס ראם בוילנא. פרסם מאמרים בכתב עת שונים, התפרנס בין היתר מחיבר כתובות למצבות. הראשון שאסף ניגונים עממיים ונוסחי תפילה ותיעדם. חיבר חוברת בתורת הנגינה ובהם גם \"זמרת יה\", \"קול יהודה\". חיבר \"קריות ספר\" ובו תיאור מ סעיו בערי ליטא ופולין, \"שמות אנשים ונשים\", ועוד."},{"i":11227,"n":"גולומבק, טוביה מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":11228,"n":"גולי, אברהם מירושלים","dt":"תקצו - כח חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":11229,"n":"גולינסקי, שלמה מקראקא","f":"משה מקראקא","k":"בעל זבח שלמה","dt":"תשן","b":"תלמיד ר יוסף שטינהרט. עלה לירושלים-תרפו בהסכמת רבו האדמור מצורטקוב. חתן ר אהרן קלירס מטבריה והתישב שם ועסק בתורה ולימודה. חיבר \"זבח שלמה\" טבריה-ירושלים תשכג."},{"i":11230,"n":"גולנפול, עקיבא","k":"בעל ספר פתגמים","bt":"1870","dt":"1938","b":"סופר ומחנך בגמנסיה האידית בוילקומיר. חבר בחברה ההיסטורית אתנוגרפית של יהודי ליטא. פרסם מאמרים בעניני פולקלור יהודי בעתוני התקופה. חיבר גם \"המדבר בלשון ערב\" והוא ספר לימוד ערבית - קידאן תרפח. ?? לא באוצר ??"},{"i":11231,"n":"גולנץ, חיים מלונדון","f":"מרדכי שמואל ברמן","k":"בעל ערך המלאכה","bt":"תריב","bp":"ברמן-גרמניה","b":"הגיע בילדותו עם אביו ללונדון. תלמיד ביהמ\"ד לרבנים בלונדון אצל ר ברוך אברהמס, הרב ד\"ר פרידלנדר, תלמיד ר נתן אדלר מלונדון שמינהו לדרשן בלונדון בגיל 19. רב במנצסטר, לונדון-תרמ על מקום ר נפתלי אדלר-שנתמנה לרב ראשי. חיבר ספרים ותרגם ספרים לאנגלית והו\"ל ספרי קדמונים."},{"i":11232,"n":"גולק אשר","bt":"1881","dt":"ה'תש 1940","bk":[["אוצר השטרות",""]]},{"i":11233,"n":"גולר, יצחק ממנצסטר וליברפול","bt":"1891","bp":"ליטא","dt":"1939","b":"הגיע למנצסטר-אנגליה. מנהל המכון לחנוך יהודי בלידס-אנגליה. רב ביהכ\"נ \"קובנא\" במנצסטר, רב קהילה בלונדון, ליברפול. חיבר ספרים באנגלית."},{"i":11234,"n":"גומבינר, אברהם אבלי מקאליש","f":"חיים מגומבין","k":"בעל מגן אברהם","r":"אב\"ד קאליש","bt":"שצז","bp":"גומבין","dt":"תמג - ט תשרי","b":"דיין בקאליש. חיבר \"מגן אברהם\" ונדפס ע\"י בנו - ר חיים. חתנו - ר משה יקותיאל קויפמן.","bk":[["זית רענן – ילקוט שמעוני",""],["שמן ששון - על התורה",""],["מגן אברהם – או\"ח",""]]},{"i":11235,"n":"גומבינר, יהודה הלוי","f":"חיים מגומבין","b":"רב בקראקא-ת\"ל"},{"i":11236,"n":"גומבינר, יעקב יצחק","b":"רב בליסא-ת\"מ"},{"i":11237,"n":"גומיו, משה מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',"},{"i":11238,"n":"גומיש סילווה, שלמה משלוניקי","dt":"תקל","dp":"שלוניקי","b":"בחור בשלוניקי. נהרג עק\"ה-תקל."},{"i":11239,"n":"גומפל מפפד\"מ","f":"ליבען","b":"מראשי קהלת פפד\"מ-תקנד, חתם על מכתב מטעם הקהלה יחד עם ר משה (מאיר) בן אנשיל רוטשילד."},{"i":11240,"n":"גומפל מפרשבורג","f":"זלמן","b":"מחכמי פרשבורג, חתם-תקכח על תקנות החברא קדישא."},{"i":11241,"n":"גומפל, מרדכי מלונדריש","k":"בעל תוכחת מגילה","b":"רב ורופא בלונדריש. תלמיד ר דוד פרנקל מברלין בעל \"קרבן העדה\". מרצה בבית מדרש ברופאים במלכות סוויציאה. חיבר \"תוכחת מגילה\" - כנגד פירוש מנדלסון - המבורג. ?? לא באוצר ??"},{"i":11242,"n":"גומפלין, פולד מפפד\"מ","b":"דיין מחכמי פפד\"מ-תע."},{"i":11243,"n":"גומפריך מפפד\"מ","f":"יצחק מזולקוא בן שמוא","b":"מחכמי פפד\"מ. חתנו - ר מרדכי מליסא."},{"i":11244,"n":"גומפרכט אשכנזי מאזמיר","b":"מדפיס באזמיר אצל ר דוד חזן-תצג."},{"i":11245,"n":"גומפרכט מדויטץ","dt":"קט","b":"נהרג עק\"ה בפרעות קט."},{"i":11246,"n":"גומפרץ-ניימגן, יהודה ליב","f":"בנדדיט מפרשבורג","k":"בעל מערכי לב","bt":"תקמב","bp":"פרשבורג","dt":"תריט - ד סיון","dp":"עיר חדש","b":"תלמיד החת\"ס. מצאצאי ר שמשון ורטהיימר, ונכד ר אליהו ניימעגען. חתן ר משה הכהן לוצקא מעיר חדש ועבר לשם, גביר בעיר חדש-תקסו. בנו ר שמשון הו\"ל את ספר אביו \"מערכי לב\"."},{"i":11247,"n":"גומץ פאטו, חיים יהודה מחברון","dt":"תקמד","b":"מחכמי חברון-תקיח, קרובו של החידא, גידל בביתו את ר יצחק זאבי לאחר שנתייתם, תלמידו הוא ר חיים יצחק קאריגל. בשנת תקד חתם על כתב שליחות ר אברהם גדיליה, בשנת תקיג חתם על כתב שליחות החיד\"א. בשנת תקיח חתם על הסכמה ל\"אורים גדולים\" לר אברהם זאבי, בשנת תקכג על כתב שליחות ר רחמים בגאיו ור יצחק מלמד, בשנת תקלד על כתב שליחות ר משה סקלי הכהן. בשנת תקמב על כתב שליחות ר ישראל זאבי."},{"i":11248,"n":"גומץ פאטו, שמעון (שמשון)","bp":"מצרים או ספרד","dt":"תעד - אייר","dp":"מקרינורי-ליד ארטא","b":"מחכמי ירושלים, דיין אצל ר אברהם יצחקי - תע, וחתמו יחד על החרם נגד נחמיה חיון. בשנת תס חתם על תעודה בענין החלוקה. בשנת תסד הסכים על \"עין יהוסף\", עבר למצרים ומשם יצא בשליחות בתורכיה ונהרג ביון על ידי שודדים."},{"i":11249,"n":"גומץ, יצחק מאמשטרדם","b":"ממשפחת אנוסים שברחו להולנד, קרובו של ר שמשון גומץ-פאטו."},{"i":11250,"n":"גונא, זרח מפאס","f":"משה","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":11251,"n":"גונדרסהיים, חיים מפפד\"מ","f":"יוסף","dt":"תקנה - י סיון","dp":"פפד\"מ","b":"ר\"מ בפפד\"מ."},{"i":11252,"n":"גונדרסהיים, יוסף מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקן, השתתף במשלחת אל הקיסר ליאופולד, עם חבריו ר יצחק שפייר, ור שלמה האז. השתתפו גם במשלחת אל הקיסר פרנץ השני-תקנב. התנגד להקמת בית ספר בגרמנית-תקנד ואף שכנע את ר פנחס הורביץ להחרים את המוסד ולבסוף חזר בו."},{"i":11253,"n":"גונדרסהיים, שניאור זיסקינד חיי","k":"בעל מקור חיים","dt":"תקסג - יד תשרי","dp":"פפד\"מ","b":"תלמיד ר יעקב פופרש מפפד\"מ. מראשי קהילת פפד\"מ-תקך, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\". רב בקובלנץ ומדינת טריר, מיינץ, דיין בפפד\"מ."},{"i":11254,"n":"גונזינו, אליהו חיים מאיטליה","f":"בנימין","k":"בעל אגרת חמודות","b":"תלמיד ר בנימין מהר אלצוני. רופא מחכמי איטליה-ש'. חיבר ספרים שחלקם אבדו ובהם \"אגרת חמודות\" - שחיבר לבקשת ר דוד בן בנימין מהר אנצולינו(=אלצוני) ובו משיג על האברבנל ועל פירוש לספר יצירה המיוחס לראב\"ד (ובאמת הוא מר יוסף הארוך בן שלום), והרדב\"ז משיב עליו ב\"מגן דוד\", חיבר מאמר בענין \"אצילי בני ישראל\" לבקשת ר יעקב דילי קורלנדי שפגשו בעיר מעסינא. חיבר קונטרס להכריע במחלוקת בין ר אביגדור מפאנו שחיבר קונטרס \"אהבת נשים\", לבין ר אברהם מסברטני שחיבר קונטרס \"שנאת נשים\". חיבר קונטרס ויכוח על הויכוח שהיה בינו לבין הכומר פרנציסקו דאקווא סינטציטו - שהיה בעיר אורביטא (ושם כונה אליהו מאגיסטראטוס). ר יהודה אריה מודנא ב\"ארי נוהם\" משיג עליו בחריפות."},{"i":11255,"n":"גונצהויזר, יעקב מבון","b":"חתנו - יצחק נייבורג ממנהיים נתן גט לבתו (אשתו של יצחק), והגט כונה כגט מקליווא - דבר שעורר מחלוקת בין רבני התקופה."},{"i":11256,"n":"גונציהויזן, אהרן מהמבורג","f":"יצחק מהמבורג","b":"דיין בהמבורג. מחברי הקלויז-תק."},{"i":11257,"n":"גונציהויזן, יצחק מהמבורג","dt":"תקכט","b":"אחד מחמשת חברי הקלויז החדש שיסד ר יונתן איבשיץ בזמן המחלוקת עם ר יעקב עמדין. בנו ר אהרן."},{"i":11258,"n":"גונצר, אלתר משה","bt":"1879","bp":"וילקומיר","dt":"1940","dp":"תל אביב","b":"תלמיד ישובות ליטא, עבר לברלין והיה מזכירו של ראובן בריינין, ופתח בימ\"ס והוצאת ספרים. פרסם מאמרים בעתוני הזמן. עורך \"הקשת\", עלה לארץ."},{"i":11259,"n":"גוסטמן, יוסף אהרן מלשקוביץ","b":"רב בלשקוביץ-תרנח."},{"i":11260,"n":"גוסטמן, יעקב מזסטובנה","f":"מאיר מנובוסליץ","bt":"תרן","dt":"תשג","b":"רב בזסטובנה-בוקובינה. נספה בשואה. תשובה אליו \"צור יעקב\"-תרפט."},{"i":11261,"n":"גוסטנסקי, ישכר דוב","dt":"תשג","b":"רב ברישטיץ"},{"i":11262,"n":"גוץ, רפאל שלמה","bp":"שאוולי","dt":"1920","dp":"יאלטה","b":"גביר תלמיד חכם ונדבן. חתן קלונימוס ויסוצקי. תמך במוסדות תורה רבים ובהם הקבוץ בפוניבז, ישיבות אודיסה, לידא, שאוולי, שוואניציאן. בזמן מלחמה\"ע ה-I עמד בראש ועד העזרה לרבנים הפליטים. ממיסדי הגימנסיה העברית במוסקבה. חובב ציון וביקר בארץ. תרם להקמת סמינר \"המזרחי\" בירושלים. הניח עזבון גדול לקק\"ל."},{"i":11263,"n":"גוקליר, יום טוב מירושלים","b":"מחכמי קושטא, עלה לירושלים עם ר עזריא וילייסיד."},{"i":11264,"n":"ג'וקריל, בן ציון מאזמיר","f":"שלמה","b":"מחכמי אזמיר-תרו, חתן ר' חיים פאלאג'י, ממונה על השוחטים באזמיר."},{"i":11265,"n":"גו'קריל, חנניה מקושטא","f":"שלמה","b":"רב בקושטא-שנות ה-ש'."},{"i":11266,"n":"ג'וקריל, יום טוב מירושלים","b":"מחכמי קושטא, עלה לירושלים-שפ - בערך."},{"i":11267,"n":"גו'קריל, שלמה מאזמיר","b":"רב באזמיר, מחותנו של ר חיים פלאג'י - בנו ר בן ציון חתן ר חיים. נזכר בספרי ר חיים פלאג'י."},{"i":11268,"n":"ג'וקריל, שלמה משלוניקי","b":"דיין בשלוניקי-שצח."},{"i":11269,"n":"גור אריה הלוי ממנטובה-גא\"ל","k":"בעל גור אריה","dt":"תקיד - א טבת","b":"רב במנטובה-תמ בזמן הרמ\"ז, ומזכיר הרבה את מנהג פיררה. חיבר \"הגהות על השו\"ע - מנטובה. מתורתו בספרי חכמי דורו."},{"i":11270,"n":"גור אריה, אברהם אליהו","f":"שמואל מחוראן","b":"תלמיד ישיבת לובאויטש."},{"i":11271,"n":"גור אריה, אריה ליב מחרול","f":"דוד","bt":"תקעח","dt":"תרסט - ט תשרי","dp":"ירושלים","b":"נכד ר נתן בילאייעווקער מויטקא. רב בחארול, עלה לירושלים. בנו - ר שמואל מחארול. אחיו - ר שמריהו."},{"i":11272,"n":"גור אריה, דוד מחארול","f":"שמואל מחוראן","b":"חתן ר אלחנן חן מפירייטין. רב בחרול. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":11273,"n":"גור אריה, יהודה","k":"בעל בן פורת","b":"חיבר \"בן פורת\" ובו גם פירוש על הל' יסודי התורה לרמבם (ברשימת ספרי ר חיים בן יוסף מיכל)."},{"i":11274,"n":"גור אריה, משה יהושע","f":"שמואל מחוראן","b":"תלמיד ישיבת לובאויטש. חתן ר משה יודל בינשטין מקאבליאק."},{"i":11275,"n":"גור אריה, שמואל מחארול","f":"אריה ליב מחרול","b":"מחשובי חסידי חב\"ד. רב בחארול-פלך פולטובה-תרע על מקום אביו. בניו: ר דוד על מקומו אחריו, ר משה יהושע, ר אברהם אליהו, ר שניאור זלמן ישראל יעקב."},{"i":11276,"n":"גור אריה, שמריה מניו יורק","b":"חתן האדמור ר יוסף יצחק מלובאביטש."},{"i":11277,"n":"גור אריה, שמריהו","f":"אריה ליב","b":"אחיו אריה ליב ואביו של הגביר ר שניאור זלמן."},{"i":11278,"n":"גור אריה, שניאור זלמן","f":"שמריה","b":"גביר תלמיד חכם. בניו הגבירים: ר שמואל, ר נתן, ר מנחם מנדל."},{"i":11279,"n":"גור אריה, שניאור זלמן ישראל יע","f":"שמואל מחוראן"},{"i":11280,"n":"גור אריה, שניאור זלמן מנ\"י","b":"פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":11281,"n":"גור הקראי מקושטא","b":"ראש עדת הקראים בקושטא-שנות ה-ת', היה שואל את ר יהושע בן ישראל בנבנישתי."},{"i":11282,"n":"גור יהודה","bt":"1862","dt":"ה'תשי 1950","bk":[["בית הספר לבני ישראל",""]]},{"i":11283,"n":"גורא, גרשון","b":"פרסם מאמרים ב\"יבנה\" - לבוב תרפט."},{"i":11284,"n":"גורבינסקי, ידידיה מוידוקלה","b":"רב בוידוקלה, עלה לא\"י-תרפד."},{"i":11285,"n":"גורביץ, אריה זאב מלונדון","b":"ראש ישיבת גייטסהד-אנגליה. הו\"ל כתב עת \"אור תורה\" - לונדון תרצד. פרסם מאמרים ב\"החיים\" - לונדון תש, \"המסילה\" - לונדון תשז."},{"i":11286,"n":"גורביץ, חיים מגדרוביץ","b":"רב בגדרוביץ-ליטא."},{"i":11287,"n":"גורביץ, יוסף ליפמן מאוסטרליה","b":"רב במלבורן-אוסטרליה-תשיג."},{"i":11288,"n":"גורביץ, יצחק","b":"גביר מופלג. חתנו - ר זלמן אנצילביץ ממאזיר."},{"i":11289,"n":"גורביץ, משה מארה\"ב","f":"יהושע השל","bt":"תרסא","bp":"פלשצניץ-ליד בוריסוב","b":"תלמיד ישיבות סלובודקה, מרכז הרב בירושלים. נסמך מאת הרב קוק, ר אבא יעקב בורוכוב, ר יעקב משה חרלפ. רב קהלת \"עין יעקב\" בניו יורק. חברת אגודת הרבנים באמריקה. מעורכי \"אורות הקודש\" לרב קוק."},{"i":11290,"n":"גורדון, אברהם יעקב מבריסק","b":"חתן ר חיים בער גרינגרוס מקרמנצוג. משגיח בישיבת תורת חיים בבריסק-תרפה אצל ר משה סוקולובסקי."},{"i":11291,"n":"גורדון, אברהם ליב מקובנה ונ\"י","f":"צבי","k":"בעל אהל אברהם","b":"רב בקובנא, ניו יורק. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג. מתלמידיו - ר שלום אלחנן הלוי יפה."},{"i":11292,"n":"גורדון, אברהם מוילנא","f":"יחיאל מיכל דוקטור","dt":"תקמא","dp":"וילנא","b":"נכד ר אהרן דאקטאר גורדון. גביר ופרנס בוילנא. אחיהם של ר אהרן דוקטור, ר דב בר. בנו - ר ישראל קריינעס. פעל לטובת בית העלמין בוילנא-תקמב (עם חבריו: ר יהודה בן ליפמן, ר ליב בן ליזר, ר אריה ליב מייטעס מפינסק)."},{"i":11293,"n":"גורדון, אברהם שמואל"},{"i":11294,"n":"גורדון, אהרן דוד","f":"יחיאל מיכל","k":"בעל אפיק נחלים","bp":"וילנא","dt":"תריד - א שבט","b":"סופר בתחילת המאה ה-19. חיבר \"עיט צבוע\", \"אפיק נחלים\" או \"לץ היין\" וילנא תקצו - ובה ביקורת על מנהגי הקבורה בישראל. בנו המשורר-המליץ ר מיכל גורדון."},{"i":11295,"n":"גורדון, אהרן מוישנובה ונ\"י","f":"מאיר","k":"בעל אבן מאיר","bp":"ליד וילנא","b":"תלמיד ר נחמן ראובן מדאקשין, ר יוסף שיווענט מוילנא. רב בווישנאווע(=וישנובה), היגר לארה\"ב וכיהן כרב ברוצ'סטר-תרנג, ניו יורק-תרסב. נסמך מאת: ר שלמה הכהן מוילנא. פרסם מאמרים ב\"המאסף\" - ירושלים תרנו. ?? לא באוצר ??"},{"i":11296,"n":"גורדון, אורי משה מלודז","b":"ר\"מ תורת חסד בלודז-תר\"ע. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":11297,"n":"גורדון, אליהו זאב מקמאי","k":"בעל דברי אליהו","bt":"תרכה","bp":"ליטא","dt":"תרצב","b":"דרשן, רב בצייקישוק-תרלד, דוגלישקי-תרנב, וידז, קאמאי-תרנט, וילנא-תרנז, ניו-יורק-תרפג. חיבר גם \"דמעת העשוקים\", ועוד. בנו הסופר ד\"ר הירש ליב גורדון."},{"i":11298,"n":"גורדון, אליעזר הגדול","f":"אברהם שמואל גורדון","k":"בעל תשובת רבי אליעזר","bt":"תרא","bp":"סוויר-פלך וילנא","dt":"תרעד","dp":"לונדון","b":"תלמיד ר ישראל סלנטר בקובנה, רב בסלובודקה. קלם-תרלד על מקום ר אליקים גציל הורביץ - ולצדו ר יצחק הורביץ חתנו של ר אליקים גצל (בהסכם פשרה של ר ישראל סלנטר), טלז-תרמד וייסד את ישיבת טלז ועמד בראשה (לאחר סגירת הישיבה בפיקלן). לאחר השרפה-תרע נסע ללונדון כדי לשקם את הישיבה ונפטר בשליחותו. ממיסדי \"כנסת ישראל\" שממנה התפתחה \"אגו\"י\". חיבר תשובות ר אליעזר. מאמר ממנו ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":11299,"n":"גורדון, אריה - ג'רונים","k":"בעל אורח מישור","bt":"1826","bp":"מאליטא-ליטא","b":"תרגם לעברית את \"מפעלות היהודים\" למ. שליידן - וילנא תרמב - אודות תפקיד היהודים בתחיית המדע בימי הביניים, \"הנסתרות והנגלות\", ועוד."},{"i":11300,"n":"גורדון, אריה ליב מירושלים","f":"שלמה","k":"בעל מסלול ודרך לדקדו","bt":"תרה","bp":"קלם או ראסיין","dt":"תרעג","dp":"פתח תקוה","b":"למד בישיבת וולוזין, בשנת תרנא עלה לארץ. הדפיס ספר \"דקדוק אליהו\" לגר\"א עם הוספות משלו וילנא תרלד, חיבר \"מסלול ודרך לדקדוק שפת עבר\" וילנא תרנט. הו\"ל \"משפטי הלשון העברית\" לפי שיטת הגר\"א - וילנא תרלד. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":11301,"n":"גורדון, דובער מזיטקוביץ","f":"אליהו","bt":"תרל","b":"נכד-אבי אביו ר זלמן גרינהויז ממוסקבה, ונכד-אבי אמו ר זונדל הוטנר בעל \"ביכורי יוסף\". תלמיד ישיבות ראדין, וולוזין, איישישוק. רב בזיטקוביץ-פלך מינסק-תרנח. נסמך מאת: ר משה מסלובודקא."},{"i":11302,"n":"גורדון, דוד (דב בר)","f":"דב בער","k":"בעל מבחר מאמרים","bt":"תקפו","bp":"פודמאראטש-פלך וילנא","dt":"תרמו - טו אייר","dp":"ליק","b":"תלמיד ישיבות ליטא, הצטרף לזרם ההשכלה בהשפעת מרדכי אהרן גינצבורג, היגר לליברפול-אנגליה והיה שם מורה, עורך \"המגיד\" - ליק. פרסם מאמרים ובהם תיאר את רדיפות היהודים ברוסיה. תרגם לעברית \"מסעי ישראל\", \"מלחמת החושך והאור\" - ליק תרכא, ועוד. הצטרף לחובבי ציון וביקר אצל מוניפיורי ורוטשילד. ציר בועידת קאטוביץ. מבחר מאמריו נדפסו בתל אביב תשב."},{"i":11303,"n":"גורדון, הירש ליב","f":"אליהו","k":"בעל דאס צווי שארפיקע","bt":"1896","bp":"דויגלישקי-פלך וילנא","b":"תלמיד ישיבות סלובודקה, לידא, וולוזין. למד באוניברסיה בניו יורק ורמא. מורה לתלמוד בקולגיו רביניקו-פירנצה איטליה, ובקולג' למורים בניו יורק. למד רפואה ברומא. בזמן מלחה\"ע ה-I שירת בלגיון היהודי בארץ ישראל. תרגם ספרים לאידיש. חיבר סיפורים ושירים ופרסם מאמרים בעותנים שונים."},{"i":11304,"n":"גורדון, יהודה ליב","f":"אשר קראנער","k":"יל\"ג -בעל אגרות יל\"ג","bt":"1830","bp":"וילנא","dt":"1892","dp":"פטרבורג","b":"תלמיד ר ליפא-תלמידו של ר חיים מוולוזין. משורר עברי מראשי תנועת ההשכלה. מורה בבתי ספר ממשלתיים בפוניבז, שאוולי, וטלז. מזכיר הקהילה בפטרבורג ומנהל חברת מפיצי השכלה. היה במחלוקת עם האורתודוכסים. בגלל הלשנה נאסר בחשד פעילות מהפכנית-1879 ושוחרר. מורה לבני הברון גינצבורג בפטרבורג. התאכזב מרעיונות ההשכלה לאחר פרעות-1880. חיבר גם \"שיחת חולין\", ועוד."},{"i":11305,"n":"גורדון, יהודה ליב מלומזה","f":"מאיר אברהם אבא","k":"בעל דברי יהודה","bt":"תריג","bp":"רעזיצא-פלך ויטבסק","dt":"תרפה - טז ניסן","dp":"שיקגו","b":"תלמיד ר ירחמיאל זיסקינד מרעזיצא, ר משה דנישבסקי מסלובודקה. רב במיכאילשאק-פלך וילנא-תרמג, אגוסטוב-פלך סובלאק-תרמו, אוסטרוב-תרנה, סמרגון-תרסב, לומזה-תרעג. הגיע לאמריקה כדי לגייס עזרה לישיבת לומזה וכיהן כרב בשיקגו-תרפא כ-5 שנים, היה חבר באגודת הרבנים, ומחשובי הרבנים באמריקה. חיבר גם \"תשובת יהודה\", דגלי יהודה\", חיבר בשפה הרוסית \"החסידות מה היא\" - כנגד המומר פפרקורן וחבריו שהלשינו על החסידות ושר החינוך שוורץ פקד לסגור את כל מוסדות החסידים ובזכות דבריו בוטלה הגזירה, ו\"התלמוד מה הוא\" כנגד אנטישמי פולני בשם גרודשצקו שפרסם ספר \"מסתרי התלמוד\" - לבקשת השלטון הרוסי, וגדול הסופרים ברוסיה - טולסטוי - התפעל מספריו וכתב לו שהאיר עיניו בנוגע לתלמוד ולחסידות ועמד עמו בקשרי מכתבים. ?? לא באוצר ??"},{"i":11306,"n":"גורדון, יהושע מדוביניק","dt":"תשג","b":"רב בדוביניק"},{"i":11307,"n":"גורדון, יחיאל מיכל מוילנא","f":"אהרן דוקטור","dt":"תקטז - אחרי","b":"מחכמי וילנא ופרנס. נזכר בפנקס המדינה בהתועדות בקהילת אמדור-תף, חתם בפנקס היסו\"ד כפרנס וילנא על מכירת מקום קבורה ליסו\"ד ואשתו-תקי. בניו: ר אברהם פרנס בוילנא, ר אהרן מוילנא, ר דב בער-אביו של ר משה אהרן אב\"ד ואשלישוק. חתנו ר זאב וולף מראסיין."},{"i":11308,"n":"גורדון, יחיאל מרדכי מארה\"ב","f":"משה אהרן","k":"בעל נתיב ים","r":"ראש ישיבת לומז'א","bt":"תרמג","bp":"ליד טרוקי(=טראק)","dt":"תשכה - יג טבת","dp":"פתח תקוה","b":"תלמיד ישיבת ר צבי לויטן בסלובודקה, ישיבת סלובודקה (אצל ר נתן צבי פינקל) וכונה ר מאטעל טראקער ולאחר הפילוג עבר עם רבו לישיבת \"כנסת ישראל\". חתן ר אליעזר שולביץ מלומזה ור\"מ בישיבתו-תרסז על מקום ר טבל דינובסקי (שעבר למאלטש). עבר לארה\"ב. העביר חלק מהישיבה לארץ-[תרפ..], מגדולי מרביצי התורה בדורו. עלה לארץ-תשטו וכיהן כראש ישיבת לומזה בפתח תקוה. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב. גיסו - ר יהושע זליג רוך. בניו - ר חיים שמחה מארה\"ב, שניאור זלמן - נהרג עק\"ה בפרעות תרצט בירושלים. חתנו - ר נח קשטקובסקי - נספה בשואה עם משפחתו.","bk":[["נתיב ים (ר\"י לומז'א)",""],["נתיב ים",""],["נתיבי ים",""]]},{"i":11309,"n":"גורדון, יעקב דוד מארה\"ב","f":"יהודה (משה?)","k":"בעל דור דור ודורשיו","bt":"תרלג","bp":"וואקשנה-פלך קובנא","b":"נתייתם בילדותו וגדל אצל דודו ר יוסף גורדון בלייזובה(=לייזאווא)-פלך קובנא. תלמיד ר יוסף רזניק מפאפעלאן, ישיבות טלז, איישישוק, שאוולי, וקרוזק, ואצל ר משה דנישבסקי בסלובודקה. חתן ר יוסף ליב אפשטין מקראז-פלך קובנא. היגר לארה\"ב-תרסה, וכיהן כרב בשיקאגו-תרסה, נורפולק-תרסז. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי, ר צבי הירש ואלק מפינסק, ר צבי הירש מה יפית מולקוביסק. חיבר \"הד הזמן\", \"דור דור ודורשיו\" נ\"י תשו. פרסם מאמרים ב\"היהודי\" - נ\"י תרצו."},{"i":11310,"n":"גורדון, יעקב מאנגליה","b":"רב בבורנמות-אנגליה. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"בית ועד לחכמים\" - סטמר תרפב."},{"i":11311,"n":"גורדון, יעקב מביאליסטוק","k":"בעל בת הרב","bt":"תריד","bp":"וילקומיר","b":"עבר לברלין, תלמיד ביהמ\"ד לרבנים בפריס, מורה בביאליסטוק. חיבר גם \"דער רייזענדער אין פריס\", \"ברום שמים\", ועוד."},{"i":11312,"n":"גורדון, יעקב מוילנא","f":"אברהם","bp":"ליטא","b":"מחכמי וילנא. חיבר לוח על אלף שנה - וילנא תריד, והיה המקור ללוחות רבים שלקחו ממנו."},{"i":11313,"n":"גורדון, יעקב מטורונטו","f":"אריה ליב","k":"בעל מנחת יעקב","bt":"תרלז","dt":"תרצד-ה -יח כסלו","b":"תלמיד ישיבות וולוזין, מינסק, קובנא. היגר לקנדה-תרסד וכיהן כרב קהלת \"גואל צדק\" בטורונטו, יסד בית ספר בשיטת לימוד עברית בעברית. מראשי המזרחי. פנה לממשלת קנדה להנהיג שבוע עבודה בן חמשה ימים-תרצט (כדי למנוע חלול שבת מיהודים). חיבר מאמרים לאנציקלופדיה \"אוצר ישראל\"."},{"i":11314,"n":"גורדון, יעקב משטפורד","b":"רב בשטפורד. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":11315,"n":"גורדון, יקותיאל מוילנא","f":"שלמה זלמן","dt":"תקעג - ט חשון","dp":"וילנא","b":"נפטר צעיר."},{"i":11316,"n":"גורדון, ישראל קריינעס מוילנא","f":"אברהם בן יחיאל מיכל","bt":"תקלח","bp":"וילנא","dt":"תרטז - יג טבת","dp":"וילנא","b":"נינו של ר אהרן דוקטור גורדון. נקרא גם קריינעס ע\"ש אמו-קריינע-בת ר שמעון ברודא. לאחר שנתייתם נישאה אמו לר ישראל מיורבורג וגדל אצלו. חתן ר אברהם דוד שטרשון מוילנא. גביר ופרנס בוילנא, רב בוילנא (מטעם) לפני השלטונות-תקצז על מקום ר אבלי פאסוועלער, בנו ר אברהם נפטר בחיי אביו. חתניו ר בנציון אברהם לונץ משאוול, הגביר ר איזיק סענדרס אביו של ר אברהם שמעון טרויב מקיידאן. נכדו ר אברהם שמעון טרויב מקידאן עזר לו ברבנות. שלח מכתב לצאר ניקולאי ובו מתלונן על ביהמ\"ד לרבנים בוילנא (ב\"הכרם\" לר אלעזר אטלס וארשא תרמח). מבניו: ר אברהם ונכדו הגביר ר מרדכי-חתן ר יהודה ליב קליבנסקי מקובנא. חתנו - ר יצחק איזיק טרויב מקידאן ונכדו - ר אברהם שמעון מקידאן."},{"i":11317,"n":"גורדון, מיכל","k":"בעל שירי מ גארדען","bt":"1823","bp":"וילנא","dt":"1890","b":"משורר וסופר ופעיל בתנועת ההשכלה. גיסו של יל\"ג. כתב בעברית ובאידיש. הטיף להתבוללות בתרבות הגויים, ויצא נגד מנהגי ישראל ובעיקר נגד החסידים.","bk":[["תפארת בנים",""]]},{"i":11318,"n":"גורדון, מנחם שלמה ממינסק","f":"אליהו","k":"בעל מנחם שלמה","dt":"תרלא - יא טבת","dp":"מינסק","b":"רב במינסק."},{"i":11319,"n":"גורדון, משה","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":11320,"n":"גורדון, משה אהרן מארה\"ב","dt":"תרפט - יח אב","dp":"בוסטון","b":"שו\"ב ומלמד תורה בכפר ליד טרוקי(=טראק), היגר לארה\"ב ולימד תורה בבוסטון. בנו - ר יחיאל מרדכי בעל \"נתיב ים\"."},{"i":11321,"n":"גורדון, משה אהרן מואשלישוק","f":"דב בער","b":"מצאצאי ר אהרן דוקטור מוילנא - רופא מלך פולין וראש משפחת גורדון בוילנא. חתן ר אברהם יצחק הלוי מקרלין בן ר אליעזר בעל \"שיח השדה\"-מצאצאי המהרש\"א. הסכים על \"פתח השער\" לר מרדכי בן יהודה מראדין-תקם, ועוד. בניו: ר יהודה ליב מוילנא, ר אשר מוילנא. חתנו ר בנימין שיק בן ר אריה יהודה ליב מואשלישוק ונכדו ר אליהו שיק."},{"i":11322,"n":"גורדון, עזריאל מסקופישוק","b":"רב בסקופישוק-ליטא."},{"i":11323,"n":"גורדון, פנחס משה מביאליסטוק","f":"אברהם אליהו מטלז","k":"בעל תפארת אברהם","b":"ר\"מ בביאליסטוק. חיבר גם \"תפארת אליהו\"."},{"i":11324,"n":"גורדון, ראובן הכהן","b":"רב בפראפויסק-תר\"ל"},{"i":11325,"n":"גורדון, רפאל מביאליסטוק","f":"שמשון","k":"בעל נחל עדן","bt":"תרח","bp":"מאליאט-ליטא","dt":"תרצא","dp":"ביאליסטוק","b":"בילדותו כונה העילוי ממאליאט. בגיל 16 פגש את ר בצלאל הכהן מוילנא שאמר עליו כי \"לא ראה צעיר בגילו בקי ובעל זכרון כמוהו\". נשא אישה מאמדור ועבר לשם, היה בקי גם בחשבון ומדעים ותכונה. רב בוואשליקובה, ביאליסטוק. היה מהראשנים שגילו את הזיוף בירושלמי על סדר קדשים."},{"i":11326,"n":"גורדון, שלמה זלמן","bt":"תקס","dt":"תרלב-ח","b":"מו\"צ ודרשן במאריאמפול."},{"i":11327,"n":"גורדון, שלמה זלמן מוילנא","f":"אהרן","dt":"תקסח","dp":"וילנא","b":"מחכמי וילנא."},{"i":11328,"n":"גורדון, שלמה מדרוסקניק","f":"יעקב","k":"בעל בנין שלמה","bt":"תרי","dt":"תרצה - כט סיון","b":"ממשפחת ר אברהם אופנהים בעל \"אשל אברהם\". רב ביעלינוב-תרלב, לודנבר(=לודענעווא)-פלך סובאלק, דרוסקניק(=דרוסקעניק)-פלך גרודנא. חיבר גם \"חשק שלמה\", \"זכרון יעקב\"."},{"i":11329,"n":"גורדון, שמואל ליב","k":"בעל כנור ישורון","bt":"1867","bp":"לידא - פלך וילנא","dt":"1933","dp":"תל אביב","b":"מנחך וסופר. תלמיד ישיבות ליטא. תרגום לעברית ספרים שונים. עלה לארץ-תרנח, חזר לוארשא וערך עתון לילדים \"עתון קטן\" בהוצאת גיסו א' בן אביגדור. חזר לארץ-1924 ועסק בכתיבת פירוש לתנ\"ך."},{"i":11330,"n":"גורדין (גורדון), אבא","f":"יהודה ליב מלומז'ה","k":"בעל התלמוד מהו","bt":"1887","bp":"מיכאילישוק","dt":"1964","dp":"תל אביב","b":"אביו היה רב בסמרגון ובלומז'ה. אחיו של זאב ונודעו ביחד כ\"האחים גורדין\" והצטיינו כעילויים. התצרפו לציונות והנהיגו דיבור עברי בביתם, נפגשו במוסקבה ב-1917 וכל אחד מהם פתח שם מועדון לדעותיו שהיו בעלי השפעה גם בשורות הצבא - וכך מי שהתנגד למעשי אלימות ברוסיה נקרא בשם גורדונובצי, נאסרו והצליחו לברוח. אבא היגר לניו יורק וחיבר ספרים ומאמרים. עלה לארץ-1958 והתישב ברמת גן."},{"i":11331,"n":"גורדין, אברהם מצייקישוק","b":"רב בצייקישוק-תרסג"},{"i":11332,"n":"גורדין, ישראל שלמה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":11333,"n":"גורדין, משה","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח, \"תלפיות\" - שנחאי תשו."},{"i":11334,"n":"גורדינסקי, חיים ישכר מניו יורק","f":"יעקב מאיר גורדנסקי","k":"בעל דברי חיים","bt":"תרכח","dt":"תרצא - ח חשון","b":"רב בסרברינקה, ניו יורק"},{"i":11335,"n":"גורדינסקי, יעקב מאיר","b":"רב במינסק-תרן."},{"i":11336,"n":"גורדן, יהודה ליב מוילנא","f":"משה אהרן מואשלישוק","k":"בעל ספר הברית","dt":"תקפא","b":"מקובל מחכמי וילנא. נדד בערים שונות וביניהם למברג, האג, אויבן, פרשבורג. חיבר \"ספר הברית\" ברין תקנז - נדפס בעילום שמו ותורגם גם ללדינו, \"מצוות טובים\", \"מטמוני סתרים\". בנו - ר שמואל."},{"i":11337,"n":"גורוצו די, יצחק מספרד","b":"רב ממגורשי ספרד, והתישב בפיררה-רנב."},{"i":11338,"n":"גורז'ד = גארגז'ידאי","b":"ליטא - מחוז קרטינגה. העיר קרובה לממל וליד הגבול עם גרמניה ותושביה עסקו במסחר עצים עם גרמניה. ראשית ההתישבות המאה ה-16. לפני מלחה\"ע ה-I ישבו בה כ-1500 יהודים, לפני השואה כ-1000. רבנים: ר משה יפה-תר-תרמה כ-45 שנה, בנו ר יוסף, ר יצחק יעקב רבינוביץ-ר איצה'לה מפונוביז, ר אהרן ולקין, ר יצחק איזיק פרידמן, ר שבתאי אהרן בן משה שפירא, ר מאיר לוין - רבה האחרון נספה בשואה."},{"i":11339,"n":"גוריון, אהרן שאול זליג הכהן","f":"מאיר שלום הכהן","k":"בעל מגן שאול","bt":"תקעג","dt":"תרלט","b":"ר\"מ במינסק (מגיל 18 ועד שנתו ה-40), רב בפרוזנאי, דינבורג(=דוינסק) על מקום ר ליב בטלן ור ראובן בעל \"ראש לראובני\" על מקומו אחריו. אחיו - ר משה יואל בעל \"ראשי בשמים\"."},{"i":11340,"n":"גוריון, מאיר שלום הכהן מקרליץ","f":"שמריהו הכהן","bp":"קרליץ","dt":"תקצט - יז סיון","dp":"ירושלים","b":"תלמיד ר חיים מוולוזין ושימש אותו 14 שנה, נשלח על ידי ר חיים לוילנא לעמוד בראש הישיבה. רב באיויא, מאלאט, עלה לירושלים-תקצז. בן למשפחה המיוחסת לנקדימון בן גוריון ומכאן שמם."},{"i":11341,"n":"גוריון, משה יואל הכהן מאניקשט","f":"מאיר שלום הכהן","k":"בעל ראשי בשמים","b":"רב באניקשט-תרכ על מקום ר משה אליהו בן חיים ור שלמה שלוסברג על מקומו אחריו, מאליאט. בנו - ר שמריהו-חתנו של ר איצעלע שירווינטער מוילנא. אחיו - ר שאול זליג בעל \"תשובות לשואל\"."},{"i":11342,"n":"גוריון, שמריהו הכהן","f":"משה יואל מאניקשט","b":"חתן ר איצעלע שירווינטער גרדזנסקי מוילנא. רב-שנת תר\"נ, בנו ר מאיר שלום ממאליאט-ליטא."},{"i":11343,"n":"גורל, יהונתן מגרוזיה","f":"אהרן","bt":"תרלח","bp":"אכלציק-גרוזיה","dt":"תרצג - יז כסלו","dp":"ירושלים","b":"ראש עדת יהודי גרוזיה בירושלים. בניו: מאיר, יהונתן, רחמים, אליהו, גבריאל, משה, חתנו - ר יעקב בן שמעון יחזקאל."},{"i":11344,"n":"גורליצקי, משה אליהו מקונסק","b":"תלמיד ישיבת חב\"ד באוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":11345,"n":"גורליק, יחיאל הלל","dt":"תרפג - א תמוז","b":"דרשן,רב בקזנה-ורדק"},{"i":11346,"n":"גורליק, שניאור זלמן מברזנה","f":"יהושע","bt":"תרמ","bp":"רוגטשוב","dt":"תשלד - ח סיון","b":"תלמיד ישיבת \"תומכי תמימים\" בלובאוויץ. חתן ר אברהם שמואל ואלטשאק מברזנה. רב בברזנה(בערעזנע)-פלך צרניגוב-תרסב על מקום חותנו, הומל, עלה לארץ והתישב בכפר חב\"ד-תשח. נסמך מאת: ר צבי דב מהומל, ר דוד צבי חן מצרניגוב, ר דוד יקובסון מליכוביץ."},{"i":11347,"n":"גורלנד, אהרן","k":"בעל המסתורין והקבלה","bt":"1881","bp":"וילנא","b":"למד באוניברסיטת הידלברג, ג'נבה, ברן. צירו בקונגרס הציוני החמישי, חבר ב\"יהודה החפשית\". השתקע בפטרבורג-1906. פרסם ספרים על תרבות ישראל בספרד על הרמן כהן ועוד. ומאמרים שונים בכתב עת. היגר לאנגליה-1915, ארה\"ב. הצטרף ללגיון היהודי. עלה לארץ והתישב בטבריה, חזר לוילנא ופרסם ספר על המסתורין והקבלה בישראל. חי בברלין עד 1929 ומאז נעלמו עקבותיו. ?? לא באוצר ??"},{"i":11348,"n":"גורלנד, חיים יונה מוילנא","f":"יצחק אליהו בן מאיר","k":"בעל לקורות הגזרות על","bt":"1843","bp":"קלצק-פלך מינסק","dt":"ה'תרנ 1890","b":"תלמיד ביהמ\"ד לרבנים בוילנא. למד שפות המזרח באוני' פטרבורג אצל הפרופ' דניאל חוולסון. העתיק משלי לוקמאן מערבית לרוסית, ופרסם ספר על שיטת הרמב\"ם בפילוסופיה כנגד שיטות הערבים. חיבר מאמרים רבים","bk":[["גנזי ישראל בס\"ט פיטורבורג",""],["לקורות הגזרות",""]]},{"i":11349,"n":"גורלנד, יעקב","f":"יצחק אליהו","b":"אחיו של ר חיים יונה. תלמיד בימ\"ד לרבנים בוילנא. הגיה מטעם הממשלה את ספר \"אוצר שרשים\" בעברית וריסת למנדלשם. חיבר אוצר המלים מהתלמוד ברוסית יחד עם אחיו ר חיים יונה - ולא נשלם. רב מטעם בפולטבה."},{"i":11350,"n":"גורלנד, מאיר איש וילנא","f":"אברהם פאלק חלפן","bp":"ברודי","dt":"תקעא - כ אב","dp":"וילנא","b":"בן אחותו של הנודע ביהודה, הגיע מברודי לוילנא. חתן משפחת גורדון והתעשר בעסקי חלפנות מטבעות. שם משפחתו שילוב של גורדון ולנדא. אבי משפחות גורלנד."},{"i":11351,"n":"גורלנד, שלום מארה\"ב","k":"בעל שלום במרומיו","b":"רב בארה\"ב-תרמט. ?? לא באוצר ??"},{"i":11352,"n":"גורמן, יעקב מפולטוסק","b":"גביר מפולטוסק. חתנו - ר שמואל צבי האדמור מאלכסנדר, וגם אביו האדמור ר ירחמיאל ישראל מאלכסנדר היה נשוי לבת משפחת גורמן."},{"i":11353,"n":"גורן (גרינבלט), נתן","f":"אשר","k":"בעל פייבוש - תרעא","bt":"1886","bp":"ווידז","dt":"1956","dp":"תל אביב","b":"סופר ומחנך. תלמיד ישיבת סלובודקה, קיבוץ בחרוים אצל ר חיים עוזר גרודזנסקי, הצטרף לחוג חשאי של בחורי ישיבה ורכשו השכלה כללית. הצטרף לפועלי ציון וס\"ס נאסר ושוחרר על פעילות מהפכנית. התישב באודסה-1910 והיה עתונאי ומרצה, עבר לפוצ'פ-פלך צ'רניגוב, ליטא-1921 והיה מורה בגימנסיות בקובנא.עורך \"דאס ווארט\", ועוד.עלה לארץ-1935 ועסק בהוראה וכתיבה."},{"i":11354,"n":"גורן, שלמה (גורונצ'יק)","b":"רב ראשי לצה\"ל. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":11355,"n":"ג'ורנו, משה מאלגיר","bt":"תרי","dt":"תרץ - בערך","b":"רב במיליאנא-אלגיר, בני בצאף. סייע בהדפסת \"בית שלמה\" ירושלים תרנב מאת ר א' ש' פרידמן."},{"i":11356,"n":"גורנובסקי, אברהם מארה\"ב","f":"ישראל","k":"בעל אבן ישראל","bp":"וולצלאווק","b":"רב בקהלת \"אמונת ישראל\" בניו יורק. חיבר ספר דרשות \"אבן ישראל\"."},{"i":11357,"n":"גורניצקי, יקותיאל (י. קיסין)","bt":"1886","bp":"קובנא","dt":"1950","dp":"דייטון-אוהיו","b":"סופר אידי. היגר לארה\"ב-1904. חיבר ספרים ומאמרים, ותרגם לאידיש יצירות שונות."},{"i":11358,"n":"גורניש, מ'","b":"מחדושיו על התלמוד ב\"מהררי נמרים\"."},{"i":11359,"n":"גורפין, יוסף מסמבור","b":"תשובה אליו \"שושנים לדוד\""},{"i":11360,"n":"גורפין, יצחק מבוצאץ","b":"ממשתתפי \"ועד חכמים\"."},{"i":11361,"n":"גורפין, משה אהרן","b":"תשובה אליו במהר\"י הכהן."},{"i":11362,"n":"גורפין, משה דוד מפודגורזע","b":"תשובה אליו \"מנחת יחיאל\"-תרצא."},{"i":11363,"n":"גורפין, שמחה אשר ממליץ","k":"בעל מנחת חיי","b":"התישב במליץ. חיבר \"מנחת חיי\". סירב לרבנות. עבר לבריגל. גיסו של הגביר ר ירחמיאל קנרק. ?? לא באוצר ??"},{"i":11364,"n":"גורפינקל, שלמה חיים","dt":"תשג","b":"רב בקאמניץ"},{"i":11365,"n":"גז, אברהם מתונס","b":"מרבני תונס"},{"i":11366,"n":"גזאל, משה הלוי מדמשק","b":"רב בדמשק-תמב."},{"i":11367,"n":"גזונדהייט, יעקב מוארשא","f":"יצחק","k":"בעל תפארת יעקב","bt":"תקעו","dt":"תרלח - יב אלול","b":"תלמיד ר אריה ליב צונץ. רב בפראגה-פרבר וארשא, רב בוארשא על מקום ר בעריש מייזלש-תרל, היה מחלוקת כנגדו מצד החסידים ונאלץ לעזוב."},{"i":11368,"n":"גזונדהייט, יעקב מוארשא - ב","b":"מזכיר ועד הרבנים בוארשא-תרפט, בזמן ר צבי יחזקאל מיכלסון."},{"i":11369,"n":"גזית (זיסלה), דב","f":"צבי יעקב","bt":"1897","bp":"יאנובה","dt":"1960","dp":"תל אביב","b":"תלמיד ישיבת סלובודקה. למד לימודים כללים והיה מורה בינאובה ווילנא, יסד בפילווישוק את ביה\"ס העממי העברי הראשון בליטא. עלה לארץ-1924. פרסם מאמרים וספרים."},{"i":11370,"n":"גטובמן, מאיר מנאוי-בעליץ","f":"שמעון","b":"רב בנאווי-בעליץ"},{"i":11371,"n":"גטיניו, ליאון אברהם משלוניקי","b":"מראשי קהלת שלוניקי-תרפא."},{"i":11372,"n":"גטיניו, ליאון משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":11373,"n":"גטניו בנבנשתי מרקדו בן חיים אברהם","dt":"ה'תקל 1770","bk":[["מצרף לכסף",""],["תרומת כסף",""]]},{"i":11374,"n":"גטניו, אברהם משלוניקי","f":"בנבנישתי בן חיים אבר","k":"בעל צל הכסף","dt":"תרם","dp":"שלוניקי","b":"תלמיד ר אברהם דוד, דיין יתומים ואלמנות-תרט, רב ראשי בשלוניקי-תרלה ולצדו ר שמואל ארדיטי ור מאיר נחמיאש, ונאלץ לפרוש לאחר מחלוקת עם הגבירים שרצו להעלות את המס מהעניים. בנו - בנבנישתי נהרג-תריט ע\"י שודדים יחד עם כמה מחבריו. הו\"ל ספרי זקניו \"אלף כסף\" ו\"מצרף לכסף\", ותרגם ללאדינו פרקים מספר הברית-תרז. נספד מאת ר יעקב מנשה."},{"i":11375,"n":"גטניו, אברהם משלוניקי","f":"רבינו","b":"מחכמי שלוניקי, הגיה \"מלאכת שלמה\" לר שלמה חכים-תרג, \"ידי דוד\"-תרכז לר דוד קרסו."},{"i":11376,"n":"גטניו, אברהם משלוניקי - הנכד","f":"בנבנישתי","k":"בעל אלף כסף","dt":"תקסט - אדר","b":"נכד ר אברהם גטניו. רב הכולל בשלוניקי-תקנב על מקום ר רפאל חיים אברהם קובו - יחד עם כמה מחבריו, חיבר ספר \"אלף כסף\". בשליחות קהלת שלוניקי אצל השלטונות בקושטא לאחר עלילת היונים בשלוניקי שסיכנה את בני קהלתו."},{"i":11377,"n":"גטניו, אליקים מאזמיר","f":"יצחק","k":"בעל תועפות ראם","bt":"תק - בערך","bp":"שלוניקי","dt":"תקנה - ה שבט","dp":"אזמיר","b":"תלמיד ר חיים אלפנדרי מקושטא. רב בשלוניקי, עבר לאזמיר ולימד תורה, חיבר גם \"אגורה באהליך\"."},{"i":11378,"n":"גטניו, בנבנישתי - מירקאדו","f":"אברהם","k":"מירקאדו","dt":"תקל - ח אייר","b":"דיין בשלוניקי, רב הכולל על מקום ר יצחק בן יעקב הלוי-מהר\"י סגל. סייע בהדפסת ספרים בשנים תקד-תקלא ובהם \"בתי כהונה\". מתורתו ב\"מצרף לכסף\", וספר אביו \"צרור הכסף\", רוב פסקיו נשרפו-תר, חיבר תשובה לקהלת קורפו בשם \"שפר קריאת שמע\" עם חתימת 8 רבנים נוספים. חתנו - הרופא ר יצחק די ליאון משלוניקי."},{"i":11379,"n":"גטניו, בנבנישתי משלוניקי","f":"משה","k":"בעל משחקים בכסף","dt":"תר - כד טבת","dp":"שלוניקי","b":"דיין-תקץ בביה\"ד של חזקות בשלוניקי. חיבר דרשות והספדים בשם \"משחקים בכסף\". נדפס עם דרשות מבנו יהודה-שנפטר בחייו, בעזרת בניו - ר לוי ור אברהם בשנת תר (ולא כאומרים שנדפס ב-תרי)."},{"i":11380,"n":"גטניו, בנבנישתי משלוניקי","f":"אברהם-צרור הכסף","dt":"תקעט","dp":"שלוניקי","b":"מחכמי שלוניקי. הו\"ל \"צרור הכסף\" לאביו עם הוספות ממנו. בנו - ר אברהם-רב ראשי בשלוניקי."},{"i":11381,"n":"גטניו, זכריה ממצרים","b":"גביר מחכמי מצרים-שנות ה-ש', ר משה וינטורא מטיבולי התארח אצלו בקהיר."},{"i":11382,"n":"גטניו, חיים אברהם - הזקן","dt":"תעא - יב תמוז","dp":"ירושלים","b":"דיין ומקובל מחכמי שלוניקי, עלה לירושלים. תלמיד ר שלמה אמריליו בעל \"כרם שלמה\", לימים רבה של שלוניקי. הסכים על \"מאורות נתן\" - תמז. בנו ר בנבנשתי ונכדו ר חיים אברהם גטניו (הנכד)"},{"i":11383,"n":"גטניו, חיים אברהם משלוניקי","f":"בנבנשתי","k":"בעל טירת כסף","bt":"תך - בערך","dt":"תצ - ח סיון ?","dp":"שלוניקי","b":"תלמיד ר שלמה אמריליו. רב ודרשן בשלוניקי, ומלמד לתלמידים. חתם על הסכמת ר יוסף קובו-תפה - בענין פטור תלמידי חכמים ממס, ועל הסכמה נוספת-תפט. חיבר גם \"צרור הכסף\" עם הוספות מבנו - ר בנבנישתי."},{"i":11384,"n":"גטניו, חיים משלוניקי","b":"רופא בשלוניקי-תרכז."},{"i":11385,"n":"גטניו, חיים שמואל משלוניקי","f":"אברהם - אלף כסף","k":"בעל ערך כסף","dt":"תקצה","dp":"שלוניקי","b":"דיין בשלוניקי-תקעח - ליתומים ואלמנות. מתורתו בספר אחיינו-\"צל הכסף\", ובספרי חכמי דורו. הגיה \"פני אהרן\"-תקנו, שו\"ת ר ישראל מברונא-תקנח, \"פני מבין\"-תקעא, ועוד. חיבר \"ערך כסף\"?. חתם-תקף עם ר יעקב רפאל מנשה ור דוד הלוי קרסו בתשובה לר אברהם משירון, וחתם-תקפד עם ר דוד קרסו ור חננאל הכהן חסיד."},{"i":11386,"n":"גטניו, יהודה משלוניקי","b":"מחכמי שלוניקי, בשליחות עצמו באמשטרדם יחד עם חבריו דוד אברהם ויעקב קובו - לאחר השריפה הגדולה בשלוניקי-תר."},{"i":11387,"n":"גטניו, יוסף משלוניקי וירושלים","dt":"תסט (תרט?)","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים. מורו ודודו של ר אברהם גטניו רבה של קהילת אראגון בשלוניקי בעל \"טירת כסף\", ונספד שם."},{"i":11388,"n":"גטניו, יעקב מוידין","b":"גביר בוידין, בנה מחדש את ביהכ\"נ-תקיו."},{"i":11389,"n":"גטניו, יעקב מחברון","b":"מחכמי חברון, חתם על כתב שליחות ר חייא דיין בשנת תכא."},{"i":11390,"n":"גטניו, יצחק בנבנישתי משלוניקי","k":"בעל מעשה חושב","b":"מורה לעברית בביה\"ס כי\"ח בשלוניקי. חיבר ספר דקדוק \"מעשה חושב\"-שלוניקי תרלו."},{"i":11391,"n":"גטניו, יצחק מאזמיר","f":"אליקים בעל תעפות ראם","k":"בעל בית ישחק","dt":"תקס - יד אלול","dp":"אזמיר","b":"רב באזמיר. רבו של ר חיים פאלג'י. חיבר גם \"בית מועד\", \"יצחק ירנן\", ועוד."},{"i":11392,"n":"גטניו, יצחק משלוניקי","dt":"תקצט","dp":"שלוניקי","b":"מחכמי שלוניקי. תשובות ממנו ב\"באר המים\". נפטר במגיפה."},{"i":11393,"n":"גטניו, יצחק משלוניקי - א","b":"רב בשלוניקי-שנות ה-ש'. נזכר ב\"דברי ריבות\" על מחלוקת שהיה לו עם מהרשד\"ם."},{"i":11394,"n":"גטניו, ליאון אברהם משלוניקי","b":"נשיא הקהלה בשלוניקי-תרץ."},{"i":11395,"n":"גטניו, מנחם משלוניקי","b":"דיין בשלוניקי-שנות ה-תק'. תשובות ממנו ב\"באר המים\" לר יעקב מנשה, וב\"ירך אברהם\" לר אברהם אישטרושה. חתם-תקפד עם ר משה ברכה ור אברהם ן חסון."},{"i":11396,"n":"גטניו, משה משלוניקי","b":"מחכמי שלוניקי-שץ, תלמיד ר שלמה ן מאיור."},{"i":11397,"n":"גטניו, משה משלוניקי","f":"בנבנישתי","dt":"תקסג","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של ר אברהם-הרב הכולל בשלוניקי."},{"i":11398,"n":"גטניו, שמואל בכור משלוניקי","b":"רב בשלוניקי-תרם. חתן ר אברהם גטניו, והספדו על חותנו נדפס ב\"צל הכסף\"."},{"i":11399,"n":"גטניו, שמואל משלוניקי","f":"בנבנישתי","dt":"תקל - טז אייר","dp":"שלוניקי","b":"מחכמי שלוניקי-תקכח, הגיה את \"שער המים\" לר מרדכי מיוחס."},{"i":11400,"n":"גטניו, שמואל משלוניקי","f":"יהודה","dt":"תרמו","dp":"שלוניקי.","b":"דיין בשלוניקי. בן אחיו של ר אברהם-הרב הראשי."},{"i":11401,"n":"גיאון ן, יהודה ממראקש","b":"רב במראקש בזמן הרשב\"א, חברו של ר יוסף גליל."},{"i":11402,"n":"גיאות, יהודה","f":"יצחק ן גיאות","b":"משורר ופייטן-ד'תת\"פ"},{"i":11403,"n":"ג'יאן - משפחה","b":"ראשוני המשפחה הידועים - ר יוסף בר יושת ממדינת ג'יאן, ור ישראל ג'יאן מתלמסאן-שם."},{"i":11404,"n":"ג'יאן, אליהו מטריפולי","bt":"תקם","dt":"תרי - בערך","b":"סופר קהלת טריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":11405,"n":"ג'יאן, יהודה ממראקש","dt":"ע","b":"מחכמי מראקש."},{"i":11406,"n":"ג'יאן, יונה מטבריה","dt":"תקסה - לפני","b":"ממשפחה מאלגיר, מחכמי טבריה. חתם עם רבני טבריה - תקי - תקל. מתורתו ב\"ויעתק יצחק\" המצורף ל\"מנחת יוסף\" - ליוורנו תקפז."},{"i":11407,"n":"ג'יאן, יוסף מטריפולי","f":"כמוס","bt":"תרמג","bp":"טריפולי","dt":"תשכ - ח שבט","dp":"בני ברק","b":"תלמיד ר ציון ביתאן, דיין בבנגזי-תרצא אצל ר כמוס פלאח ורב ראשי ואב\"ד-תשא על מקומו אחריו. עלה לארץ-תשט והתישב ברמת גן."},{"i":11408,"n":"גי'אן, יעקב","f":"מאיר","k":"בעל צניף מלוכה?","b":"לדברי בן יעקב חיבר \"צניף מלוכה\" ולפי טולדנו זו טעות."},{"i":11409,"n":"ג'יאן, ישראל מתלמסאן","bt":"תקל","dt":"תרי - בערך","b":"רב ודיין בתלמסאן על מקום ר נתן ג'ייאן (אביו או אחיו?). חתום על הקדמה לספר הזכרון - ליוורנו תרה. חתם בפנקס הזכירה של בית הדין בתלמסאן."},{"i":11410,"n":"ג'יאן, מרדכי מאלגיר","dt":"תקמג","b":"מחכמי אלגיר, ולמד קבלה עם ר אברהם טוביייאנא. אולי הוא החותם באגרת שליחות ר\"י בנבנשתי ור חיים בונאן."},{"i":11411,"n":"ג'יאן, נתן מאלגיר - א","f":"ישראל","bt":"תך","dt":"תץ - בערך","b":"רב ומשורר בתלמסאן. אולי הוא הדיין שעל מקומו נתמנה ר מרדכי ג'יאן."},{"i":11412,"n":"ג'יאן, נתן מאלגיר - ב","f":"ישראל","dt":"תקפה - בערך","b":"רב בתלמסאן. תשובה ממנו לקהילת אוג'דא - בענין גט. מתורתו ב\"ירך יעקב\" לר יעקב פיתוסי, חיבר סליחות, קינות ושירים ומפיוטיו ב\"שבחי אלקים\". מתורתו ב\"ירך יעקב\" ליוורנו תרב."},{"i":11413,"n":"גיאת ן, אלכסנדר","k":"בעל פירלאס דיל תלמוד","bp":"אזמיר","dt":"תרפד","b":"סופר ועתונאי באזמיר, הו\"ל \"איל מיסיריט\", \"איל קיסמיט פואיטה\", ועוד בספניולית ובתורכית. פרסם ספורים ותרגומים."},{"i":11414,"n":"גיאת ן, חיים אברהם מאזמיר","dt":"תקמח - יד אדר","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":11415,"n":"גיאת ן, חיים יצחק מירושלים","dt":"תקפו"},{"i":11416,"n":"גיאת ן, יהודה מגרנדה","f":"יצחק","b":"משורר ופייטן מחכמי גרנדה-ספרד - שנות ה-ד'תתק, חברו של ר יהודה הלוי - שלחו שירים זה לזה."},{"i":11417,"n":"גיאת ן, יחיאל אפרים מירושלים","dt":"תקמד - כה כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":11418,"n":"גיאת ן, יצחק מלוצנה=אליסונה","f":"יהודה","k":"בעל הלכות כלולות","bt":"ד'תשץ (1030)","bp":"לוצנה (ליד קורדובה)","dt":"ד'תתמט","dp":"קורדובה - אליסונה","b":"רב בלוצנה וראש ישיבה, הרי\"ף על מקומו אחריו בראש הישיבה. מגדולי דורו. ידיד ר שמואל הנגיד ובנו יוסף שנרצח בפוגרום בגרדנה-ד'תתכו ותמך באלמנה ובנה ר עזריה שנמלטו אליו ללוצנה. חיבר \"מאה שערים\", ספרים שאבדו, ופיוטים שנכנסו למחזורי קהלות צרפת ספרד ואיטליהשמרו. תלמידיו - בנו ר יהודה ן גיאת, ר משה ן עזרא, ר יוסף הדיין ור יעקב ן סהל."},{"i":11419,"n":"גיאת, אהרן","f":"יהודה","bp":"צנעא","b":"מחכמי צנעא"},{"i":11420,"n":"גיבטא, חיים","b":"מחכמי צפת, בשנת שע חתם מכתב בקשת עזרה לר אהרן ברכיה ממודנא"},{"i":11421,"n":"גיבנר, משה מקרומלא","b":"תלמיד מהר\"ם שיק, ר יהושע השל פריד מקאפוש. שו\"ב בקרומלא."},{"i":11422,"n":"גיברמן, אברהם ליב מקלן","b":"רב בקלן בדור שלפני השואה."},{"i":11423,"n":"גיג', אברהם מאלגיר","f":"מרדכי","bt":"תקך","dt":"תקץ - בערך","b":"נכד הפייטן ר שלם גיג'. רב וסופר בקצמטינא. העתיק מחזור מנהג קצמטינא."},{"i":11424,"n":"גיג', אליהו חי מתונס ואלגיר","f":"יוסף - פי המדבר","k":"בעל תפילה בכל לשון","bt":"תר","bp":"תונס","dt":"תרסח","b":"הגיע מתונס לאלגיר, מגיה ספרים ומתרגם לערבית יהודית. חיבר \"תפילה בכל לשון\". חיבר שיר \"כליני נסכר יא יהודי\" שנדפס בהגדת ליוורנו, ועוד. חיבר \"ארחא דמלתא\" - חדושים בש\"ס, \"פרסומי נסה די פורים\", ועוד. הו\"ל ספר אביו \"פי המדבר\"."},{"i":11425,"n":"גיג', אליהו מאלגיר - אג\"ן","f":"כלפה","bt":"תקס","dt":"תרמב","b":"רב ומקובל בקצמטינא. חיבר \"פרי אג\"ן\". בניו: ר כלפה בעל \"חמשה גנים\", ר שלום."},{"i":11426,"n":"גיג', יוסף","dt":"תרצה - כה אלול","b":"ראש רבני תוניס"},{"i":11427,"n":"גיג', יוסף","f":"דוד","k":"בעל פי המדבר","bt":"תקנג","dt":"תריג","b":"חיבר פירוש להגדה \"פי המדבר\" (והוא ר\"ת פירוש הגדה ממני יוסף בן רבנו דוד). בנו - ר אליהו חי הו\"ל את הספר."},{"i":11428,"n":"גיג', יעקב מאלגיר","f":"אליהו חי","bt":"תרך","dt":"תרץ - בערך","b":"רב באלגיר. מדפיס ומו\"ל שירים עממיים ובהם \"כתאב גנאייאת בלערבייא\", \"גנאיית בלערבייא\", ועוד."},{"i":11429,"n":"גיג', כלפא מקצמנטינא-אלגיר","f":"אליהו - אג\"ן","k":"בעל כגן הירק","dt":"תרעו - ל תשרי","dp":"ירושלים","b":"מחכמי אלגיר, רב וראש ישיבת לומדי קבלה בקצמטינא-אלגיר, עלה לירושלים-תרנז, והיה מתלמיד \"בית אל\". מכונה \"חמשה גנים\" ע\"ש חמשת חבוריו והם \"כגן הירק\", \"כגן רווה\", \"כגן עדנים\", \"כגן רטוב\", \"מעיין גנים\". שאלה ממנו לר רחמים יוסף פרנקו ב\"שערי רחמים\"."},{"i":11430,"n":"גיג', ראובן מאלגיר","f":"שלום","k":"בבא זיזי","bt":"תרכז","dt":"תשיג","b":"פייטן רב ומלמד תורה בקצמטינא. חיבר \"בן אדם באש טאג'י\" - בערבית יהודית. פיוטים ממנו ב\"כגן רווה\". סגי נהור - וכשישב קושיה בישיבת ר סידי פרג' חלימי - קרא עליו ר סידי \"והיית לנו לעינים\"."},{"i":11431,"n":"גיג', רחמים מאלגיר","dt":"תשטו","b":"רב בבטנא-אלגיר. נהרג עק\"ה."},{"i":11432,"n":"גיג', רפאל מאלג'יר","bt":"תקל - בערך","dt":"תר - בערך","b":"דיין בקצמטינא-אלגיר אצל ר נתן טובייאנה."},{"i":11433,"n":"גיג', שלום מאלג'יר","bt":"[תם]","dt":"תקי - בערך","b":"פייטן רב ודיין בקצמטינא-אלג'יר, ובקי במנהגי קצמטינא. שאלות ממנו לרי\"ש צרור בעל \"פרי צדיק\". כנראה שהוא ר שלם שמפיוטיו במחזור קצמטינא ונזכר ב\"אהל דוד\"."},{"i":11434,"n":"גיג', שלום מאלגיר - ב","f":"[אליהו]","b":"רב בבטנא-אלגיר. נזכר בהקדמה להגדה \"ויגד לאברהם\" מאת ר אברהם חלימי. כנראה אחיו של ר כלפא."},{"i":11435,"n":"גיג', שלמה מאלגיר","b":"רב בקצמטינא. חיבר ספר על תולדות היהודים באלגיר ובצפון אפריקה - ונעלם."},{"i":11436,"n":"גיגי, אברהם ממרוקו","f":"דוד","b":"רב בדבדו(מרוקו)-ת\"מ"},{"i":11437,"n":"גיגי, אברהם ממרוקו","b":"מחכמי מרוקו-שנות ה-תק'. חתם-תץ על מעשה בי\"ד."},{"i":11438,"n":"גיגי, אליהו מאלגיר","k":"בעל קול צעקת הרועים","bt":"תרל","bp":"דברו(=דבדו)-מרוקו","dt":"תרצא","dp":"סעידא","b":"הגיע ממרוקו ולמד תורה בתלמסאן. רב בסיג, סעידא-אלגיר, חיבר \"קול צעקת הרועים\" - בענין טחינת קמח לפסח במכונה. חיבר פירושים על ראב\"ע - ואבדו."},{"i":11439,"n":"גיגי, דוד","f":"אברהם","k":"בעל אוצר נחמד","b":"נכד ר יהודה הכהן טאנוג'י. מחכמי טבריה בשנת תקל, עבר לשפרעם בשנת תקלג ובה כתב את ספרו \"משבצת זהב\" (בכתב יד). בשנת תקכז כתב \"אוצר נחמד\" והוא השלמות לספר \"מנחת יהודה\" לר יהודה בן עטר..חיבר גם \"נר דוד\"."},{"i":11440,"n":"גיגי, דוד","bt":"תרלח","bp":"דברו-מרוקו","dt":"תשלד","b":"מרביץ תורה בדבדו"},{"i":11441,"n":"גיגי, דוד מתאזא-מרוקו","b":"רב בתאזא, חתם על מעשה בי\"ד-תקך עם ר אליהו הצרפתי, ר מתתיה סירירו."},{"i":11442,"n":"גיגי, יהושע מתאזא-מרוקו","f":"דוד","b":"רב בתאזא-מרוקו-תקסד, על ההסכמה למינויו כרב חתמו גם רבני פאס - ר שאול סירירו, ר אליהו הצרפתי, ר יצחק פינטו ועוד."},{"i":11443,"n":"גיגי, יוסף מלונדון","b":"חיבר שיר לכבוד הכנסת ס\"ת לביהכ\"נ \"שער השמים\" - לונדון תקעד."},{"i":11444,"n":"גיגי, יוסף ממרוקו","b":"מחכמי מרוקו. בנו - ר ישועה."},{"i":11445,"n":"גיגי, יצחק מדבדו-מרוקו","f":"יהודה","bt":"[שץ]","dt":"תן - בערך","b":"מחכמי דבדו,"},{"i":11446,"n":"גיגי, יצחק מפאס","b":"מחכמי פאס, חתם-תקפד עם ר רפאל אהרן מונסונייגו."},{"i":11447,"n":"גיגי, ישועה ממרוקו","f":"יוסף","b":"מחכמי מרוקו-שנות ה-ת'. אביו של ר מנחם."},{"i":11448,"n":"גיגי, מנחם מתאזא-מרוקו - א","f":"ישועה","b":"מחכמי תאזא-מרוקו-תקכא. תשובה ממנו ב\"שופריה דיעקב\" יחד עם ר יהושפט גיגי."},{"i":11449,"n":"גיגי, מנחם מתאזא-מרוקו - א","f":"דוד","b":"מו\"ץ בתאזא-מרוקו."},{"i":11450,"n":"גיגי, משה מאלגיר וטבריה","bt":"תקנט","bp":"אלגיר","b":"עלה לארץ-תקץ והתישב בצפת, רב ומקובל בטבריה, ומסופר שהתנבא על הרעש בצפת אולם לא שמעו לו. חתם על אגרות בצפת."},{"i":11451,"n":"גיגי, משה ממרוקו","k":"המג\"ן","bp":"דברו-מרוקו","dt":"תשיז - כג ניסן","dp":"לוד","b":"תלמיד ר אברהם ן שושן, ובישיבת ר דוד הכהן סקלי (=הרד\"ך) בעל \"קרית חנה דוד\". רב \"קהילת לעיון\". חיבר שיר לכבוד מורו הרד\"ך ונדפסה ב\"קרן לדוד\". עלה לארץ."},{"i":11452,"n":"גיגי, משה מתאזא-מרוקו","b":"מחכמי תאזא-שנות ה-תק'."},{"i":11453,"n":"גיגיליה, יוסף הפייטן מפרובאנס","f":"יצחק","b":"רופא ופייטן בפרובאנס-שנות ה-ק'. חיבר פיוט ליום יג שבט."},{"i":11454,"n":"גיגר אברהם","bt":"1810","dt":"ה'תרלד 1874","bk":[["מלא חפנים",""],["פרשנדתא",""],["ציצים ופרחים",""]]},{"i":11455,"n":"גידאלי, יחיאל מפרשבורג","b":"מזכיר ישיבת פרשבורג. נספה בשואה."},{"i":11456,"n":"גידונג, אהרן משה אריה מפעזינג","dt":"תקצ - יח ניסן","b":"רב בפזינג(=פעזינג)-תקמ. השתתף בועידת רבנים בראשות ר משלם איגרא - לבחירת רב בעיר חדש על מקום ר בנימין זאב עמריך-תקנד."},{"i":11457,"n":"גידמן, משה","b":"רב בווינה-תר\"ס"},{"i":11458,"n":"ג'יהן ברוכוף, ארי","f":"אברהם","bt":"תרמו","bp":"טשקנט-בוכרה","b":"עסקן צבור, עלה לירושלים-תרץ והיה מראשי הקהלה."},{"i":11459,"n":"ג'יהן ברוכוף, משיח מבוכרה וי-ם","bt":"תרלו","bp":"בוכרה","b":"עלה בילדותו לירושלים-תרמב. תמיד \"דורש ציון\", נסע אל אחיו במוסקבה והתעשר, עבר לטשקנט, תרם להקמת שכונה בירושלים \"אבן ישראל\"-תרסז, ביקר בארץ כמה פעמים ותרם למטרות חסד. עלה לירושלים-תרעח ועסק בפעילות צבורית."},{"i":11460,"n":"ג'יהן, ברוך מבוכרה וירושלים","f":"יהושע","dt":"תרנח - יד אדר","dp":"ירושלים","b":"עלה מטשקנט לירושלים-תרמב, גביר שתמך בתלמידי חכמים, וסייע בהו\"ל חבורים שונים, הקים ביכ\"נ שנקרא ע\"ש."},{"i":11461,"n":"גיז, יהודה מתונס","f":"יעקב גיז","k":"בעל נחלת יעקב","dt":"תרצה - כד טבת","b":"מקובל, רב בתונס. חיבר גם \"נחלי יעקב\", \"אבי הנחל\"."},{"i":11462,"n":"גיז, יעקב","k":"בעל ירך יעקב","b":"מגדולי חכמי תוניס-תר\"ס. ?? לא באוצר ??"},{"i":11463,"n":"גיזה, זידלר מקאראן סבש","b":"רבה האחרון של הקהילה הניאולוגית בקאראן סבש."},{"i":11464,"n":"גיזלר, צבי הירש מטלומטש","b":"אב\"ד טלומטש-תרט. תשובה אליו ב\"מאמר מרדכי\"."},{"i":11465,"n":"גיטינגא, עזרא מספרד","f":"שלמה אשטרוך","b":"מחכמי סרגוסה, אקרימונטה. חיבר פירוש לאבן עזרא."},{"i":11466,"n":"גיטינגן, אהרן מפפד\"מ","f":"גומפרכט","dt":"תקלא - כב סיון","dp":"פפד\"מ","b":"ר\"מ בפפד\"מ בביהמ\"ד של ר אליהו שייאר."},{"i":11467,"n":"גיטלביץ, שמחה שלמה מקובנא","dt":"תשג","b":"רב בקובנא. פרסם מאמרים ב\"דברי תבונה\" - קובנה תרף, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"תבונה\" - קובנא תרפא."},{"i":11468,"n":"גיטלזון, בנימין מקליבלנד","f":"יהודה ליב","k":"בעל הפותח והחותם","bt":"תריא","bp":"אוז'וואנט-פלך קובנא","dt":"תרצב","b":"תלמיד ישיבת סלובודקה. רב באוואנטה, טראשקון-תרמג, רב בקליבלנד-תרן. פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד, \"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"בית ועד לחכמים\" - סטמר תרפב, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג. ?? לא באוצר ??"},{"i":11469,"n":"גיטלזון, נחמיה","bt":"1853","bp":"סוואנציאן","dt":"1932","dp":"ניו יורק","b":"תלמיד ישיבות מיר, וולוזין. היגר לארה\"ב וחזר לוילנא כמה פעמים. מיסד חברת ש\"ס בביהכ\"נ \"בני ישראל קאלואריה\" בניו יורק, והיה מנהיגה הרוחני כ-25 שנה. היה בעל ספריה תלמודית גדולה ומסרה לסמינר התיאולוגי בניו יורק."},{"i":11470,"n":"גיטלין, יעקב","bt":"1878","bp":"דונילוביץ-פלך וילנא","dt":"1953","b":"תלמיד ישובות דוינסק, מינסק. היגר לדרום אפריקה-1902 והשתקע בקייפטאון. ממנהיגי הקהלה ופעיל ציוני, ומראשי יהדות דרום אפריקה."},{"i":11471,"n":"גיטלצר, מרדכי שמואל","bt":"תרמג","b":"מו\"צ בוורשה-תר\"ע"},{"i":11472,"n":"גיטלר, אברהם מאיר מסאסנוביץ","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":11473,"n":"גיטמן, מרדכי אברהם מיברוב","b":"תשובה אליו בשו\"מ."},{"i":11474,"n":"גיטעליס, אברהם ממאציוב","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":11475,"n":"גייגר, אברהם מפפד\"מ","dt":"תצב - ד תשרי","dp":"פפד\"מ","b":"דיין בפפד\"מ."},{"i":11476,"n":"גייגר, אברהם מפפד\"מ - א","f":"למל","dt":"תצא","b":"דיין מחכמי פפד\"מ-תע."},{"i":11477,"n":"גייגר, אברהם מפפד\"מ - ב","dt":"תקכה","b":"דיין בפפד\"מ. אביו של ר שלמה."},{"i":11478,"n":"גייגר, אברהם מפפד\"מ וברסלוי","f":"יחיאל מיכל","k":"בעל וואס האט מאהמעד","bt":"תקע","bp":"פפד\"מ","b":"מראשי חכמת ישראל בגרמניה, רב ריפורמי בברסלוי, פפד\"מ, ברלין."},{"i":11479,"n":"גייגר, אהרן יחיאל מיכל מפפד\"מ","b":"ש\"ץ בפפד\"מ-תקעח, בנו - ר שלמה זלמן בעל \"דברי קהלת\"."},{"i":11480,"n":"גייגר, ישראל מקאשוי","b":"חתן החת\"ס. בנו - שמואל."},{"i":11481,"n":"גייגר, שלמה זלמן מפפד\"מ - ב","f":"אברהם מפפד\"מ","k":"בעל כרם שלמה","dt":"תקלה","dp":"פפד\"מ","b":"נינו של ר שלמה רוטשילד. דיין בפפד\"מ-תק\"ל (או תקם). היה מחלוקת כנגד ספרו בפפד\"מ - בגלל שהדפיסו בלי הסכמות רבני פפד\"מ (בין המסכימים ר משה חגיז מירושלים)."},{"i":11482,"n":"גייגר, שלמה זלמן מפפד\"מ - ג","f":"אהרן יחיאל מיכל","k":"בעל דברי קהלת","b":"מחכמי פפד\"מ. אחיו - אברהם מפפד\"מ וברסלוי-מראשי הריפורמים."},{"i":11483,"n":"גייגר, שלמה מפפד\"מ - א","f":"אברהם","dt":"תקכה - יט אב","dp":"פפד\"מ","b":"דיין בפפד\"מ ומראשי הקהילה."},{"i":11484,"n":"גיילנהוזן, יעקב הלוי","f":"יקותיאל זלמן מול","b":"מגדולי חכמי דורו באשכנז,אביר הרועים-ר\"י"},{"i":11485,"n":"גיינסו, יוסף","k":"בעל דיואן","dt":"ת בערך","dp":"ירושלים","b":"תלמיד ר ישראל נג'ארה, היה רב בברושא (תורכיה) בין תלמידיו ר שלמה אלגזי (הראשון). פייטן ומשורר וחיבר דיואן בכתב יד. בשנת שע כתב ספר חדושי תוספות בכתב יד."},{"i":11486,"n":"גייער, אברהם יצחק מברוד","f":"משה","dt":"תרכח - יז ניסן","dp":"לבוב","b":"דיין בלבוב-תרטז."},{"i":11487,"n":"גיירינג, אהרן משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":11488,"n":"גיירינג, אליהו משטמפן","dt":"תקעד - כד טבת","dp":"שטמפן","b":"חתן ר דוד בן בנימין וולף עמריך מעיר חדש. מחכמי שטמפן, חתם-תקסג עם ראשי הקהלה. בניו - ר משה גומפל, ר נתן."},{"i":11489,"n":"גיירינג, זנויל משטמפן","f":"רפאל משטמפן","b":"מחכמי שטמפן, חתם-תקנט על מינוי ר לוי פולק לרב בשטמפן."},{"i":11490,"n":"גיירינג, יהודה ליב משטמפן","b":"חתם-תקעד על צוואת ר יוסף קוטנפלן, חתם-תקעו על כתב רבנות ר מרדכי בנט."},{"i":11491,"n":"גיירינג, יוחנן משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":11492,"n":"גיירינג, יצחק איצק משטמפן","f":"שמואל זנויל","dt":"תקלז - טו אד\"א","dp":"שטמפן","b":"פרנס ממנהיגי קהלת שטאמפי(=שטמפן)-תקו. יצג את קהלת שטאמפי בבוררות עם קהלות פרשבורג וסערדהאלי. חתנו - ר נתן אורהולץ - רבה של שטאמפי."},{"i":11493,"n":"גיירינג, יצחק משטמפן - ב","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":11494,"n":"גיירינג, משה גומפל משטמפן","f":"אליהו משטמפן","dt":"תרטז - כה אייר","dp":"שטמפן","b":"נכד(-אבי אמו) ר דוד עמריך מניקלשבורג. דיין ומו\"ץ בשטמפן, נתמנה למלא מקומו של ר אריה יהודה ליב טלטש-טויבר באופן זמני עד למינוי ר מרדכי בנט, וכן מילא את מקומו של ר יוסף קוטנפלן עד מינוי ר אליעזר וינטר."},{"i":11495,"n":"גיירינג, משה מאזוס משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":11496,"n":"גיירינג, נתן אריה ליב משטמפן","b":"מחכמי שטמפן, חתם-תקנט על מינוי ר לוי פולק לרב בשטמפן. תשובה אליו בשו\"ת החת\"ס."},{"i":11497,"n":"גיירינג, נתן משטמפן","f":"אליהו משטמפן","dt":"תריד - כז אדר","dp":"שטמפן","b":"מחכמי שטמפן. אחיו - ר משה גומפל משטמפן."},{"i":11498,"n":"גיירינג, רפאל משטמפן","f":"קויפמן","dt":"תקנג - יא אד\"א","b":"מוהל בשטאמפי-תקיא-תקנב, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן. בנו - ר זנויל."},{"i":11499,"n":"גיירינג, רפאל משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":11500,"n":"גיירינג, שלמה משטמפן","dt":"תריג - כה אלול","dp":"שטמפן","b":"מחכמי שטמפן, חתם-תקסג עם ראשי הקהלה. בנו - רפאל שנפטר בחיי אביו."},{"i":11501,"n":"גיירינג, שמחה משטמפן","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן."},{"i":11502,"n":"גילדברג, מרדכי מביעלסק","b":"ראש ישיבת נוברדוק בביעלסק-פודולסקי-תרצג. כנראה נספה בשואה."},{"i":11503,"n":"גילדרין, שמעון","b":"חכם וסופר, בן אצילים שנדד בעולם, היה בירושלים-תקכו ונאלץ לברוח בגלל גזרות הממשלה. ר ירוחם אלישר רצה לתת לו את בתו לאשה. נכדו(-בן בתו) היינריך היינה."},{"i":11504,"n":"ג'יליבון מוינה","f":"אשר","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":11505,"n":"ג'יליבון מורון, אברהם","b":"מחכמי איזמיר"},{"i":11506,"n":"ג'יליבי, יצחק הרופא מקושטא","k":"בעל שמאל ישראל","b":"רופא בקושטא-שנות ה-ת', מקורב לחצר המלכות, פעל לטובת יהודי ירושלים. חיבר גם \"שפת אמת\"."},{"i":11507,"n":"ג'יליבי, שלמה ממצרים","b":"מחכמי דאמייאט(=פיתום)-מצרים-שנות ה-ת'."},{"i":11508,"n":"ג'ילמיסי, נחום משלוניקי","b":"דיין בשלוניקי-שס בערך - בזמן ר אהרן ן חסון."},{"i":11509,"n":"גילרנטר","k":"ראה: גלרנטר","dt":"תשד","b":"רב בחוסט"},{"i":11510,"n":"גימרק, משה מאלסיאד","b":"נכד ר אברהם קרניץ רבה של אלסיאד. שימש כרב - לא רשמי באלסיאד."},{"i":11511,"n":"גינאט, ברוך מפיעטרקוב","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":11512,"n":"גינז, חיים צבי ממונקטש","f":"שמעון מזענטא","bt":"תרלז","bp":"זענטא","dt":"תרצו - בערך","b":"מצאצאי ר שמואל גינז מאיזנשטט. תלמיד הכת\"ס, ואחיו ר יעקב יוסף גינז מביסרמן. חתן ר פנחס חיים קליין מסעליש. מחכמי מונקטש ומזכיר הקהלה. רשם מתורת רבו - מהשנים תרנז-תרנט."},{"i":11513,"n":"גינז, יהודה ליב מאיזנשטט","b":"מחכמי איזנשטט בזמן כהונת ר עקיבא איגר בפוזנא (אולי ממשפחתו)."},{"i":11514,"n":"גינז, יהושע מאפץ","f":"יעקב יוסף גינז","dt":"תשד","b":"רב באפץ. מחותן עם ר זאב ציטרון מדאראג."},{"i":11515,"n":"גינז, יעקב יוסף מבסרמין","f":"שמעון מזענטא","k":"בעל הרי בשמים","dt":"תרפה - ה ניסן","b":"רב בטשאבא-תרמג, בסרמין(=בוסערמין)-תרנב. חתנו - ר ישכר טייכטל בעל \"אם הבנים\"."},{"i":11516,"n":"גינז, מאיר (גינזמן)","dt":"תלד","b":"שתדלן המדינה. בנו - ר אליה איגר, ומצאצאיו ר עקיבא איגר מפרשבורג."},{"i":11517,"n":"גינז, מרדכי מפרשבורג","f":"שמואל","dt":"תקפג - ג תשרי","dp":"פרשבורג","b":"מחכמי פרשבורג. ש\"ץ בביהכ\"נ הגדול. חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":11518,"n":"גינז, משה מאיזנשטט","k":"חתן ר' עקיבא איגר","b":"רב באייזנשטט-תק\"כ. בניו: ר עקיבא איגר מפוזנא, ר שמחה בונם ממטרדסורף."},{"i":11519,"n":"גינז, משה מטשעטש","b":"רב בטשעטשע-תר\"נ"},{"i":11520,"n":"גינז, שלמה","b":"רב בגינז,רוסקה-תר\"י"},{"i":11521,"n":"גינז-איגר, אליה","f":"מאיר גינזמן","dt":"תסג","b":"גביר. בנו - ליב, מצאצאיו ר עקיבא איגר מפרשבורג."},{"i":11522,"n":"גינז-איגר, משה מהמבורג","f":"שמחה בונם איגר ממטרס","k":"בעל פירוש על האידרא","dt":"תריח - יד תשרי","dp":"המבורג","b":"תלמיד דודו ר עקיבא איגר. מחכמי וילהען, מיושבי הקלויז בהמבורג-תקץ אצל ר ליב בן שאול. הכין לדפוס הרבה מתורת דודו ר עקיבא איגר. נזכר פעמים רבות אצל ר עקיבא איגר ואצל החת\"ס בספריהם. (חתם שמו - גינז-איגר)."},{"i":11523,"n":"גינז-שלזינגר, אלעזר שמחה בונם","f":"שמואל מאבראהאם","dt":"תרע - כד טבת","dp":"באדרג-קרעסטור","b":"נכד ר יצחק נתן ליפשיץ מסנטוב. תלמיד הכת\"ס. רב באבראהאם, טשאבא, באדראג-קרסטור(=קרעסטור). בנו ר משה אב\"ד באדרג-קרעסטור. מחדושיו בתוך \"חוט המשולש\" על פרקי אבות."},{"i":11524,"n":"גינז-שלזינגר, חיים אלתר","f":"משה מקרסטור","dt":"תש..","b":"רב בקרסטור-תרפח על מקום אביו. הו\"ל ספר אביו \"חוט המשולש\". נספה בשואה."},{"i":11525,"n":"גינז-שלזינגר, יהודה צבי מאויבן","f":"שמואל","bt":"תקסז","bp":"איזנשטט","dt":"תרכג - בערך","b":"תלמיד החת\"ס, ודודו ר עקיבא איגר-גינז מפוזנא. חתן ר משה מינץ מאויבן. רב באויבן-תקצו - לא נתמנה לאב\"ד על מקום חותנו - פנה למסחר והתעשר."},{"i":11526,"n":"גינז-שלזינגר, יוסף מפרשבורג","f":"שמחה בונם איגר ממטרס","k":"בעל טל אורות","dt":"תרלא - כד ניסן","dp":"מטרסדורף","b":"חתן ר אברהם משה קלישר מפילא ז\"ל (שאשתו - בת ר עקיבא איגר - נשאה בזיוו\"ש לחת\"ס) והיה סמוך על שלחן חותנו חורגו החת\"ס. החת\"ס הציעו לרבנות ביינק. הו\"ל תשובות החת\"ס - שנמסרו לו מהחת\"ס (בצוואתו מסר החת\"ס את כתביו לבניו - אולם ציין כי נתן רשות לחתנו להדפיסם בחייו). עבר לוינה ושם ניהלה אשתו בית מסחר ספרים. חיבר \"מצות השם\", \"כנף רננים\" ועוד. ?? לא באוצר ??"},{"i":11527,"n":"גינז-שלזינגר, משה מאדרג-קרסטור","f":"אלעזר שמחה בונם","k":"בעל חוט המשולש","bt":"תרכג","dt":"תרפה - ו אד\"ב","dp":"באדראג-קרססטור","b":"תלמיד השב\"ס, וזקנו ר שמואל גינז-שלזינגר מאבראהם. חתן ר אריה ליב ואהלברג מבאדראג-קרסטור, ועבר לשם. רב באדראג-קרסטור-תרנד על מקום חותנו ובנו ר חיים אלתר על מקומו אחריו והו\"ל את ספרו. מתורתו בכתבי עת וקבצים תורניים שנדפסו בתקופתו. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. ?? לא באוצר ??"},{"i":11528,"n":"גינז-שלזינגר, עקיבא מוינה","f":"יוסף מפרשבורג","bt":"תרב","bp":"פרשבורג","dt":"תרנח - ז טבת","dp":"מטרסדורף","b":"תלמיד הכת\"ס, ומהרם שיק. חתן ר יעקב יהודה שטרסר מטאב - חתן הכת\"ס. התישב בוינה והמשיך במפעל אביו בהוצאת ספרי קדש."},{"i":11529,"n":"גינז-שלזינגר, שמואל בנימין","f":"עקיבא מוינה","k":"בעל חדושים בש\"ס","bt":"תרלב","dt":"תרצג - יג אדר","dp":"מטרדסדורף","b":"תלמיד השב\"ס. חתן ר ישראל אולמן מגרוסורדין. מחכמי בודפשט-תרנז ויסד שם הוצאה ובית מסחר לספרי קודש, עבר לוויצען."},{"i":11530,"n":"גינז-שלזינגר, שמואל מאבראהאם","f":"שמחה בונם גינז","bt":"תקעה","bp":"מטרסדורף","dt":"תרנב - כא שבט","dp":"אבראהאם (פעלשא אבראני)","b":"תלמיד החת\"ס, ודודו ר עקיבא איגר. חתן ר יצחק נתן ליפשיץ מסנטוב, ובזיוו\"ש חתן ר שלמה זלמן מינצנט ממיהאלפלווא. רב באבראהאם-תריא."},{"i":11531,"n":"גינזברג, חיים דובער מדולהינוב","b":"פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":11532,"n":"גינטיל, מיכאל משלוניקי","dt":"רפב - כח אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":11533,"n":"גיניאו, אברהם משלוניקי","dt":"תרפז - יט אב","dp":"שלוניקי"},{"i":11534,"n":"גיניאו, יעקב משלוניקי","dt":"תרלה","dp":"חברון","b":"מחכמי שלוניקי וראש ישיבת \"בית יעקב\" שהיתה ידועה בשם ישיבת גיניאו (התקיימה עד השואה). סייע בהדפסת \"חזוק אמונה\" בלאדינו-תר (ושם נכתב בטעות שמו - יצחק)."},{"i":11535,"n":"גיניאו, מאיר חי מירושלים","bt":"תרנד","bp":"ירושלים","b":"תלמיד ביהמ\"ד לרבנים של תנועת \"עזרה\" בירושלים, מזכיר הקהלה הספרדית, וציר בועידת היהודים הספרדים בוינה."},{"i":11536,"n":"ג'יניליו, אברהם משלוניקי","dt":"תכז","dp":"שלוניקי","b":"רב בשלוניקי"},{"i":11537,"n":"ג'יניליו, אלברטו משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":11538,"n":"ג'יניליו, אליעזר מקושטא","b":"מגדולי חכמי קושטא-ש\"כ"},{"i":11539,"n":"ג'יניליו, אליעזר משלוניקי","dt":"תיג - טז טבת","dp":"שאלוניקי","b":"תלמיד ר אשר הכהן ן ארדיט. ר\"מ בשלוניקי."},{"i":11540,"n":"ג'יניליו, שמואל משלוניקי","dt":"שעט - יג טבת","dp":"שלוניקי","b":"ש\"ץ, סופר ורב בשלוניקי."},{"i":11541,"n":"גינינו, אברהם","b":"בשנת תקכז חתם על מכתב רבני צפת לקהילת פיסא."},{"i":11542,"n":"גינס, יוסף בונם מפרשבורג","k":"בעל מצות השם","b":"חיבר \"מצות השם\"."},{"i":11543,"n":"גינץ, שמעון מפרג","bt":"תקג","bp":"אויגסבורג","dt":"תקפד","dp":"פרג","b":"למד בפירטה ובפרנקפורט, למד חכמת החשבון בברלין. חיבר עשרה ספרים בתורת החשבון וכדומה. ולימד חשבון לתלמידים בפרג. למרות שהיה כופר בדת סירב להמיר את דתו - כפי שעשה בנו שנהיה פרופסור למתמטיקה בלינץ. (התגאה בכשרון היהודים בחשבון ותלמיד עברי שלא ידע לענות לו - היה אומר לו כי לא מזרע ישראל הוא)."},{"i":11544,"n":"גינצבורג - משפחה","b":"משפחה באשכנז, פולין, רוסיה ועוד. מקורה בר יחיאל מפורטו שבאיטליה, ונכדו ר שמעון מפוזנא שהתישב בעיר גינצבורג - בשוועבן-גרמניה והיה הראשון שנקרא בשם זה. חלק מבני המשפחה נקראו בשם אולמא - כשם העיר הסמוכה שגם בה התגוררו בני המשפחה."},{"i":11545,"n":"גינצבורג אולמא, אביגדור","f":"אלעזר ליפמן הילדסהים","k":"בעל מראה המוסר","b":"מחכמי פולין-ש'. חיבר אוסף משלים ומליצות מהש\"ס בלשון אשכנז בשם \"מראה המוסר\" - פרג שב."},{"i":11546,"n":"גינצבורג אולמא, משלם מוינה","dt":"תטז - לפני"},{"i":11547,"n":"גינצבורג מנשה יוסף בן משה שלמה","bt":"1850","dt":"ה'תרפה 1925","bk":[["גבעות עולם",""]]},{"i":11548,"n":"גינצבורג רי\"פ, יואל מוילנא","f":"אהרן יהודה ליב","b":"ממשפחת גינצבורג. חתן ר מנחם נחום קצנלנבוגן."},{"i":11549,"n":"גינצבורג שפירא, משה מפרג","f":"צבי הירש","b":"רב בפרג-תקכד. השם - גינצבורג מצד זקנתו - אם אביו. נכדו של ר ר זכריה מנדל שפירא מפרג - חתן ר יוסף גינצבורג מפרג."},{"i":11550,"n":"גינצבורג, אברהם","f":"יחיאל מפורטו","b":"אביו של ר שמעון גינצבורג מפוזנא - ראש משפחת גינצבורג."},{"i":11551,"n":"גינצבורג, אברהם","b":"הו\"ל פירוש הרד\"ק לבראשית - פרשבורג תרב, ו\"קובץ ויכוחים\" לר יצחק אקריש."},{"i":11552,"n":"גינצבורג, אברהם ברוך הלוי מסמי","b":"חתן ר שניאור זלמן מלאדי. רב בסמיליאן. בנו - ר נחמיה בעל \"דברי נחמיה\"."},{"i":11553,"n":"גינצבורג, אברהם חיים מפלאצק","f":"[מרדכי בן חיים ]","b":"אב\"ד פלאצק וגליל מאזיר-תקלז, והסכים אז על \"עטרת יוסף\" לר יוסף מליסקווא זולקוא תקנז. ואולי הוא בנו של ר מרדכי בן חיים מדובראווניצי."},{"i":11554,"n":"גינצבורג, אהרן יהודה ליב רי\"פ","f":"אשר בן קלונימוס קלמן","k":"ליב אשר'ס - רי\"פ","dt":"תקסד - יז אב","b":"חתן ר יעקב מסוכטשוב, וסוקולוב. בניו ר נפתלי הירץ, ר מרדכי קלאצקי (שינה שמו מגינצבורג), ר יואל, ר אברהם רי\"פ,"},{"i":11555,"n":"גינצבורג, אהרן מאיר יעקב","f":"דב","k":"הו\"ל חושן משפט","bt":"תקפ","bp":"גרודנא","dt":"תרכ","dp":"וילנא","b":"מחכמי וילנא ועסק במסחר. חיבר ביאורים לש\"ס. הו\"ל חו\"מ עם ביאור הגר\"א ועם הערות והגהות ממנו. גיסו - ר אלכסנדר משה לפידות."},{"i":11556,"n":"גינצבורג, אהרן מבולטימור","b":"רב בבולטימור-תרח."},{"i":11557,"n":"גינצבורג, אהרן מוילנא","f":"יצחק אייזיק גינזבורג","b":"מגדולי מנהיגי ווילנה"},{"i":11558,"n":"גינצבורג, אהרן שתדלן מוילנא","f":"יצחק איזיק בן שמעון","b":"נזכר בפנקס המדינה-תכז כשתדלן - ולא כינה עצמו גינצבורג."},{"i":11559,"n":"גינצבורג, אורי' בער ממזריטש","f":"אריה ליב בן טוביה","bp":"וילנא","dt":"תריט - טז סיון","b":"חתן ר אלכסנדר זיסקינד מינץ מברודי, ובזיוו\"ש חתן הגביר ר אהרן מינץ ממזריטש, ובזיוו\"ש חתן ר יקותיאל זלמן אשר ענזיל צויזמערער מסטרי. עבר מוילנא למזריטש, גביר במזריטש, ראש המשגיחים בבקור חולים במזריטש. בניו: הגביר ר אריה ליב, ר טוביה. מחותן עם הרבנים והגבירים: ר משה יצחק לוין מקרלין בן שאול, הגביר ר מאיר זוסמן מאוסטרהא, ר מרדכי זאב איטינגא מלבוב, הגביר ר אלכסנדר זיסקינד מינץ מברודי, הגביר ר שאול פפירנא מפאריטש, ר יצחק אליהו לנדא מוילנא, הגביר ר ליבל הלפרין מבריסק, הגביר ר שלמה רוזנצוייג ממזריטש, הגביר ר יודל אפאטוב מוילנא."},{"i":11560,"n":"גינצבורג, איסר","k":"בעל דער תלמוד - תרע","bt":"1872","bp":"דאולטוב-פלך קובנא","dt":"1947","dp":"ניו יורק","b":"סופר, רופא ועתונאי. תלמיד ישיבות וילקומיר, וילנא. היגר לארה\"ב-1893 ולמד רפואה בקורנל. חיבר ספרים מחקרית ומאמרים."},{"i":11561,"n":"גינצבורג, איסר מארה\"ב","f":"מנשה יוסף מסמרגון","bt":"תרמה","bp":"סמרגון","b":"חתן ר חנוך הנדל פרידלנר מפאריטש, תלמיד ישיבות סלובודקה, וולוזין, ור חיים עוזר גרודזנסקי. נסמך מאת: ר רפאל שפירא מוולוזין, ר אליעזר רבינוביץ ממינסק. רב בפאריטש-פלך מינסק, היגר לארה\"ב וכיהן כרב בוילמסברידז-ברונקס. חיבר שו\"ת בכת\"י. גיסו - ר אברהם ועלס מניו יורק."},{"i":11562,"n":"גינצבורג, אליהו שמואל","f":"יצחק אזיק בן אליהו","k":"בעל מאורי אש","dt":"תרנא - כה אייר","b":"מחכמי וילנא. חתן ר מיכאלע זעזמערער, ובזיוו\"ש חתן אחות ר העשיל לוין בעל \"עליות אליהו\". רב באווגוסטואו, וחזר לוילנא. חתנו - ר משה רייכערסון בעל \"חלקת הנקוד\". ?? לא באוצר ??"},{"i":11563,"n":"גינצבורג, אליעזר מהלינקא","k":"בעל דמשק אליעזר","bt":"תרט","dt":"תרצה - טז שבט","b":"רב בהלינקע,קאוועל-תרע\"א"},{"i":11564,"n":"גינצבורג, אליעזר מצפת","f":"שמעון מפוזנא","dp":"צפת","b":"חתן הרמ\"א. עלה לצפת"},{"i":11565,"n":"גינצבורג, אלתר אלעזר משדליץ","f":"חיים יהודה משדליץ","b":"רב בשדליץ על מקום אביו."},{"i":11566,"n":"גינצבורג, אפרים מרדכי","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה. עורך \"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תורה אור\" - שנחאי תשו."},{"i":11567,"n":"גינצבורג, אריה יהודה ליב","f":"נפתלי - בעל שבע רצון","dt":"תקיא - יט חשון","dp":"לבוב","b":"גביר בלבוב."},{"i":11568,"n":"גינצבורג, אריה ליב","f":"משה שלמה מאיליא","bt":"תנ\"ה","dt":"ט\"ו תמוז תקמ\"ה","dp":"קאמייא","b":"נפטר צעיר-בגיל 20 שנה.","bk":[["גבורת ארי",""],["טורי אבן",""],["שאגת אריה",""],["שאגת אריה [השלם]","שו\"ת-מערכות"],["שאגת אריה החדשות","שו\"ת-מערכות"]],"e":"תנ\"ה-תקמ\"ה"},{"i":11569,"n":"גינצבורג, אריה ליב מוולוזין","f":"אשר מוויזון","k":"בעל שאגת אריה","bt":"[תנה]","bp":"וויז'ון-ליטא","dt":"תקמה - כה תמוז","b":"נכד ר ליבל בעל התוספות-רבה של מינסק. ראש ישיבה במינסק-תצג (וכונה בשם ר ליבל ראש ישיבה'), ותלמידיו וקרובו ר רפאל הכהן המבורגר על מקומו אחריו-תקב, (ישנו סיפור כי גורש מהעיר לאחר שפגע בכבוד הרב ר יחיאל הלפרין - כשאמר על דרשתו - כשם שהוא רוקד כך אינו יכול). רב לצד אביו רב הגליל. ומכר את רבנותו לאחיו ר יצחק אברהם. רב בוולוזין-תקי וראש ישיבה שם, סמילאויטש, ושוב בוולוזין, ושני תלמידיו שם ר שמחה ואחיו ר חיים מוולוזין, רב במיץ-תקכה. מחותן עם ר יחזקאל לנדא בעל \"נודע ביהודה\". השיב בענין הגט מקליווא - ופסק להיתר ושכנע את רוב חכמי דורו בצדקתו. חיבר גם \"טורי אבן\" בעזרת תלמידו ר גדליה רוטנבורג שהעתיק את כתביו, ולאחר שכהה מאור עיניו היה קורא בפני רבו לפי בקשתו. חיבר גם \"שות שאגת אריה החדשות\" - והמגיה ר\"מ פלונגיאן - העיד כי ר בצלאל הכהן מוילנא עשה ביקורת על הספר ומחק ממנו דברים שכתב המחבר כנגד רבנים גדולים. בנו ר אשר מקארלסרוא, ומחותן גם עם ר נתן נטע משקלוב - דרך בתו, ונכדו ר נתן נטע נטקין מירושלים. (לפי איזנשטין-מינסק היה בנו של ר אשר בן ליב בעל התוספות שהיה רב בגליל מינסק)."},{"i":11570,"n":"גינצבורג, אריה ליב מויזון","f":"מאיר גינזבורג","b":"רב בויזון-תק\"מ"},{"i":11571,"n":"גינצבורג, אריה ליב מוילנא","f":"משה ר\"א ר\"ת","k":"ר ליב כתבן","dt":"תקל","dp":"וילנא","b":"גביר ופרנס בוילנא-תקכט. חתניו - ר חיים מוולוזין, ור חנוך זונדל בן יצחק טריוויש. בניו ר שמואל מהורדנא, ר יצחק מהורדנא , ור נטע."},{"i":11572,"n":"גינצבורג, אריה ליב מוילנא","f":"יצחק איזיק בן אליהו","k":"ליבל איזיק'ס","bt":"תקנו","dt":"תרי - כה ניסן","dp":"וילנא","b":"נכד ר אליהו פעסעלעס (ראש משפחת פרנס), מצאצאי בעל \"באר הגולה\". רב בוילנא-תקצה על מקום ר משה זאב ליפשיץ. חתן ר חיים גיטקע טויבה'ס."},{"i":11573,"n":"גינצבורג, אריה ליב מוילקוביסק","b":"ספרא ודיינא בוילקובישק(=וילקוביסק)."},{"i":11574,"n":"גינצבורג, אריה ליב מיאנוב","k":"בעל אבק מוגמר","b":"מצאצאי ר אלישע בעל \"פי שנים\" ו\"קב ונקי\". רב ביאנאווע(=יאנוב). נכדו - ר יהודה ליב פיין מאסמינא. חיבר \"אבק מוגמר\" - בכת\"י, ובספרו תולדותיו."},{"i":11575,"n":"גינצבורג, אריה ליב פייגעס מויל","f":"טוביה בן אברהם אבלי","b":"מחכמי וילנא. אביו של ר אורי' בער ממזריטש."},{"i":11576,"n":"גינצבורג, אשר - אחד העם","f":"ישעיהו מגעפישיצע","k":"אחד העם","bt":"תרטז","bp":"קווירא","b":"התישב באודסה. פרסם מאמרים תחת השם \"אחד העם\". חיבר ספרים ומאמרים רבים. ביקר בארץ. ממיסדי חברת \"אחיאסף\", הו\"ל \"השלוח\"."},{"i":11577,"n":"גינצבורג, אשר אהרן","f":"הרוזן שמעון גינזבורג","b":"רב-שנת ש\"כ"},{"i":11578,"n":"גינצבורג, אשר אנשיל מפרג ווינה","f":"יוסף גינזבורג","dt":"תעט - י אייר","b":"רב פעלים בפרג,ווינה"},{"i":11579,"n":"גינצבורג, אשר לעמל אהרן אולמא","f":"שמעון מפוזנא","dt":"שסא","b":"רב באולמא-שן. זקנו של ר יוסף מפיורדא בעל \"תורת יוסף\". בנו ר יעקב מקרידבורג חתן דודו ר אליעזר גינצבורג."},{"i":11580,"n":"גינצבורג, אשר מהורדנא","f":"בצלאל מהורדנא","b":"גביר ופרנס בהורדנא. גיסו של ר אברהם יונה יעוונין בעל חדושי מהרא\"י."},{"i":11581,"n":"גינצבורג, אשר מויזון","f":"שאול מפינסק","k":"בעל מעונות אריות-כתי","dt":"תקא - אחרי","b":"רב בוויזון-תנה-תסח, על מקום ר צבי הירש הלוי בעל \"אספקלריא המאירה\", ואחר כך חבר בועד בגליל עליון דרוסיה - מינסק או פינסק, וחתם בפנקס ועד המדינה. אב\"ד בפינסק-תעד או תפ או תצב. חתן ר אברהם קצנלנבוגן וגיסו של ר יחזקאל קצנלנבוגן מאה\"ו. מחדושיו בספרי חכמי דורו. בנו ר אריה בעל \"שאגת אריה\". גיסו - יהודה בן ליב - אביו של ר יעקב בעל \"מורה צדק\". חתם בראש קבוצת רבנים על זכות \"חזקה\" לקראים בליטא על ענפי מסחר שונים. חיבר גם \"אמרי בינה\"."},{"i":11582,"n":"גינצבורג, אשר מוילנא","f":"אהרן גינזבורג","b":"מגדולי וילנה,מנהיג מדינה-תל\"ג-תמ\"ו"},{"i":11583,"n":"גינצבורג, אשר מוילנא","f":"קלונימוס קלמן מפינסק","k":"ר אשר אבא קלאצעס","dt":"תקנא - כג אד\"א","dp":"וילנא","b":"חתן ר אברהם אבא קלאצעס. חתנו - ר ישכר בער בן שלמה זלמן - אחי הגר\"א. פרנס וגבאי דצ\"ג בוילנא, חתם על כתב הרבנות של ר שמואל בוילנא. בניו ר אהרן יהודה ליב אשר'ס, ר בנימין וולף מוילנא-נפטר בחיי אביו, ור שמעון מוילנא-נפטר בחיי אביו. נכדו - ר בנימין וולף קלצקי."},{"i":11584,"n":"גינצבורג, אשר מסוכטשוב","f":"מנחם נחום גינזבורג","b":"רב בסאכטשוב-תר\"מ"},{"i":11585,"n":"גינצבורג, אשר קלמנס מוילנא","f":"אהרן שתדלן מוילנא","k":"ר אשר ר קלמנס מוילנא","dt":"תמז - אחרי","b":"נכדו או חתנו של ר קלונימוס קלמן בן שלמה מניישטעטיל-שצה, וכנראה על שמו נקרא - ר קלמנס. בועד המדינה-תלג. בנו ר יצחק איזיק."},{"i":11586,"n":"גינצבורג, בן ציון מסוראז","f":"צמח","bt":"תרכד","b":"רב בסוראז-פלך גרודנא-תרנד."},{"i":11587,"n":"גינצבורג, בנימין","f":"שמעון","b":"נבחר-תקלז ע\"י ועד מוהילוב לעשות תקנות רצויות בעד קהילת פעטראוויצי, יחד עם ר יוסף בן מאיר גינצבורג, ור משולם פיבש בהר\"א חפץ, ונזכרו בפנקס פעראוויצי."},{"i":11588,"n":"גינצבורג, בנימין וולף הרופא","b":"הלך מפולין ללמוד רפואה בגאטינגען-גרמניה-תצז. ונעזר בגביר ר אליהו מאדיבורג. שאל את היעב\"ץ בענין ניתוח גופות בשבת לצרכי לימוד והיעב\"ץ השיב לו בכבוד. חיבר ספר בלטינית - געטינגען תקג, בענין רפואה והתלמוד. החכם דוד מגיד בספרו - משפחת גינצבורג - אומר - יתכן והוא החכם מאוסטרהא שמחידושיו ב\"גורל יהושע\" לר יהושע בן יהודה ליב מקאסווי. אולם ב\"מזכרת גדולי אוסטרהא\" - סובר כי המדובר בחכם אחר - בנו של ר יוסף גינצבורג אב\"ד אוסטרהא שנקרא גם הוא ר בנימין וולף גינצבורג."},{"i":11589,"n":"גינצבורג, בנימין וולף מאוסטרהא","f":"יוסף - לקט יוסף?","b":"נכד ר מרדכי מבריסק, ונינו של ר בנימין וולף ונקרא כנראה על שמו. העדות לקיומו - ב\"גורל יהושע\" הובא חדושים מר בנימין וולף גינצבורג מאוסטרהא - ודעת מנחם מנדל ביבער (מזכרת אוסטרהא) שאין המדובר ברופא מפולין כי אם בבנו של רבה של אוסטרהא שהיה לו בן ע\"ש זקנו."},{"i":11590,"n":"גינצבורג, בנימין וולף מוילנא","f":"אשר בן קלונימוס קלמן","dt":"תקמח - כז טבת","dp":"וילנא","b":"פרנס מחכמי ומנהיגי וילנא. חתן ר שלמה זלמן ממיר. נפטר בחיי אביו. נקבר לצדו של ר דוד בן שמעון ברוידא."},{"i":11591,"n":"גינצבורג, בנימין זאב","b":"רב במיץ-ת\"כ"},{"i":11592,"n":"גינצבורג, בנימין מויזון-ליטא","f":"מאיר מוויזון בן יצחק","b":"אב\"ד גליל וויזון-תקמב על מקום אביו. בנו ר יונה דיין בוילנא-תקנז."},{"i":11593,"n":"גינצבורג, בנימין ממיץ","b":"רב במיץ-שנת ת'"},{"i":11594,"n":"גינצבורג, בנציון מיאנישוק","b":"מגיד שיעור ביאנישוק. חתנו - ר אהרן שמואל כץ מראסיין."},{"i":11595,"n":"גינצבורג, בצלאל מהורדנא","f":"שמואל מהורדנא","b":"גביר ופרנס בהורדנא, בניו ר אשר פרנס בהורדנא, ר ליב. וחתנו ר אברהם יונה יעוונין בעל \"חדושי מהרא\"י\" על הרמב\"ם.."},{"i":11596,"n":"גינצבורג, בצלאל מטרנופול","b":"דיין בטרנופול, בנו ר יוסף מילא את מקומו."},{"i":11597,"n":"גינצבורג, ברוך","dt":"תשג","b":"רב ביאנווע"},{"i":11598,"n":"גינצבורג, ברוך נחום","bt":"ה'תרמב","dt":"תש..","b":"רב בקיבארט-ליטא. נספה בשואה.","bk":[["מקור ברוך [עניני קדשים-טהרות]",""]]},{"i":11599,"n":"גינצבורג, גבריאל יעקב מקאמניץ","f":"נפתלי הרץ מוילנא","bt":"תקנג","bp":"וילנא","dt":"תריג - כד ניסן","dp":"סימפעראפל","b":"לאחר שנתייתם גדל אצל זקנו ר אהרן יהודה ליב. חתן דודו ר יואל בן ר אהרן יהודה ליב, ובזיוו\"ש חתן הגביר ר יוסף יוזל מויטבסק, ובזיוו\"ש חתן ר ליפעלי מרגליות. גביר ונדבן בויטבסק, קמניץ, סימפרפול, וילנא. תרם לנצרכים ומוסדות יהודיים בוילנא, ויטבסק, קמניץ סימפרופול-בנה שם בית חולים יהודי ולפי המלצת שר האוצר הרוסי העניק לו הצאר ניקוליא הראשון אזרחות כבוד לדורותיו. אביו של הברון יוסף יוזל גינצבורג, וחתניו ר חיים יהושע השיל רוזנברג, ור זאב בן נתן מערפערט. על מצבתו קינה מהמשורר אד\"ם הכהן."},{"i":11600,"n":"גינצבורג, גדליה נסויזער מאוסטר","k":"גדליה דער גרויסער","b":"רב בכמה קהלות, אוסטרהא-תקם. חתנו - ר אריה ליב ראצקער(=רצקר) מראדין."},{"i":11601,"n":"גינצבורג, גרשון","f":"משלם זלמן גינזבורג","b":"רב בהארקי-תקמ\"ד"},{"i":11602,"n":"גינצבורג, גרשון חנוך מבריסק","f":"ישראל בן ציון","k":"הו\"ל כבוד התורה","b":"חתן ר יוסף שלמה מזל מארגנטינה. מחכמי בריסק ועבר לארגנטינה. הו\"ל ספר חותנו \"כבוד התורה בארגנטינה\"."},{"i":11603,"n":"גינצבורג, גרשון מרוזדוביץ","b":"אב\"ד רוזדוביץ, רב בחודרוב-תריד, אולי בנו הוא ר יעקב אב\"ד חודרוב."},{"i":11604,"n":"גינצבורג, דב בער מהמבורג","f":"שאול מויזון","b":"רב בהמבורג. אחיו - ר אשר אביו של בעל שאגת אריה. בנו - ר יעקב מוילנא."},{"i":11605,"n":"גינצבורג, דב בר מברוד","k":"הו\"ל לשון למודים","bt":"תקלו","bp":"ברודי","dt":"תקפא","b":"נתמך ע\"י ר אלכסנדר קאליר הגביר מברודי שדאג להשכלתו. סופר קהילת ברודי, חיבר הגהות והערות ל\"לשן למודים\" לרמח\"ל. פרסם שירים ב\"המאסף\", וב\"בכורי העתים\". בנו המשורר ר חיים."},{"i":11606,"n":"גינצבורג, דובער","f":"משלם זלמן","b":"רב דמדינת רוסיה"},{"i":11607,"n":"גינצבורג, דוד טעבל מירושלים","f":"שמעון (שמשון?)","b":"מחכמי ירושלים בשנת תס, חתם עם חכמי ירושלים על המכתב נגד סיעתו של ר יהודה החסיד שנתפסו לשבתאות."},{"i":11608,"n":"גינצבורג, דוד מאליק ופינסק","f":"שאול מפינסק","bp":"[פינסק]","dt":"תקיא - אחרי","b":"רב באליק-תפב, וחזר לפינסק-תקיא. הסכים על כמה ספרים ובהם \"זרע ישראל\", ועל ספר מחותנו ר אהרן זליג בן יואל פיבש מאוסטרהא \"עולת אהרן\" אופיבך תצג, ועוד. מחותן נוסף - ר אליהו פינס בעל \"תנא דבי אליהו\". נזכר בהגהות ל\"אור תורה\" לר מנחם די לונזאנו."},{"i":11609,"n":"גינצבורג, דוד מאמשטדם","f":"אשר אנשל מאמשטרדם","b":"עסק במסחר באמשטרדם עם אביו, ופעם נסעו לפורטוגל ולא חזרו עשר שנים והתירו נשיהם עגונות - ונידון בבי\"ד ונזכר ב\"חות יאיר\" לר יאיר בכרך."},{"i":11610,"n":"גינצבורג, דוד מבורשטין","f":"נתן בן מתתיהו מאויבן","b":"רב בבורשטין. הסכים על \"הדרת אליהו\"-תקמה."},{"i":11611,"n":"גינצבורג, דוד מויזון","f":"יצחק איזיק בן שאול","b":"רב במאהליב והגליל-תצג-תצט, רב בויזון והגליל על מקום אחיו ר מאיר, כשבטל הגליל עבר לכהן כרב בסואנציאן, וידז."},{"i":11612,"n":"גינצבורג, דוד מפולדא","f":"יצחק","k":"בעל דוד משכיל","b":"רב בפולדא-שנה. אולי הוא נכדו של ר שמעון מפוזנא. חיבר גם \"אמת המשפט\", ספריו בכת\"י ונזכרו ב\"אור החיים\" לר חיים מיכל."},{"i":11613,"n":"גינצבורג, דוד מצרפת","f":"מאיר","k":"בעל דברי דוד האחרוני","bp":"ברייזאך-צרפת","dt":"תקסח","b":"הגיע מברייזאך ואורינגען בצרפת, ללמוד בישיבת ר משולם זלמן הכהן בפיורדא, וחזר לארצו. וחיבר ספרים ודרש ולימד תלמידים. אשתו הו\"ל את כתביו בשם \"דברי דוד האחרונים\" פפד\"א חשד (אצל רוסט נרשם תרכז - אך הדבר לא יתכן שאשתו היתה אז בחיים)."},{"i":11614,"n":"גינצבורג, דוד מרוזדול","dt":"תקכד","b":"אב\"ד רוזדול, בנו ר משה אחריו על כסאו."},{"i":11615,"n":"גינצבורג, דוד מרוצ'סטר-ארה\"ב","f":"יצחק איזיק מפטרבורג","bt":"תרלו","bp":"ווידז","b":"גדל אצל זקנו בזמן שאביו כיהן כרב בפטרבורג. הגיע לארה\"ב-תרנח וכיהן כרב ברוצ'סטר. חיבר ספרים בהלכה ואגדה. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":11616,"n":"גינצבורג, הלל","b":"רב בראדין"},{"i":11617,"n":"גינצבורג, הרץ","dt":"תמז - כב תמוז","b":"רב בסלוצק"},{"i":11618,"n":"גינצבורג, הרץ מוינה","f":"אברהם אטטינגען","b":"גביר באטטינגען, ועבר לוינה והיה סוכן בחצר המלך, יצא בגלות-תל עם אחיו ועבר לפרשעמיסל. נכד ר מאדל גינצבורג בן ר שמעון מפרג (כך אצל כרמולי בשם כת\"י הנקרא \"סדר שלשלת היוחסין של ר שמעון גינצבורג) והכוונה לר מרדכי מאטל בן ר שמעון מפוזנא (שהיה גם בפרג). בניו ר משה מפינטשוב, ר זעליג מסלוצק, ור ליב מוינה - שלשתם היו גם רופאים."},{"i":11619,"n":"גינצבורג, זנוויל","f":"שמעון מפוזנא","b":"נזכר בהקמת מהר\"ם שי\"ף כבנו של ר שמעון גיצבורג מוורמייזא וכנראה הוא ר שמעון מפוזנא. נזכר ב\"חוט השני\" לר משה שמעון ואביו ר שמואל בכרך."},{"i":11620,"n":"גינצבורג, זעליג מסלוצק-ליטא","f":"הירץ מוינה","b":"רופא בסלוצק-ליטא."},{"i":11621,"n":"גינצבורג, חיים אליעזר","b":"רב בקארלין-תר\"מ"},{"i":11622,"n":"גינצבורג, חיים יהודה משדליץ","bt":"תרטז","dt":"תרצ - יב אייר","b":"רב בשדליץ-תרסז. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"קובץ דרושים\" - פיעטרקוב תרפג. בנו - ר אלתר אלעזר משדליץ."},{"i":11623,"n":"גינצבורג, חיים מאיר משימבורג","f":"מרדכי","k":"בעל שפוט השופטים","b":"נכד ר שמעון גץ. רב בשיסבורג, עבר לבירז והתפרנס ממסחר, יסד ישיבה ולימד תורה."},{"i":11624,"n":"גינצבורג, חיים מנחם מסטרוזיניץ","f":"שלום גרשון מסטרוזיני","k":"בעל מסלות חיים","bt":"תרעא","bp":"ברגסאס","dt":"תשנט","b":"תלמיד ישיבות ברגסאס, חוסט. חתן האדמור חנוך הניך טברסקי ממאלין שיקגו. נסמך מאת: רי\"צ דושינסקי, ר אלימלך פרידלנדר מבארגא פרונד, ר משה אהרן קרויס מבאנאי. היגר לשיקגו לפני השואה. חתן רח\"ה טברסקי ממלין. רב במיניאפוליס-מינסוטה. עלה לארץ-תשלט וכיהן כרב בבית וגן. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט, ועוד. פרסם מאמרים ב\"אוצר הדרושים\" לאחיו ר מרדכי הי\"ד."},{"i":11625,"n":"גינצבורג, חיים מקרמניץ ירושלים","f":"ראה: הורביץ, חיים","k":"בעל חיבת ירושלים"},{"i":11626,"n":"גינצבורג, חנוך הניך","dt":"תרסג - יא תמוז","b":"רב בהיידוצישאק-תרן. בנו - הסופר א. גינצבורג הספידו ב\"המליץ\"."},{"i":11627,"n":"גינצבורג, ידידיה מז'אזמיר","b":"רב בז'אזמיר, ור יהושע השל אליאשזון על מקומו אחריו. חתנו ר חיים ש\"ס"},{"i":11628,"n":"גינצבורג, יהודה אשר מסלאנט","f":"מנחם","dt":"תקפג - א סיון","dp":"וילנא","b":"מחכמי סלאנט-תקע, משכיל ובקי בחכמות ושפות. עבר לוילנא בניו ר מרדכי אהרן גינצבורג = רמא\"ג, ר שמואל זאב ור משה ליב. מחיבוריו נדפוס אגרות בסוף ספר \"דביר\"."},{"i":11629,"n":"גינצבורג, יהודה ליב","f":"שמעון מסלוצק","k":"בעל עמודי עולם","b":"רב-שנת ת\"ס. חיבר \"עמודי עולם\" אמשטרדם תעג."},{"i":11630,"n":"גינצבורג, יהודה ליב","f":"מאיר מוויזון בן יצחק","b":"כנראה מרבני ליטא. הסכים על \"עוזר ישראל\" שקלוב תקלח."},{"i":11631,"n":"גינצבורג, יהודה ליב","f":"צבי מאראניאש-מעדיאש","dt":"תרצג - יט כסלו","b":"רב באראניאש-מעדיאש ליד סטמר-תרנג על מקום אביו. התפרסם כשבזמן חגיגות האלף לממלכה ההונגרית הוריד את דגל המדינה מעל בית הכנסת - ועל כך נחקר בידי השלטונות."},{"i":11632,"n":"גינצבורג, יהודה ליב מאראניאש","f":"צבי הירש","bt":"תרכו","dt":"יט כסלו","b":"נכד-אבי אמו ר שמואל שמלקא קליין בעל \"צרור החיים\". רב באראניאש-מעדיאש(=אראניאץ-מעדיעץ)-תרנג. חתן ר שמואל רוטנשטין מסטמר."},{"i":11633,"n":"גינצבורג, יהודה ליב מברלין","f":"עקיבא","k":"לוין ווייט-פייט","dt":"תפא - ג אייר","b":"גביר בברלין, היה אחראי על קניית הזהב עבור אוצר המטבעות של המלך, נפטר בחיי אביו והכסף נעלם, והיה קצף נגד היהודים עד שר מיכל חסיד החרים את מי שיודע היכן הכסף."},{"i":11634,"n":"גינצבורג, יהודה ליב מדנבר-ארה\"","f":"דב בער","k":"בעל מוסר המשנה","bt":"תרמה","bp":"וילאן-פלך ויטבסק","dt":"תרצו או תשו","b":"תלמיד ישיבת סלובודקה. רב בירוסלב, היגר לארה\"ב וכיהן כרב בניו הייבן-קונטיקט, קהלת \"זרע ישראל\" בדנבר-ארה\"ב-תרצא. חיבר גם \"ילקוט יהודה\"."},{"i":11635,"n":"גינצבורג, יהודה ליב מלאזדיי","b":"רב בלאזדיי-ליטא-תרלב."},{"i":11636,"n":"גינצבורג, יהודה ליב מפילפיאווע","b":"רב בפילפיאווע - בשנות ה-תק'. נזכר ב\"עמודי אור\" לר יחיאל העלר - קניגסברג תרטו."},{"i":11637,"n":"גינצבורג, יהודה ליב שאול","f":"רפאל יוסל","bt":"תרלב","dt":"תשג","b":"תלמיד אביו בקלויז של ר שמעון מרקל בקובנה. רב ביאקובשטט-תרנו - למעלה מ-40 שנה."},{"i":11638,"n":"גינצבורג, יהודה שמעון","b":"רב, היה מהמערערים על הגט מקליווא-תקכו."},{"i":11639,"n":"גינצבורג, יואל מבורשטין","f":"יעקב משלם","bp":"זולקווא","dt":"תשב","dp":"בקטשביץ","b":"אביו היה רבה של חודרוב. היה ראש ישיבה בברזאן אצל המהרשם. רב בבורשטין-תרסח או תרע עד השואה."},{"i":11640,"n":"גינצבורג, יונה מויזון ווילנא","f":"בנימין מויזון","b":"דומ\"צ בוילנא-תקנו."},{"i":11641,"n":"גינצבורג, יוסף","f":"מאיר מוויזון בן יצחק","b":"אביו של ר בן ציון אביו של ר דב בער מהורדנא אביו של ר אהרן מאיר יעקב מוילנא שהו\"ל חדושי הגרא על חו\"מ."},{"i":11642,"n":"גינצבורג, יוסף יוזל מפטרבורג","f":"גבריאל יעקב","k":"ברון גינצבורג","dt":"תרלח - ח שבט","dp":"פאריס","b":"גביר וברון, חבר בועד הרבנים מטעם ממשלת רוסיה-1861. נספד בכל קהלות רוסיה. לזכרו \"פורת יוסף\" לר צבי הירש הכהן מקובנא. נוסח קברו ע\"י המשורר יל\"ג (נדפס ב\"האסיף\" תרמט). לזכרו \"שמעתתי דרבנן\" - אודסה תרמז."},{"i":11643,"n":"גינצבורג, יוסף ליב מסקלט","b":"רב בסקלט-תרנו. תשובות אליו בשות מהרשם."},{"i":11644,"n":"גינצבורג, יוסף מאוסטרהא","f":"מרדכי מבריסק","k":"בעל לקוטי יוסף","dt":"תעו - א כסלו","dp":"אוסטרהא","b":"חתן ר שמואל שמלקא ז\"ק מאוסטרהא. רב בחעלם-תכג, בריסק-תל, אוסטרוב(=אוסטרהא). חיבר \"לקט יוסף\". בניו: הרב מאליק (ואולי הוא טעות), ר מרדכי מזבריז המכונה ר מרדכי ר אייזיקס. חתנו - ר אברהם אב\"ד זוויהל. (נכדו היה ר שמואל שמלקא ב\"ר צבי הכהן ???). (לפי אוצר הרבנים , בניו: ר אשר אנשל (3551), ר משה (14541). חתנו - ר זכריה מנדל שפירא (5595)"},{"i":11645,"n":"גינצבורג, יוסף מזולקוא","b":"דמתקרי דן אב\"ד סניטון. רב בסניטון-תקנב, הסכים אז על \"אהבת דודים\" לר בנימין מזלאזיץ."},{"i":11646,"n":"גינצבורג, יוסף מטרנופול הזקן","b":"מחכמי טרנופול. קרובו של ר יהושע השל בן יצחק באבד מטרנופול - ונזכר בספרו \"ספר יהושע\"."},{"i":11647,"n":"גינצבורג, יוסף מטרנופול הנכד","f":"בצלאל (כנראה)","b":"אב\"ד טרנופול. מצאצאי ר יוסף מטרנופול המוזכר ב\"ספר יהושע\"."},{"i":11648,"n":"גינצבורג, יוסף מסניאטין","f":"חיים","k":"המכונה דן","bt":"תק","bp":"זולקווא","dt":"תקס","b":"גיסו של ר נחמן מהורודנקא. מחכמי ברודי. רב בסניאטין-תקל."},{"i":11649,"n":"גינצבורג, יוסף מפרג","b":"בנו ר אשר אנשיל מוינה - נפטר תעט, וחתנו ר זכריה מנדיל פרנקל מפרג -תסד אחד מחמשת הדיינים הנקראים אפלנטים."},{"i":11650,"n":"גינצבורג, יוסף מפרמישלא","f":"משה גינזבורג","b":"ראב\"ד בפרעמיסלא-תק\"ע"},{"i":11651,"n":"גינצבורג, יוסף משאט","f":"מאיר","b":"רב בשאט, פטרוביץ. נבחר-תקלז ע\"י ועד מוהילוב לעשות תקנות רצויות בעד קהילת פטרוביצי, יחד עם ר בנימין בן שמעון גינצבורג, ור משולם פיבש בהר\"א חפץ, ונזכרו בפנקס פעראוויצי."},{"i":11652,"n":"גינצבורג, יחיאל מיכל מקאשיווקא","f":"שמואל מקאשיווקא","k":"אדמור מקאשיווקא","b":"חתן ר משה אפרתי מברדיטשוב-בן ר אליעזר מפינסק, ובזיוו\"ש חתן ר יהודה מאיר משפיטובקא (קוריץ). חתנו - ר יצחק מנסכיז."},{"i":11653,"n":"גינצבורג, יעקב אולמא","f":"אשר אהרן לעמל","dt":"שע","b":"חתן דודו ר אליעזר גינצבורג. רב בפרידבורג, פרידלאנד. ומתלמידיו - בעל תוי\"ט, ר אליהו בעל שם לואנץ מוורמייזא, ר אליעזר זוסמן מפולדא, ר משה בורגל רב בפרידבורג על מקום רבו אחריו."},{"i":11654,"n":"גינצבורג, יעקב מוילנא","f":"מאיר מוויזון בן יצחק","b":"מחכמי וילנא - שנות ה-תק'. נזכר בפנסק בוילנא."},{"i":11655,"n":"גינצבורג, יעקב מפרג","f":"יצחק דוד","k":"בעל זרע יעקב","dt":"תקנח - בערך","b":"רב בפרג-תקכח, אחיו של ר משה מפרג. תלמיד ר מאיר פישלס מפרג. ר\"מ בישיבה בפרג. , רב בהעלישוי"},{"i":11656,"n":"גינצבורג, יעקב מפרידבורג","b":"חתן דודו ר אליעזר גינצבורג. רב בפרידבורג, פרידלאנד. ומתלמידיו - בעל תוי\"ט, ר אליהו בעל שם לואנץ מוורמייזא, ר אליעזר זוסמן מפולדא, ר משה בורגל רב בפרידבורג על מקום רבו אחריו."},{"i":11657,"n":"גינצבורג, יעקב משלם מזדובה","f":"ישראל מזדובה","k":"בעל משפטים לישראל","bt":"תרנה","bp":"סטרוזזיניץ","dt":"תשך","b":"חתן רמ\"מ באב\"ד מגורא-הומורא. רב בגורא-הומורא על מקום חותנו יחד עם גיסו ר אברהם משה, בוקרשט. ניצל מהשואה. עלה לירושלים-תשז. רב וכותב באנציקלופדיה תלמודית. חיבר \"קול יעקב\" סטמר תרצה. פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":11658,"n":"גינצבורג, יעקב משלם מחודרוב","f":"שמואל מחודרוב","dt":"תרנו","b":"אב\"ד חודרוב-תרך בערך על מקום אביו, בנו ר משה ראובן מילא את מקומו אחריו."},{"i":11659,"n":"גינצבורג, יצחק אברהם מסמילוביץ","f":"אשר מויזון","dt":"תקלו - יט חשון","b":"רב בוויזון, התישב בסמילוביץ-פלך מינסק - כאביו לפניו, וכיהן כרב גליל מינסק-תקט עד תקטו ור רפאל הכהן על מקומו אחריו (לאחר שהתפטר מהרבנות ונשאר לגור במינסק), והיה מחלוקת עם ר משה הלפרין שירש את רבנות מינסק מאביו בעל \"סדר הדורות\". אחיו - בעל שאגת אריה. הסכים על \"באר אברהם - שקלוב תקמג, \"תפארת ישראל זוטא\" פפד\"א תקלד. (תאריך פטירתו נרשם גם - תקעו)."},{"i":11660,"n":"גינצבורג, יצחק איזיק"},{"i":11661,"n":"גינצבורג, יצחק איזיק","f":"שמעון גינזבורג"},{"i":11662,"n":"גינצבורג, יצחק איזיק","f":"שמעון מסלוצק","b":"מתורתו בספר אחיו ר נפתלי איזיק ב\"נפתלי שבע רצון\"."},{"i":11663,"n":"גינצבורג, יצחק איזיק","f":"ר אשר ר קלמנס","b":"חתן ר משה גאלדש מפינסק - נכד הט\"ז."},{"i":11664,"n":"גינצבורג, יצחק איזיק אולמא","f":"שמעון גינצבורג מפוזנ","b":"נקרא גם בשם אולמא כמו חלק ממשפחת גינצבורג. רב בפפערשי-שע."},{"i":11665,"n":"גינצבורג, יצחק איזיק הלוי","b":"רב בגינצבורג-ש'. מחותן עם ר שמעון גינצבורג מפוזנא, ועמד לימין מחותנו בכמה מחלוקות, היה במחלוקת עם ר אליעזר טרוויש מפפד\"מ ותמכו בו הרמ\"א, מהר\"ם קצנלנבוגן מפדובה ועוד."},{"i":11666,"n":"גינצבורג, יצחק איזיק מדריבין","f":"שאול מפינסק","dt":"תקג","b":"חתן ר משלם זלמן מירלש מהמבורג. רב בדובנא-תעב על מקום ר שמואל בן שלום שכנא כהנא, ור אלעזר באבד על מקומו אחריו, דריבין-פלך מוהליב-תצא (ולפי פעסיס אב\"ד מוהליב-תעה), אב\"ד מדינת רוסיה-תפג על מקום אביו. בניו - ר משלם זלמן, ר מאיר ור דוד - שניהם כיהנו כרבני ויזון והגליל. גיסו - החכם צבי."},{"i":11667,"n":"גינצבורג, יצחק איזיק מוורמייזא","f":"שמעון שאטלס","b":"מחכמי וורמייזא, ואחר גירוש-שעה עבר לפולין. חתנו ר אברהם דיין בפוזן ונכדו ר חנוך העניך בעל \"ראשית בכורים\" - רב בגניזין."},{"i":11668,"n":"גינצבורג, יצחק איטציג מפרשמיסל","f":"ליב מוינה ופרשמיסל","b":"רופא בפרשמיסל."},{"i":11669,"n":"גינצבורג, יצחק אליהו","b":"מו\"צ בביאליסטוק-תר\"מ"},{"i":11670,"n":"גינצבורג, יצחק דב בער","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":11671,"n":"גינצבורג, יצחק דוד מפרג","f":"משה גינזבורג","b":"מחכמי פרג-ת\"ק"},{"i":11672,"n":"גינצבורג, יצחק מהורדנא","f":"אריה ליב מוילנא-כתבן","b":"רב בהורדנא. גיסו של ר חיים מוולוזין, וגיסו מצד אשתו של ר וולף בן ישראל אינהורן בעל פירוש מהרז\"ו על המדרש - וילנא תרטו."},{"i":11673,"n":"גינצבורג, יצחק מויטקווא","b":"רב בוויטקווא-תק\"מ"},{"i":11674,"n":"גינצבורג, יצחק מוילנא","f":"חיים [מסלוצק]","b":"חתן ר נטע ראשקעס מצאצאי \"בער הגולה\". גביר ופרנס בוילנא-תעו, וחתם כמה פעמים על תקנות, ובהם עם ראשי העדה-תץ, ויתכן שהיה עדיין פרנס ב-תקב. חתנו - ר דוד בן משה חר\"ז (חתן ר זלקינד) בעל \"מצודת דוד\" - אלטונא תצו."},{"i":11675,"n":"גינצבורג, יצחק מנאויעלנא","dt":"תשג","b":"רב בנאוויעלנא"},{"i":11676,"n":"גינצבורג, יצחק פנחס מסטרוזיניץ","f":"שלום גרשון מסטרוזניץ","dt":"תשנה","b":"רב בבקוי. היגר לארה\"ב וכיהן כרב בלוס אנגלס."},{"i":11677,"n":"גינצבורג, יקותיאל זלמן מדרוהוב","f":"יוסף גינזבורג","b":"רב בדראהביטש-ת\"ר"},{"i":11678,"n":"גינצבורג, ישכר בריש שלמה","f":"אפרים","bt":"תרלג","b":"תלמיד זקנו ר יוסף נחמיה מסטאשוב. נסמך מאת: ר יחיאל מיכל מאוסטרובצה, ר יהודה ליב מאקאווע בעל \"חבלים בנעימים\". רב בשטעשקצין-פלך קיעלץ-תרסג."},{"i":11679,"n":"גינצבורג, ישראל חסיד מהמבורג","f":"יעקב","k":"ישראל חסיד","dt":"תקכז - ח שבט","dp":"אלטונא","b":"דיין בהמבורג אצל ר יחזקאל קצנלנבוגן. נזכר אצל ר יעקב עמדין."},{"i":11680,"n":"גינצבורג, ישראל מזארעצא-וילנא","f":"אליעזר בן יואל","bt":"תקמד","bp":"וילנא","dt":"תריז - ח תמוז","dp":"וילנא","b":"מצאצאי ר יעקב גינצבורג אולמא. אביו נהרג במצור הרוסי על וילנא-תקנד. נתברך ע\"י הגר\"א. תלמיד ר אברהם דנציג והו\"ל את ספרו \"חיי אדם\" וכתב לו הקדמה, ובהמלצת רבו כיהן כאב\"ד בזארציה(=זארעצא)-ליד וילנא-תקפד והקים שם ישיבה. מתלמידיו ר קלמן שולמן, הפרופסור המומר דניאל חאוולסון. הו\"ל מחדש את ספרי רבו. הניח כתבים בכת\"י. נספד ב\"קינת יהודא וישראל\" וילנא תריח. חתנו - ר מרדכי בן שלמה זלמן זאלקע גינצבורג - שו\"ב בוילנא."},{"i":11681,"n":"גינצבורג, ישראל מזדובה","f":"יעקב משלם מחודרוב","dt":"תשב - כב תשרי","b":"רב בזדובה(=זאדובה)-בוקובינה. חתן ר שמחה גינצבורג מסטרוזיניץ. נספה בשואה."},{"i":11682,"n":"גינצבורג, לוי (לואיס) מניו יור","f":"יצחק","k":"בעל שרידי הירושלמי","bt":"1873","bp":"קובנא","b":"תלמיד ישיבות קובנא, טלז. למד באוניברסיטת ברלין, שטרסבורג והידלברג. היגר לארה\"ב-1899. פרופסור לתלמוד בסמינר התיאולוגי היהודי - שכטר בניו יורק. חוקר ספרות המשנה והתלמוד. עורך המחלקה הרבנית באנציקלופדיה היהודית. חיבר \"גנזי שכטר\", פירוש לתלמוד ירושלמי. ספר יובל לכבודו - נ\"י תשו, ועוד."},{"i":11683,"n":"גינצבורג, לוי מארה\"ב","k":"בעל תשובה בדבר היין","b":"רב בארה\"ב. חיבר תשובה בדבר היינות הכשרים - נ\"י תרפב. ?? לא באוצר ??"},{"i":11684,"n":"גינצבורג, ליב מהורדנא","f":"בצלאל מהורדנא","b":"גביר נדיב - כנראה בהורדנא. גיסו של ר אברהם יונה יעוונין בעל חדושי מהרא\"י."},{"i":11685,"n":"גינצבורג, ליב מוינה","f":"הירץ מוינה","b":"רופא, וגביר בוינה, גורש עם אביו-תל ועברו לפרשעמיסל. בניו ר יצחק ור מאיר - שניהם רופאים."},{"i":11686,"n":"גינצבורג, ליביש מחודרוב","f":"יעקב משלם","b":"דיין בחודרוב-תרנד."},{"i":11687,"n":"גינצבורג, מאיר","f":"דוד גינזבורג","b":"רב-שנת תק\"ל"},{"i":11688,"n":"גינצבורג, מאיר יעקב","f":"דובער מהורדנא","k":"בעל הגהות רמ\"ג","bt":"תקף","bp":"הורדנא","dt":"תרך","dp":"וילנא","b":"נכד ר בן ציון מפינסק בן ר יוסף משאט. חתן ר צבי הירש לפידות מוילנא והתישב בוילנא. מגדולי חכמי וילנא סירב לרבנות ועסק במסחר. הו\"ל \"שו\"ע חו\"מ עם באור הגר\"א עם הגהות וחדושים ממנו ומראי מקומות. בנו - ר בנציון מיאנישוק."},{"i":11689,"n":"גינצבורג, מאיר יעקב","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":11690,"n":"גינצבורג, מאיר מויזון","f":"יצחק איזיק בן שאול","b":"מחכמי וילנא-תקב, אב\"ד רוסיא וגליל וויזון-תקיג על מקום דודו ר אשר-אבי השאגת אריה ואחיו ר דוד על מקומו אחריו, ראב\"ד בדובנא ומדינת רייסן. חתן ר שמחה הכהן רפפורט מהורדנא. קיבל הצעה לרבנות וילנא על מקום ר העשיל-תקט, אך היסו\"ד - שהיה הגביר הגדול בוילנא דאג למנות את חתנו ר שמואל, ור מאיר נתן כתב פטור לר שמואל וליסו\"ד - כנראה בניגוד לרצונו - והיה מחלוקת בענין זכויותיו בוילנא. מחותן עם ר מנחם נחום בן יקותיאל זוסמן כהנא מצערקאב בעל \"צמח מנחם\". ומחותן עם ר יעקב הלוי שור, שבנו ר אברהם הלוי מעמדין בעל \"מרכבת המשנה\" היה חתנו של רמ\"ג. בניו - ר יעקב, ר יוסף, ר יהודה ליב, ר בנימין רב גליל וויזון-תקמב על מקום אביו. חתניו - ר אברהם שור הלוי מקרוז, ר אריה ליב קצנלנבוגן. (לפי ליפמן-קובנא היה בנו של ר שאול ולא נכדו)."},{"i":11691,"n":"גינצבורג, מאיר מוילנא","f":"נפתלי הרץ מירושלים","dt":"תרכח - יח כסלו","dp":"וילנא","b":"חתן ר יצחק ר זלמן ר אורי'ס, ובזיוו\"ש חתן ר יוסף אליהו עליאשברג, ובזיוו\"ש חתן ר יצחק מוולוזין. גביר מחכמי וילנא."},{"i":11692,"n":"גינצבורג, מאיר מפטרוביץ","f":"אברהם","bt":"תרכו","b":"רב בפטרויץ(=פיטראוויץ)-פלך מוהילוב-תרנז."},{"i":11693,"n":"גינצבורג, מאיר מפרשמיסל ולובלי","b":"רופא בפרשמיסל, עבר ללובלין-תם והיה רופא הקהלה."},{"i":11694,"n":"גינצבורג, מיכאל יצחק מדוינסק","b":"חתן ר אלכסנדר משה לפידות. רב בדוינסק."},{"i":11695,"n":"גינצבורג, מנחם","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":11696,"n":"גינצבורג, מנחם נחום","b":"אביו של ר משה."},{"i":11697,"n":"גינצבורג, מנשה יוסף מסמרגון","f":"משה שלמה מאיליא","dt":"תרפה","b":"חתן ר חיים אברהם שפירא מסמרגון. רב בסמרגון-תרנ על מקום חותנו (והיה מחלוקת על הרבנות וחלק מהעיר בחר בר חיים ליב ליטווין מסוסניץ). בנו - ר איסר מניו יורק. חתנו ר אברהם ועלס מניו יורק."},{"i":11698,"n":"גינצבורג, מרדכי אהרן מוילנא","f":"יהודה אשר מגנוס מסלנ","k":"רמא\"ג - בעל אביעזר","bt":"תקנו","bp":"סלנט","dt":"תרז - טז חשון","dp":"וילנא","b":"מחכמי פלונגיאן, מורה ומתרגם במיטאוי. אחרי חתונתו עבר לשאוועל, והיה תלמיד קרובו ר דב הלוי משאוועל. ואחר נדודים רבים התישב בוילנא. פנה להשכלה והיה סופר, אך נשאר שומר מצוות, התקרב ללילינטל שפעל להפצת השכלה מטעם השלטון הרוסי, ויסד יחד עם שלמה זלקינד בי\"ס מודרני. לאחר זמן היה מחלוקת ביניהם וביקר קשות את שיטתו בספרו \"מגיד אמת\" לייפציג תרג. חיבר גם \"תולדות בני האדם\"-תקצב, ועוד. תרגם מגרמנית \"גלות ארץ ישראל\" - \"מסע קולומבוס\", \"קרית ספר\" וילנא תקצה, \"עתותי רוסיא\", \"הצרפתים ברוסיה\", חיבר גם בשם בדוי \"דאקטר פראנקאלס\" ספור על שני בדחנים - וילנא תרטז (נדפס בסוף קרית ספר), \"מגיד אמת\" כנגד \"מגיד ישועה\" ללילנטל וחתם בעילום שמו בשם \"יונה בן אמתי\", ועוד."},{"i":11699,"n":"גינצבורג, מרדכי מאטל","f":"שמעון מפוזנא","b":"כנראה בנו השישי של ר שמעון. נקרא גם איטינגא, בנו ר אברהם איטינגן מוינה - יועץ הקיסר."},{"i":11700,"n":"גינצבורג, מרדכי מבריסק","f":"בנימין וולף","dt":"תמט - ח אב","dp":"בריסק","b":"מגדולי דורו. חתן ר איצק זאלקווער (ר יצחק בן שמואל זנויל מזולקוא). רב בבריסק-תל. כנראה היה מגולי וינה. היה מרבני הועדים וחתם בפנקס ליטא ובתקנות סעלץ-תל, בחאמסק-תלט, בלענטשני-תמא, והיתה מצודתו פרוסה על עשר קהילות בסביבות בריסק - שהיו עצמאיות למחצה. הסכים על ספרים רבים. חיבר חדושי דינים בכת\"י. בנו ר יוסף בעל \"לקט יוסף\". וחתנו ר צבי הירש קצנלנבוגן אב\"ד מזריטש. (באוצר הרבנים שם אביו - יקותיאל זלמן). מגדולי דורו, רב בהורדנא, פינסק, בריסק. חתם-תמב בפנקס ליטא. הסכים על \"שערי שמים\" להשל\"ה, \"דברי חכמים\"-תלט."},{"i":11701,"n":"גינצבורג, מרדכי מדובראווניצי","f":"חיים","b":"אב\"ד דובראווניצי-תקט."},{"i":11702,"n":"גינצבורג, מרדכי מהרמילוב","b":"מחכמי הרמילוב. תשובות אליו \"טוב טעם ודעת\"."},{"i":11703,"n":"גינצבורג, מרדכי מסטרוזניץ","dt":"תשג","b":"רב בסטראזניץ"},{"i":11704,"n":"גינצבורג, מרדכי מקאשיווקא-לוצק","f":"שמואל מקאשיווקא","k":"אדמור מקאשיוקא לוצק","dt":"תרעו"},{"i":11705,"n":"גינצבורג, משה","f":"יוסף גינזבורג","b":"רב-שנת ת\"ק"},{"i":11706,"n":"גינצבורג, משה","b":"זקנו של ר יעקב בעל \"זרע יעקב\" פרג תקעד. מחדושיו בספר נכדו."},{"i":11707,"n":"גינצבורג, משה","f":"שמעון מפוזנא","b":"חתן ר ענזל מחשובי אשכנז, והיה סכסוך בינו לאשתו ומשפחתה וגרם למחלוקת שהגיעה לערכאות, וגדולי הדור ובהם המהרש\"ל ור אייזיק הלוי אב\"ד גינצבורג - תיווכו ועשו שלום."},{"i":11708,"n":"גינצבורג, משה אהרן מקכנביץ","bt":"תרז","b":"תלמיד ר זלמן לנדא. רב בדרויא-תרל, קוכענעוויטש(=קכנביץ)-פלך ויטבסק-תרס. נסמך מאת: ר נתן מפאשטוב, ר יהושע חיים מגריווא."},{"i":11709,"n":"גינצבורג, משה יוסף מברזוביץ","dt":"תשג","b":"רב בברזוביץ"},{"i":11710,"n":"גינצבורג, משה מסמיאטיץ","f":"נחום","b":"רב בסמיאטיץ. הסכים על \"אבות דר נתן\" עם ביאור-תקצב."},{"i":11711,"n":"גינצבורג, משה מפולנאה","f":"שלמה חריף","b":"רב בפולנאה-תק\"כ"},{"i":11712,"n":"גינצבורג, משה מפינטשוב","f":"הירץ מוינה","b":"רופא בפינטשוב- בשנות התל'."},{"i":11713,"n":"גינצבורג, משה מפרג","f":"יצחק דוד","b":"דיין בפרג-תקכח, אחריו של ר יעקב מפרג."},{"i":11714,"n":"גינצבורג, משה מפרג וא\"י","f":"אשר אנשל גינזבורג","dp":"צידון","b":"דיין מו\"ש בפרג-ת\"ק,עלה לא\"י"},{"i":11715,"n":"גינצבורג, משה מראזדיל","dt":"תקסה - ז אדר","b":"רב בראזדיל"},{"i":11716,"n":"גינצבורג, משה ראובן מחודרוב","f":"יעקב משלם","bt":"תרכז","dt":"תרץ","b":"חתן ר יחיאל מיכל היבנר. אב\"ד חודרוב-תרנו על מקום אביו, התפטר מתפקידו בתרצב עם ר שלמה איכנשטין. חיבר קונטרס \"כרמי שלי\" שנדפס עם ספרו של חמיו \"זכר רב\" למברג תרנג."},{"i":11717,"n":"גינצבורג, משה שלמה מאיליא","f":"ניסן מאיליא","b":"חתן ר אריה ליב שפירא מקובנא, וגיסו של ר מנחם זונדל שפירא מאיליא. רב באיליא-תרמ. בניו - ר מנשה יוסף, ר אריה ליב-נפטר צעיר."},{"i":11718,"n":"גינצבורג, משלם זלמן ממוהילוב","f":"יצחק איזיק בן שאול","b":"רב במוהילוב, אב\"ד מדינת רוסיה-תצז, אחיו ר מאיר היה אב\"ד אחריו (וכנראה בזמן הזה עדיין היה בוילנא). בנו ר גרשון מהארקי, והארי-תקמג."},{"i":11719,"n":"גינצבורג, משלם מגורא-הומורא","b":"תשובה אליו בטוט\"ד."},{"i":11720,"n":"גינצבורג, משלם פיביש מרובשוב","f":"מנחם אשכנזי","b":"מחכמי רובשוב-תלז. גביר ופרנס ועד ארבע ארצות ביריד ירוסלב. הסכים על תנ\"ך אידיש טייטש - אמשטרדם תלט."},{"i":11721,"n":"גינצבורג, מתתיהו מאויבן","b":"רב באויבן(=בודא). הסכים על \"זרע יצחק\" לר יעקב קוניץ - תקכה."},{"i":11722,"n":"גינצבורג, נחום ברוך מיאנובה","f":"צמח דוד","k":"בעל מקור ברוך","bt":"תרמב","bp":"פוניביז","dt":"תשא","b":"תלמיד ר הרצל קרצ'מר בעל \"נועם המצוות\". רב באופינה-פלך קובנא-תרסג, וירזן, קיברט, רבה האחרון של יאנובה-תרצ, ונשיאה האחרון של אגודת הרבנים בליטא. נספה בשואה עם בני עדתו. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"תורה מציון\" - ירושלים תרנה-תרסה. ?? לא באוצר ??"},{"i":11723,"n":"גינצבורג, נחום מסוכטשוב","b":"רב בסוכאטשוב"},{"i":11724,"n":"גינצבורג, נחום מסמיאטיץ","dt":"תקצב - לפני","b":"רב בסמיאטיץ. בנו ר משה רב בסמיאטיץ-תקצב."},{"i":11725,"n":"גינצבורג, נחמיה הלוי מדווברובנ","f":"אברהם בירך מסימליאן","k":"בעל דברי נחמיה","bt":"תקמד-סח","dt":"תריב - טו שבט","b":"רב בדוברוונא. תלמיד בעל התניא, בנו ר דב בער, וחתנו ר מנחם מנדל מליובאויטש. חתן ר זלמן מדובראוונא, ובזיוו\"ש חתן ר חיים אברהם-בנו של בעל התניא. לעת זקנותו נבחר כרב בבוברויסק אך נפטר בטרם הספיק לכהן. בנו ר דב ליב בעל \"אמונת חכמים\". מתורתו ב\"פליטת סופרים\" - וילנא תרכג."},{"i":11726,"n":"גינצבורג, נטע מוילנא","f":"אריה ליב מוילנא-כתבן","b":"גביר בוילנא-תקלא, גיסו של ר חיים מוולוזין."},{"i":11727,"n":"גינצבורג, ניסן מאילא","b":"אב\"ד איליא. בנו - ר משה שלמה, ונכדו ר מנשה מסמרגון."},{"i":11728,"n":"גינצבורג, נפתלי הרץ מוילנא","f":"אהרן יהודה ליב","dt":"תקנז - אדר","b":"ראש ונגיד בוילנא. חתן ר אוריה ספרא דמתא (וילנא) - החתום ראשון על החרם נגד החסידים. נפטר בחיי אביו. אחיו בחרו לעצמם שמות שונים - במקום גינצבורג - קלאצקי, רי\"פ. בנו - ר גבריאל יעקב."},{"i":11729,"n":"גינצבורג, נפתלי הרץ מזאבלודאו","b":"ראב\"ד זאבלודוב-תל, חתם בועד סעלץ-תל."},{"i":11730,"n":"גינצבורג, נפתלי הרץ מירושלים","f":"יוסף מברוד","dt":"תרכא - ט כסלו","dp":"ירושלים","b":"חתן הגביר ר יצחק איזיק איזועניצער בן יוסף אליהו בן ר אברהם פה טהור. עלה לירושלים."},{"i":11731,"n":"גינצבורג, נפתלי הרץ מסלוצק הזק","f":"יצחק איזיק בן שמעון","dt":"תמז - כב תמוז","b":"חתן נכדת ר שאול וואהל. מגדולי חכמי דורו. רב בפוזנא-תז, פינסק-תכד, סלוצק-תל, היה בועד זאבלוראווי(=זאבלודובה)-ליטא-תכד. בנו ר שאול על מקומו אחריו בפינסק. נרשם ב\"זכרונות רבני סלוצק\" - כת\"י - כאב\"ד סלוצק-תכד. ב\"גדולת שאול\" מספר כי אשתו של חכם זה נשאה אחר פטירתו לר העשיל מקראקא שנפטר-תכד, ועל מצבתה נכתב \"אלמנת תרין מלכין\" - וכנראה הפך הסדר. בנו ר יצחק נפטר בחיי אביו - תלח."},{"i":11732,"n":"גינצבורג, נפתלי הרץ מפטרבורג","f":"יוסף יוזל","k":"ברון גינצבורג","bt":"1833","bp":"ניגראדקא","b":"חתן הגביר רי\"ה רוזנברג מקיוב. התישב בפטרבורג בעקבות אביו. נשיא חברת \"מפיצי השכלה\" על מקום אביו-תרלח. מקורב לשלטון וחבר בועד הממשלתי בדבר \"שאלת היהודים\". תרם מכספו וייסד מוסדות חסד בפטרבורג. בניו יורק הוקמה קרן ע\"ש להדפסת ספרים מובחרים בתולדות ישראל."},{"i":11733,"n":"גינצבורג, נפתלי הרץ מפפד\"מ ופו","f":"שמעון מסלוצק","k":"בעל נפתלי שבע רצון","b":"מחכמי פפד\"מ. רב בפולין-תן. היו לו רק בנות. נכדו ר נפתלי זאב בן קלונימוס בעל \"נר תמיד\" - רב בצ'כנוביץ, גאנייניץ, וויסאקי."},{"i":11734,"n":"גינצבורג, נתן מאובן ישן","dt":"תקמח - כז חשון","b":"רב הקהלה האשכנזית בבלגרד-תצט על מקום ר לוי יצחק ירושלמי (שעבר לטימישואר), ראב\"ד באויבן ישן(=בודון)-תקך (לפי רוזניס - תקיד). הסכים על \"זרע יעקב\" לר יעקב קוניץ - פיורדא תקכה. (לפי רוזניס נפטר - תקמא)."},{"i":11735,"n":"גינצבורג, עקיבא מברלין","f":"פיבש","k":"יעקב ווייט-פייט","dt":"תפט - יג אייר","b":"גביר בברלין, בנו ר יהודה ליב שנפטר בחיי אביו היה המממן של רכישת הזהב לאוצר המטבעות של המלך וכשנפטר נעלם כסף המלכות והיה קצף על היהודים עד שר מיכל חסיד כינס את כל היהודים והחרים את מי שיודע היכן הכסף ואינו מספר - ובוטלה הגזירה. שם אביו פיבוש הפך לשם המשפחה פייט."},{"i":11736,"n":"גינצבורג, פנחס מירושלים","b":"תלמיד או ר\"מ בישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":11737,"n":"גינצבורג, פרידריך מברסלוי","b":"רופא בברסלוי-תקעג, חיבר ספר בחכמת הרפואה. חתם על \"תרועת מלך\" לבנימין פרנקל - ברסלוי תקעג."},{"i":11738,"n":"גינצבורג, צבי הירש","dt":"תרמב","b":"רב במעריעש"},{"i":11739,"n":"גינצבורג, צבי הרש מאראניאש","f":"יהודה אריה ליב מצעהל","bp":"צעהלים","dt":"תרמב-נג","dp":"אראניאש מעדיאש","b":"תלמיד הכת\"ס, חתן ר שמואל שמלקא קליין מחוסט וסעליש, ועבר לשם. רב בסעליש-תריח, אראניאש-מעדיאש-ליד סטמר-תרך, ובנו ר יהודה אריה ליב על מקומו אחריו."},{"i":11740,"n":"גינצבורג, צבי מאיר מדוקלא","f":"עקיבא","b":"ר\"מ בדוקלא. חתן ר יקותיאל ראטה מסקול. נכדו - ר משולם פייש האדמור מחוסט בניו יורק."},{"i":11741,"n":"גינצבורג, ק' זגפ'","dt":"תרך","dp":"ברסלוי","b":"מחכמי הריפורמים, עבר לברסלוי. חיבר ספרים בגרמנית על מנהגי אשכנז, ספרים לנערים, ועוד. יצא בקול קורא את בני הנעורים החפצים לנהות אחרי דגל ארץ מולדתם ולהחנך במלאכת המטיפים אצל יאקאבסון ויעקב בעער בברלין."},{"i":11742,"n":"גינצבורג, קלונימוס קלמן מפינס","f":"יצחק איזיק בן אשר","b":"גביר מחמכי פינסק-תקי. חתן ר שימן (שמעון) מביאלי נכד ר שימן מלובלין. חתנו ר אברהם הלוי מארלא, ונכדו ר יעקב הלוי בעל \"תולדות יעקב\" -ביאליסטוק תקסו."},{"i":11743,"n":"גינצבורג, רפאל וולף הכהן","f":"בנימין","k":"בעל באור הערוך","b":"מחכמי אשכנזי. נזכר ב\"ברכת משה\" ברלין תקצד."},{"i":11744,"n":"גינצבורג, רפאל יוסף","f":"שניאור זלמן","bt":"תרז","b":"נכד-אבי אמו ר נחמיה מאליאצקי. תלמיד ר מאני מוידז. רב בדוינסק, רב בשרקורשצינא(=סארקויסצענע)-פלך וילנא-תרמד. נסמך מאת: ר אריה ליב מדוינסק, ר ראובן הלוי מדוינסק. בנו - ר יהודה ליב שאול מיאקובשטט, חתנו - ר אברהם ישראל רבינוביץ."},{"i":11745,"n":"גינצבורג, שאול","bt":"1866","dt":"1940","b":"היסטוריון, עורך ומבקר. פרסם מאמרים ומחקרים ובהם סדרת מאמרים אודות משומדים."},{"i":11746,"n":"גינצבורג, שאול מויזון ופינסק","f":"נפתלי הירץ מפינסק","dt":"תפז - טו שבט","b":"מגדולי דורו. רב בויזון-תמד, פינסק על מקום אביו-תסד, ואב\"ד הראשון במדינת רוסיה-תסד, ולימד תלמידים בישיבה. מתלמידיו ר אליעזר בן יצחק איזיק מויסאקי בעל \"כרם חמד\". הסכים על ספרים רבים. בניו ר יצחק איזיק מדריבין על מקומו אחריו, ר דוד מאליק, ור אשר מוויזון, ר דב בער מהמבורג. חתנו - ר צבי רפפורט מילקוביסק."},{"i":11747,"n":"גינצבורג, שלום גרשון מסטרוזיני","dt":"תשג","b":"אדמור בברגסאס, רב בסטראזניץ(=סטרוזיניץ)-בוקובינה."},{"i":11748,"n":"גינצבורג, שלמה מלאהישין","f":"דוד","b":"רב בלאהישין, הסכים על \"אבות דר נתן\" עם ביאור-תקצב."},{"i":11749,"n":"גינצבורג, שמאי","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\"."},{"i":11750,"n":"גינצבורג, שמואל מהורדנא","f":"אריה ליב מוילנא-כתבן","b":"גביר ופרנס בהורדנא, גיסו של ר חיים מוולוזין. בנו ר בצלאל פרנס בהורדנא, שבנו ר אשר היה פרנס בהורדנא. (לפי ברוורמן-אנשי שם - אולי ר בצלאל היה חתנו ולא בנו)."},{"i":11751,"n":"גינצבורג, שמואל מקאשיווקא","f":"יחיאל מיכל מקאשיווקא","k":"אדמור מקאשיווקא","b":"חתן ר אהרן צינץ מטורבין-בן ר אריה ליב מפלאצק."},{"i":11752,"n":"גינצבורג, שמואל שמעלקא","f":"יהודה ליב מאראניאש","dt":"תש..","b":"חתן ר שלמה זלמן בן אליעזר קליין. מחכמי סילאג'צה. רב במעדיאש-תרצג על מקום אביו וההכתרה נדחה בשנתיים בגלל מחלוקת בקהלה. נספה בשואה."},{"i":11753,"n":"גינצבורג, שמחה אשר מויטעבסק","f":"גרשון מהארקי","b":"מחכמי ויטעבסק-תקמח, עבר לשם כנראה מהארקי."},{"i":11754,"n":"גינצבורג, שמחה מסטרוזיניץ","b":"רב בחדורוב, סטרוזיניץ-בוקובינה-תרם, בנו ר שלום גרשון על מקומו אחריו."},{"i":11755,"n":"גינצבורג, שמעון אולמא מפוזנא","f":"אברהם","bt":"רסו","dt":"שמו","dp":"צפת","b":"נכד ר יחיאל זכס מפורטו, חתן ר יצחק לינץ. גביר מלומד ומקורב למלכות ופגש את המלך זיגמונד אוגוסט. ראש יהודי אשכנז, רב בפוזן, פרג, פרנקפורט. אבי משפחת גינצבורג. חתנו ר עקיבא נוישא (פרנקפורטר) בן יעקב מפפד\"מ, חתנו ר מאיר העכעל (או העבל) בן שלמה האז מפפד\"מ גירש את אשתו ואחר שנישאה טען שהגט היה פסול - והרמ\"א התערב והכשיר את הגט. מחותן עם הרמ\"א - בנו ר אליעזר חתן הרמ\"א. ובנו ר אשר לעמל אהרן אולמא גיצבורג זקנו של בעל \"תורת יוסף\", ובנו הרביעי ר יצחק אולמא רב בפפערשי-שע, הבן החמישי ר זנוויל ונזכר ב\"חוט השני\", ואולי בנו גם ר מרדכי מאטל. עלה עם בנו ר אליעזר לצפת. מוזכר בשו\"ת הרמ\"א. היה מעורב במחלוקת עם ר נתן שאטן והיו מעורבים בה ר אליעזר טריווש עם כמה חכמים ותמך בר שמעון - ר יצחק איזיק גינצבורג עם חכמים אחרים."},{"i":11756,"n":"גינצבורג, שמעון מאמשטיסלב","b":"רב באמשטיסלב-תקכה. הסכים על \"בית יעקב\" יחד עם ה\"שאגת אריה\", ועל \"עבודת המלך\" - זולקוא תקל."},{"i":11757,"n":"גינצבורג, שמעון מבעשינקאביץ","b":"רב בבעשינקוביץ-תקמח, ואולי הוא זה שהיה אב\"ד אמשטיסלב-תקכה"},{"i":11758,"n":"גינצבורג, שמעון מוילנא","f":"אשר בן קלונימוס קלמן","dt":"תקן - ח אב","b":"פרנס מחכמי ומנהיגי וילנא. חתן ר משה בן מיכאל מקלצק בן מאיר איזנשטט בעל \"פנים מאירות\". גבאי הת\"ת בוילנא. בניו ר שלמה זלמן קלאצקי, ור בנימין וולף קלאצקי. נפטר בחיי אביו."},{"i":11759,"n":"גינצבורג, שמעון מסלוצק","f":"יצחק איזיק בן שמעון","b":"רב בסלוצק ומדינת רוסיה-ת\"ל. אביהם של ר נפתלי הירץ בעל \"נפתלי שבע רצון\", ר יצחק איזיק, ור יהודה ליב בעל \"עמודי עולם\"."},{"i":11760,"n":"גינצבורג, שמעון מפפד\"מ","f":"שלמה בן יאיר ריזמן","k":"בעל פירוש למרדכי","dt":"שפד - ט סיון","b":"מחכמי פפד\"מ."},{"i":11761,"n":"גינצבורג, שמעון מפרמישלא","b":"חתם-תכד בועד זוירז על תקנת זולקוא."},{"i":11762,"n":"גינצבורג, שמעון שאטלס מפפד\"מ","f":"יעקב אולמא מפרידבורג","k":"שמעון שאטלס","b":"רב ופרנס בפפד\"מ - שנות הש'. חתן ר משה האס. חתנו ר נתן גרינהוט מפפד\"מ, ונכדו ר יעקב בעל \"טוב ראי\" ומזכירו בספרו, חתנו השני - ר אברהם אביו של ר דוד אופנהים מניקלשבורג - נשיא ארץ ישראל. בנו ר יצחק איזיק מוורמייזא - ובגירוש-שעה עבר לפולין."},{"i":11763,"n":"גינצבורג, שניאור זלמן יונה","f":"יצחק","bt":"תרלו","b":"רב במינא-פלך צערניגוב-תרסד, וואראנוק-פלך צערניגוב-תרסו. נסמך מאת: ר שמריה נח שניאורסון מבוברויסק, ר דוד צבי חן מצערניגוב, ור צבי דב מהומל."},{"i":11764,"n":"גינצבורג-ולרשטין, אריה ליב","f":"אשר מולרשטין","b":"נכד השאגת אריה. (מכתב המלצה אליו מרבני אשכנז - תר)."},{"i":11765,"n":"גינצבורג-ולרשטין, אשר מקרלסרוא","f":"אריה ליב - שאגת אריה","k":"בעל קול שחל","bt":"תקטו-כא","bp":"ליטא","dt":"תקצז-ט -כה תמוז","b":"רב בוואלרשטיין, קארלסרוהא כל ימיו. מכר את כתבי אביו לר גרשון אמשטרדם מוילנא, וכן את התוספות ממנו שנדפסו בשם \"הגהות אשר\". התכתב עם גדולי דורו, וחיבר סספרים בכת\"י שנמכרו גם הם לר גרשון הנ\"ל. מתלמידיו ר אליהו בן אפרים וילדשטעטער, שכיהן כרב בקארלסרוא על מקומו אחריו. בנו ר אריה ליב (מכתבי המלצה אליו מרבני אשכנז - תר). מתלמידיו - ר יעקב עטלינגר."},{"i":11766,"n":"גינציג, יחיאל מיכל מקראקא","b":"מחכמי קראקא-תרצו. תשובה אליו ב\"דובב מישרים\". בנו עזריאל - מנהל ביה\"ס תחכמוני באנטורפן אחרי השואה."},{"i":11767,"n":"גינצלר, אברהם מאויהל","f":"אליעזר","k":"בעל תוכחת מגולה","bt":"תר","bp":"אויהל","dt":"תרע","dp":"קראקא","b":"מחכמי סיגט, עורך השבועון \"התור\" - העתון הראשון בהונגריה, ועבר לקראקא.חיבר מאמרים וספרים נגד הריפורמים. חיבר \"הספד מר\" קראקא תרמג, \"תוכחת מגולה\" קאשוי תרכח. היה עורך \"מחזיקי הדת\"."},{"i":11768,"n":"גינצלר, אברהם צבי","dt":"תשא","b":"רב בהומענע"},{"i":11769,"n":"גינצלר, זאב וולף משלגוי טאריאן","f":"ישראל מקרסטור","k":"בעל תולדות ישראל","dt":"תשד - טו סיון","dp":"אושוויץ","b":"אביו היה גבאי של האדמור ר ישעיה שטינר מקרסטור. תלמיד האדמור מקרסטור, ור דוד מייזלש מפולין. דומ\"צ בשאלגא-טאריאן(=שאלגוי-טאריאן)-תרפח וראב\"ד על מקום ר\"מ דייטש וראש הישיבה - אחת הישיבות הגדולות בהונגריה, רב בפעהר-יארמוט(=דיארמט)-תרצג. נספה בשואה. חיבר \"תולדות ישראל\" - קלינורדין תרצז. ?? לא באוצר ??"},{"i":11770,"n":"גינצלר, יוסף מרדכי","k":"בעל מי באר ישעיהו","b":"אב\"ד קרסטיר. חיבר ספר על ר ישעיה מקרסטיר בשם \"מי באר ישעיהו\" - טורנא תרפח."},{"i":11771,"n":"גינצלר, משה יהודה ליב מאויהל","b":"רב באויהעל-ת\"ר"},{"i":11772,"n":"גינצלר, צבי הירש","k":"בעל ארץ נחלי מים","b":"רב בערדא-בעניא-תר\"כ"},{"i":11773,"n":"גינצלר, שמואל שמעלקא מווישווה","f":"משה יהודה ליב","k":"בעל משיב נפש","bt":"תקצה","bp":"אויהל","dt":"תרעא - ד אייר","dp":"ווישווה","b":"תלמיד גיסו ר אברהם יהודה שוואץ בעל \"קול אריה\". חתן ר יצחק אריה כהנא מוויישווה(=אויבר-וישווא)-חתנו של בעל \"קונטרס הספיקות\". ועבר לשם, רב בווישווה-תרכד כ-45 שנה על מקום ר חנוך זונדל פוגל שעלה לארץ, ור אליעזר דוד גרינוולד על מקומו אחריו. הו\"ל \"תרומת הכרי\" לבעל \"קונטרס הספיקות\"-חותנו זקנו.","bk":[["משיב נפש – תורה ומועדים",""]]},{"i":11774,"n":"גינצלר, שמעיה מירושלים","b":"ממיסדי כולל אונגרן \"שומרי החומות\"-תרך."},{"i":11775,"n":"גיספאן, יהודה","k":"בעל מנחת יהודה","bt":"תקנה","bp":"צנעא","dt":"תקצז","dp":"צנעא","b":"מהרי\"ץ,חיבר \"מנחת יהודה על התורה והפטרות"},{"i":11776,"n":"גיספאן, שלמה מתימן","k":"בעל חשק שלמה","dt":"תרל","dp":"צנעא","b":"מחכמי צנעא-תימן. חיבר גם \"שמע שלמה\", ו\"דברי שלמה\"."},{"i":11777,"n":"ג'יפורט, מאיר משלוניקי","dt":"תצד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":11778,"n":"גיפטר, מרדכי מטלז וארה\"ב","k":"בעל פתי מנחה","bt":"תרעז","bp":"פורטסמות-וירג'יניה","b":"נסע מאמריקה ללמוד תורה בישיבת טלז בליטא. חתן ר זלמן בלוך. ר\"מ בישיבת טלז בקליבלנד-אוהיו-תשה. חיבר הערות על ה\"מנחת חינוך\" בשם \"פתי מנחה\". פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג, \"תבונה\" - ירושלים תשא-תשח."},{"i":11779,"n":"ג'יפרוט, משה מאזמיר","b":"מדפיס באזמיר אצל ר דוד חזן-תצג."},{"i":11780,"n":"ג'יקו (קטן), יצחק מקוס","b":"רב באי קוס(=איססטאנקיאוי)-ליד רודוס-תע."},{"i":11781,"n":"ג'יקוריל, יצחק","b":"גביר בשלוניקי ותרם לת\"ת בשלוניקי-שנז."},{"i":11782,"n":"גיקטיליא, יוסף מסאלי-מרוקו","f":"אברהם","k":"בעל שערי אורה","b":"תלמיד ר אברהם אבולעפיה בספרד. רב בסאלי-מרוקו- שנות ה-ק'-ר'. חיבר גם \"גנת אגוז\", \"שערי צדק\", ועוד. (היה כמה חכמים בשם זה - ויש בלבול ביניהם)."},{"i":11783,"n":"גיקטיליא, יוסף מספרד","f":"אברהם","k":"בעל גנת אגוז","bt":"ח","bp":"סאלא-ספרד","dt":"ס","dp":"פינאלי","b":"מקובל,בעל מופת בקסטיליא"},{"i":11784,"n":"גיקטיליא, יוסף מפאס - ד","b":"מו\"ץ בפאס-שצח עם ר אברהם חאזיז, ר שלמה ן דנאן, ר שאול סירירו, ר סעדיה ן דנאן. חתם על פס\"ד-שצח."},{"i":11785,"n":"גיקטיליא, יצחק מספרד","k":"בעל אזהרות לשבועות","b":"מגדולי המדקדקים הראשונים-ד'ת\"ש"},{"i":11786,"n":"גיקטיליא, יצחק מפאס","b":"נגיד ורב בפאס, חתם על הסכמה-שנח עם חבריו ר משה הלוי, ר יעקב רותי, ר דוד ן זמרא."},{"i":11787,"n":"גיקטיליא, משה מספרד","f":"שמואל","k":"בעל זכרים ונקבות","bp":"קורדובה","b":"תלמיד ר יונה ן ג'נאח, מחכמי סרגוסה-ספרד, פייטן ומדקדק. בר פלוגתא של ר יהודה בן בלעם. חיבר פירוש בערבית לתנך."},{"i":11788,"n":"גיקטיליא, שמואל מפאס","dt":"של","b":"רב בפאס."},{"i":11789,"n":"ג'יראסי, אברהם משלוניקי","dt":"שלה - אב","dp":"שלוניקי","b":"מחכמי קהלת סיציליה בשלוניקי."},{"i":11790,"n":"ג'יראסי, דוד - א","b":"מרביץ תורה, מחכמי טורקיה בזמן הרשד\"ם"},{"i":11791,"n":"ג'יראסי, דוד משלוניקי","f":"אליה","dt":"תיט - ד תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי, ור\"מ ב\"חברת ת\"ת\". בנו - ר יהודה."},{"i":11792,"n":"ג'יראסי, דניאל משלוניקי ואזמיר","f":"דוד בן אליה","k":"בעל אודה השם","dt":"תסה","b":"תלמיד ר' חסדאי פרחיה הכהן. רב בשלוניקי, איזמיר-תלג, ויניציאה-תמב. חיבר \"אודה השם\" - דרשות בדרך דרושי איטליה."},{"i":11793,"n":"ג'יראסי, יהודה משלוניקי","dt":"תצג","dp":"שלוניקי","b":"שו\"ב בשלוניקי. השוחט האחרון ממשפחת שוחטים בשלוניקי, ור יוסף מולכו על מקומו אחריו."},{"i":11794,"n":"ג'יראסי, יהודה משלוניקי","f":"דוד משלוניקי","b":"מחכמי שלוניקי-שץ ראש השו\"בים, ור יוסף מולכו על מקומו אחריו. תלמיד ר שלמה הלוי הבחור."},{"i":11795,"n":"ג'יראסי, שמואל משלוניקי","f":"דוד","dt":"תכד","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":11796,"n":"גירון מרדכי מאדרינופול","f":"יקיר אסטרוק","dt":"תרמט","b":"רב באדרינופול-תרלט על מקום אחיו - ר אברהם יעקב."},{"i":11797,"n":"גירון, אברהם יעקב מאדרינופול","f":"יקיר אסתרוק מאדרינופ","dt":"תרלט - ניסן","b":"רב הכולל באדירונופול-תרלב על מקום אביו (שעלה לירושלים), בזמנו נפרדו קהלות רבות שנספחו לאדרינופול (גם בגלל עצמאות בולגריה שחלק מהקהלות עברו לרבנות סופיה) ביקר בירושלים-תרלד על קבר אביו. אחיו - ר מרדכי. (באוצר הרבנים תאריך פטירתו - תרמט)."},{"i":11798,"n":"גירון, אברהם מאדרינופול","f":"מנחם גירון","dt":"תצ","b":"מגדולי חכמי אדרינופולי"},{"i":11799,"n":"גירון, אברהם מאדרינופול","f":"שמואל דוד גירון","b":"רב באדרינופול-תר\"ב"},{"i":11800,"n":"גירון, אברהם רפאל יעקב מאדרינו","f":"מרדכי מאדרינופול","k":"בעל מקרא סופרים","bt":"תל","dt":"תקיא - ח סיון","b":"מצד אמו בן למשפחת אלאמאן (שקבלה מהשולטן סולימן פטור ממס על עזרתם בכיבוש בודון). חתן ר אברהם צרפתי מאדרינופול וירושלים, רב באדרינופול-תק על מקום חותנו והיה מחלוקת כנגדו ונבחר גם ר מנחם בן יצחק אשכנזי - אבי משפחת בכמוה\"ר. בניו - ר ירוחם אליקים על מקומו אחריו באדרינופול, מרדכי, ישעיה יהודה, חתנו - ר שמואל דנון. (אצל רוזניס מופיע עם תאריכים שונים ובהם נולד בשנת - ש').","bk":[["מקרא סופרים ותיקון סופרים [על העיטור]",""],["תיקון סופרים",""]]},{"i":11801,"n":"גירון, אליקים בכור מאדרינופול","f":"יעקב אברהם","k":"בכוראג'י","dt":"תקצה-ח","b":"דיין בסטארה זאגורה-בולגריה, רב באדרינופול-תקפו על מקום אביו. ישב בדין בזאגרה-תקפה עם הדיינים ר יצחק אסא ור גבריאל משה קריספין."},{"i":11802,"n":"גירון, אליקים בכור מאדרינופול","f":"ראה גם: ירוחם אליקים"},{"i":11803,"n":"גירון, אליקים מאדרינופול","dt":"תקס","b":"רב באדרינופולי, התיישב בקושטא. אחיו - ר רפאל יעקב אברהם."},{"i":11804,"n":"גירון, חיים יצחק מאדרינופול","f":"יעקב אברהם גירון","b":"דיין באדרינופולי-תק\"פ"},{"i":11805,"n":"גירון, יהודה אריה ליאונטי","b":"מגדולי חכמי איטליה,רב בקסאלי-תצ\"ט-תקכ\"א"},{"i":11806,"n":"גירון, יהושע מירושלים","f":"יעקב אברהם","dt":"תקצא - ה תמוז","dp":"ירושלים","b":"דיין באדרינופול, עלה לירושלים ונמנה על חכמיה. חתם-תקעח עם ר אהרן קניטי, ר יצחק בן מרדכי."},{"i":11807,"n":"גירון, יוחנן מפרינצי","b":"רב בפרינצי-תעא, תשובה ממנו ב\"פחד יצחק\", ו\"שמש צדקה\". חיבר תפלה על רעש הארץ - אנקונה 1690."},{"i":11808,"n":"גירון, יעקב אברהם קונורטי מאדר","f":"יקיר איסתרוק מאדרינו","k":"בעל אביר יעקב","bt":"תקכה","dt":"תקפו - כד טבת","dp":"אדרינופול","b":"מכונה בשם קונורטי(=מנחם). רב באדרינופול-תקסו, ורב הכולל-תקעב על מקום אביו. לפי רוזניס הוא המחבר \"אביר יעקב\" (ולא קרובו ר יקיר אשטרוק השני)."},{"i":11809,"n":"גירון, יצחק מאדרינופול","b":"רב באדרינופול-תקע בערך."},{"i":11810,"n":"גירון, יצחק מאיטליה","b":"מגדולי חכמי איטליה,רב בקסאלי"},{"i":11811,"n":"גירון, יקיר אשטרוק בכור - השני","f":"אליקים מאדרינופול","k":"בעל אביר יעקב","bt":"תקנג או תקעג","bp":"אדרינופול","dt":"תרלד - יז שבט","dp":"ירושלים","b":"רב באדרינופול-תקצה על מקום אביו, קושטא-תרב (על מקום אביו?) והיה ראש הרבנים בתוגרמה, עלה לירושלים-תרלא. היה מקורב לשולטן עבד אל מג'יד, ופגש את קיסרית צרפת, ואת קיסר אוסטריה בזמן שבקרו בקושטא. בנו ר אברהם."},{"i":11812,"n":"גירון, יקיר אשטרוק מרדכי - א","f":"אליקים (או מרדכי?)","k":"פריסיאדו (=יקר)","bt":"תק","bp":"אדריאנופול","dt":"תקעז - כו אייר","dp":"ירושלים","b":"רב באדרינופול על מקום אביו, אחראי גם על העיר אוחזוק והיה מחלוקת על הרבנות עם מוהר\"ם בן מרדכי - ובעל \"חקרי לב\" עשה פשרה ביניהם. בשנת תקעב עלה לארץ ישראל, וחתם עם ר יעקב משה עייאש, ובשנת תקעד חתם על תקנת חלב עכו\"ם. (אצל רוזניס יש שני רבנים האחד בנו של ר אליקים והשני בנו של ר מרדכי-אחיו של ר אליקים - אך יש ערבוב ביניהם)."},{"i":11813,"n":"גירון, יקיר מרדכי מירושלים","f":"מרדכי","b":"נכד ר רפאל יעקב אברהם גירון. עלה לירושלים. (לפי ריבלין הוא אותו החכם ר יקיר אסטרוק בן אליקים, ולפי רוזניס מדובר בשני חכמים שונים)."},{"i":11814,"n":"גירון, ירוחם אליקים מאדרינופול","f":"רפאל יעקב אברהם","bt":"תפ","bp":"אדרינופול","dt":"תקם","dp":"קושטא","b":"רב באדריאנופול על מקום אביו-תקיא, והיה מחלוקת על כך וחלק מהקהלות מינו לרב את ר אליהו פרץ ואחרות את ר מנחם בכמוהר\"ר מרדכי, וקיבל הסכמת ביה\"ד בקושטא לרבנותו (וחתמו ר משה יצחקי, ר אברהם מיוחס, ור אליעזר הכהן). עזב את הרבנות ועבר לקושטא, ובנו ר יקיר אשטרוק (מרדכי) על מקומו אחריו. עלה לירושלים וחזר לקושטא."},{"i":11815,"n":"גירון, ישעיה יהודה מאדרינופול","f":"רפאל יעקב אברהם","dt":"תקלא - כח אב","dp":"אדרינופול","b":"מחכמי אדרינופול. אחיו - ר ירוחם אליקים."},{"i":11816,"n":"גירון, ישראל שלמה","bt":"תרך","bp":"ג'ומולג'ינה-בולגריה","dt":"תרצא - כ חשון","dp":"הרטוב-ישראל","b":"פעיל ציוני בבולגריה, עלה לארץ והיה ממיסדי המושבה הרטוב."},{"i":11817,"n":"גירון, מנחם מאדרינופול","b":"רב באדרינופולי-ת\"מ"},{"i":11818,"n":"גירון, מרדכי מאדרינופול","b":"גביר מחכמי אדרינופול-שנות ה-ת'. אבי הרבנים לבית גירון. בנו - ר אברהם מאדרינופול."},{"i":11819,"n":"גירון, מרדכי מאדרינופול","f":"רפאל יעקב אברהם","dt":"תקכח - כה אדר","dp":"אדרינופול","b":"מחכמי אדרינופול, נפטר צעיר. אחיו - ר ירוחם אליקים. בנו - ר יקיר."},{"i":11820,"n":"גירון, סימן טוב מאדרינופול","b":"מחכמי אדרינופול-תרנא, לא זכה ברבנות העיר."},{"i":11821,"n":"גירון, שמואל מאדרינופול","f":"מרדכי מאדרינופול","b":"נכד ר יקיר אסטרוק. רב באדרינופול-תרמט על מקום אביו, והיה הרב האחרון שם למשפחת גירון, אחריו נבחר ר אברהם צמח."},{"i":11822,"n":"גירונדי - משפחה","b":"משפחה חשובה באיטליה, מקור המשפחה בספרד ומאבות המשפחה - ר עזרא תלמיד ר יצחק בן הראב\"ד, ר יונה גירונדי, הר\"ן והמקובל רבינו עזריאל."},{"i":11823,"n":"גירונדי, אפרים רפאל מפדובה","f":"מרדכי שמואל מפדובה","b":"מחכמי פדובה-תריב, הו\"ל ספר אביו - תולדות גדולי ישראל באיטליה."},{"i":11824,"n":"גירונדי, בן ציון אריה מפדובה","f":"מרדכי","bt":"תקכד","dt":"תקעח - יט כסלו","dp":"ציטדילה (ליד פדובה)","b":"מגדולי חכמי איטליה, רב במאציטאדלה, פדובה. גדל על ברכי אמו המלומדת בנוינידה גירונדי (מריני). תלמיד ר יצחק רפאל פינצי. חיבר חדושים על התנך, חידות דרושים ומוסר - בכת\"י."},{"i":11825,"n":"גירונדי, בן ציון צרפתי","k":"בעל קיצור הלכות שחיט","b":"תשובה ממנו בענין מחלוקת המקוה ברוויגו-שמט. תשובה ממנו ב\"משבית מלחמות\"-שסו, ובשו\"ת מהר\"י הלוי. חיבר קיצור הלכות שחיטה. נכדתו מרת בנוינידה מריני - היתה בקיאה בתורה ובדקדוק וחברה פירוש ושירים בכת\"י ואף נשאה ונתנה בהלכה עם גדולי הדור - בעלה - ר מרדכי גירונדי ונכדם - ר מרדכי שמואל גירונדי."},{"i":11826,"n":"גירונדי, בנוינידה (מזל טוב)","b":"גדולה בתורה ובדקדוק והעמידה תלמידים רבים. נשאה לר מרדכי גירונדי."},{"i":11827,"n":"גירונדי, ברכיה הלוי מפרובנס","f":"יצחק","b":"גדול בהלכה ובפיוט, מגדולי הראשונים בלוניל-ד'תתפ - אחיו של הרז\"ה בעל המאור."},{"i":11828,"n":"גירונדי, וידאל אפרים","dt":"קנא","b":"עק\"המגדולי חכמי ספרד,בקי בחכמה ומדעים,רב בגירונה,בפאלמה דה מיורקה"},{"i":11829,"n":"גירונדי, יונה מספרד","f":"אברהם","k":"בעל שערי תשובה","bt":"ד'תתק\"ס","dt":"כד - כח חשון","b":"תלמיד ר שמואל בן שניאור, ור שלמה מן ההר (מונטפלייר). מחותן עם הרמב\"ן, מגדולי דורו, רב בגירונה, טולידו.","bk":[["שערי תשובה, קבור בספרד",""],["משלי - עם ביאור רבינו יונה",""],["עליות דרבינו יונה",""],["רבינו יונה",""],["שערי תשובה",""]],"e":"ד'תתק\"ס-ה'כ\"ד"},{"i":11830,"n":"גירונדי, יצחק הלוי מפרובנס","f":"זרחיה","k":"אבי הרז\"ה","b":"מחכמי פרובינצא(=פרובנס), פייטן בגירונדי-ד'תתע. אביו של ר זרחיה בעל המאור, וחיבר שיר לכבוד בנו."},{"i":11831,"n":"גירונדי, יצחק מאיטליה","f":"בן ציון","b":"נזכר בספרי ר מנחם נאמרה מוירונה - שם מסופר כי חיבר חדושים ופירושים על שו\"ע."},{"i":11832,"n":"גירונדי, מרדכי שמואל (אברהם)","f":"בן ציון אריה","k":"בעל מירא דכיא","bt":"תקנט-תקס","dt":"תריב - יג טבת","b":"נכד ר אברהם ישראל חי הכהן מאיטליה. תלמיד ר יצחק רפאל פינצי, ור שבתי אהרן חיים מוריני, ור ישראל קוניאן, ור אברהם ריגיו. חתן ר רפאל לוצאטו. רב בפדובה-תקפט. חיבר גם \"תולדות גאוני ישראל באיטליה\", \"יד מרדכי\". יצא כנגד המשורר יעקב פראנסיש שחיבר שיר כנגד חכמת הקבלה - וכתב כנגדו במלים חריפות. בניו ר אפרים רפאל, ר בן ציון יוסף משה."},{"i":11833,"n":"גירונדי, נסים","f":"רבינו ראובן","k":"הר\"ן","dt":"קמ","b":"מגדולי הראשונים והפוסקים,רופא,שלם במדעים,מרביץ תורה בברצלונה"},{"i":11834,"n":"גירונדי, שלמה אליעזר מפדובה","f":"בן ציון צרפתי","k":"בעל מעשה נסים","b":"רב בפדובה. חיבר \"מעשה נסים\". תשובה אליו ב\"דבר שמואל\"."},{"i":11835,"n":"גירונדי, שמואל מספרד","f":"משלם","k":"בעל אהל מועד","bt":"צה","b":"פוסק מגדולי חכמי ספרד, רב ומרביץ תורה בגירונדי. נזכר ב\"בית יוסף\". חיבר אהל מועד-קנו (נדפס לראשונה - תרמו עם פירוש \"סביב לאהל\" לר חיים אברהם גאגין)."},{"i":11836,"n":"ג'יריבי, שושן מתונס","b":"דיין מנאבל-תונס - תקמח, עם ר אפרים פרץ, ר אברהם סעאדה ור אברהם פלוס. נזכר ב\"משכנות הרועים\"."},{"i":11837,"n":"גישאדו, אהרן מצפת","b":"מחכמי צפת, בשנת רסד חתם על תעודה (בניהו \"ספר אסף\")"},{"i":11838,"n":"גלאויטשאווער, אברהם בנימין","b":"רב באוסטרובה. עורך \"אור המאיר\" - וארשא תרצו, \"יגדיל תורה\" - וארשא-פראגא תרפז. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, \"שערי תורה\" - קראקא תרפה."},{"i":11839,"n":"גלאויטשאווער, שמואל משה","dt":"תרצו - א אדר","dp":"פראגא-וארשא","b":"לזכרו חוברת \"אור המאיר\" - וארשא תרצו."},{"i":11840,"n":"גלאז, זליג","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":11841,"n":"גלאז, חיים שמואל מזלישטשיק","f":"מאיר יהודה ליב","k":"בעל אמרי שב\"ח","bt":"תרך","dt":"תרצה","b":"חתן רבו ר אברהם תצאומים אב\"ד זלישטשיק. היה מחכמי זלישטשיק ועסק בהדפסה. רב ביגלניצה-תרן. חיבר \"אמרי שב\"ח\" זלישטשיק תרנה, ועוד."},{"i":11842,"n":"גלאז, יצחק יעקב מידלינסק","b":"רב בייעדלינסק-תר\"ל"},{"i":11843,"n":"גלאז, מאיר יהודה ליב מרוהטין","f":"שמואל","bt":"תקפה","bp":"גרידינג","dt":"תרנד","dp":"נייסנץ","b":"חתן ר נפתלי הירץ הלפרין. רב בפמורן-תרכז בהמלצת ה\"דברי חיים\", רב ברוהטין. סירב להדפיס את כתביו."},{"i":11844,"n":"גלאז, נתן נטע מידלינסק","f":"יצחק יעקב מידלינסק","bt":"תריד","b":"רב ביעדלינסק-פלך ראדום-תרנב על מקום אביו. נסמך מאת: ר מאיר יחיאל מאוסטרווצא, ר אברהם צבי פרלמוטר מראדום."},{"i":11845,"n":"גלאז, שמואל שמלקא","dt":"תשג","b":"רב בלאטשוב"},{"i":11846,"n":"גלאם, כליפה מלוב","bt":"תרן","dt":"תשך - בערך","b":"רב ומלמד תשב\"ר במצראתה-לוב."},{"i":11847,"n":"גלבהאוז, יהושע שמואל מטיסמניץ","bt":"תרי","bp":"טיסמניץ","dt":"תרפח","dp":"וינה","b":"תלמיד ביהמ\"ד לרבנים בברלין. רב בקרלסבד, נורדהאוזן, פרג, וינה. חיבר ספר על ר יהודה הנשיא ועריכת המשנה - תרלו (בגרמנית?), ועוד."},{"i":11848,"n":"גלבוקס, שמעון מודוביצה","bt":"תרט","dt":"תשג","b":"דיין בודוביצה ודרשן. נספה בשואה."},{"i":11849,"n":"גלבלום, אביגדור","b":"רב בשידלוביץ"},{"i":11850,"n":"גלבלום, יוסף משידלובצא","f":"אביגדור גלבלום","bt":"תר","b":"רב בשידלובצה(=שידלאווצי)-פלך ראדום-תרלח."},{"i":11851,"n":"גלבפיש, שרגא פיבל מוארשא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":11852,"n":"גלבר, אברהם מקופיטשיניץ","b":"תשובה אליו - \"ארץ צבי\"."},{"i":11853,"n":"גלבר, יהודה ליב מפרשבורג","dt":"תרס - ה סיון","dp":"פרשבורג.","b":"משמש בקודש אצל החת\"ס בפרשבורג."},{"i":11854,"n":"גלבר, יואל מפרשבורג","f":"יהודה ליב מפרשבורג","b":"מחכמי פרשבורג."},{"i":11855,"n":"גלברג, יצחק אריה ליב","b":"תשובה אליו - מהר\"י הכהן."},{"i":11856,"n":"גלברד, יהודה צבי הירש מיזלוביץ","f":"משה יצחק (כנראה)","k":"בעל החלום","bt":"תרב","dt":"תרעב","b":"מחכמי יזלוביץ, מלמד ודרשן שהרבה לנדוד. חיבר \"החלום\" למברג תרמב, \"ויכוח הדת והאמונה\" דרוהוביטש תרנד, ועוד."},{"i":11857,"n":"גלברט, אברהם מהורדנא","f":"משה","bt":"תריב","dt":"תרצח - בערך","b":"מו\"צ בהורדנא-תרן, ואחראי על קופת הצדקה של ר נחומק'ה מהורדנא על מקומו של ר נחום-תרם. בנו - ר משה יצחק, חתנו - ר מיכל דוד מהורדנא."},{"i":11858,"n":"גלברט, שמואל מלודז","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"התפוח\" - בנדין תרפח."},{"i":11859,"n":"גלבשטין, הלל מירושלים","b":"מחבורת המקובלים בירושלים-תשיב, מתלמידי ר יהודה אשלג בעל הסולם."},{"i":11860,"n":"גלבשטין, הלל משה מעשיל","f":"צבי הירש","k":"בעל משכנות לאביר יעק","bt":"תקצד","dt":"תרסח - כד חשון","dp":"חברון","b":"חתן ר אליהו מסוקולקא. מצאצאי השלה, בילדותו התקרב לר מנחם מנדל מקוצק ושם התידד עם בעל חדושי הרי\"ם. בהסכמת רבו נסע גם אל ה\"צמח צדק\" בלובביץ. עלה מביאליסטוק לירושלים-תרכט, עבר לחברון. האדר\"ת כבדו כרבי, התידד עם ה\"שדי חמד\", למד ולימד קבלה. חיבר ספר \"משכנות לאביר יעקב\" ירושלים תרלה. ודרכו ניסה להציב משמרות כהנים ללמוד סדר קדשים, ארגן תפלות בכותל, גאל חצרות סביב לכותל כדי להקים שם בתי תפלה ומדרש. חיבר חיבר גם \"חוסן ישועות\", ועוד. עבר לחברון ושם נפטר.","bk":[["אור לישרים",""],["חוסן ישועות",""],["משכנות לאביר יעקב",""],["סדור תפלה",""],["אור זרוע לצדיק",""],["אור לישרים – פסחים",""],["טהרת הקודש",""],["משכנות לאביר יעקב - תמיד",""],["סידור תפילה - ביאור",""],["פתיל תכלת - נגד הנהגת התכלת בזמנינו",""],["תפילה למשה",""]]},{"i":11861,"n":"גלגר, ישראל ז' מראדזיווי","dt":"תשג","b":"רב בראדזיווי"},{"i":11862,"n":"גלדוורט, יעקב זליג מקראקא","bt":"תקע","dt":"תרלג","b":"דיין בקראקא אצל ר שאול לנדא."},{"i":11863,"n":"גלדצילר, אורי","f":"יוסף","b":"נכד-מצד אמו ר אפרים אליעזר יולס האדמור מסמבור פילדלפיה. חתן ר אברהם חיים מברגסאס. אדמור מסמבור פילדלפיה על מקום זקנו."},{"i":11864,"n":"גלדצילר, אליהו יהושע מארה\"ב","f":"מנחם שלום מאנטורפן","b":"ר\"מ בישיבת \"אור ישראל\" בניו יורק. חתן ר אליהו אליעזר דסלר."},{"i":11865,"n":"גלדצילר, יוסף - אבי המשפחה","b":"משפחה שגרה בקולבסוב מאות שנים. במקור מפפד\"מ. וקבלה בידם שהגיעו לשם מגירוש ספרד בשנת רנב. אבי המשפחה ר יוסף חסיד ר הירש מרימנוב"},{"i":11866,"n":"גלדצילר, יעקב צבי מסאנוק","f":"ישראל","bt":"תרסה","bp":"סאנוק","dt":"תשב","b":"רב באלכסנדר קויבסקי (ליד פיעטרקוב). נספה בשואה."},{"i":11867,"n":"גלדצילר, מנחם שלום מאנטורפן","f":"משה חיים מקולבסוב","bt":"תרנט","bp":"אנטורפן","dt":"תשלא","b":"חתן הגביר ר שלמה הכהן מסונדרלנד. ניצל מהשואה, הגיע לארה\"ב-תשא."},{"i":11868,"n":"גלדצילר, משה חיים מקולבסוב","f":"אליהו יהושע","bt":"תרנט","bp":"קולבסוב","dt":"תרצג","dp":"אנטורפן","b":"התישב באנטורפן-תרנא עם הוריו. עבר לאמשטרדם. התכתב עם דודו האדמור ר יהושע מדזיקוב - והמכתבים נדפסו ב\"עטרת ישועה\" תשלו. חתן ר מנחם שלום הלוי גולדמן מזלין."},{"i":11869,"n":"גלה, חיים מחירוב","b":"ממשתתפי \"אספת חכמים\"-תרעב."},{"i":11870,"n":"גלובובסקי, טוביה מנ\"י","b":"פרסם מאמרים ב\"הלבנון\" - סטמר תרפח."},{"i":11871,"n":"גלובמן, מרדכי","k":"בעל ששים שנות חיים","bt":"תרלב","dt":"תשג","b":"חיבר ספר זכרונות אודות חסידות צרנוביל, ובהם כתב גם על אח זקנתו - ר עקיבא חיות מדובובא."},{"i":11872,"n":"גלוגא, חיים מקרעשוב","dt":"תעה - א תמוז","b":"רב בקרעשוב"},{"i":11873,"n":"גלוגא, יחזקאל הלוי מבומסלא","f":"שמואל","k":"בעל מראה יחזקאל","dt":"תקפא","dp":"בומסלא(=בונצלוי)","b":"חתן ר אברהם בונדי מפרג בעל \"זרע אברהם\". רב בבומסלא-תקמ. חיבר \"מראה יחזקאל\" פרג תקפב. בנו - ר ליב הספידו ב\"אבל אב\" - פרג תקפב."},{"i":11874,"n":"גלוגא, מאיר","f":"יחזקאל גלוגא","k":"בעל שמן המאור","dt":"תקפט - כה אב","b":"ראב\"ד בפרג","bk":[["דברי מאיר – כמה מסכתות",""],["שמן המאור – או\"ח",""]]},{"i":11875,"n":"גלוגא, משה מהמבורג","f":"צבי הירש מגלוגא","b":"מחכמי המבורג. חיבר ספר בעניני תוכחה \"חבל להחיות\"."},{"i":11876,"n":"גלוגוי משה","bt":"1760","dt":"ה'תקפא 1821","bk":[["חבל להחיות",""]]},{"i":11877,"n":"גלוני, אליהו","f":"משה","k":"בעל תולדות אדם","b":"מחכמי טורקיה, חיבר \"תולדות אדם\" - ובו חכמת הפרצוף, ועוד."},{"i":11878,"n":"גלוסברג, יעקב סגל מברלין","f":"מרדכי","k":"בעל זכרון ברית לראשו","b":"שו\"ב בברלין. חיבר \"זכרון ברית לראשונים\" בהלכות מילה - ברלין תרנב."},{"i":11879,"n":"גלוסקא, זכריה מתימן","f":"דוד","bt":"תרנו","bp":"חידאן-תימן","b":"עלה לארץ והיה פעיל באגודת \"צעירי המזרח\", ו\"התאחדות התימנים\"."},{"i":11880,"n":"גלוסקי, משה ראובן","dt":"תשג","b":"רב בבריסק"},{"i":11881,"n":"גלוסקין, אהרן מפאריץ'","b":"רב בפאריץ', ובנו ר מנחם מנדל רב מטעם לצדו או אחריו."},{"i":11882,"n":"גלוסקין, מנחם מנדל","f":"אהרן מפאריץ'","bt":"תרמז","dt":"תרצז - יג כסלו","dp":"לנינגרד","b":"חתן ר אליעזר רבינוביץ ממינסק-חתנו של הגדול ממינסק. פעל לחזוק היהדות במחתרת הסובייטית, אב\"ד ורב מטעם בפאריטש(=פאריץ'), פרילוקי, ניזין, מינסק-תרפד על מקום חותנו, רב ראשי בלנינגרד-תרצד וליהדות רוסיה."},{"i":11883,"n":"גלזמן, ארי","f":"צבי","k":"בעל א פענצטער צו דער","bt":"1912","bp":"פוסבול","dt":"1941","dp":"קובנא","b":"עתונאי סופר ומשורר. ממיסד ועורכי כתב העת \"פתח\" בקובנא. נספה בשואה בטבח האינטלקטואלים בגיטו קובנא. ?? לא באוצר ??"},{"i":11884,"n":"גלזנר, אברהם מקלויזנבורג","f":"יקותיאל","bt":"תקפה","bp":"רוזנברג-מחוז פרשבורג","dt":"תרלח - כב כסלו","dp":"קלויזנבורג","b":"תלמיד ר בער ממיקלוש בעל \"מנחת עני\", ר שלמה קוועטש, והכת\"ס. חתן ר דוד צבי ארנפלד-חתנו של החת\"ס. רב ביינק(=גונק)-תריג בהמלצת הכת\"ס, קלויזנבורג-תרכג על מקום ר שרגא פייש, ובנו ר משה שמואל על מקומו אחריו. השאיר חבורים רבים בכת\"י."},{"i":11885,"n":"גלזנר, בנימין מקלויזנבורג","f":"משה שמואל מקלויזנבור","bt":"תרנב","bp":"קלויזנבורג","b":"תלמיד ישיבת פרשבורג ועוד. חתן ר יחזקאל רייך מבאנוביץ. מחכמי קלויזנבורג, פעיל במזרחי, וסופר. נספה בשואה. עורך כתב העת \"אהל שם\" בשנים תשב-תשה."},{"i":11886,"n":"גלזנר, יהודה צבי מלוס אנגלס","f":"עקיבא מקלויזנבורג","k":"הו\"ל דור דורים","b":"נכד ר יהודה צבי בלום מהאנשוביץ. נבחר למלא מקום אביו בקלויזנבורג, עבר לארה\"ב וכיהן כרב בלוס אנגלס - וממונה על הכשרות שם. חתן ר חיים אהרן דוד דייטש מבאלאש-יארמוט."},{"i":11887,"n":"גלזנר, משה שמואל מקלויזנבורג","f":"אברהם מקלויזנבורג","k":"בעל שביבי אש","bt":"תרד או תרטז","bp":"פרשבורג","dt":"תרפה - כב תשרי","dp":"ירושלים","b":"נכדם של ר עקיבא איגר והחתם סופר, תלמיד אביו והכת\"ס. חתן ר יהודה ליב לעב מבוטשאם. רב בקלויזנבורג על מקום אביו-תרלח וראש ישיבה ורבה של טרנסילבניה ובנו ר עקיבא על מקומו אחריו. הקהלה הניאולוגית פרשה בזמנו-תרמז בגלל \"חסידותו היתרה\" (כך ב\"אונגאריש איזראעליט\" המתלונן על קרבתו לחסידות בלז), והיה מחלוקת כנגדו בגלל פעילותו הציונית ואף היה פילוג בקהלה - (נאלץ לבטל השתתפותו בועידת המזרחי בפרשבורג בגלל לחצי החרדים), תמך ב\"מזרחי\" והיה ציר בקונגרס הציוני. עלה לירושלים-תרפג ולימד בביהמ\"ד למורים בירושלים. בנו ר עקיבא על מקומו אחריו. חיבר גם \"אור בהיר\", \"דור רביעי\", ועוד. ב\"בית ועד לחכמים\" - סטמר תרפד, נכתב כנגדו שספריו טעונים גניזה. פרסם מאמרים ב\"תל תלפיות\" - וייצען תרנב-תרעד."},{"i":11888,"n":"גלזנר, עקיבא מקלויזנבורג","f":"משה שמואל גלזנר","k":"בעל בעקבי הצאן","bt":"תרמו","bp":"קלויזנבורג","dt":"תשיז - כט תשרי","dp":"ציריך - ירושלים","b":"רב בטשיקסערעדא(=צ'יק-סערעדא)-תרעג, האנשביץ, קלויזנבורג-תרפג על מקום אביו וראש ישיבה, ניצל מהשואה - עבר לשוייץ ברכבת ההצלה. לאחר השואה. חיבר \"דור דורים\" - קלויזנבורג תרצד, ועוד. ?? לא באוצר ??"},{"i":11889,"n":"גלזנשטין, מרדכי יהודה ליב","f":"רי\"צ","k":"בעל פי אריה","bt":"תרא","b":"חתן ר דניאל מוילנא. תלמיד ר מרדכי מלצר. רב בראסני-פלך מוהילוב-תרכה.","bk":[["פי אריה",""]]},{"i":11890,"n":"גלזר, אברהם יצחק מקראקא","bt":"תרכט","bp":"קראקא","dt":"תש","b":"חתן ר מנחם מנדל הולס ממושציסק."},{"i":11891,"n":"גלזר, דוד צבי מירושלים","k":"בעל חמדת צבי","bt":"תרכח","dt":"תשיג","b":"חסיד גור, מחכמי ירושלים. חיבר גם \"שפתי צדיקים\", ועוד."},{"i":11892,"n":"גלזר, זכריה דב ממיעס","f":"יוחנן","bp":"פרשבורג","b":"תלמיד הכת\"ס והשב\"ס. חתן ר שלמה זלמן יעקבוביץ מלקנבך. רב בקניגסווארט-תרמג, רונשפערג, מיעס."},{"i":11893,"n":"גלזר, חיים צבי הירש מפשמישל","bt":"תרכו","bp":"פולין","dt":"תש","b":"חסיד בלז. חתן ר משה מייזלס מפשמישל ואחר כך חתן ר יוסף קליגר אב\"ד גריידונס. רב בדרוהוביטש, רב בפשמישל-תרעא על מקום חותנו. השתתף באהל מועד - פודגורזע תרנח."},{"i":11894,"n":"גלזר, יהושע השל","b":"רב בקרזמיר-תר\"י"},{"i":11895,"n":"גלזר, יהושע מטוריסק","f":"משה שמואל","bt":"תרכג","dt":"תרצא","b":"רב בקאלקי-ווהלין, טוריסק-ווהלין. חתנו ר משה."},{"i":11896,"n":"גלזר, יואל יהודה מקופיל","f":"משה","k":"בעל סוגה בשושנים","bt":"תרי","b":"רב בקרניצע-ווהלין-תרלג, קופין-פודוליה, למיטוב(=לעטיטשוב)-ווהלין, וונקוביץ(=ואנקאויץ)-ווהלין, קופיל-ווהלין."},{"i":11897,"n":"גלזר, יוחנן מפרשבורג","f":"אברהם צבי הרש איסרלס","dt":"תרם - א אייר","dp":"פרשבורג","b":"אביו היה הרב בקרומונוי. משמש בקדש אצל החת\"ס. מחכמי פרשבורג."},{"i":11898,"n":"גלזר, יום טוב ליפמן מניקלשבורג","b":"חתנו - ר אהרן שמואל אסאד מסערדאוהל"},{"i":11899,"n":"גלזר, יעקב אריה מפיעטרקוב","k":"ר יענקלה דיין","dt":"תשג","dp":"פיעטרקוב","b":"חסיד אלכסנדר (והאדמורים שלו קמו לכבודו). ראב\"ד בפיעטריקוב-תרסב גם אצל ר מאיר שפירא שכבדו מאוד. פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר. נספה בשואה."},{"i":11900,"n":"גלזר, ישעיה יחיאל מזדונסקי ואל","b":"אב\"ד זדונסקי-ואלי. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":11901,"n":"גלזר, ישראל מירושלים","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא."},{"i":11902,"n":"גלזר, משה מסטרי","f":"יוסף","k":"בעל אמרי משה","bt":"תרמו","bp":"סטרי","dt":"תשכב","b":"רב בברין (צכיה). עלה לארץ-תש. רב בחיפה. חיבר \"אמרי משה\" תל אביב תשטז."},{"i":11903,"n":"גלזר, צבי הירש","dt":"תשג","b":"דומ\"צ בפרעמיסלא"},{"i":11904,"n":"גלזר, שמעון מליטא","k":"בעל מדריך ביהדות-אנ'","bt":"תרלז","bp":"ארז'ווילקי-ליטא","dt":"תרצט","b":"היגר לארה\"ב-תרנז, היה פעיל ציוני ולחינוך יהודי. ממיסדי ועידת הרבנים האורטודוכסית באמריקה ונשיאה. כיהן כרב בכמה קהלות, ניו יורק-תרפג. פרסם מאמרים בעתונות היהודית. תרגם לאנגלית את משנה תורה לרמב\"ם. חיבר ספרים באנגלית ובהם \"תולדות ישראל\", ועוד."},{"i":11905,"n":"גלט, דוד מבערטש וניו יורק","f":"ישראל יוסף","k":"בעל זבד טוב","bt":"תרכד","dt":"תשד","b":"מחכמי ברטש, נשא ונתן עם חכמי דורו. עבר לניו יורק. חיבר \"זבד טוב\" ניו יורק תשיט."},{"i":11906,"n":"גלט, יהודה ליב מגרודזיסק","b":"רב בגרודינסק"},{"i":11907,"n":"גלט, יהודה ליביש מטיטשין","f":"ישראל יוסף מברטש","k":"אדמור מטיטשין","bt":"תרלד","bp":"ברטש","dt":"תשך","b":"נכד ר יהודה ליב מגרודינסק. חתן ר ישראל דרליך אב\"ד טיטשין. ניצל בשואה ועבר לניו יורק, כיהן כאדמור מטיטשין בארה\"ב."},{"i":11908,"n":"גלט, ישראל יוסף מברטש","f":"יהודה ליב מגרודזיסק","k":"בעל פלפול הלכה","bt":"תר","dt":"תרסו","b":"אב\"ד ברטש, רוזזניאטוב-תרס. חיבר \"פלפול הלכה\" פרמישלא תרס."},{"i":11909,"n":"גלט, צבי אלימלך מדזיקוב","f":"יהודה ליבש","bt":"תרה","dt":"תרע","b":"מחכמי דזיקוב, השתתף ב\"אהל מועד\"-תרנח."},{"i":11910,"n":"גלטמן, מנחם נחום מצרניגוב","b":"רב בצרניגוב-תר\"כ"},{"i":11911,"n":"גלטשטין, יואל זאב (צבי) מהעלמץ","f":"שמעון מבאלאש יארמוט","bt":"תרלב","dt":"תשג-ד","b":"חתן ר יוסף ואלד מהעלמעץ. רב בלעלעס, העלמעץ(=קיראלי העלמעץ) על מקום חותנו וראש ישיבה. חתן ר יוסף ואלד מקירל-העלמץ. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"וילקט יוסף\"."},{"i":11912,"n":"גלטשטין, שמעון מבאלאש-יארמוט","f":"מרדכי אריה ליב מקירל","dt":"תרלח - כ אלול","b":"ראב\"ד ביאווא, באלש-יארמוט(=דארמוט)."},{"i":11913,"n":"גליזר יואל יהודה בן משה","bt":"1850","dt":"ה'תרעה 1915","bk":[["סוגה בשושנים",""]]},{"i":11914,"n":"גלייגו, אברהם","b":"בשנת שע חתם על מכתב רבני צפת לר אהרן ברכיה ממודנא"},{"i":11915,"n":"גלייוויץ, יעקב","k":"בעל עטרת שלמה","dt":"תקעא","b":"רב בזעמלין,אויסטרליץ"},{"i":11916,"n":"גלייזל, בן ציון","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":11917,"n":"גליכר, יעקב","f":"נחום מסנוק","bt":"תרעב","bp":"סנוק","dt":"תש..","b":"תלמיד ישיבת \"עץ חיים\" בסנוק. נספה בשואה."},{"i":11918,"n":"גליכר, משה יהודה מבליגרד","bt":"תרסג","bp":"בליגרד (גליציה)","dt":"תשמא","b":"חסיד צורטקוב. עבר לארה\"ב ולמד בישיבת רבי יצחק אלחנן. מראשי אגו\"י. כתב בעתונים החרדים לפני השואה. חיבר ספר באידיש על ישראל דהאן \"מאמשטרדם עד ירושלים\"."},{"i":11919,"n":"גליל ן, יוסף מספרד או מרוקו","b":"מגדולי הראשונים בספרד-שנת ס', מחכמי סווטא (מרוקו?), בזמן הרשב\"א."},{"i":11920,"n":"גלינסקי, ליפא","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":11921,"n":"גלינקין, מרדכי מארה\"ב","f":"ראובן מחרסון","k":"בעל דרשות הרי\"ב","bt":"תרמד","bp":"זעלודק-ליד וילנא","b":"תלמיד ישיבת לומזה, טיקטין, ר אליהו משה לוין מזעלודק וכונה \"המתמיד מחרסון\". חתן ר אברהם דוד. נסמך מאת: ר מרדכי וייצל מאשמינא, ר בנימין זקהיים מיקטרינסלב. רב בזיטומיר-תרעג ויסד בה ישיבת נוברדוק, דוקשיץ-ליד וילנא, רוזינאי-ליד גרודנא-תרצב, דנציג-תרצה, היגר לארה\"ב וכיהן כרב בואוסטר-תרצט. חיבר \"גלי ים\", \"דרשות הרי\"ב\". חבר אגודת הרבנים באמריקה ותנועת המזרחי."},{"i":11922,"n":"גליס, אהרן דב בר מאיזנשטט","b":"רב באייזנשטט. חתניו - ר מרדכי קורנפין משטיינמנגר, ור משה קרמר."},{"i":11923,"n":"גליס, דוד יצחק","b":"רב-שנת תר\"כ"},{"i":11924,"n":"גליס, הרץ מדרוהוביטש","b":"רב בישיבה בדרוהוביטש. תשובה אליו \"אביר יעקב\"."},{"i":11925,"n":"גליס, יעקב מירושלים","k":"בעל תולדות גדולי ירו","dt":"תשנז - ג חשון","dp":"ירושלים","b":"מחכמי ירושלים וחוקר ירושלים. חיבר גם ליקוט מבעלי התוספות על התורה, ועוד."},{"i":11926,"n":"גליס, יעקב מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":11927,"n":"גליס, נחום אורי מסלטוינה","f":"דוד יצחק","bt":"תרטו","dt":"תרץ","b":"רב בקידרניץ-תרלז, סלטוינה-תרמד על מקום חותנו. סידר לדפוס שות דרושים והספדים. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג. נסמך מאת: ר צבי אורנשטין, ר יצחק שמלקיש מלבוב, ר\"י וידינפלד מהרומילוב, ר יואל אשכנזי מזלוטשוב."},{"i":11928,"n":"גליפפא מבורך, אליהו דוד מירושל","f":"דוד או חיים מבורך","k":"בעל יד אליהו","bp":"סופיה","dt":"תק או תקכח","dp":"רודוס","b":"מחכמי טורקיה, עלה לארץ-תסב, ולימד תורה בירושלים, נאלץ לעזוב מחמת רדיפות לרודוס, שם התמנה לרב. חיבר \"יד אליהו\" קושטא תפח. נספד בספר \"קידש ידיד\"."},{"i":11929,"n":"גליפפא מבורך, אליהו מרודוס","b":"רב ברודוס-תפד - משנהו של ר אליהו ן ארדיט."},{"i":11930,"n":"גליפפא מבורך, חיים מסופיה","f":"אליהו","bp":"אדרינופול","dt":"תלד - כט שבט","dp":"סופיה","b":"רב הכולל בסופיה-שנות ה-ת'. בנו - ר אליהו מסופיה וירושלים."},{"i":11931,"n":"גליפפא, אליהו מאזמיר","b":"רב באזמיר, עסק גם במסחר."},{"i":11932,"n":"גליפפא, חיים מספרד","k":"בעל אגרת הגאולה","b":"מגדולי חכמי ספרד,רב בפמפלונא-קס, חיבר \"אגרת הגאולה\" - על ביאת המשיח - והיתה בידי הרב אברבנאל ובעל העיקרים שהזכירוה בחיבוריהם. האגרת הגיעה לידי ר דוד אופנהיים. וחיבור ממנו על מסכת עבודה זרה היה בידי די רוסי. חיבר גם \"עמק הרפאים\", פירוש לסדר העבודה (כת\"י פארמא)."},{"i":11933,"n":"גליפפא, יצחק מחברון","b":"חזן הקהלה בחברון-שנות ה-ש' - בזמן כהונת ר יצחק גריש."},{"i":11934,"n":"גליפפא, שאלתיאל מאזמיר","b":"רב באזמיר תחילת המאה ה-17, עם ר שאול חמאני, ר שלום ראובן, ר אברהם פעטשו ועוד."},{"i":11935,"n":"גליצנשטין, שמעון מירושלים","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפו, \"שערי ציון\" - ירושלים תרפא, \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":11936,"n":"גליצקי, חיים משה הלוי","f":"יעקב","bt":"תריט","b":"רב בהנישישוק(=האנעשישאק)-תרמד."},{"i":11937,"n":"גליק, אביגדור הלוי מצעהלים","b":"אביו של א אברהם צבי מצעלקדאמלעק."},{"i":11938,"n":"גליק, אברהם יצחק מטאלטשווא","f":"שמאי","k":"בעל יד יצחק","r":"אב\"ד טולטשווא","bt":"תקפו","bp":"וירטש-ליד דברעצן","dt":"תרסט - ב אייר","b":"תלמיד ר שמואל שמלקי מדבלקן וסעלעש, ר יצחק צבי מרגרטן מאבראהאם בעל תוקף התלמוד, ר משה פערלס מבאניהאד. רב בטאלטשווא-תריט. חתן ר ישעיה בנט מקאלוב. חיבר גם \"באר יצחק\". הסכים על כתב העת \"וילקט יוסף\" - עם גדולי רבני הונגריה, והספד עליו שם. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא, \"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג, \"תורה מציון\" - ירושלים תרנה-תרסה, \"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["באר יצחק – גיטין",""],["יד יצחק – שו\"ת",""],["באר יצחק [עהש\"ס]",""]]},{"i":11939,"n":"גליק, אברהם צבי מצעלדאמלעק","f":"אביגדור הלוי מצעהלים","bt":"תרן","bp":"צעהלים","dt":"תשד - טז תמוז","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור אליעזר דוד גרינולד, ור יהודה ליב פרידמן מפרשבורג. חתן ר יחיאל הופמן. ר בצעלדאמלעק. נספה בשואה. בנו ר חנוך שלום רב בניו יורק."},{"i":11940,"n":"גליק, אליהו","f":"חנוך הניך מפאפא","b":"תלמיד החת\"ס."},{"i":11941,"n":"גליק, גדליה מבוקין","f":"חנוך הניך","k":"בעל חיי עולם","bt":"תקנו","bp":"פאפא","dt":"תרמב - כא חשון","dp":"בוקין","b":"מחכמי בוקין-תקף. תלמיד ר בנימין זאב וולף בסקביץ מבאניהאד והחת\"ס. חתן ר אברהם אורנשטין (בהשפעת רבו) מבוקין ועבר לשם, ובזיוו\"ש חתן ר משה ליברמן (שטרן) מאבראהאם. תשובה אליו ב\"חתם סופר\"."},{"i":11942,"n":"גליק, חנוך הניך מטערצל","f":"נתן נטע מפאפא","b":"תלמיד הכת\"ס. חתן ר יהודה ליבש פנט מטערצל, וגיסו של ר יחזקאל פנט מקרלסבורג."},{"i":11943,"n":"גליק, חנוך שלום הלוי מניו יורק","f":"אברהם צבי מצעלאדמלק","b":"רב קהל \"בית אברהם\" בניו יורק. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":11944,"n":"גליק, יהודה ליב מרצפערט","f":"חנוך הניך","b":"תלמיד החת\"ס. רב ברצפערט-תריא."},{"i":11945,"n":"גליק, יהושע דוד מבוזנוב","b":"דיין בבוזנוב, תשובה אליו ב\"שערי דעה\"."},{"i":11946,"n":"גליק, יואל צבי מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":11947,"n":"גליק, יוסף הכהן","b":"רב בטעלעכאן"},{"i":11948,"n":"גליק, יוסף ישעיה מסטמר","dt":"תרצ.. - בערך","b":"מחכמי סטמר-תרנו, וראש ביהמ\"ד חברה משניות."},{"i":11949,"n":"גליק, יוסף ישעיה משימלויא","bt":"שימלויא","b":"תלמיד הכת\"ס, ור מרדכי שוורץ משימלויא. רשם את חדושיו רבו הכת\"ס. רב בסילאדי-טשעה וחתם בתרנז על פסק דין יחד עם האב\"ד."},{"i":11950,"n":"גליק, יוסף מאיר מקזמרק","f":"יצחק-חינוך בית יצחק","bt":"תרלח","b":"חתן ר אברהם גרינברג מקזמרק(=קעיזמארק). תלמיד ר שמואל רוזנברג מאונסדורף. דומ\"צ בקזמרק-תרן אצל חותנו."},{"i":11951,"n":"גליק, יעקב יצחק משעסבורג","f":"נתן נטע","bp":"דברצין","dt":"תרע","b":"תלמיד הכת\"ס, ר מנחם מנדל פאנט בדעש. חתן ר בנימין בינוש פרקש (שען שזכה לאות הצטיינות מן הקיסר על המצאה שהמציא). רבה הראשון של שסבורג. חתנו - ר מרדכי רוקח הרב מבילגוריי ואביו של האדמור ישכר דב רוקח מבלז."},{"i":11952,"n":"גליק, יצחק מניו יורק","k":"בעל עולת החודש","b":"רב בניו יורק. עורך הירחון \"עולת החודש\" נ\"י תשלו, יחד עם ר אהרן פר\"מ."},{"i":11953,"n":"גליק, יצחק מסנט-פעטר","k":"בעל חינוך בית יצחק","bt":"תקצה","dt":"תרמח - ז טבת","b":"מרביץ תורה, רב בפלדיהאז(=פעלגי-האז), סט-פטר(-סנט-פעטר)-תרל על מקום ר חיים סופר וראש ישיבה וחתנו ר חיים פריד על מקומו אחריו. מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד. חתנו - ר חיים יוסף בן שמואל דוד יונגרייז."},{"i":11954,"n":"גליק, ישראל מאיר מקעזמרק","f":"יצחק גליק","dt":"תשד","b":"דומ\"צ בקעזמרק-תר\"נ. פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח, \"הנשר\" - טירנוי תרצג-תשד."},{"i":11955,"n":"גליק, מנחם מנדל מקעמעטשע","f":"גדליה מבוקין","bt":"תקעח","dt":"תרסה - ד אלול","dp":"קעמעטשע","b":"תלמיד החת\"ס, ור מאיר א\"ש. חתן ר משה יהודה ליב אדליס מוועקע, ובזיוו\"ש חתן ר אבא גוטמן מוועקע. רב בקעמעטשע-תרך, חתנו ר אברהם יצחק שטיין (או לנורוביץ) על מקומו אחריו."},{"i":11956,"n":"גליק, מנחם מערלוי","f":"יצחק מסנט פעטער","b":"דיין בערלוי(=אויהל). חתן ר שבתי שעפטל ברוינפלד מערדא-טעלעק."},{"i":11957,"n":"גליק, מנשה מקאפוש","b":"מראשי קהלת קאפוש, חתם-תרמב על מינוי ר יהושע פריד."},{"i":11958,"n":"גליק, מרדכי יהודה ליב מיאהאנא","bp":"סאנטוב","dt":"תרכו - יז אלול","dp":"יאהאנא","b":"תלמיד החת\"ס והכת\"ס. גיסו של ר מנחם מנדל פרידלנדר מסענט-ירגין. עבר לבוהר-סנט מיקלאש-תקצב אל חותנו. רב ביאהאנא-תקץ. חתנו - ר יעקב לויפר מיאהאנא."},{"i":11959,"n":"גליק, מרדכי ליב נייראטה מיאהאנ","dt":"תרכד - יז אלול","dp":"יאהאני(=יאהאנא)","b":"תלמיד החת\"ס. רב בסאנטוב, יאהאנא. נזכר בשו\"ת החת\"ס."},{"i":11960,"n":"גליק, משה","b":"פרסם מאמרים ב\"כתר תורה\" - אושפיצין תרצט."},{"i":11961,"n":"גליק, נתן נטע מפאפא","f":"חנוך הניך מפאפא","b":"תלמיד החת\"ס. מחכמי פאפא. בנו - ר חנוך הניך מטערצל."},{"i":11962,"n":"גליק, צבי הירש","f":"זאב וולף","bt":"1921","bp":"וילנא","dt":"1944","dp":"אסטוניה","b":"משורר ופרטיזן. חיבר את שיר הפרטיזנים \"זאג נישט קיינמאל..\". נספה בשואה. לתולדותיו ויצירתו \"הירשקע גליק\" מאת מ. דבורז'צקי - פאריס 1966."},{"i":11963,"n":"גליק, ראובן מואראזשדין","b":"חתן ר אברהם זינגר מוארפאלטא. רב בואראזשדין."},{"i":11964,"n":"גליק, ראובן ממוהליוב","b":"ר\"מ במוהליב, רב בקוחאנובקה, מלחובקה, עלה לארץ תרצד. פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":11965,"n":"גליק, שמואל","dt":"תשד","b":"רב באוילאק"},{"i":11966,"n":"גליק, שמואל צבי מירושלים","bt":"תרד","dt":"תרפט - ב אלול","b":"רב בריגה,ברונקס,עלה לא\"י-תרפ\"ב. תרגם עין יעקב לאנגלית. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":11967,"n":"גליקו, אלישע מצפת","f":"גבריאל","k":"בעל פירוש שיר השירים","dt":"שמג","dp":"צפת","b":"מחכמי צפת בזמן מהר\"י בן לב, תלמיד ר יוסף קארו, חתום עמו על פסק המופיע בשות \"אבקת רוכל\" ביחד עם ר משה מטראני ור משה אלשיך. מתשובותיו בספר \"כנסת הגדולה\", חיבר פירוש על מגילת קהילת ונציה שלח, אסתר שם שמג, ושיר השירים שמז. ועוד ספרים. נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים. בסוף ימיו עמד בראש ישיבה גדולה. בנו - גבריאל. מתלמידיו ר גרשון קוציאן בן שמחה, ר יוסף בנבנישתי."},{"i":11968,"n":"גליקו, אפרים ממודנא","f":"יוסף יצחק","k":"בעל שעשועי אפרים","b":"מחכמי מודנא-תקמ. תלמיד בעל \"זרע אמת\". חיבר \"שעשועי אפרים\"."},{"i":11969,"n":"גליקו, ברוך ממנטובה","dt":"שפט","b":"רב במנטובה-שפ\"ב"},{"i":11970,"n":"גליקו, גבריאל מצפת","f":"אלישע","b":"מקובל מחכמי צפת-שפב, בשליחות, לאחר פרעות הערבים עזב, רב בטיריא. מקורב לר יוסף טרני-מהרי\"ט."},{"i":11971,"n":"גליקו, דוד","f":"יהודה"},{"i":11972,"n":"גליקו, יואב ממנטובה","b":"מגדולי חכמי מנטובה-שנת ת'"},{"i":11973,"n":"גליקו, יוסף יצחק ממודנא","b":"רב במודנא-תק בזמן בעל \"תודת שלמים\". בנו ר אפרים על מקומו אחריו."},{"i":11974,"n":"גליקו, מנחם מצפת","b":"רופא מחכמי צפת - בשנות ה-ש. תשובה ממנו בשות מהריט\"ץ. נזכר ב\"מעשה חייא\""},{"i":11975,"n":"גליקו, מרדכי מצפת","b":"רב ומקובל בצפת. מתלמידי הארי ונזכר בספר החזיונות, אחיו של ר יהושע."},{"i":11976,"n":"גליקו, משה","b":"נזכר בחיד\"א שראה מכתבו."},{"i":11977,"n":"גליקו, רפאל משה שלמייא מירושלי","dt":"תקלא - יא שבט","dp":"ירושלים","b":"מחכמי ישיבת \"דמשק אליעזר\" בירושלים-תקיח, ממשפחת רבנים באיטליה, בשנת תקיא הצטרף לחבורת המקובלים, מחכמי ישיבת \"חסד לאברהם ובנין שלמה\", והיה מחותמי כתב התקשרות \"אהבת שלום\"-תקיד."},{"i":11978,"n":"גליקו, שלמה אברהם","b":"רב בסיינה. תשובה ממנו בשו\"ת הרמ\"ז-תכח."},{"i":11979,"n":"גליקו, שמואל מצפת ואיטליה","k":"בעל עסיס רמונים","b":"מקובל מחכמי צפת-שס, תלמיד הרמ\"ק. רב בונציה, פיררה, מנטובה. חיבר קיצור ל\"פרדס רמונים\" לרמ\"ק בשם \"עסיס רמונים\" עם הגהות ר מרדכי דאטו."},{"i":11980,"n":"גליקיען, יצחק מירושלים","b":"מחכמי ירושלים, חתם-תרה על שטר חזקה עם ר יוסף יואל ריבלין. נכדיו(-בני בתו) האחים אמדורסקי."},{"i":11981,"n":"גליקליך, אהרן מניר-באטור","dt":"תשד","b":"רב בניר-באטור"},{"i":11982,"n":"גליקליך, אורי מניר-באטור","dt":"תשד","b":"רב בניר-באטור"},{"i":11983,"n":"גליקליך, יוסף מנחם מנאנאש","f":"יעקב מהלישוי","k":"אדמור מליסקא","dt":"תרסח - יג סיון","dp":"ליסקא","b":"מצאצאי בעל הש\"ך. חתן ר צבי הירש האדמור מליסקא."},{"i":11984,"n":"גליקליך, יוסף מקלינורדין","dt":"תשד","b":"רב בקליינוורדיין"},{"i":11985,"n":"גליקליך, יצחק ננשר","f":"מיכאל","b":"רב בננש, על מקומו ר אלכסנדר משה קליין."},{"i":11986,"n":"גליקליך, מיכאל מננש","f":"יעקב מהלישוי או יוסף","dt":"תרט - ח אב","b":"מחסידי אשוואר של ר יצחק איזיק טויב מקאליב, וחסיד ר נפתלי צבי מרופשיץ. רב בננש-הונגריה, ושם משפחתו גם ננשר. מנכדי הש\"ך - ירשו את דירתו בהלישוי. חסיד קאליב ורופשיץ. חתנו - ר ברוך'ל גולדברגר ננשר מרצפרט. בנו ר יצחק ננשר על מקומו אחריו. צוואתו נדפסה בתוך \"נחלת צבי\" - גליון ו."},{"i":11987,"n":"גליקמן, אלתר מאיר דוד","dt":"תשד","b":"רב בסוסנובצה"},{"i":11988,"n":"גליקמן, אריה ליב מדבלין","b":"רב בדבלין-אירלנד. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":11989,"n":"גליקמן, יוסף מברזוב","f":"יחיאל מרדכי","dt":"תרצט","b":"שו\"ב לחסידי רוזין בברזוב.חתן ר יצחק בלומנפלד."},{"i":11990,"n":"גליקמן, יצחק","b":"רב בסוסנוביץ, מחכמי ירושלים, בשנת רסט חתם על התקנה לשחרור תלמידי חכמים ממס."},{"i":11991,"n":"גליקמן, יצחק מברזוב","f":"יוסף מברזוב","k":"בעל שואה ותקומה","b":"חתן ר משה זכריה הלוי מסנוק בן אברהם צבי הלוי מאיר. ניצל מהשואה - גורש לסיביר, רב במחנות בגרמניה. עלה לארץ-תשט וכיהן כרב בחולון. חיבר \"שואה ותקומה\" תל אביב תשכד."},{"i":11992,"n":"גליקמן, משה ממינסק","b":"משכיל וסופר במינסק-תרן."},{"i":11993,"n":"גליקמן, נפתלי צבי מסוסנוביץ","f":"יצחק","k":"אדמור מסוסנוביץ","bp":"סוסנוביץ","dt":"תשנה","b":"חתן ר נחמיה פרלוב מקוידנוב. ניצל מהשואה. היגר לארה\"ב. כיהן כאדמור מסוסנוביץ-קוידנוב. מחותן עם האדמור ממזבוז."},{"i":11994,"n":"גליקסברג, שמואל יעקב","bt":"תרנד","dt":"תשלד - ו אדר","b":"רב ביונוב-תר\"פ,בונס-אירס-תש\"ו,עלה לירושלים"},{"i":11995,"n":"גליקסברג, שמעון יעקב מאודסה","f":"מאיר דב הלוי","k":"בעל מושגי החיים","bt":"תרל-ב","bp":"מזריטש-פלך סיעדליץ","dt":"תשיא - כט כסלו","b":"תלמיד ר יוסף הכהן ראויטש מברסטוביץ. חתן ר מרדכי דוד אלפרט בעל \"יד מרדכי\". תלמיד קיבוץ האברכים במינסק ומגיד שיעור, דרשן, חכם וסופר, חובב ציון, רב בוואקזאל-פינסק-תרסב, אודיסה-תרסז, עלה לארץ וכיהן כרב בתל אביב-תרצז. חיבר גם \"ישראל ואורייתא\".","bk":[["ישראל ואורייתא",""],["מושגי החיים",""],["תורת הדרשה",""]]},{"i":11996,"n":"גליקסון, מרדכי חיים מחברון","f":"צבי הירש","k":"בעל ילקוט קרית ארבע","dp":"ירושלים","b":"רב בחברון, והיה ראש קהלת חסידי ללוב שם, עבר לירושלים."},{"i":11997,"n":"גליקסון, צבי דב הלוי מוארשא","dt":"תשב","dp":"גיטו וארשא","b":"חתן ר חיים סולוביציק. ראש ישיבת \"תורת חיים\" בוארשא מיסודו של חותנו. נספה בשואה (בגיטו וארשא). חתנו - ר מאיר פינקל הי\"ד בן אלעזר יהודה ממיר."},{"i":11998,"n":"גליקסון, צבי הירש מוארשא","k":"חתן ר חיים סולוביציק","b":"חתן ותלמיד ר חיים סולוביציק. ראש ישיבת תורת חיים בוורשה-תרפ. חתנו - ר אברהם מאיר פינקל."},{"i":11999,"n":"גליקסמן, אברהם ישעיה מאללכסנדר","f":"צבי מאיר","bt":"תרכ","b":"רב בשלוש עיירות (ברבנות משותפת) - סליזעווא, צעחאצינעק ואלכסנדרוב-פלך וארשא-תרמח, ולאחר פיצול הקהלות-תרסו נשאר כרב באלכסנדרוב."},{"i":12000,"n":"גליקסמן, ברוך בנדט חריף מלאסק","f":"יעקב מקויל","k":"בעל נחלת ברוך","bt":"תקמח","bp":"קויל","dt":"תרח - כו טבת","dp":"לאסק","b":"תלמיד ר אברהם טיקטין בעל \"פתח הבית\" בגלוגא, חתן הגביר ר צבי הירש מלאסק. רב בטורעק-תקצח, מחכמי לאסק - סירב לרבנות. היה מתנגד לחסידות. בנו - ר חיים מזדונסקא וואלא התחבר לחסידי קוצק. חתניו - ר אברהם משירדז."},{"i":12001,"n":"גליקסמן, חיים מזדונסקא-וואלא","f":"ברוך בנדיט מלאסק","k":"ר חיים גבאי","dt":"תריח - ג טבת","b":"מחשובי חסידי קוצק. בניו - ר אברהם ר חיים'ס, ר יצחק ר חיימ'ס."},{"i":12002,"n":"גליקסמן, יהושע","dt":"תשג","b":"רב בסוסנובצה"},{"i":12003,"n":"גליקסמן, יוסף מצנסטחוב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":12004,"n":"גליקסמן, ירחמיאל מנחם מנדל מלו","b":"רב בלודז. פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":12005,"n":"גליקסמן, צבי דב (גליקסון?)","f":"אברהם מוארשא","b":"חתן ר חיים סולוביציק."},{"i":12006,"n":"גלמבוצקי, משה","f":"אליעזר","k":"בעל ספורים ואגדות","bt":"1882","bp":"שטוצ'ין-ליטא","dt":"1944","b":"סופר ועתונאי. תלמיד ישיבת מיר. פרסם מאמרים וכתבים בכתבי עת ובהם \"השלוח\". היגר לארה\"ב-1909, והיה עורך \"שבלים\", ועוד. חזר לרוסיה ותיאר את חיי היהודים באמריקה. ערך עתוני ילדים ובהם \"השחר\", ועוד. עלה לארץ-1925. ותרגם ספרים לעברית. חיבר גם \"דור עובר\", ועוד. ?? לא באוצר ??"},{"i":12007,"n":"ג'למיסי, נחום משלוניקי","b":"דיין בשלוניקי אצל ר אהרן ן חסון."},{"i":12008,"n":"גלמן, מרדכי מטרנירודה","b":"תשובה אליו במהרש\"ם."},{"i":12009,"n":"גלמן, פנחס מיקטרינסלב","f":"ישראל אפרים","bt":"תרמ","dt":"תרפ","b":"רב ביקטרינסלב(=יעקאטרינסלאוו)-תרסז."},{"i":12010,"n":"גלמסי, אברהם","b":"בשנת שח חתום על תקנה לשחרור תלמידי חכמים ממסים"},{"i":12011,"n":"גלנדואר, אברהם מהאלטש","f":"חיים","bt":"תקפד","bp":"עיר חדש","dt":"תרטז - ד תמוז","dp":"עיר חדש","b":"תלמיד הכת\"ס, ור יצחק משה פרלס מבאניהאד. רב בעיר חדש-תריג, נבחר לרב בהאלאש-תרטז אולם נפטר לפני הגיעו לשם."},{"i":12012,"n":"גלנדוי, אברהם","dt":"תרטז","dp":"ניישטטל","b":"נתקבל לרב בהאלאש אך נפטר בדרכו לשם"},{"i":12013,"n":"גלנהויזר, שלמה מפפד\"מ","dt":"שצח","b":"מחכמי פפד\"מ."},{"i":12014,"n":"גלנט, אברהם נפתלי הלוי מנ\"י","f":"אליהו יוסף מרודזינוב","k":"בעל משל ומליצה","bt":"תרלו","dt":"תרצו - כט שבט","b":"נסמך מאת ר יונה זלוטניק מפלוצק, היגר לארה\"ב-תרסו, רב בניו יורק-תרפז. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט. חיבר גם \"חזיונות אברהם\"."},{"i":12015,"n":"גלנט, אליהו יוסף מרדזינוב","b":"אב\"ד רדזינוב. בנו - ר אברהם נפתלי מניו יורק."},{"i":12016,"n":"גלנטי - משפחה","b":"מקור השם - \"גלנטי אומו\" באיטלקית - איש בעל מידות טובות."},{"i":12017,"n":"גלנטי אברהם בן מרדכי","dt":"ה'שכ 1560","bk":[["קול בוכים",""]]},{"i":12018,"n":"גלנטי שמואל בן מרדכי","bt":"1750","dt":"ה'תקע 1810","bk":[["בנוית ברמה [ב\"ח]",""],["נתיבות עולם",""]]},{"i":12019,"n":"גלנטי, אברהם מאיטליה וצפת","f":"מרדכי אנגל מרומי","k":"בעל ריח יקר","bp":"רומא","dt":"שכא-שמח","dp":"צפת","b":"אחיו של ר משה-המוסמך. רב ומקובל בצפת. תלמיד ר משה קורדובירו, והאר\"י. בנה מכספו את ציון הרשב\"י במירון. חיבר פירוש על הזהר בשם \"ריח יקר\" שנדפס קיצור שלו ע\"י ר אברהם אזולאי בשם \"זהרי חמא\" ונציא תטו. קינת סתרים ונציא שמט, זכות אבות בילגוריי תרעא, וכן מספר כתבי יד. בניו ר שמואל מצפת, ר מנחם בעל \"ירח יקר\"."},{"i":12020,"n":"גלנטי, אברהם מדמשק","f":"משה","b":"מרבני דמשק, מקובל"},{"i":12021,"n":"גלנטי, אברהם מרודוס","bt":"תרם","bp":"רודוס","b":"הסטוריון, הו\"ל \"לה ב'ארה\" בקהיר, פרופ' בפורטוגל, עורך \"המנורה\" בקושטא. חיבר ספרים בצרפתית בנושאי הסטוריה של יהודי המזרח."},{"i":12022,"n":"גלנטי, אברהם משלוניקי","f":"משה","dt":"תן","dp":"שלוניקי","b":"רב בשלוניקי. אולי הוא שעלה לירושלים והיה בצפת-תנב."},{"i":12023,"n":"גלנטי, אברהם משלוניקי - ב","f":"משה - המוסמך","b":"אחיינו של ר אברהם בן מרדכי גלנטי. תלמיד ישיבת ר אברהם מוטאל בשלוניקי, רב בשלוניקי."},{"i":12024,"n":"גלנטי, אברהם משלוניקי וירושלים","f":"משה","dt":"תנו","dp":"דמשק","b":"רב בשלוניקי, עלה לירושלים, בשליחות ירושלים-תמה בתורכיה ויוון, רב בצידון על מקום ר שלמה בן בנימין הלוי, צפת-תנב."},{"i":12025,"n":"גלנטי, אברהם מתורכיה","f":"משה","k":"בעל לקורות היהודים ב","bt":"תרלג","bp":"בודרום-תורכיה","b":"פעיל פוליטי ומקורב לתורכים הצעירים, יסד מפלגה בשם \"ועד יהודי מצרי\", פרסם מאמרים בעתונים."},{"i":12026,"n":"גלנטי, אהרן מדבלין","b":"רב בדבלין-אירלנד. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":12027,"n":"גלנטי, ידידיה","f":"משה - המוסמך","k":"בעל מודעת זאת בכל","bp":"צפת","b":"בכמה מקומות נקרא בטעות יום טוב במקום ידידיה. מחכמי צפת, בשנת שסז-שעד בשליחות, חיבר \"מודעת זאת בכל הארץ\" ונציה שסט, הדפיס בונציה את ספרו של אביו שאלות ותשובות ובסופו חדושים ודרושים שלו. חיבר \"שיטה\" לכמה מסכתות וילמרסדורף תעו. ר יום טוב צהלון מביא ממנו בספרו."},{"i":12028,"n":"גלנטי, יונתן מדמשק","f":"משה מדמשק - ברך משה","b":"הקדשה ממנו לגביר נתנאל די לישבונה על ספר אביו - ברך משה."},{"i":12029,"n":"גלנטי, יונתן ממצרים","b":"דיין ומו\"צ באלכסנדריה-תקכ, מתלמידיו - ר ידידיה ישראל גלנטי."},{"i":12030,"n":"גלנטי, יונתן מצפת","f":"משה - המג\"ן","dt":"תלח - תמוז","dp":"צפת","b":"מחכמי צפת, יצא בשליחות צפת בשנים תטו ותיט עם ר ברוך ברזילי, בהיותו בקושטא-תטז כיהן כדיין להתרת עגונה. רבה של צפת לאחר ר שמואל עדילה. בנו היה ר משה גלנטי, וחתניו ר משה חביב ור שלמה הלוי. מחדושיו בספר \"זבח השלמים\" ו\"קרבן חגיגה\" לבנו ר משה - המג\"ן. חתם עם רבני צפת בשנת שצז."},{"i":12031,"n":"גלנטי, יוסף","b":"רב בטירה"},{"i":12032,"n":"גלנטי, מנחם מצפת","f":"אברהם - ריח יקר","b":"מחכמי צפת, בשנת שע חתם עם חכמי צפת על מכתב בקשה לר אהרן ברכיה ממודנא."},{"i":12033,"n":"גלנטי, מרדכי אנגל מרומא","b":"גביר מחכמי רומא, אבי משפחת גלנטי. תשובות ממנו ב\"ברכות מים\" להרב מיוחס. עוד שו\"ת בכת\"י. בניו: ר משה - המוסמך, ר אברהם."},{"i":12034,"n":"גלנטי, מרדכי מדמשק","f":"משה","k":"בעל דברי מרדכי","dt":"תקמא","dp":"דמשק","b":"מחכמי ארץ ישראל, רב בדמשק ובנו ר משה בעל \"ברך משה\" על מקומו אחריו. חיבר \"דברי מרדכי\" ליוורנו תרך. מתשובותיו ב\"בית דין של מעלה\"."},{"i":12035,"n":"גלנטי, משה הלוי מסטריזוב","f":"מרדכי","k":"בעל משל ומליצה","bt":"תקטו","bp":"שנדישוב","dt":"תקעה","b":"מחכמי סטריזוב - אחיו ר שמואל כיהן שם כרב. חיבר \"משל ומליצה\" למברג תרן."},{"i":12036,"n":"גלנטי, משה מדמשק","f":"מרדכי - דברי מרדכי","k":"בעל ברך משה","dt":"תקסז","dp":"דמשק","b":"נינו של ר משה גלנטי מצפת. רב בדמשק. מחותן עם ר חי משה פיגוטו. חיבר גם \"דרש דרש משה\"."},{"i":12037,"n":"גלנטי, משה מוידין","b":"רב בוידין - שנות ה-ש'."},{"i":12038,"n":"גלנטי, משה מחלב","b":"מחכמי חלב-תכז. מתלמידי ש\"ץ."},{"i":12039,"n":"גלנטי, משה מירושלים - ג","b":"נכד ר משה בן יונתן גלנטי. מו\"צ בירושלים-תק בערך. דודו של ר יוסף מרדכי מיוחס-מי\"ם המזכירו בספרו."},{"i":12040,"n":"גלנטי, משה מצפת (הנכד) - המגן","f":"יונתן","k":"המגן - בעל זבח שלמים","bt":"שפ","bp":"צפת","dt":"תמט - כא שבט","dp":"ירושלים","b":"מחכמי צפת, תלמיד ר ברוך ברזילי, התיישב בירושלים, ובין תלמידיו היו חתנו ר ישראל יעקב חגיז, ר חזקיה די סילוה ור אברהם יצחקי. בשנת תכז בשליחות בתורכיה. בשנת תכח היה בבודין (הונגריה) והסכים לרב אפרים הכהן רבה של בודין על תשובה. חיבר \"זבח השלמים\" אמשטרדם תסח, ועוד. גיסו(-בעל אחותו) ר שלמה הלוי מאזמיר. (הואשם ע\"י גרץ בשבתאות - ופרומקין מגן עליו)."},{"i":12041,"n":"גלנטי, משה מצפת - המוסמך","f":"מרדכי אנגל","k":"בעל מפתח הזהר","bt":"ש","bp":"רומא","dt":"שמז או שעב","dp":"צפת","b":"אחיו של ר אברהם גלנטי, עלה לצפת עם אביו, ולמד אצל ר יוסף קארו ואף נסמך על ידו. בשנת שמ רבה של צפת כממלא מקום המבי\"ט. חיבר \"מפתח הזוהר\" קושטא של, ועוד. לדעת ד. תמר ב\"סיני\" תכז נפטר אחרי שנת שעד. בניו היו ר ידידיה ר אברהם ור יונתן שהיה ראש הרבנים בצפת."},{"i":12042,"n":"גלנטי, משה משלוניקי","dt":"תמה","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":12043,"n":"גלנטי, שמואל הלוי מסטריזוב","f":"מרדכי","k":"בעל בנוית ברמה","bt":"תקי","bp":"שנדישוב","dt":"תקע","b":"רב בסטריזוב-תקן, שנדישוב-תקסב. חיבר \"בנוית ברמה\" למברג תקסא, \"נתיבות עולם\", ועוד."},{"i":12044,"n":"גלנטי, שמואל מצפת","f":"אברהם","b":"מגדולי חכמי צפת-שס. הו\"ל את ספרי אביו, ונזכר ב\"קול בוכים\"."},{"i":12045,"n":"גלנטי, שמעון מצפת","f":"אברהם","b":"מחכמי צפת, בשנת שע חתם על מכתב לר אהרן בן ברכיה ממודנא."},{"i":12046,"n":"גלניקטין, מרדכי מדוקשיץ ונ\"י","k":"בעל דרשות הרי\"מ","b":"רב בדוקשיץ, ניו יורק-תרעג. ?? לא באוצר ??"},{"i":12047,"n":"גלנץ, אריה הכהן מטישוויץ","b":"רב בטישוויץ"},{"i":12048,"n":"גלנץ, ישראל בנימין","b":"מו\"צ בפאוולוביץ-גליל אונגוואר."},{"i":12049,"n":"גלנץ, מנדל הכהן משינאווי","f":"צבי גלנץ","b":"דיין בשינעווע-תר\"כ"},{"i":12050,"n":"גלנץ, מרדכי יצחק מקומרנא","f":"צבי הירש","bt":"תקע","dt":"תרם","b":"חתן ר אלעזר ויטלס אב\"ד קומרנא. ראב\"ד בקומרנא-תרמ על מקום חותנו, וחתנו ר יעקב ישראל לנגנויר מילא את מקומו."},{"i":12051,"n":"גלנץ, מרדכי מאיר מפלשטין","b":"תשובה אליו בשו\"מ-תריח."},{"i":12052,"n":"גלנץ, עוזר מלודאש","f":"זיסקינד","dt":"תרצז - כ כסלו","b":"שו\"ב בלודאש. חתנו - ר מנחם בן דוד צבי הירש."},{"i":12053,"n":"גלנץ, צבי הירש משינאווא","f":"יעקב דב בר","bt":"תקן","bp":"ציעשינוב","dt":"תרט","b":"חתן ר אריה ליבוש ליפשיץ בעל \"אריה דבי עילאי\". אב\"ד קרסטור-תקעו, שרושפאטיק-תקפו, שיניבה-תקץ על מקום חמיו."},{"i":12054,"n":"גלנץ, שלמה זלמן ממארוש-אויוואר","b":"שו\"ב במארוש-אוייואר-תרם, וכיהן כרב בפועל עד למינוי רבה הראשון ר יזקאל פאנט-תרסב."},{"i":12055,"n":"גלנצברג, איזיק מקנטשונה","b":"דיין בקנטשונה-תרלב."},{"i":12056,"n":"גלנצברג, בצלאל הלוי מליביטשוב","b":"רב בליביטשוב. תשובה אליו \"שערי בנימין\"-תרנו."},{"i":12057,"n":"גלנצר, אברהם מאיר הכהן","f":"יעקב מזאלין","k":"בעל אגם מים","bt":"תרלב","bp":"זלין","dt":"תרפה - טו אייר","dp":"ארה\"ב","b":"תלמיד ר משה גרינוולד בחוסט, ואצל בעל \"קדושת יום טוב\" בסיגט. חתן ר אשר פרידמן מזבורוב. חסיד בלוזוב. עבר להוניאד, רב בזלין. רב בקלינורדין, גרוסורדין-תרס. עסק כטוען ובורר בדיני תורה, יצג את חסידי סטמר בדין תורה על התפלגותם מהקהילה. היגר לארה\"ב וכיהן כרב חסידי בלוזוב שם. הו\"ל מאסף - \"אגם מים\" סיגט תרס."},{"i":12058,"n":"גלנצר, אלחנן","f":"אברהם מאיר-אגם מים","b":"תלמיד ר שמואל רוזנברג מאונסדורף."},{"i":12059,"n":"גלנצר, אריה ליבוש הכהן מבוצאץ","b":"תלמיד המהרש\"ם. חתן הגביר ר ניסן מבוצאץ. רב בבוצאץ. נספה בשואה."},{"i":12060,"n":"גלנצר, יוסף מסעליש","f":"שלמה","dt":"תרכו - ז סיון","dp":"סעליש","b":"חתן ר חיים משה הכהן מסעליש. דומ\"צ באוילאק, סעליש."},{"i":12061,"n":"גלנצר, יעקב הכהן מבולין","b":"רב בבולין-תרמט. תשובות אליו ב\"בית יצחק\"."},{"i":12062,"n":"גלנצר, יעקב מזלין","b":"תשובה אליו \"שדה יהושע\" - תרס."},{"i":12063,"n":"גלנצר, ליבוש מבוצאץ","b":"רב בבוצאץ-תרסא. פרסם חדושים ב\"אהל מועד\"-תרסא ותרפז."},{"i":12064,"n":"גלנצר, משה אבלי מרוהטין","b":"תשובה אליו - \"בית יצחק\"-תרכה."},{"i":12065,"n":"גלנצר, משה אברהם מלבוב","b":"מחכמי למברג-תרסד. תשובה אליו בשות מהר\"ש."},{"i":12066,"n":"גלס, יוסף ירמיהו","f":"נטע רביקוביץ","k":"בעל החדר - תרסח","bt":"1860","bp":"דורביאנקה-פלך צרניגוב","dt":"1933","dp":"וילקומיר","b":"תלמיד ישיבה בליטא, עבר לשאוולי ופתח \"חדר מתוקן\", עסק בחינוך ובכתיבה בנושאי חינוך."},{"i":12067,"n":"גלפיש, אברהם דוד","b":"פרסם מאמרים ב\"תלפיות\" - שנחאי תשו."},{"i":12068,"n":"גלפרין, יעקב","f":"מרדכי","bt":"1840","bp":"וילנא","dt":"1914","dp":"ניצה-צרפת","b":"עורך דין ופקיד בכיר בממשלת הצאר ברוסיה, ובעל התואר \"יועץ סתר\" - שכמעט ולא ניתן ליהודים. משכיל עברי ופעיל צבור. ממיסדי רשת \"אורט\" ונשיאה. פרסם מאמרים ומחקרים בתולדות יהודי רוסיה בכתב העת \"ווסחוד\", \"פאראזיטוייה\", ועוד."},{"i":12069,"n":"גלצר, אלחנן מברוד","bt":"תרלא","bp":"ברודי","b":"תלמיד ר יצחק חיות וכונה \"העילוי מברודי\", ועבר עם רבו ללמברג. עבר לסקול ומתלמידיו שם - דב סדן. עבר לוינה בזמן מלחמת העולם ה-I. פגש את פרופ' אפטוביצר שהעיד עליו כי הוא מגדולי התלמודיים בדור. חזר לברודי וכיהן כרב לצד ר יוסף פופרש - אך לראבד נבחר ר\"י קטן מלשנוב. כתביו אבדו בשואה. אחיו ר אליעזר מלמד בכפר אובין וחזר לברודי."},{"i":12070,"n":"גלצר, חיים מליטא ונ\"י","f":"יעקב","k":"בעל פרי חיים","bt":"תרלט","bp":"קוברין","dt":"תשט","b":"תלמיד ישיבת ראזינאי, לומזה, סלובודקא אצל ר משה מרדכי אפשטין, כולל האברכים בקובנא, איישישוק. חתן ר דוד לוין מאיוויע-פלך וילנא. נסמך מאת: ר יוסף זונדל מאיישישוק, ר משה דנישבסקי, ר מאיר אטלס מקוברין, ר משה שמואל מברויסק, ר שמואל קיפניס מדאוורוטש וירושלים. רבב בזיים-פלך קובנא-תרסו, טעלציץ-פלך מינסק-תרעג, סלבשנה(=סלאוועשנא)-פלך ווהלין-תרפא, היגר לארה\"ב וכיהן כרב בנוארק-ניו ג'רסי-תרפד. נסמך מאת: ר משה דנישבסקי מסלובודקא, ר מאיר אטלס משאוועל, ר יוסף זונדל מאישישוק. חיבר \"פרי חיים\" - בכת\"י."},{"i":12071,"n":"גלצר, יעקב מטבריה","f":"יהודה","b":"מחסידי טבריה-תקמו, ר מנחם מנדל מויטבסק מבשר על בואו. חתם על כתב שליחות-תקנו."},{"i":12072,"n":"גלקון, אפרים מפאס","f":"שלמה","b":"מחכמי פאס בזמן הרשב\"ש ונזכר בשו\"ת הרשב\"ש."},{"i":12073,"n":"גלקון, שלמה ממרוקו","b":"מחכמי פאס-מרוקו, בנו ר אפרים נזכר בשות הרשב\"ש."},{"i":12074,"n":"גלר, אברהם מקריפטש","f":"דוד","bt":"תקנג","bp":"סמבור","dt":"תרנו - כג תמוז","b":"מקורב לגדולי החסידות, תלמיד ר מנחם מנדל מרימנוב, ור שמעון מירוסלב, ועוד. חתן ר צבי בן דוד שיף מקריפטש. רבה של קריפטש למעלה משבעים שנה. נכדו ר דוד ארי כיהן כרבה האחרון של קריפטש. נפטר למעלה מגיל מאה. צוואתו נדפסה בספר נינו \"ויקונן דוד\". בניו: ר דוד מניזקוביץ, ר בנימין זאב, ר משה אליעזר. חתנו ר דוד אלימלך וורובל מיאשניץ."},{"i":12075,"n":"גלר, אליהו צבי","b":"תשובה אליו - \"מחזה אברהם\"-תרמד."},{"i":12076,"n":"גלר, אריה ליב מרדימנא","b":"אולי בנו של ר משה מרעדים."},{"i":12077,"n":"גלר, בנימין זאב מבוברקא","f":"דוד מניזנקוביץ","bt":"תרכא","bp":"ניזנקוביץ","dt":"תרפט","b":"חתן ר עוזר מגריידונג. רב בניזנקוביץ לצד אביו. רב בקריפטש-תרנה על מקום זקנו ר אברהם. רב בוברקא. חסיד בלז."},{"i":12078,"n":"גלר, דוד מניזנקוביץ","f":"אברהם","bt":"תקף","dt":"תרנו - כט תמוז","b":"אב\"ד ניזנקוביץ-תרך. חתן אחותו של ר אליעזר ליפמן קנביל מרוזניאטוב - והחל לסדר את כתביו לדפוס. בנו ר בנימין זאב רב בקריפטש."},{"i":12079,"n":"גלר, יעקב מדוניוב","b":"היגר מדוניוב לארה\"ב וכיהן כרב ביוסטון-טקסס. מחדושיו שכתב בנערותו יחד עם ר יחיאל מיכל לייטר, נדפס - \"מזכרת אהבה\" - פשמישל תרנב."},{"i":12080,"n":"גלר, מנחם מנדל מפשמישל","b":"סוחר יין מפשמישל. גיסו של ר בריש אברמוביץ מצאנז. ר נתן הבנשטריט העיד עליו שהוא נאמן."},{"i":12081,"n":"גלר, משה אליעזר מקריפטש","f":"אברהם","bt":"תקעג","dt":"תרנה - כב חשון","b":"מחכמי קריפטש לצד אביו הראב\"ד. חתן ר משולם זישא ברצ\"א מדינוב."},{"i":12082,"n":"גלר, צבי הירש","dt":"תקכו - כז טבת","b":"רב בגולוגור,אוסצי,ראש ישיבה בברודי"},{"i":12083,"n":"גלרווג, יוסף מדוניוב","b":"תשובה אליו - מהרש\"ם-תרמג."},{"i":12084,"n":"גלרנט, אליעזר מסטרי","b":"תשובה אליו - \"תועפות ראם\"."},{"i":12085,"n":"גלרנטר, אברהם","dt":"תרפו - טו אלול","b":"רב בניו יורק"},{"i":12086,"n":"גלרנטר, אברהם יוסף יעקב הזקן","f":"ישראל דב בר-רביד הזה","k":"בעל אמרי יא\"י","bt":"תקצו","bp":"ישיניצה","dt":"תרעד","b":"אב\"ד ישיניצה-תריח על מקום אביו, בנו ר מנדל על מקומו אחריו. עלה לירושלים-תרעב. חיבר \"אמרי יא\"י\" ירושלים תרעג. בנו גם ר שמואל נח."},{"i":12087,"n":"גלרנטר, אברהם יוסף יעקב הנכד","dt":"תש..","b":"רב בישיניצה על מקום זקנו. נספה בשואה."},{"i":12088,"n":"גלרנטר, אברהם יוסף מיבלונוב","f":"צבי הירש","k":"בעל תפארת ישראל","bt":"תקמה","dt":"תר","b":"אב\"ד אלטשטט ויבלונוב. חיבר \"תפארת ישראל\" על התורה."},{"i":12089,"n":"גלרנטר, אברהם יעקב בשקא","f":"משה בישרא מטומשוב","b":"רב בטישוויץ-תקעה. הסכים על \"שבחי הבעש\"ט\" - לשצוב תקעה. בנו ר יוסף-חותנו של ר גרשון חנוך מראדזין (איזביצא)."},{"i":12090,"n":"גלרנטר, אברהם מארה\"ב","f":"שלום","bp":"ירושלים","dt":"תרפז - טו אלול","dp":"ניו יורק","b":"היגר לארה\"ב, רב ודרשן בברונזויל, ניו יורק."},{"i":12091,"n":"גלרנטר, אלתר פנחס מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא, \"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף."},{"i":12092,"n":"גלרנטר, דב בריש מבורשטין","f":"שרגא פיבל","dt":"תרצח","b":"מחכמי בורשטין. חתן הגביר ר יוסי לינדנר. עבר ללמברג."},{"i":12093,"n":"גלרנטר, זאב וולף מקראקא","b":"רב בקראקא"},{"i":12094,"n":"גלרנטר, זאב מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":12095,"n":"גלרנטר, חיים מקיטוב","f":"יוסף שמואל מקיטוב","k":"בעל פרי עץ חיים","bt":"תריז","bp":"יבלונוב","dt":"תרפט","b":"חתן ר ישראל ראובן הכהן פיילהאבער מסניאטין. נסמך מאת: ר יצחק אהרן איטינגא, ר יצחק שמלקיש, ר יהודה ליב לנדא מסדיגורא, ר אריה ליב הורביץ מסטניסלב. רב בסניאטין וביבלונוב-תרן על מקום אביו וגיסו ר חיים שמיר, קיטוב-תרנה על מקום אביו, במלחמת העולם הראשונה ברח לגרץ-אוסטריה ונתמנה על ידי הממשלה לרב לפליטים במחוז צעלע, עבר לוינה-תרפד, קיטוב-תרפט. חיבר \"פרי עט חיים\" נדפס חלקית בטשרנוביץ בלמברג ובפשמישל, \"שמחת הח\"ג\" פשמישל תרנב. הסכים על \"אהל יצחק\" סטמר תרסג. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"הבונה\" - לבוב תרסד, \"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה."},{"i":12096,"n":"גלרנטר, יוסף מבריסל","dt":"תשג","b":"רב בבריסל. פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":12097,"n":"גלרנטר, יוסף מדומברובה ולונדון","f":"יהודה ליב מקלימנטוב","b":"רב בארזדוב, דומברובה, ניצל מהשואה (היה גם באושוויץ ואיבד את כל משפחתו) ואחריה רב בלונדון. מכתב ממנו ממחנה הפליטים פלדפינג אל קרובו ר דוד רבינוביץ ומבקש את עזרתו במעבר ללונדון."},{"i":12098,"n":"גלרנטר, יוסף מהוריבשוב","f":"אברהם יעקב גלרנטר","b":"אב\"ד הוריבשוב-תרי. חתנו - ר גרשון חנוך האדמור מראדזין מחדש התכלת."},{"i":12099,"n":"גלרנטר, יוסף מטורלא","f":"מאיר יהושע גלרנטר","b":"חתן ר שמחה מקשינז בעל \"אמרי מהרש\"ח\". רב בטארלא-תר\"ל"},{"i":12100,"n":"גלרנטר, יוסף מקלימנטוב","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":12101,"n":"גלרנטר, יוסף שמואל מקיטוב","f":"משה דב","bt":"תקף","dt":"תרנח","b":"חתן ר ישראל דב בר גלרנטר מישניצא. רב יבלונוב-תרח וקיטוב ובנו ר חיים על מקומו אחריו. חיבר ספרים והשאיר כתב יד שרובם נשרפו."},{"i":12102,"n":"גלרנטר, יצחק מנוביטנץ","f":"ישעיה יחיאל מיכל","k":"בעל יקרה מפנינים","bt":"תרם","dt":"תש","b":"חתן בן דודו ר חיים אב\"ד קיטוב. אב\"ד נוביטנץ על מקום אביו, עבר לקראקא. חיבר \"יקרה מפנינים\" פודגורזע תרפז. חיבר ספרים נוספים שלא נדפסו. ?? לא באוצר ??"},{"i":12103,"n":"גלרנטר, ישעיה יחיאל מיכל","f":"ישראל דב בר מישניצא","bt":"תרב","dt":"תרעד","b":"חתן ר זאב וולף וייס מסנוק, אב\"ד נוביטניץ-ליד סנוק-תרמה, ובנו ר יצחק על מקומו אחריו."},{"i":12104,"n":"גלרנטר, ישראל דב","b":"פרסם מאמרים ב\"תצא תורה\" - קריניצה תרצא."},{"i":12105,"n":"גלרנטר, ישראל דב בר מישניצה","f":"אברהם יוסף מעיר ישן","k":"בעל רביד הזהב","bt":"תקסז","dt":"תרכז-ח","b":"חתן רב ר יעקב מרימנוב. תלמיד ר יעקב צבי יולס מדינוב ו\"החוזה מלובלין\", ואצל גדולי החסידות, למד בלובלין עם ר נפתלי מרופשיץ. נבחר כרבה של סטריזוב-תריז אך ויתר. רב ביבלונוב(=סטאפטשעט)-תרי, רב ואדמור בישיניצה ובנו ר אברהם יוסף יעקב על מקומו אחריו. נזכר ב\"בני ישכר\" שהביא מחדושיו בספרו. חיבר \"רביד הזהב\" למברג תרל, ועוד. בניו: ר משה, ר נפתלי צבי מהורודנקא, ר ישעיה יחיאל מיכל מנאויטאניץ. חתנו ר יוסף שמואל גלרנטר מקיטוב."},{"i":12106,"n":"גלרנטר, מאיר יהושע","f":"צבי הירש גלרנטר","b":"רייוויץ-ת\"ר,טרלא,קונסקי-ווליא,קלימינטוב"},{"i":12107,"n":"גלרנטר, משה","f":"ישראל דב בר מישניצה","b":"רב ברייביץ-תרן. חתנו - ר סנדר איכנשטין מזידיטשוב, ומצאצאיו שושלות אדמורי זידיטשוב וספינקא."},{"i":12108,"n":"גלרנטר, משה מקלוצק","f":"מנחם מנדל","k":"בעל דת משה וישראל","bt":"תרמז","dt":"תשכה","b":"אב\"ד קלוצק ודז'רז'נוב עד תשי. עלה לארץ-תשי וכיהן כרב ברמת גן. חיבר \"דת משה וישראל\" רמת גן תשך."},{"i":12109,"n":"גלרנטר, נפתלי צבי מהורודנקא","f":"ישראל דב בר מישניצא","b":"רב בהורודנקא."},{"i":12110,"n":"גלרנטר, צבי הירש מטומשוב","b":"רב בטומשוב-תקף. תלמיד החוזה מלובלין, ר אברהם יהושע השל מאפטא, וגיסו ר צבי הירש מזידיטשוב. מחותן עם ר אריה ליב מאוזורוב. בנו - ר מאיר יהושע."},{"i":12111,"n":"גלרנטר, ראובן מרדומישל","f":"יוסף מטרלא","b":"רבה של רדומישל קטן עד השואה. כתב ב\"הבאר\"-תרפד."},{"i":12112,"n":"גלרנטר, שאול יהושע מברוד","f":"משה","bt":"תקי","dt":"תקפז","b":"מחכמי ברודי, חתן ר יקותיאל זלמן מברוד."},{"i":12113,"n":"גלרנטר, שמואל נח","f":"אברהם יעקב יוסף","b":"נכד ר ישראל דב בעל רביד הזהב."},{"i":12114,"n":"גלרנטר, שמחה מקלימנטוב","f":"יוסף מטארלא","bt":"תרלב","dt":"תשג","b":"תלמיד זקנו ר מאיר יהושע מקלימנטוב, ר פתחיה הערענבלום מוארשא בעל \"פתחי עזרה\", ר יוסף חיים פרגר בעל \"גן יוסף\". חתן ר אלימלך רובינשטין מראחוב בעל \"כהונת אלימלך\". רב בוואלומין-ליד וארשא-תרנז, קלימנטוב-פלך ראדום-תרסא. נסמך מאת: ר אריה יהודה אפשטין מאיזרוב, ר מאיר יחיאל מאיסטרובצה, ר ירחמיאל מינצבג מלוקובה, ר שלמה מטשכנוב, ר יחיאל מיכל רבינוביץ מנאוי מינסק."},{"i":12115,"n":"ג'מיל ן, יצחק נסים מירושלים","f":"שם טוב נסים","k":"בעל באר לחי רואי","b":"מחכמי טורקיה שעלה לירושלים. רב בירושלים-תכז. זקנו של ר חיים אבולעפיה. חיבר \"באר לחי רואי\" שנדפס עם ספר \"ישרש יעקב\" לנכדו ר חיים (אזמיר תפט). בשנת תכז חתם עם חכמי חברון. חיבר גם \"חיים וחסד\"."},{"i":12116,"n":"ג'מיל ן, משה מסופיה","f":"שלמה","b":"רב בסופיה, בזמן ר יוסף אלמושנינו שעמו התכתב ונזכר ב\"עדות ביהוסף\"."},{"i":12117,"n":"ג'מיל ן, שלמה מסופיה","bp":"יאנינה","b":"רב הקהלה הרומאנית בסופיה-שנות ה-ת'. ולצדו ר ישראל בן שמואל אהובי."},{"i":12118,"n":"ג'מיל ן, שם טוב מספרד ואלגיר","f":"שמואל","k":"בעל שם טוב","bt":"קע - בערך","bp":"ספרד","dt":"רן - בערך","dp":"תלמסאן","b":"רב בטודילא די נאבארה-ספרד, אחרי הגירוש הגיע למרוקו, ומשם לתלמסאן. ?? לא באוצר ??"},{"i":12119,"n":"גמינדר, ישראל זאב וולף ממעליץ","b":"דיין במעליץ-תרכד."},{"i":12120,"n":"גמליאל","b":"רב בשאנלנק-תק\"צ"},{"i":12121,"n":"גמליאל מאלטונא","f":"גמליאל","k":"בעל עבודת הלב","bt":"תקכ","dt":"תקץ - ה סיון","dp":"אלטונא","b":"ר\"מ, דיין באלטונא. בנו - ר פנחס, נכדו - הרופא ר גבריאל לאנצקראן. ?? לא באוצר??"},{"i":12122,"n":"גמליאל מבודה","f":"אברהם","b":"גביר מראשי קהלת בודה-שנות ה-ש'."},{"i":12123,"n":"גמליאל פרובישץ","f":"אברהם","b":"שמש ונאמן קהלת פרובישץ(=פוהרבישט), חתם-תקסט על כתובת האדמור ר ישראל מרוזין."},{"i":12124,"n":"גמליאל, דוד","k":"בעל חפץ דוד","b":"מחכמי צנעא, חיבר \"חפץ דוד\""},{"i":12125,"n":"גן, ישראל יהודה מבאלין-פודוליה","f":"אהרן זאב","bt":"תרכז","b":"מצאצאי ר יעקב יוסף מפולנאה בעל \"תולדות יעקב יוסף\". רב בבאלין-פודוליה-תרנו."},{"i":12126,"n":"ג'נאח בוטלאק, גבריאל מלוב","f":"יהודה","bt":"תרס","dt":"תשיט","b":"סגי נהור. תלמיד ר ציון ביתאן, רב ודרשן בכפר ידדר-לוב, סרת-לוב, מצראתה-לוב."},{"i":12127,"n":"ג'נאח ן, יונה מספרד","k":"רבינו מרינוס","b":"גדול חכמי הדקדוק, רופא בקורדובה-ד'תת. חיבר ספר הרקמה, ספר השרשים."},{"i":12128,"n":"ג'נאח, יעקב מטריפולי","bt":"תקי","dt":"תקף - בערך","b":"מחכמי טריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":12129,"n":"ג'נאח, ישראל מטריפולי","bt":"תף","dt":"תקן - בערך","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":12130,"n":"ג'נאח, מסעוד מטריפולי","dt":"תקלח - לפני","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":12131,"n":"גנאסיה, דניאל מאלגיר","f":"יוסף","dt":"תשמז","dp":"דימונה","b":"רב בקמצטינא, ר\"מ בישיבת \"אור תורה\", עלה לארץ-תשכב. הו\"ל \"מחמד עין\" - סוסה תשח, ועוד."},{"i":12132,"n":"גנאסיה, יוסף מאלגיר","f":"דוד","bt":"תרם","dt":"תשכב","dp":"דימונה","b":"תלמיד ר נסים עלוש. רב ודיין בקצמטינא-תשח. ר\"מ בישיבת \"עץ חיים\", עלה לארץ והתישב בדימונה. נחשב לגדול המתרגמים במגרב ותרגם כ-130 ספרים לערבית יהודית. היה מאחרוני הרבנים בסגנון המסורתי וגם בדרך לימודו - בשיטה המסורתית המבוססת על שינון והבנה בערבית יהודית."},{"i":12133,"n":"גנאסיה, שלום מאלגיר","f":"מרדכי","bt":"תקף","dt":"תרן","b":"מחכמי קצמטינא. שאלות ממנו לר אליהו חזן."},{"i":12134,"n":"גנאסיה, שמעון מאלגיר","f":"מרדכי","bt":"תקס","dt":"תרל","b":"רב וסופר בקצמטינא. כנראה אחיו של ר שלום מקצמטינא."},{"i":12135,"n":"גנגר, דוד מצאנז","f":"מרדכי מצאנז","b":"מחותמי כתב הרבנות להבאת הדב\"ח וכיהן בבית דינו של הדב\"ח. בנו ר ליבוש מבובוב והיה דיין אצל ר שלמה הלברשטם."},{"i":12136,"n":"גנגר, יוסף יעקב מביליץ","f":"יצחק ישעיה","dt":"תשנז","b":"תלמיד קרובו רד\"ב מטשבין. חסיד בלז. עבר לניו יורק ומשם תמך במוסדות בלז."},{"i":12137,"n":"גנדור, יוסף מירושלים","dp":"ירושלים","b":"מחכמי ירושלים, בספר \"פרי האדמה\" (מצורף ל\"פני האדמה\") ישנה תשובה ממנו בענין ספר תורה, היה סופר מומחה והגיה ספר תורה."},{"i":12138,"n":"גנוט, דוד אריה מארה\"ב","f":"יצחק איזיק","bt":"תרסא","b":"תלמיד ישיבות ניראטשאט אצל ר יקותיאל יהודה ליכטנשטין, אויבר-וישיבא אצל ר אליעזר דוד גרינוולד, ר יעקב שלום קליין. נסמך מאת: ר שבתי שפטל קרמר, ר יהודה השל לוונברג. חתן ר חיים איינהורן. רב בסאוד נארוואלק-ארה\"ב-תרפט, קליבלנד-תרצג. חיבר חדושים בכת\"י. חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":12139,"n":"גנון, אברהם ממרוקו","dt":"תרסו","dp":"מראקש","b":"חכם כולל"},{"i":12140,"n":"גנון, יהודה מאלגיר","bt":"תף","dt":"תקס","b":"רב באלמעסכר-אלגיר. הסכים על \"מאמר מרדכי\" לר מרדכי דרמן."},{"i":12141,"n":"גנון, מסעוד","b":"מרבני איטליה-תק\"ל"},{"i":12142,"n":"גנון, מסעוד החסיד מאלגיר","k":"בעל זרע רב","dt":"תנג","b":"רב באלגיר, העתיק והגיה את חדושי המקובל ר יהודה בן חנין. חיבר פירוש לתנ\"ך - ואבד. כנראה שהיה חשוך בנים. חיבר \"זרע רב\" בתוך \"יכין ובועז\" ועוד."},{"i":12143,"n":"גנון, שלמה מאלג'יר","bt":"תץ","dt":"תקע - בערך","b":"רב בבליידא(=בלידא)-אלגיר. נזכר ב\"זרע יעקב\"."},{"i":12144,"n":"גנז בכרך, נפתלי הרץ","f":"ישכר בער בכרך","b":"מגדולי חכמי פרנקפורט-ת\"פ"},{"i":12145,"n":"גנז, (יהושע) זליגמן מפרג","f":"שלמה","dt":"שסט - כח טבת","dp":"פרג","b":"אחיו של ר דוד בעל \"צמח דוד\". דיין בפרג. (באוצר הרבנים תאריך פטירתו - ל כסלו שעג)."},{"i":12146,"n":"גנז, אליעזר מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":12147,"n":"גנז, אנשיל מפפד\"מ","b":"חתן ר משה ראפ מפפד\"מ. מחכמי פפד\"מ-תק."},{"i":12148,"n":"גנז, אריה ליבש מפשמישל","k":"בעל פני אריה","bp":"פשמישל","b":"אב\"ד וישנה, דיין בפשמישל. חיבר \"פני אריה\" פרזעמישל תרנה."},{"i":12149,"n":"גנז, דוד מפרג","f":"שלמה","k":"בעל צמח דוד","bt":"שא-ו","bp":"ועסט פאהלען","dt":"שעג - ה-ח אלול","b":"תלמיד הרמ\"א, מגדולי חכמי פרג. חיבר גם \"נחמד ונעים\", ועוד."},{"i":12150,"n":"גנז, הרץ מפפד\"מ","b":"דיין בפפד\"מ. ב\"דברי קהלות\" לגייגר - נתן העזתי בא לפרנקפורט וגורש מן העיר עלי ידי הדיין וראש הקהילה ר הרץ גנז."},{"i":12151,"n":"גנז, יצחק מפפד\"מ","f":"יהודה","dt":"תך - ח ניסן","dp":"פפד\"מ","b":"מחכמי פפד\"מ"},{"i":12152,"n":"גנז, ישראל ברוך מאמשטרדם","b":"רב באמשטרדם בדור שלפני השואה."},{"i":12153,"n":"גנז, ישראל זליגמן","k":"בעל אור ישראל","b":"מגדולי חכמי אשכנז-ש\"צ, רב בקראקא-ש\"צ"},{"i":12154,"n":"גנז, שמואל מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":12155,"n":"גניביש, אברהם אביש מגורליץ","f":"נתן","bt":"תרנה","bp":"גורליץ","dt":"תשלה","b":"חסיד ר ברוך הלברשטם מגורליץ. חתן ר יעקב הלפרין מוינה ועבר לשם. עבר ללונדון-תרצח."},{"i":12156,"n":"גניביש, חנינא מגורליץ","f":"יוסף","bt":"תרסח","bp":"גורליץ","b":"תלמיד ר מאיר ארק בטורנא ובישיבת בובוב. מחכמי גורליץ. נספה בשואה. עורך \"הלבנון\" ירחון של ישיבת \"תפארת בחורים\" בגורליץ - פיוטרקוב תרפח."},{"i":12157,"n":"גניביש, יהודה מגורליץ","f":"פנחס איזנטל מגניביש","b":"אחיו ר אלימלך איזנטל. בנו ר חנינא עורך \"הלבנון\"."},{"i":12158,"n":"גניביש, פנחס מקוזניץ","f":"יהודה","k":"אדמור מקוזניץ","b":"מקורב לאדמורי דורו, ובעיקר לר נפתלי מרופשיץ. כיהן כאדמור מקוזניץ."},{"i":12159,"n":"גניחובסקי, אליהו משה מבני ברק","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"בכורי ציון\" - ירושלים תשד."},{"i":12160,"n":"גניש"},{"i":12161,"n":"גניש, דוד מטריפולי","bt":"תרי","bp":"זליטן-לוב","dt":"תרעב","dp":"טריפולי","b":"רב ודיין ומקובל בטריפולי. הניח חדושי תורה - בכת\"י."},{"i":12162,"n":"גניש, חואתו מלוב","bt":"תרס","dt":"תשל - בערך","b":"רב בזליתן-לוב (שם נמצא ביהכ\"נ המקודש \"בושאייף\"), עלה לארץ וכיהן כרב באשקלון."},{"i":12163,"n":"גניש, יוסף מלוב","bt":"תקף","dt":"תרם","b":"רב בלוב. הניח חדושים בכת\"י."},{"i":12164,"n":"גניש, כליפה מלוב","bt":"תקץ","dt":"תרס","b":"רב ומקובל בזליתן-לוב. מסופר עליו ב\"ספר לנו ולבנינו\" ת\"א תשמו."},{"i":12165,"n":"גניש, מאיר מלוב","dt":"תרעב","b":"רב בזליתן-לוב."},{"i":12166,"n":"גנסין, יהושע נתן מסטרדוב","f":"אורי ניסן","bt":"תר","b":"ר\"מ בסטרדוב, קריטשוב-תרמג, פאצעפ-פלך צרניגוב."},{"i":12167,"n":"גנצוייך, אברהם מזווירצה","f":"ישראל ליב מזווירצה","k":"אדמור מזווירצה","dt":"תרעה - יב טבת","b":"רב בזווירצה על מקום אביו ואדמור שם, חתנו ר ליביש הורביץ על מקומו אחריו."},{"i":12168,"n":"גנצוייך, ישראל יהודה ליב מזויר","f":"יעקב","dt":"תרסד","b":"ממשפחת ר משה יהודה ליב מסאסוב. רב בקרימלוב, זווירצה ובנו ר אברהם על מקומו אחריו וגם אדמור שם."},{"i":12169,"n":"גנצפריד, יוסף","f":"שלמה","b":"בנו של בעל \"קיצור שו\"ע\"."},{"i":12170,"n":"גנצפריד, שלמה מאונגואר","f":"יוסף","k":"בעל קיצור שולחן ערוך","bt":"תקסד","dt":"תרמו - כח תמוז","b":"רב בברעזוביץ,ראב\"ד באונגוואר-תר\"י","bk":[["אפריון",""],["לחם ושמלה",""],["פני שלמה",""],["קיצור שולחן ערוך",""],["קסת הסופר",""]],"e":"תקס\"ד-תרמ\"ו"},{"i":12171,"n":"גסנבויאר, בן ציון מקומרנא","f":"שמואל נחום","k":"בעל חוקת הפסח","bt":"תרי","dt":"תרעג","dp":"קומרנא","b":"מחכמי קומורנא, חיבר \"חוקת הפסח\" פדגורזע תרנח."},{"i":12172,"n":"גסנבויאר, יצחק צבי מווהנילוב","f":"מנחם ישראל","bt":"תרכז","dt":"תש","b":"אב\"ד ווהנילוב על מקום אביו-תרנד. גבאי ארץ ישראל. חתנו - ר מרדכי אריה הברמן מגוליגור."},{"i":12173,"n":"גסנבויאר, מנחם ישראל מווהנילוב","f":"שמואל נחום מווהנילוב","bt":"תקץ","dt":"תרנד","b":"אב\"ד ווהנילוב על מקום אביו שעבר לליביטשוב. הוציא לאור את ספרי אביו. חתנו - ר נפתלי ארליך מדלטין."},{"i":12174,"n":"גסנבויאר, שמואל נחום מווהנילוב","f":"קהת","k":"בעל נבל עשור","bt":"תקס","bp":"זולקווא","dt":"תריז","dp":"ליזנסק","b":"תלמיד הישועות יעקב. וחסיד ר אורי מסטרליסק ור יהודה צבי מסטרטין. רב בווהנילוב-תקצח, לוביטשוב-תקצט, ליזנסק-תרטו. חיבר \"נבל עשור\" למברג תריד, ועודו."},{"i":12175,"n":"גסנבויאר, שרגא מווהנילוב","f":"שמואל נחום","dt":"תרפה","dp":"צפת","b":"מחכמי ציעשינוב-תרכב, עלה לצפת-תרלז. בשליחות מטעם כולל גליציה."},{"i":12176,"n":"גסקון, יוסף מאנקונא","dt":"שיו - ג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא יחד עם אחיו שמואל, על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":12177,"n":"גסקון, שמואל מאנקונא","dt":"שיו - ג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא יחד עם אחיו יוסף, על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":12178,"n":"גסקין, אברהם מבלגרד","bp":"שלוניקי","b":"רב במונאסטיר-אלבניה, בולגראצי(=בלגרד)-ש' ונזכר בספרי חכמי דורו."},{"i":12179,"n":"געטשליק הלוי מאונגריש-ברוד","b":"רב באונגריש-ברוד"},{"i":12180,"n":"געטשליק מקוניץ","f":"אלכסנדר","b":"רב בקוניץ"},{"i":12181,"n":"געליבטער, אברהם משה מוארשא","b":"תלמיד ישיבת חב\"ד באוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":12182,"n":"געללעם, אביגדור מהוסיאטין","b":"אישר את חתימתו של ר אליעזר ליפא שוואגער מהוסיאטין-תרצב."},{"i":12183,"n":"גענזל, מאיר מטריטש","b":"רב בטריטש, הסכים על \"ספר החינוך\" - ברין תקנח עם ר לוי פולק, ור מאיר טורני."},{"i":12184,"n":"געץ האן, אליקים מגיירינג","f":"משה","bt":"תקעה","bp":"דוב (בוהמיה)","dt":"תרמד","b":"תלמיד החת\"ס ור יהושע כץ רפפורט מבאלאש-ירמוט. רב בטעלטש הומפלטץ, גיירינג-תקצט. חיבר קונטרס מתורת רבו החת\"ס."},{"i":12185,"n":"געץ קניגסברג, אליקים מקובלסדור","dt":"תר","b":"רב בקובלסדורף,קורמנד"},{"i":12186,"n":"געצאוו, זאב וולף ממינסק","f":"אברהם","dt":"תרנא - כא אדר","dp":"מינסק","b":"מחכמי מינסק. בנו - הגביר ר מרדכי."},{"i":12187,"n":"געצאוו, נחמן צבי מנוברדוק","f":"אברהם יוסף ממינסק","k":"בעל דרשות ציוני","b":"מחכמי נוברדוק. חיבר גם \"הדעת או הזכרון והשכחה\", \"התנאים והעם\", ועוד. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":12188,"n":"געצל","f":"מאיר","b":"בשנת תסד שליח ירושלים בברסלוי, יחד עם ר אהרן זליג בן ישכר בר."},{"i":12189,"n":"געשיל, דוד מרדכי משטפנשט","f":"יצחק מאיר","dt":"תשכד - כב טבת","b":"רב בשטעפינעטש"},{"i":12190,"n":"געשיל, יצחק מאיר","f":"שמואל","b":"רב-שנת תר\"ס"},{"i":12191,"n":"געשיל, מנחם נחום מלאצק","f":"יצחק מאיר","b":"רב בלוצק-תר\"ע"},{"i":12192,"n":"גפן טוביה","bt":"1870","dt":"ה'תשל 1970","bk":[["זכרון בספר",""],["לב יוסף",""],["נזר יוסף",""],["נחלת יוסף",""],["קרני ההוד",""]]},{"i":12193,"n":"גפן, טוביה מארה\"ב","f":"יוסף","k":"בעל לב יוסף","bt":"תרל-ג","bp":"קובנא","b":"תלמיד ישיבת קובנא, סלובודקא. חתן ר ליב רבינוביץ מקובנא. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי, הרידב\"ז. היגר מליטא לארה\"ב-תרסג, וכיהן כרב בניו יורק (בקהילת בני לעבעדאווא \"אהבת צדק\"), ניו ארק?, קנטון-אוהיו-תרסג, אטלנטה-תרעא. חיבר גם \"קרני ההוד\", \"נחלת יוסף\", ועוד. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":12194,"n":"גפן, יהודה אריה ליב (אויסבעל)","f":"טוביה גרינבוים","bt":"תרע","bp":"טרנוב","dt":"תשיז","b":"תרגם את השם גרינבוים לגפן. תלמיד ר מאיר אריק, תלמיד ישיבת חכמי לובלין ואחר כך בהנהלת הישיבה. אב\"ד ליפסק-תרצו, דרילדז (אילזא)-תרצט. ברח לרוסיה בזמן השואה וחזר לפולין-תשו וכיהן כרב במחנות הפליטים באולם-גרמניה. הוזמן לכהן כרבה של לובלין אך סירב ועלה לארץ-תשט. יסד ישיבה \"יחל ישראל\" בחיפה יחד עם האדמור מסערט ויזניץ. רבה של קרית אתא-תשיג. חיבר מאמרים ב\"קול תורה\".","bk":[["לוית חן ואור יקרות",""]]},{"i":12195,"n":"גפן, יעקב ברוך מירושלים","k":"בעל אותיות מחכימות","b":"רב-שנת תר\"מ,עלה לירושלים"},{"i":12196,"n":"גפן, יצחק אליהו מריטובה","b":"רב בריטובה-תרע."},{"i":12197,"n":"גפן, שם טוב מירושלים","k":"בעל תולדות הנבואה הט","r":"אב\"ד מאגענדארף ואח\"כ בגלאנטא","bt":"תרטו","bp":"כפר בריביס-קליבולוט","dt":"תרפז - כו סיון","dp":"תל אביב","b":"זקנו ר חיים לוי יצחק בורסקי (שינה שמו לגפן בגלל הצבא) היה רב בקליגורקה-פלך קיוב. חתן ר ישראל קרסונסקי. עלה לארץ- והתישב בתל אביב. תלמיד חכם ובקי במדע וחיבר ספרים אודות שילוב התורה והבריאה והטבע. חיבר גם \"תורת הממדים לאין ספרות\" - 1896. ?? לא באוצר ??"},{"i":12198,"n":"גפן-בורסקי, חיים לוי יצחק","f":"מרדכי בורסקי","b":"רב בקליגורקה-פלך קיוב. חברו של ר יעקב האדמור מסמילה (מוצא שניהם מהעיר \"בער\"). נכדו ר שם טוב גפן."},{"i":12199,"n":"גפני, דוד מטבריה","b":"בשנת תקלו בשליחות טבריה במרוקו. אגרת שליחותו בספרית אבן צור בפאס."},{"i":12200,"n":"גץ, יוסף ישכר בער מקרעמזיר","f":"אלחנן מוינה ופפד\"מ","k":"בעל ארבעה חרשים","b":"רב בקרמזיר(=קרזמיר), עלה לארץ בשנת תסא עם משפחתו. חיבר \"ארבעה חרשים\" פרנקפורט תם הכולל \"מלכי יהודה\"-כסא דוד, \"שלשה שריגים\", \"מלכי ישראל\"-קנאת אפרים, \"הנביאים\"-רוח חן, \"הכהנים הגדולים\" - ונדפסו השניים הראשונים - פפד\"מ תע. (האם אביו הוא ר אלחנן מוינה שחיבר גם הוא \"ארבע חרשים\"?). בנו - יוסף מאויסא(=אויסע) שנזכר ב\"מגילת סתרים\" שלא הלך בדרכי אבותיו וכו'."},{"i":12201,"n":"גץ, מאיר יהודה מתונס","bt":"תרפד","bp":"מנזל","dt":"תשנה - יג אלול","b":"תלמיד ר ישועה פיתוסי (לימים רב בצפת). רב ב\"סוק אל ארבע\"-תונס. עלה לארץ-תשט והתישב בירושלים, למד קבלה והיה תלמיד ר עובדיה הדאיה, ור מרדכי שרעבי. כיהן כרב הכותל-תשכז, והקים מחדש את ישיבת המקובלים \"בית אל\". לקט מתורתו ב\"גיצי תורה\"."},{"i":12202,"n":"גץ, מאיר פיבל","k":"בעל הדת והחינוך","bt":"1853","bp":"ראסיין-ליטא","dt":"1932","dp":"ריגה","b":"סופר ומחנך. למד לשונות המזרח בפטרבורג. מורה בתולדות ישראל בביהמ\"ד למורים בוילנא. מנהל גימנסיה עברית במוסקבה וריגה. חיבר גם מכתב גלוי לגרף טולסטוי (כנגדו), \"מזכרונותיו של שתדלן\". ?? לא באוצר ??"},{"i":12203,"n":"גץ, מיכל"},{"i":12204,"n":"גצל","f":"שמואל","dt":"תקיח - י טבת","b":"רב בראקוב"},{"i":12205,"n":"גצל, ראובן","b":"ראב\"ד בדאלינא"},{"i":12206,"n":"גצלר, חיים מרדכי","b":"פרסם מאמרים ב\"המאור\" - ברלין תרצג."},{"i":12207,"n":"גראג, יצחק גבריאל מבודפשט","dt":"תרלח - כא תשרי","dp":"בודפשט","b":"ראב\"ד באויבן(=בודפשט) על מקום ר פנחס יהודה פריידיגר."},{"i":12208,"n":"גראגאליש, יצחק משלוניקי","dt":"שטו - כא סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":12209,"n":"גראד, בנדיט","b":"רב בריטובה"},{"i":12210,"n":"ג'ראד, יוסף מלוב","bt":"תרי","dt":"תש","b":"רב ושוחט באל קוסבאת(=מסאלתה)-לוב, לצדו של ר יוסף מנחם, ועל מקומו אחריו-תרץ."},{"i":12211,"n":"גראדה, חיים","f":"שלמה מרדכי","k":"בעל דורות - נ\"י תשה","bt":"1910","bp":"וילנא","b":"תלמיד ישיבת נוברדוק. פנה להשכלה והיה סופר ומשורר. מייסד קבוצת הסופרים \"וילנא הצעירה\". פרסם בכתב עת שונים. חיבר \"מוסרניקעס\", ועוד. ניצל מהשואה וברח לאשכבד-רוסיה, ואחריה חזר לוילנא, פריס וניו יורק. ?? לא באוצר ??"},{"i":12212,"n":"גראדיס, דוד מצרפת - א","dt":"1780","b":"גביר בבורדו-צרפת, ממשפחה מגולי ספרד, מקורב למלכות. בנו - אברהם."},{"i":12213,"n":"גראדיס, דוד מצרפת - ב","f":"בנימין","bt":"תקב","bp":"בורדו-צרפת","dt":"1811","b":"עמד בראש בית המסחר של המשפחה בבורדו - אחר פטירת דוד - אברהם. חיבר ספרי פילוסופיה."},{"i":12214,"n":"גראז, זבולון","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":12215,"n":"גראז, יוסף מוערזאן","dt":"תשג","b":"רב בווערזאן"},{"i":12216,"n":"גראז, נחום מוערזאן","dt":"תשג","b":"רב בוויערזאן"},{"i":12217,"n":"גראז, ניסן","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":12218,"n":"גראז, נתנאל יוסף משאט","k":"העילוי משאט","b":"תלמיד ישיבת סלובודקה. רב באוז'וונט-תרנט - תרפו, על מקום ר שלמה נתן קוטלר ור דוד גרשון רובינשטין. רבה האחרון של ורז'אן. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":12219,"n":"גראטוואהל, מאיר מפפד\"מ וקובלנ","f":"יהודה זעלקא","dt":"תנא - ג תשרי","dp":"פפד\"מ","b":"רב בקובלנץ, ר\"מ בפפד\"מ, רב דמדינת קליבא. (באוצר הרבנים שנת פטירתו - תכא)."},{"i":12220,"n":"גראטיאה, אברהם משלוניקי","dt":"רפח - כ תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":12221,"n":"גראנבאס, אהרן משה יצחק","f":"אברהם","k":"בעל מליץ יושר","dt":"תקסו - ל אד\"א","dp":"אמשטרדם","b":"ממשפחת אצילים בשבדיה, שהגיעו לאמשטרדם והתגיירו בהיותו בן 12. מחכמי ביהמ\"ד \"עץ חיים\", וממלא מקום הרב באמשטרדם על מקום ר שאול מאמשטרדם-תקן, ואח\"כ רב קהלת \"עדת ישורון\" באמשטרדם. חיבר \"זרע יצחק\" ונדפס ע\"י בנו ר אליעזר - אמשטרדם תקסט בנו ר יצחק הו\"ל את ספרו \"מליץ יושר\" - להגן על מנהגי קהלתו."},{"i":12222,"n":"גראנר, יצחק","b":"דומ\"צ בקלוזנבורג"},{"i":12223,"n":"גראסיאני, אברהם מקאשטוריאה","b":"רב בקאשטוריאה-שנות ה-תק', ואצלו הרבנים ר יצחק קופיו ור אברהם הכהן."},{"i":12224,"n":"גראסיאני, אברהם מרוסג'וק","b":"נכד ר יעקב גראסיאני מוידין. רבה הראשון של רוסג'וק-תקס."},{"i":12225,"n":"גראסיאני, יעקב מוידין","f":"שבתי הרופא מוידין","b":"רב בוידין-תק. נכדו - ר אברהם מרוסג'וק."},{"i":12226,"n":"גראסיאני, שבתי מוידין","b":"רופא מחכמי וידין-שנות ה-תק'. בנו - ר יעקב מוידין."},{"i":12227,"n":"גראסיטו, אשר","f":"שמואל","b":"רב במנטובה-שנ\"ח"},{"i":12228,"n":"גראסיטו, משה מפדובה","dt":"שצא","dp":"פדובה","b":"דיין בפדובה אצל ר יהודה כץ מהחזנים. נזכר ב\"עולם הפוך\"."},{"i":12229,"n":"גראפין, אברהם מלבוב","f":"גרשון","dt":"תכט-נט -כט תמוז","b":"ראש הדיינים בלבוב. חתם-תיב עם ר משה בן נטע בערמנש ור יוסף בן יצחק מלבוב, וחתם-תיד עם ר מאיר הלוי ור בנימין וולף בן יואל. (בנוסח המצבה נרשם תאריך הפטירה תכט אך לפי בובר הכוונה ל-תנט)."},{"i":12230,"n":"גראפין, אהרן קלונימוס קלמן","f":"שמשון או משה אברהם","b":"רב בלבוב. חתם-תיא עם ר משלם זלצבורג מלבוב. חתם-שצז עם ר אליהו קלמנקש, ור אהרן לוריא. חתם-תד עם ר משלם בן אברהם זלצבורג, ועוד. לפי בובר ישנה טעות בקריאת חתימתו ושם אביו אינו שמשון ויש בלבול עם ר שמשון בן קלונימוס."},{"i":12231,"n":"גראפין, ישראל אליעזר מלבוב","f":"משה אברהם","dt":"שעט - כז שבט","dp":"לבוב","b":"ראב\"ד בלבוב"},{"i":12232,"n":"גראפין, שמשון","b":"מגדולי חכמי לבוב-ש\"פ"},{"i":12233,"n":"גרבוז, אפרים זאב מירושלים","k":"בעל הר אפרים","r":"מראשי ישיבת אהל תורה","bt":"תרסג","dt":"תשיט - יט תמוז","b":"עלה לארץ תרפד, מגדולי חכמי ירושלים. פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט, \"שערי אמונה\" - ירושלים תרצה - כנראה היה גם העורך.","bk":[["הר אפרים",""],["ספרי זוטא",""],["הר אפרים - הוריות, מכילתא, תוספות למס' שקלים",""],["קו המדה - מכילתא",""]]},{"i":12234,"n":"גרבוטה, מנחם נחום הלוי מקולטשי","f":"יחזקאל בן יוסף","b":"רב בקולטשין-תרל על מקום אביו, ובנו ר ישראל חיים על מקומו אחריו."},{"i":12235,"n":"גרבטה, יחזקאל הלוי","f":"יוסף","b":"רב בקולטשין-תר, ובנו ר מנחם נחום על מקומו אחריו."},{"i":12236,"n":"גרבטה, ישראל חיים הלוי","f":"מנחם נחום מקולטשין","k":"בעל לקוטי הלכות","bt":"תריח","b":"תלמיד ר שמואל אברהם בלחמן מקונסטנטין. רב בקולטשין-ווהלין-תרמב על מקום אביו. בניו - ר יחזקאל, ר אהרן יהושע, ר בן ציון. חתנו - ר אברהם פיימן. חיבר \"לקוטי הלכות\" - בכת\"י."},{"i":12237,"n":"גרבלי, יצחק ממכנאס","k":"בעל נר לרגלי","b":"רב במכנאס, עלה לארץ וכיהן כרב בקרית מלאכי."},{"i":12238,"n":"גרג'י, יוסף מירושלים","f":"מתתיהו","k":"בעל עדות ביהוסף","bt":"תרכט - א תמוז","bp":"הראת-אפגניסטן","b":"עלה לירושלים-תרעא, מורה בת\"ת \"בני ציון\", דרשן."},{"i":12239,"n":"גרג'י, מתתיה מאפגניסטן","f":"מרדכי","k":"בעל עונג לשבת","bt":"תרה","bp":"הראת-אפגניסטן","dt":"תרעח - יד כסלו","dp":"ירושלים","b":"רב קהילת הראת-אפגניסטן על כסא אביו, בתרנו עלה לירושלים, חזר להראת ועלה שוב בשנת תרסח. רב העדה בירושלים. חיבר \"עונג לשבת\" ירושלים תרעג. בנו - ר יוסף.","bk":[["עונג שבת",""]]},{"i":12240,"n":"גרג'י, שמואל מאפגניסטן","f":"שלמה","k":"בעל מנחת שמואל","b":"מחכמי הראת-אפגניסטן, רב במרב - מרכז אסיה - בראשית המאה ה-20."},{"i":12241,"n":"גרגיר, שמואל מליוורנו","f":"חיים","b":"העתיק ספר נגיד ומצוה בליוורנו-תסו."},{"i":12242,"n":"גרדנביץ, אהרן מראויטש","f":"מנחם מנדל מראויטש","b":"מגיד בראויטש. בנו - ר רפאל מראויטש."},{"i":12243,"n":"גרדנביץ, מנחם יוסף מראויטש","f":"רפאל מראויטש","dt":"תרעג","b":"מחכמי ראויטש."},{"i":12244,"n":"גרדנביץ, מנחם מנדל מראויטש","f":"יוסף","b":"רב בראויטש-תקטו-תקנב. בנו - ר אהרן מראויטש."},{"i":12245,"n":"גרדנביץ, רפאל מראויטש","f":"אהרן מראויטש","b":"נכד ר מנחם מנדל בן יוסף מראויטש. דיין בראויטש. הסכים על \"אפיקי יהודה\"-תרז. מקור השם גרדנביץ = גראדע=נוויטץ (=שכל ישר). בנו - ר מנחם יוסף מראויטש."},{"i":12246,"n":"גרדשטין, יהושע מלובלין","f":"שמחה אפרים פישל מירו","b":"נכד-אבי אמו ר עקיבא איגר מפוזנן. מצאצאי ר חיים רפפורט מלבוב. חתן ר יהודה ליב דנציג-נינם של הגר\"א ובעל חיי אדם."},{"i":12247,"n":"גרדשטין, שמחה אפרים פישל","f":"עזריאל מאיר בן אהרן","dt":"תרמה - ב ניסן","dp":"ירושלים","b":"נינו של ר חיים רפפורט מלבוב ושל ר השל אב\"ד וילנא. חתן ר עקיבא איגר מפוזנן, ומתורתו בשו\"ת חותנו. עלה לירושלים-תרמד."},{"i":12248,"n":"גרהר, יצחק אליקים אליעזר","bt":"תקע","dt":"תרם","b":"ראב\"ד קובלסוב-תרכ, חסיד דזיקוב."},{"i":12249,"n":"גרהר, פנחס מאושפצין","k":"בעל בית פנחס","bt":"תרכח","dt":"תשב","b":"תלמיד ה\"נפש חיה\". חסיד דזיקוב ובובוב. מחכמי אושפצין (אושביץ). חיבר \"בית פנחס\" מונקטש תרעה. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד, \"כתר תורה\" - אושפיצין תרצט, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה. נספה בשואה."},{"i":12250,"n":"גרובין, חיים נתן מדלטין","b":"רב בדלטין-תרנה. תשובות אליו \"בית יצחק\", שות מהרשם."},{"i":12251,"n":"גרובנר, יחזקאל מקראקא","f":"שמעון זימל","k":"בעל כנסת יחזקאל","bp":"קראקא","b":"תלמיד ר נחמיה רוזנפלד בישיבת \"כתר תורה\" בקראקא. מעורכי \"כתר תורה\"-רדומסק. ניצל מהשואה, ואחריה רב בוולבזיך. עבר לארה\"ב וכיהן כרב ור\"מ בישיבת חכמי לובלין בדטרויט. חתן ר ישראל משה הכהן שלף. חיבר \"כנסת יחזקאל\" ירושלים תשנו. תשובה אליו ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט - מאת ר שמואל זאב שלזינגר מאונגואר. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":12252,"n":"גרובנר, יעקב מאושפיצין","b":"תלמיד ר משה נתן יונגרייז בעל תורת משה נתן."},{"i":12253,"n":"גרובר, אהרן מלמברג","b":"מחכמי למברג. חסיד ר הרש מחוליוב ומקורב גם לבלז. על תולדות המשפחה בספר \"שבעה דורות\" לר משה נכדו."},{"i":12254,"n":"גרובר, אליהו בן ציון מפאיורי","f":"מרדכי יוסף","bt":"תרמב","dt":"תשג","b":"רב בהרדורק או פאיורי-פלך קובנה-תרסח."},{"i":12255,"n":"גרובר, אפרים","b":"רב באוונטא,טווער, ארז'ווילקי(=ערזוויליך),עלה לא\"י-תרצ\"ג"},{"i":12256,"n":"גרובר, אפרים פישל","b":"תלמיד ישיבת קאליב. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":12257,"n":"גרובר, אפרים פישל מירושלים","f":"צבי אריה","bt":"תרעד","bp":"גליציה","dt":"תשמז","b":"תלמיד רי\"ץ דושינסקי. עלה לירושלים. ר\"מ בישיבת \"חיי עולם\". חסיד תולדות אהרן. עבר לארה\"ב. פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":12258,"n":"גרובר, יעקב מסאנוק","dt":"תש..","b":"ראב\"ד סאנוק. נספה בשואה."},{"i":12259,"n":"גרובר, יצחק מרדכי מויליצקה","b":"תשובה אליו - \"מנחת אברהם\"-תרצא."},{"i":12260,"n":"גרובר, מנחם מירושלים","k":"בעל הגיון התלמוד","dt":"תשו","dp":"בני ברק","b":"חתן ר זליג תרשיש. רב בארזווילקי. עלה לירושלים. חבר מכון הרי פישל."},{"i":12261,"n":"גרובר, פנחס יעקב מלונדון","k":"בעל יד פנחס","b":"רב בלונדון-תרפ. (ראה גם פנחס יעקב הכהן מלונדון)"},{"i":12262,"n":"גרובר, שאלתיאל איזיק","b":"הו\"ל \"בית המדרש\" - קראקא תרמח, \"אוצר הספרות\"."},{"i":12263,"n":"גרודזיצקי, יהושע דב","b":"מאמר ממנו ב\"תלפיות\" - שנחאי תשו."},{"i":12264,"n":"גרודזנסקי, אברהם מסלובודקה","k":"בעל חכמת המוסר","r":"מנהל רוחני של ישיבת סלבודקה בליטא","bt":"תרמא-ד","bp":"וארשא","dt":"תשד - כב תמוז","dp":"קובנא","b":"תלמיד ישיבות סלובודקה, קלם, הושפע מתנועת המוסר. חתן ר דב צבי הלר המשגיח בסלובודקה. הצטרף להנהלת הישיבה-תרעט, ולאחר עליית הסבא מסלובודקה ר נטע צבי פינקל לארץ נתמנה למשגיח על מקומו. נספה בשואה. באוצר מופיע שנפטר בתשכד. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח. ?? לא באוצר ??","bk":[["תורת אברהם - שיחות מוסר על משמעותם של הייסורים",""]]},{"i":12265,"n":"גרודזנסקי, אברהם צבי הירש מויל","f":"דוד שלמה מאיוויא","bt":"תריז","dt":"תרצח","b":"ר\"מ בישיבת ראמיילס(=מיילס, מייליס) בוילנא-תרע. אחיו הגדול של ר חיים עוזר מוילנא (והיה מכנהו בדרך צחות רב אחיא בריה דרב איוייא."},{"i":12266,"n":"גרודזנסקי, אהרן יצחק","k":"בעל לעבן","bt":"1891","bp":"ואקשנה-ליטא","dt":"1941","dp":"וילנא","b":"עתונאי סופר ומתרגם. נולד למשפחת רבנים. עבר לאנטורפן ועסק בליטוש יהלומים, חזר לוילנא ופרסם מאמרים בכתבי עת ובהם \"טאג\", ועוד. נספה בשואה. ?? לא באוצר ??"},{"i":12267,"n":"גרודזנסקי, אליהו אליעזר מוילנא","f":"יצחק שירוינטר","k":"חתן ר' ישראל סלנטר","bt":"תקצא","bp":"שירווינט","dt":"תרמז - כח ניסן","b":"תלמיד וחתן ר ישראל סלנטר בוילנא. רב בוילנא על מקום ר בערעלע בונע'ס, ואחד משלש חברי ביה\"ד יחד עם ר יוסלי ור שלמה הכהן והיה האחראי על דיני הממונות שם. החזיק פקדונות בסכומים עצומים. עסק בעניני צבור והשתתף בועידות רבנים בפטרבורג. השתתף עם חותנו ר ישראל בייסוד הכוללים וניהולם. חתנו ר חיים עוזר גרודזנסקי מוילנא."},{"i":12268,"n":"גרודזנסקי, דוד שלמה מאיוויא","f":"משה אריה ליב מאיוויה","bt":"תקצא","bp":"איווייה","dt":"תרסח","b":"חתן ר חיים עוזר אינהורן מולקוביסק. תלמיד ר ישראל סלנטר. רב באיוויע-תריח על מקום אביו. בניו: ר חיים עוזר מוילנא, ר צבי הירש מוילנא, ר משה אריה ליב, ר אליהו, ר יעקב שמואל."},{"i":12269,"n":"גרודזנסקי, חיים עוזר מוילנא","f":"דוד שלמה מאיוויה","k":"בעל אחיעזר","r":"אב\"ד וילנא","bt":"תרכג","bp":"איוויה-ליטא","dt":"תש - ה אב","b":"תלמיד בבימ\"ד של אביו באיוויה, ישיבת איישישוק, וולוזין. בגיל 17 התכתב עם גדולי דורו ובהם ר ישראל סלנטר, ר יצחק אלחנן ספקטור ואחרים. חתן ר אליהו אליעזר גרודזנסקי מוילנא, ועבר לשם. רב בוילנא על מקום חותנו-תרמז, גדול חכמי דורו, פוסק, מנהיג, בזמן מלחמה\"ע ה-I היה ביקטרינסלב, וכשחזר לוילנא-תרעח יסד את ועד העזרה בוילנא, ואת ועד החינוך החרדי בפולין, ואת ועד הישיבות. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז, \"תבונה\" - לודז תרפב, \"תבונה\" - ירושלים תשא. אחיהם של: ר צבי הירש מוילנא, ר משה אריה ליב, ר אליהו, ר יעקב שמואל. גיסיו: ר יהודה ליב מוסקוביץ, ר אליעזר מאיר הבקינד, ר יהודה ליב זלצמן.","bk":[["שו\"ת אחיעזר",""],["אחיעזר - שו\"ת",""],["אחיעזר",""],["אגרות ר' חיים עוזר",""],["אגרות רבי חיים עוזר",""]],"e":"תרכ\"ג-ת\"ש","rb":"וילנא, ליטא"},{"i":12270,"n":"גרודזנסקי, יוסף מנדל הכהן","f":"אליעזר","k":"בעל גט מקושר","dt":"תרלח","b":"גביר מחכמי וילנא. מצאצאי ר אליעזר מהורדנא, ר אלכסנדר זיקינד בעל \"יסוד ושורש העובדה\". אחיינו של הגביר ר פנחס מקאלואריה."},{"i":12271,"n":"גרודזנסקי, יצחק משירווינט","f":"אריה","k":"איצה'לה משירווינט","bt":"תקסא","bp":"פורזאלווה","dt":"תרכז - כד תמוז","dp":"וילנא","b":"תלמיד ישיבת וולוזין. חתן רבה של שירווינט(=ניישטט-שאקי) (ולפי \"עיר וילנא\" חתן הגביר ר אליעזר אפרים'ס מוירשופע, רב בשירווינט-ליד וילנא על מקום חותנו, רב באנטאקליא-וילנא, רב בוילנא על מקום ר לייבל איזיקס. חתנו - ר שמריה הכהן גוריון."},{"i":12272,"n":"גרודזנסקי, משה אריה ליב מאיווי","dt":"תריח - בערך","b":"רב באיוויא-ליטא-תרל, ובנו ר דוד שלמה על מקומו אחריו-תריח. נכדו - ר חיים עוזר מוילנא, נכד נוסף הנושא את שמו."},{"i":12273,"n":"גרודזנסקי, צבי הירש מארה\"ב","f":"מאיר","k":"בעל לקוטי צבי","bt":"תריח","dt":"תשח","dp":"אומהא-ארה\"ב","b":"תלמיד קרובו ר דוד שלמה גרודזנסקי מאיביה, כולל קובנא, ישיבת וולוזין. היגר לארה\"ב-תרנא, וכיהן כרב באומהא-תרעו. חיבר גם \"מקוה ישראל\". פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":12274,"n":"גרודזנסקי, שלמה","bt":"תרלו","dt":"תשב","b":"מרביץ תורה בלודז,רב בדיליאטיץ-תרע\"ח,ראדזייב-תרע\"ט,זגרוב,איזביץ-תרצ\"ח"},{"i":12275,"n":"גרודזנסקי, תנחום הכהן","f":"משלם זלמן","k":"בעל מראה כהן","bt":"תקעט - בערך","dt":"תרלז - יז אייר","dp":"וילנא","b":"נכד-מצד אמו ר תנחום מהורדנא ונקרא ע\"ש, ונכד ר משה הכהן מקאלואריה בן יהודה. חתן דודו-אחי אמו ר בערעלע בונעס בעל \"פעולת שכיר\" מוילנא. מחכמי וילנא ובקי בשפות. מורה לבני עשירים בליטא ובסוף ימיו התישב בוילנא. נפטר ללא ילדים."},{"i":12276,"n":"גרודזען, גדליה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":12277,"n":"גרודזקי, א' יעקב הכהן","dt":"תשג","b":"רב בוורקלן"},{"i":12278,"n":"גרודנציק, קים קדש יהושע מקישנו","f":"יחיאל יוסף","k":"בעל קהילות קדש","bt":"תרט","b":"רב בקריוואראג-תרמט, קישינוב(=קעשנוב)-תרנא. נסמך מאת: ר יוסף רוזין מסלונים-הרוגצובר, ר שלמה הכהן מוילנא, ר בנימין זקהיים. חיבר גם \"הדרת קדש\". ?? לא באוצר ??"},{"i":12279,"n":"גרודשטין, מאיר מלובלין","f":"אהרן מחמלניק","dt":"תריא","dp":"לובלין","b":"גביר מחכמי לובלין ומראשי הקהלה. חתן נכדת הרבי ר השל. שינה שם משפחתו מליפשיץ לגרודשטין. מחותן עם גדולי דורו."},{"i":12280,"n":"גרוהברט, בנימין","b":"רב-שנת תר\"ל"},{"i":12281,"n":"גרוהברט, יהודה ליב מסטשוב","f":"בנימין גרוברט","k":"בעל חבלים בנעימים","bt":"תרכב","dt":"תרצח - יב חשון","b":"תלמיד אחיו ר ישכר בריש מבענדין, חתן ר אלכסנדר זיסקינד ליפשיץ מאוזארקוב. רב ביאנוב(=יאנווא-פאלאצק)-תרמד, מאדוב(=מאקאווי)-פלך לומזה-תרמח, סטאשוב-פלך ראדום-תרסא, גלה לרוסיה במלחמה העולם ה-I, וחזר לסטשוב. עבר לאמריקה, רב בטורונטו-תרף, סט לואיס-תרפז, טורונטו בשנית. פעל רבות למען שמירת השבת וגם פנה לממשלה לתת אפשרות ליהודים לשמור על השבת. תיקן עירוב בעיר (כנראה הראשון באמריקה). נספד ב\"הפרדס\". חיבר גם \"דברים ככתבם\" סט לואיס תרצב, \"יביע אומר\", חיבר זכרון ממלחמת העולם ה-I - לודז תרפו, פרסם מאמרים ב\"המגיד\" - סטמר תרפח, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז. \"שערי ציון\" - ירושלים תרפא, \"דגל התורה\" - וארשא תרפב."},{"i":12282,"n":"גרוהברט, יקותיאל זלמן מארה\"ב","f":"ישכר בעריש מבנדין","bt":"תרנב","dt":"תשב","b":"רב בבנדין-תרע\"ג,ברוקלין-תר\"פ"},{"i":12283,"n":"גרוהברט, ישכר דב בר מבנדין","f":"בנימין","k":"בעל דברי יששכר","bt":"תרז","bp":"שרענסק","dt":"תרעד - כד חשון","b":"נקרא בשם \"העילוי משרענסק\". ר\"מ בפלאצק, רב בראטשנז-פלך פלאנצק-תרלח, פרושניץ-פלך פלאנסק-תרמא, שידליץ,בנדין. בנו - ר יקותיאל זלמן מליפנא. חיבר גם \"חזקת היד\" - בכת\"י. ?? לא באוצר ??"},{"i":12284,"n":"גרוזובסקי, אהרן מרומשישוק","bt":"תרנד","dt":"תרצח - טז חשון","b":"רבה האחרון של רומשיסק(=רומשישוק)."},{"i":12285,"n":"גרוזובסקי, יוסף מליטא","dt":"תשא","b":"רב בועד הרבנים בווילנה"},{"i":12286,"n":"גרוזובסקי, ראובן מקמניץ ומונסי","f":"שמשון ממינסק","k":"בעל חדושי ר ראובן","bt":"תרמז","bp":"מינסק","dt":"תשיח - כב אדר","b":"תלמיד ישיבות מינסק, סלובודקה, מיר. חתן ר ברוך בר ליבוביץ ונתמנה לר\"מ בישיבת חותנו, עבר עם הישיבה מקרמנצוג לוילנא ומשם לקמניץ, ראש ישיבת קמניץ, גלה עם הישיבה לראסיין-ליטא בזמן השואה, הגיע לארה\"ב-תשא וכיהן כר\"מ בישיבת תורה ודעת בארה\"ב-תשה, ראש ישיבה במונסי. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב. חבר מועצת גדולי התורה ומראשי אגודת ישראל.","bk":[["חידושי רבי ראובן",""]],"e":"תרמ\"ז-תשי\"ח"},{"i":12287,"n":"גרוזובסקי, שמשון ממינסק","b":"מרבני מינסק-תר\"פ"},{"i":12288,"n":"גרוזינגר, שמעון מזייבוי","b":"חתן ר שלמה זלמן קליין מסילאג'-צ'ה. רבי בז'יבוי. נספה בשואה."},{"i":12289,"n":"גרוטוול, זלקין מפפד\"מ","dt":"תן","b":"מחכמי פפד\"מ."},{"i":12290,"n":"גרוטוול, משה מאיר מקובלנץ ופפד","f":"זלקין מפפד\"מ","dt":"תנ","b":"רב באמריך, קובלנץ, רב בקלויז בפפד\"מ על מקום אביו."},{"i":12291,"n":"גרוטוול, משה ממנהיים","dt":"תמב - יח אדר","b":"רב במנהיים"},{"i":12292,"n":"גרומן, ישראל יהודה מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":12293,"n":"גרומן, מנחם מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":12294,"n":"גרומר, יוסף משה מאזיפולי","b":"מחכמי יעזופול גביר שתרם הרבה לצדקה ולארץ ישראל, גר ארבעים שנה בגרמניה. ביקר בטבריה-תרצה. הדפיס בלמברג \"קול קורא\" \"ברידער און שוועסטער ערוואכט\", ועוד ובו חזה שחורות לעם ישראל כמו שחזה לפני מלחמת העולם הראשונה - בתר\"ע."},{"i":12295,"n":"גרוניס, אשר","k":"בעל פרי אשר","r":"רב בוילטשין שבפולין ואח\"כ בקארדיף שבאנגליה","bt":"תרלב","dt":"תרצז - י אב","b":"רב בווילצין-תרס\"ב,קארדיף-תר\"פ","bk":[["פרי אשר - שו\"ת וחידושים",""]]},{"i":12296,"n":"גרונר, חיים מברדיוב","f":"ישראל יצחק מקראקא","dt":"תרפא","b":"אחיינו של הדב\"ח ומקורב אליו. חתן ר יחיאל צבי אונגר מטורנא ועבר אליו. למד בקלויז צאנז ולימד שם. רב בברדיוב. הניח כתבים רבים בכל מקצועות התורה."},{"i":12297,"n":"גרונר, יעקב מקשנוב","f":"אברהם ישעיה","k":"בעל זכרון יעקב","bt":"תרכח","bp":"קשנוב","dt":"תשיא","b":"עלה לירושלים-תרמד עם אביו. חתן ר אברהם אבא קוסובסקי. התחבר לחסידי קרלין בירושלים, נסע בתרנז לאדמור מסטולין והתעכב שם שנתיים. חיבר \"זכרון יעקב\". תולדותיו ומתורתו בספר \"בית אהרן וישראל\" - תשמט. ?? לא באוצר ??"},{"i":12298,"n":"גרונר, ישראל יצחק מקראקא","b":"מחכמי קראקא, חתן ר סיני שטיינר אב\"ד אולינוב. מהיושבים אצל הדב\"ח בצאנז."},{"i":12299,"n":"גרונר, שלמה מקשנוב","f":"אברהם ישעיה","bp":"קשנוב","b":"עלה לארץ עם אביו ואחיו ר יעקב ור זאב וולף. חתן ר יצחק דוד גרוסמן ואשתו נהרגה בהר הזיתים."},{"i":12300,"n":"גרונר, שמואל מארץ ישראל","f":"דוד הכהן מהארקי","b":"עלה לארץ - לפני תקמד. בשליחות קהילת החסידים ברוסיה-תקמד, תקמו. מקורב לר מנחם מנדל מויטבסק ור אברהם מקאליסק. מכתבים ממנו מהארץ."},{"i":12301,"n":"גרוס שוך, תנחום"},{"i":12302,"n":"גרוס, אברהם יעקב מקשאנוב","b":"רב בקשאנוב, תלמיד רד\"ב ויינפלד מטשבין שהשיב לו בתרצז ב\"דובב מישרים\". פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":12303,"n":"גרוס, אברהם מאושפיצין","f":"אשר זליג","bp":"יבורוזנה","dt":"תשא","b":"מחכמי אושפיצין. חתן ר חיים זאב רוזנבלום מיבורוזנה. מדפיס באושפיצין וראש הקהלה. נספה בשואה (כשגורש לסוסנוביץ)."},{"i":12304,"n":"גרוס, אהרן מלאפוש","f":"רפאל","dt":"תשא","b":"נכד ר משה דוד טיטלבוים מלאפוש, רב בלאפוש על מקום זקנו-תרצה, ומנהל הישיבה שם. חתן דודו ר אברהם חיים טיטלבוים מקרעניץ. תכנן להפוך את הישיבה לישיבת תורה ומלאכה - אך בגלל המלחמה לא הספיק. נספה בשואה."},{"i":12305,"n":"גרוס, אהרן צבי מפאמאז","f":"יעקב יוסף מאויבן","k":"בעל כל דאמר רחמנא","dt":"תשד - טז תמוז","b":"תלמיד הדעת סופר, ור יוסף אלימלך כהנא מאונגוואר, ור מרדכי יהודה ליב וינקלר מהעדילא-מאדע. חתן ר דוד יהודה זילברשטין מוויצען. רב בפאמאז-תרצב. נספה בשואה (לפי מקור אחר - שבט תשה)."},{"i":12306,"n":"גרוס, אשר מטאקייא","dp":"פרשבורג","b":"חתן ר משה נחום הירשלר מוינה."},{"i":12307,"n":"גרוס, בנדיט אלימלך הלוי","k":"בעל קול מבשר","bp":"רוזניאטוב","b":"מחכמי רוזניאטוב. חברו של ר מאיר קריגל מרוזניאטוב. מראשי חברת \"אהרת ציון\", חיבר \"קול מבשר ותורת אמת\" דרוהוביטש תרנח."},{"i":12308,"n":"גרוס, בצלאל מטאקייא","b":"אביו של ר זאב וולף מיפו. חתנו - ר אליעזר חיים דייטש מבאניהאד(=בוניהאד)."},{"i":12309,"n":"גרוס, ברוך מתל אביב - עו\"ד","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":12310,"n":"גרוס, דוד מטאב","f":"אהרן אלעזר מיעמרינג","k":"בעל זהב שב\"א","dt":"תשמט - ג אד\"ב","b":"מצאצאי ר ליפמן שארגר מיעמרינג. תלמיד הדעת סופר, ור שבתי שפטל וייס משימאני ועוד. חתן ר שמחה בונם ברייער מטאב, ובזיוו\"ש חתן ר מרדכי ליכטנשטין מטשירטש. ניצל מהשואה ואחריה דיין בבודפשט ובפרשבורג-תשו, וחבר בית הדין המרכזי לתקנת עגונות. עלה לארץ וכיהן כרב שכונת מכבי בתל אביב-תשך, רב בניו יורק ור\"מ בישיבת נייטרא מונט קיסקא."},{"i":12311,"n":"גרוס, דוד מטשבין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"הנשר\" - טירנוי תרצג-תשד."},{"i":12312,"n":"גרוס, דוד מפרשבורג","bp":"פרשבורג","dt":"תש..","b":"תלמיד ישיבת פרשבורג. הצטרף לציונות, פובלציסט ציוני, עורך \"אלגעמיינע יידשע צייטונג\" - פרשבורג תרצד, \"זשידובסקא קולטורא\" - פרשבורג - בסלובקית, \"זשידובסקא רוצנקא\" - פרשבורג תרצד. חיבר מחקרים לתולדות קהלת פרשבורג. נספה בשואה."},{"i":12313,"n":"גרוס, הלל ממארגרטן","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":12314,"n":"גרוס, זאב וולף מוינה","f":"בצלאל מטאקייא","bt":"תריז","bp":"טאקייא","dt":"תרפח - כח אדר","dp":"יפו","b":"חתן ר בנימין שלמה זלמן שפיצר מוינה - חתן החת\"ס, ועבר לוינה. עלה לארץ-תרמח בכדי להכין הדרך לחותנו שתכנן לעלות לארץ. התגורר בירושלים, יפו."},{"i":12315,"n":"גרוס, זלמן ליב","dt":"תשד","b":"רב בסעליש"},{"i":12316,"n":"גרוס, חיים ישכר דב ממונקטש","f":"בנימין צבי","k":"בעל ישמח חיים","bt":"תרם","bp":"פטריווה-מאמארוש","dt":"תרצח - כח תמוז","dp":"מונקטש","b":"רב בפעטריוא-תרסד, רב וראש ישיבה במונקטש. פרסם מאמרים בכתבי עת תורניים, ובהם, ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"הכוכב\" - מונקטש-נ\"י תרצה, \"הנשר\" - טירנוי תרצג-תשד, ועוד. מחברים רבים שלחו אליו את מאמריהם לביקורת לפני הדפסה. נזכר אצל רבים ממחברי דורו, ובחלק מהספרים נדפסו גם הערותיו, (\"שם הגדולים מארץ הגר\" ג - נכתב ע\"פ הערותיו). בנו ר יעקב הו\"ל את חבוריו \"ימות המשיח\" תרצז, ו\"ויאמר יעקב\" תש"},{"i":12317,"n":"גרוס, חיים מעגרעדי","f":"ישראל מקיש","bt":"תריג","dt":"תרעה - יא אייר","dp":"באניהאד","b":"תלמיד הכת\"ס, ומהרם שיק. חתן ר בנימין זאב זינגר. מחכמי בעגערדי, וגזבר קהילת באניהאד הסמוכה."},{"i":12318,"n":"גרוס, חנניה יום טוב ליפא מברבש","f":"רפאל מברבשט","dt":"תשלא","dp":"[ניו יורק]","b":"רבה האחרון של ברבשט-תרצד על מקום אחיו ר שמואל, שערב לקרולה. ניצל מהשואה, ואחריה המשיך לכהן כרב שם והשתתף באסיפת הרבנים בקלויזנבורג-תשה. עלה לירושלים, ועבר לניו יורק."},{"i":12319,"n":"גרוס, יאקב יוסף מאויבן","dt":"תרצח","b":"דרשן,רב באויבן-תרס\"ט"},{"i":12320,"n":"גרוס, יהודה ליב מפרשבורג","bt":"תקצ","bp":"פעהער(באלאש)-ירמוט","dt":"תרסו - יז תשרי","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור יהודה אסאד, ור יהושע כץ רפפורט מוערפעלעט ובאלאש-יארמוט. ר\"מ בישיבה בפרשבורג על מקום ר פיבל פלויט שעבר לשוראן, והיה אחראי גם על קבלת התלמידים לישיבה ושילובם בה כ-60 שנה. נחשב לחריף ושנון ואמרותיו התפרסמו גם אחרי פטירתו. פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח."},{"i":12321,"n":"גרוס, יוסף אריה מקראלי","f":"מרדכי מטשענגער","k":"בעל שארית יוסף","bt":"תרלג","bp":"טשענגר","dt":"תשיא - כד סיון","dp":"ניו יורק","b":"תלמיד השב\"ס, וזקנו ר יהושע אהרן וינברגר ממארגרטן. חתן ר משה שפירא מוראנוב. מראשי הקהלה בקראלי. התישב בפריז-תרצח, ניצל מהשואה ועבר לניו יורק."},{"i":12322,"n":"גרוס, יוסף ישעיה מקראלי","b":"ניצל מהשואה ואחריה רב בקראלי, חתם-תשח עם כמה מרבני רומניה."},{"i":12323,"n":"גרוס, יחזקאל מקראקא","b":"תשובה אליו - \"מנחת אברהם\"."},{"i":12324,"n":"גרוס, יעקב","dt":"תשג","b":"רב בטורן"},{"i":12325,"n":"גרוס, יעקב","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":12326,"n":"גרוס, יעקב דב מנאדי-רעפני","bt":"תרלז","bp":"אוואש-אויוארוש","dt":"תש..","b":"תלמיד השב\"ס. חתן ר יצחק דב רייניץ מיאנושי. שו\"ב בנאדי-רעפעני-תרסד. נספה בשואה."},{"i":12327,"n":"גרוס, יעקב יוסף מאויבן","f":"ישראל דוד ממיהלפלווא","k":"בעל תבואת יקב-תשב","b":"תלמיד ר בנימין זאב מנדלבוים מסטמר. רב באויבן, בודפשט. בניו ר אהרן צבי מפאמאז, ור מאיר משארקד."},{"i":12328,"n":"גרוס, יצחק איזיק","b":"תלמיד ישיבת וויצען. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח, \"הנשר\" - טירנוי תרצג-תשד."},{"i":12329,"n":"גרוס, יצחק מטארן","b":"רב בטארן-תש."},{"i":12330,"n":"גרוס, יצחק משה מאוברטין","dt":"תרכו","b":"רבה של אוברטין, ר מרדכי בנו מילא את מקומו."},{"i":12331,"n":"גרוס, יקותיאל יהודה","f":"שמואל מברבשט","dt":"תשד","b":"נכד האדמורים ר ישעיה מקרעסטיר, ור יעקב יוקיל טיטלבוים מוועלאווא. רבה הראשן של שוגאטאג-מארמרוש. נספה בשואה. (באוצר הרבנים עירב בינו לבין דודו בעל אותו השם)"},{"i":12332,"n":"גרוס, יקותיאל יהודה מברבשט","f":"רפאל מברבשט","dt":"תשה - כה אייר","dp":"אושוויץ","b":"רב בברבשט-תרעד על מקום אביו, ואחיו ר שמואל על מקומו אחריו, רב ודיין בסיגט-תרפו כממלא מקום דודו ר חיים צבי טיטלבוים - וכמחנכו של בן דודו ר יקותיאל יהודה טיטלבוים - היורש המיועד לרבנות שהיה בגיל 14, וראש ישיבה מקצועית שם. נספה בשואה."},{"i":12333,"n":"גרוס, ישראל דוד ממיהלפאלווא","f":"משה צבי הרש מאוואש","bt":"תר","dt":"תרעז - כו תמוז","dp":"מיהלפאלווא","b":"תלמיד הכת\"ס, ור אשר יונגרייז מטשענגער. מחכמי מיהאלפאלווא. בנו ר יעקב יוסף אב\"ד אויבן."},{"i":12334,"n":"גרוס, ישראל מאושפיצין","b":"תלמיד בישיבת \"כתר תורה\" באושפיצין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"כתר תורה\" - אושפיצין תרצט."},{"i":12335,"n":"גרוס, ישראל מוילחוביץ","k":"בעל תפארת ישראל","dt":"תרסט - י כסלו","b":"תלמיד מהר\"ם א\"ש. רב בוילחוביץ."},{"i":12336,"n":"גרוס, ישראל מטאקיא","b":"חתן ר בנימין זאב וולף פוקס מסערעד. חתנו - ר בנימין פוקס מגרוסורדין."},{"i":12337,"n":"גרוס, ישראל ממישקולץ","b":"דיין במישקולץ"},{"i":12338,"n":"גרוס, ישראל ממישקולץ","f":"צבי מרסלביץ","bt":"תריא","bp":"ראסלביץ","dt":"תרצד - ב סיון","dp":"מישקולץ","b":"תלמיד הכת\"ס. רב במישקולץ-תרלב. רשם את חדושי רבו ומשם נדפסו ב\"חדושי כתב סופר השלם\"."},{"i":12339,"n":"גרוס, מאיר משארקאד","f":"יעקב יוסף מאויבן","k":"בעל אמרי לב","bt":"תרסא","dt":"תשה - ז שבט","b":"תלמיד הדעת סופר, ור ישעיה זילברשטין מוויצען, ור מרדכי בריסק מטאשנד. חתן ר מרדכי מאיר בנט משטינמאנגר, בזיוו\"ש חתן ר דוד עזרא הירש מגאלאנטא. רב בשארקאד-תרפד. נספה בשואה."},{"i":12340,"n":"גרוס, מרדכי מאוברטין","f":"יצחק משה מאוברטין","bt":"תקץ","dt":"תרף","b":"אב\"ד אוברטין על מקום אביו."},{"i":12341,"n":"גרוס, מרדכי מטשענגר","b":"מחכמי טשענגר. חתן ר יהושע אהרן צבי ויינברגר ממארגרטן. בנו - ר יוסף אריה מקראלי - ניו יורק."},{"i":12342,"n":"גרוס, משה דוד מלוצרן","f":"נתן נטע ממאלינקא","k":"בעל דע מה שתשיב","bt":"תרמה או תרמב","bp":"מאלינקא","dt":"תשכז - טז תשרי","dp":"תל אביב","b":"תלמיד השב\"ס, ור שמעון פולק מבעלניעש, ור נח ברוך פישר מפרשוב. חתן ר אשר גרוס מטאקיא. רב בראקמאז-תרסה, קהילת יוצאי הונגריה בלוצרן (שוויץ)-תרסח. בזיוו\"ש חתן ר יעקב זילברמן מפרשוב-תרסט. עלה לירושלים-תרעג, וינה - בעל הוצאת ספרים מנורה, תל אביב-תרץ. חיבר \"אבות הדורות\" ועוד. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":12343,"n":"גרוס, משה הכהן מבוקין וירושלים","bp":"הונגריה","dt":"תרעח (באו' תרעד","dp":"ירושלים","b":"אב\"ד בוקין (הונגריה) עלה לירושלים."},{"i":12344,"n":"גרוס, משה מאונגואר","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":12345,"n":"גרוס, משה מטשעבין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":12346,"n":"גרוס, משלם פייש צבי מניו יורק","k":"בעל נחלת צבי","b":"חתן ר עמרם ישי הלוי ביליצצר מסערענטש. רב בארה\"ב-תשב. ?? לא באוצר ??"},{"i":12347,"n":"גרוס, נפתלי מויליצקה","f":"ברוך ממעליץ","bt":"תרלא","b":"חתן ר אברהם עברסמן מויליצקה ועבר לשם, ממשתתפי \"אהל מועד\"."},{"i":12348,"n":"גרוס, נפתלי מקרסטיר","f":"רפאל מברבשט","k":"אדמור מדבריצין ארה\"ב","dt":"תשמח - אלול","b":"נכד ר ישראל יעקב יוקל מואלובא. חתן ר אברהם שטינר האדמור מקרסטור(=קרסטיר). אדמור בדברצין. ניצל מהשואה ואחריה היגר לארה\"ב וכיהן כאדמור בני\"י - והתפרנס מבית דפוס שם."},{"i":12349,"n":"גרוס, עקיבא מטשבין","f":"יחזקאל אלתר","bt":"תרס","bp":"טשבין","dt":"תשכד","b":"חסיד רדומסק. תלמיד ר דב בריש ויינפלד, וממיסדי הישיבה בטשבין. ברח לרוסיה בזמן השואה. אחרי השואה חזר והיה לרב בגלייביץ (שלזיה), וזרזנוב-ריכבאך (ליד ברסלאו). בשנת תשט עלה לירושלים והיה רבה של שכונת בקעא. חתנו ר איסר פרנקל רב בתל אביב."},{"i":12350,"n":"גרוס, פנחס נחום מבלוזוב","bp":"בלוזוב","dt":"תשלד","b":"למד בביהמ\"ד לרבנים ברומא אצל קאסוטו. עבר לארה\"ב-תשז וכיהן כרב בפיטסבורג. פעיל במזרחי."},{"i":12351,"n":"גרוס, רפאל מברבשט","f":"ברוך","k":"רפאל הצדיק","dt":"תרעז - כט טבת","dp":"קרסטור-הונגריה","b":"חתן ר ישראל יעקב טיטלבוים מוואלאווע. רב בברבשט-תרמט על מקום חותנו שעבר לגורליץ. בזמן מלחמת העולם ה-I עבר אל בנו ר שמואל בקרסטור-הונגריה. רב בשמלוי."},{"i":12352,"n":"גרוס, שמואל מאונסדורף","k":"בעל כתבי מהרש\"ג","b":"תלמיד ר ברוך פרנקל מלייפניק. גביר מחכמי אונסדורף-תר. חיבר \"כתבי מהרש\"ד\" ובו מתולדותיו מאת ר משה אשר ראטה."},{"i":12353,"n":"גרוס, שמואל מקרולה","f":"רפאל מברבשט","k":"בעל עלה שמואל","bt":"תרנח","bp":"ברבשט","dt":"תשד - י סיון","dp":"אושוויץ","b":"תלמיד בן דודו ר חיים צבי טיטלבוים בסיגט. חתן ר ישעיה שטיינר האדמור מקרסטור. רב בריטשע(=ביטשקא)-מחוז זמפלן-תרפא. רב וראש ישיבה בברבשט על מקום אחיו - ר יקותיאל יהודה שעבר לסיגט, ואחיו ר חנניה יו\"ט על מקומו אחריו. רב וראש ישיבה בקרולה על מקום קרובו ר יואל טיטלבוים שעבר לסטמר והיה מחלוקת על כך - הוא היה רבם של חסידי סטמר. נספה בשואה. ?? לא באוצר ??"},{"i":12354,"n":"גרוסברג, אריה ליב מבודפשט","f":"אשר מבעלעניעש","bt":"תרל","dt":"תרפז - כג חשון","dp":"בודפשט","b":"מחכמי בודפשט, עורך העתון האורטודוכסי \"אלגעמיינע יידישע צייטונג\", ו\"זשידע אוישאג\". חתנו - ר שלמה קליין ממעזא-קערעסטעט. בניו - המו\"לים של העיתון זמידא אישאג בבודפשט-בזמן השואה."},{"i":12355,"n":"גרוסברג, אשר מבעלעניעש","f":"אליהו צבי","bt":"תקפח","bp":"טיסא-עסלאר","dt":"תרנו - יא כסלו","b":"תלמיד הכת\"ס, מהרם א\"ש, ר ירמיה לעוו ועוד. רב בבעלעניעש(=באלניש)-תרכח. בנו אריה ליב גרוסברג-לעאפאלד עורך העתון החרדי \"אלגעמיינע יידישע צייטונג\" בבודפשט. נזכר בספרי חכמי דורו."},{"i":12356,"n":"גרוסברג, חנוך זונדל","bt":"ה'תרסד","dt":"ה'תשלז","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\".","bk":[["תורת השמיטה",""],["אגרת הפורים",""],["דרישת צ’ב’י’",""],["המעשר והתרומה",""],["חוקות שדה",""]]},{"i":12357,"n":"גרוסברג, יוסף מבודפשט","f":"אריה ליב מבודפשט","bt":"תרנו","dt":"תשם - ג אייר","dp":"פתח תקוה","b":"תלמיד הדעת סופר, ור שמואל רוזנברג מאונסדורף. חתן דודו ר שלמה קליין מביהאר-מעזא קרעסטעש. עורך העתון האורטודוכסי בבודפשט עד תשד. ניצל מהשואה ואחריה רב הקהלה החרדית בבודפשט."},{"i":12358,"n":"גרוסברג, יצחק יהושע מהוסיאטין","b":"רב בהוסיאטין. תשובה אליו בשו\"מ-תרטו."},{"i":12359,"n":"גרוסברג, מנשה מלונדון","k":"בעל ראש מנשה","b":"רב בטרסטינא, לונדון. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. חיבר \"ראש מנשה\" ובו תשובות ר חיים ברלין אליו, והערות לספר ה\"יחוד\"."},{"i":12360,"n":"גרוסברגר, יעקב אריה מברומברג","b":"רופא מחכמי ברומברג-פרוסיה. פרסם מאמרים ב\"הבונה\" - לבוב תרסד."},{"i":12361,"n":"גרוסברד, אבא מפוניבז","dt":"תשז - כז אב","b":"מראשי ישיבת פוניבז' ומנהלה הרוחני."},{"i":12362,"n":"גרוסברד, אברהם אריה ליב משירוו","f":"ברוך מפיליפובה","bt":"תרלא","bp":"גאוורי-פלך סובאלק","dt":"תשא - כז סיון","dp":"שירווינט","b":"רב בפיליפובה-תרעג על מקום אביו, רבה האחרון של שירווינט, וחתנו ר זונדל קרוק לצדו. ממיסדי ה\"מזרחי\" בליטא. ביקר בארץ-תרעב ותכנן להשתקע בה אך בגלל המלחמה חזר לליטא. נספה בשואה עם כל עדתו. חתנו ר זונדל קרוק - נספה בשואה."},{"i":12363,"n":"גרוסברד, ברוך מליבירשוק","b":"רב בגאברי-תרל\"א, בליבירישוק על מקום ר אליעזר יצחק אלגזי ור אליהו פינק על מקומו אחריו."},{"i":12364,"n":"גרוסברד, יהודה ליב מגאוורי","b":"חתן ר אברהם אבלי מוארז'אן. אב\"ד גאוורי, טאווריג."},{"i":12365,"n":"גרוסברד, נחום אבא מבני ברק","b":"רב בבני ברק, חתם-תשכג על בקשת עזרה מטעם הת\"ת של הסטייפלר."},{"i":12366,"n":"גרוסברד, צבי שרגא מירושלים","b":"מראשי אגודת ישראל-תשכב, חתם עם האדמורים מגור וסלונים."},{"i":12367,"n":"גרוסהאבר, יצחק איצק מפאקש","k":"בעל מקל נועם","r":"אב\"ד פאקש, ואח\"כ בייאה והגליל, ואח\"כ חזר לפאקש","bt":"תקא-ה","bp":"קראקא","dt":"תקפג - ט כסלו","b":"מגדולי דורו בהונגריה. תלמיד הנודע ביהודה בפרג. רב בפאקש-תקמב, בייא(=בייאה) ור טוביה הארשיץ על מקומו אחריו, ושב לפאקש. החליף שו\"ת עם הנודע ביהודה והחתם סופר. חיבר \"מקל נועם\", \"קלע שריון\" (כנגד ספרי ר אהרן חורין מאראד - \"מקל נועם\" ו\"קלע בשריון\"). (יש רושמים תאריך פטירתו - תקעו). בניו - ר קופל קלמן, ר משה פריינד-גרוסהאבר.","bk":[["מקל נועם - נגד קונטרס אמרי נועם של אח\"ר (הרב מאראד - א'הרן ח'ורינר ר'בינר) שיצא להתיר את דג השטירל",""],["קונטרס התפילין - נגד העושים תפילין משתי עורות",""],["קלע בשריון - נגד קונטרס שריון קשקשים של אח\"ר (הרב מאראד - א'הרן ח'ורינר ר'בינר) שיצא להתיר את דג השטירל",""]]},{"i":12368,"n":"גרוסהאבר, קופל קלמן טעבל","f":"יצחק מפאקש","bt":"תקמ","dt":"תרטז","b":"מחכמי שימאנטארניא, ראש הקהל בפאקש-תקפ, עמד בראש האספה הגדולה-תרד. הניח חבורים בכת\"י, מהם נדפסו ב\"תל תלפיות\"."},{"i":12369,"n":"גרוסווקס, צבי יהושע מנריוב","f":"אלתר","bt":"תרס","bp":"ברזאן","dt":"תשב","b":"עבר לוינה במלחמת העולם הראשונה והתקרב שם לחסידות רוזין. חתן ר דב בריש סים אב\"ד נריוב. אב\"ד נריוב על מקום חותנו. היה גם עסקן ציוני, מראשי בני עקיבא. נספה בשואה."},{"i":12370,"n":"גרוסינגר, שמעון מזשיבא","b":"רב בזשיבא-תרע\"ד"},{"i":12371,"n":"גרוסמן ישראל בן משה שניאור זלמן","bt":"1923","dt":"ה'תשסז 2007","bk":[["אורח ישראל",""],["הליכות ישראל",""],["כנסת ישראל",""],["משכנות ישראל",""],["נצח ישראל",""],["שיעורי בבא בתרא",""],["שיעורי בבא מציעא",""],["שיעורי בבא קמא",""],["שיעורי גיטין",""],["שיעורי כתובות",""],["שיעורי נדרים",""],["שיעורי סנהדרין",""],["שעורי קדושין",""],["שערי תירוצין",""]]},{"i":12372,"n":"גרוסמן שמעון מירושלים","b":"גבאי כולל ישוב ארץ ישראל בירושלים, חתם-תרץ עם ר משה ברזל, ר זלמן לנדנרן."},{"i":12373,"n":"גרוסמן, בצלאל מטשאבא","f":"שרגא פייש מטורנא","bt":"תרכז","dt":"תרצט - כד תשרי","dp":"טשאבא","b":"תלמיד השב\"ס, ור משה נתן נטע יונגרייז מטיסא-פירעד, ור אליעזר לעוו מעוהל. חתן ר יעקב גוטמן מטארנא ועבר לשם. רב בטשאבא-תרס."},{"i":12374,"n":"גרוסמן, דוד בר מזורובנא","b":"דיין בזורובנא אצל ר יצחק שמלקיס-תרטו."},{"i":12375,"n":"גרוסמן, זאב וולף מנייהייזל","b":"ראב\"ד בנייהייזל"},{"i":12376,"n":"גרוסמן, זיגמונד מבודפשט","b":"רב ניאולוגי בבודפשט-1906, ומנהל משרד הבנות של הקהלות הניאולוגיות בהונגריה. מומחה לתולדות יהודי הונגריה. פרסם מאמרים וספרים ובהם \"יהודי הונגריה במאה ה-19\"-1917."},{"i":12377,"n":"גרוסמן, חיים צבי ממישקולץ","b":"רב במישקולץ. פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":12378,"n":"גרוסמן, יהודה מאיזנשטט","b":"רב באייזנשטט"},{"i":12379,"n":"גרוסמן, יהודה מאיפלשאג","f":"נחמן מברוקלין","k":"בעל מנחת יהודה","bt":"תריב","dt":"תרצד","b":"גדל אצל זקנו ר משה אריה ליטש-רוזנבוים מפרשבורג. תלמיד הכת\"ס, והשב\"ס. רב באיפלשאג-תרלו כ-50 שנה."},{"i":12380,"n":"גרוסמן, יוסף חיים מאטשאקוב","f":"יצחק (ליב)","k":"בעל ראשות און יוסף","bt":"תרטז","bp":"פריאסלוב-פלך פולטובה","b":"תלמיד ר אלחנן רבינוביץ מיקטרינסלב, למד עם ר זלמן בן לוי בן הצמח צדק בניעזין. רב בקכטקזווה(=קאכטאקאואווע)-פלך חרסון-תרסא, אטשאקוב-פלך חרסון-תרע. נסמך מאת: ר ישראל נח מניעזין, ר אברהם דב מניקולייב, ר ליב מקיוואזיר, ר מרדכי דובער מהורנסטיפולי. בניו - ר לוי ממאקרוב, אליהו."},{"i":12381,"n":"גרוסמן, יוסף מארה\"ב","bt":"תרכד","dt":"תרפ","b":"רב בהיזלסון,פילדלפיה-תר\"ס"},{"i":12382,"n":"גרוסמן, יחזקאל שלמה מטורנא","b":"תלמיד ר שמשון נייפלד, ובעל \"באר שמואל\" באונסדורף. תושב טורנא. נספה בשואה."},{"i":12383,"n":"גרוסמן, יצחק איזיק","dt":"תשג","b":"רב בלודמיר-תרפ, גראייבה, בנדין-תרצז. פרסם מאמרים ב\"ירושלים\" - וארשא תרצו."},{"i":12384,"n":"גרוסמן, ישעיה מגריווא","f":"ירמיה","b":"מראשי קהלת גריווא, יסד ביכ\"נ-תרח בערך."},{"i":12385,"n":"גרוסמן, לוי ממאקרוב","f":"יוסף חיים מאטשקוב","k":"בעל שם ושארית","bt":"תרמג-ו","bp":"קנטקוזיבה","dt":"תשכ","b":"תלמיד ר מרדכי פרנקל מסאראקי, ר צבי בלוך בחרסון. חתן הגביר ר אברהם ברברמן מסטעפניץ-פלך קיוב. רב במאקרוב(=מקרוב)-פלך קיוב-תרע, מרבני תל אביב-תרצט. פרסם מאמרים בכתבי עת, וספרים - בכת\"י."},{"i":12386,"n":"גרוסמן, נחמן מניו יורק","k":"בעל מקראות קטנות","bt":"תקפה","bp":"טרענטשין","dt":"תרנז - יד אד\"ב","dp":"ניו יורק","b":"תלמיד הכת\"ס. חתן ר משה אריה ליב ליטש רוזנבוים מפרשבורג. רב בקאריטשן-תרכג, ואראזשדין-תרכז, עבר לאמריקה, רב בקנזס סיטי-תרלג, ניו יורק-תרלה. חיבר \"עשרת הנסיונות\" ושא\"ס בל\"א."},{"i":12387,"n":"גרוסמן, צבי הירש מדלטין","f":"משה","bt":"תקל","dt":"תקצג","dp":"קולומיאה","b":"תלמיד גדולי האדמורים. רב ואדמור בדלטין-תקסב. בנו ר יצחק משה הכהן אידלשטין - רב בפרוביזנא."},{"i":12388,"n":"גרוסמן, צבי יהודה מקיטוב","k":"אדמור מקיטוב","b":"מצאצאי הבעשט ור אברהם המלאך. רב ואדמור בקיטוב-תרסו - תרעח, ובנו ר שמעון מנחם על מקומו אחריו."},{"i":12389,"n":"גרוסמן, צבי משעננא","b":"נכד ר ישראל אפרים סופר מנאנאש בעל \"אפסי ארץ\". תלמיד ר שמעון ארנפלד ממיהאלביץ. רב בשעננא, ואמוש-פירטש."},{"i":12390,"n":"גרוסמן, ש.ל. מסט לורינץ","k":"בעל מועדים לשמחה","b":"רב בסט לורינץ-מחוז באראניא - עד תרעז. חיבר \"מועדים לשמחה\"."},{"i":12391,"n":"גרוסמן, שניאור זלמן מירושלים","b":"מראשי חסידי קרלין בירושלים-תשה."},{"i":12392,"n":"גרוסמן, שרגא פיבל פייש מטשאבא","dt":"תרסח","b":"תלמיד ר משה נתן יונגרייז בעל \"מנוחת משה\". חתן ר אדוניה שמלצר בעל \"נפש אדוניהו\". דיין בפטרווסעלי. אב\"ד טשאבא. הניח חדושים ודרושים בכת\"י. בנו - ר משה נתן (על שם רבו)."},{"i":12393,"n":"גרוסמן, שרגא פייש מטורנא","b":"רב בטורנא-תר\"מ"},{"i":12394,"n":"גרוספלד, בן ציון מקראקא","f":"שלמה זלמן","k":"בעל ציוני תורה","bt":"תרנז","bp":"קראקא","dt":"תרצו","b":"תלמיד ר מאיר ארק, ר\"י אנגל, והרב דמביצר ראב\"ד קראקא. חתן ר שלמה צבי הברמן מזבירציה ועבר לשם. חזר לקראקא ונשלח לארץ-תרפו מטעם חברת נחלת קראקא - לרכוש קרקע בארץ. בשובו עבר בטריאסט ונתקבל לרבנות לשנה, רב בלאזי (ליד זבירציה), שטעקטשין-תרצא. חיבר \"ציוני תורה\" פיעטרקוב תרצד. ?? לא באוצר ??"},{"i":12395,"n":"גרוספלד, יהושע השל מדוברומיל","bt":"תקעה","dt":"תרמה","b":"תלמיד ר מנחם א\"ש באונגוואר. חתן ר אברהם גוט מדוברומיל. מחכמי דוברומיל. מילא את מקום ר אלימלך מנחם רימלט שנפטר עד שגדל בנו ר אברהם מרדכי. חתנו - ר מרדכי הירצמן."},{"i":12396,"n":"גרוספלד, יחזקאל מטשאפ","f":"נפתלי","k":"בעל צפיחית בדבש","dt":"תרעא","b":"מ\"מ בקלינורדין, רב בטשאפ-תרם. הו\"ל \"בנין אהל מועד\"."},{"i":12397,"n":"גרוספלד, יעקב מדוברומיל","dt":"תרעז - ז טבת","b":"רב בדוברומיל"},{"i":12398,"n":"גרוספלד, פנחס מחאדלע","dt":"תשג","b":"רב בחאדלע"},{"i":12399,"n":"גרושובסקי, אהרן מסלובודקא","b":"תלמיד בכולל בסלובודקא. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב."},{"i":12400,"n":"גרושקא, צבי מסארנא","b":"מתורתו ב\"תורה אור\" - שנחאי תשו."},{"i":12401,"n":"גרושקין, אברהם יצחק הכהן","bt":"תרמ","dt":"תרצה - כה תמוז","b":"מו\"צ בפינסק,עלה לירושלים-תרצ\"ה"},{"i":12402,"n":"גרושקין, אברהם יצחק מביסיגולה","f":"רפאל","dt":"תרמה","b":"רב בביסיגולה 19 שנה."},{"i":12403,"n":"גרושקין, רפאל","f":"אברהם יצחק מביסיגולה","k":"בעל הדסה","bt":"תרי","bp":"ביסיגולה-ליטא","dt":"תרצב","dp":"וילקומיר","b":"בן למשפחה מיוחסת שהעמידה פרנסים ושתדלנים בוילנא. ואמו ממשפחת אטלס. תלןמיד ישיבות ליטא. מחובבי ציון. התישב בוילקומיר והיה יו\"ר ועד הקהילה והקים מוסדות לתלמוד תורה מושב זקנים ובית יתומים.פרסם מאמרים בעתוני זמנו. חיבר גם \"משלות\" - מבוא לספר משלי עם פירוש \"אור נוגה\". נכדו - אברהם (יאיר) שטרן מפקד ארגון הלח\"י. ?? לא באוצר ??"},{"i":12404,"n":"גרזו, שלמה משלוניקי וצפת","b":"מחכמי שלוניקי-שנות ה-ר'-ש', עלה לצפת."},{"i":12405,"n":"גרזון, יעקב יצחק איטשקה מלאסק","f":"יהושע","bt":"תרטז","bp":"זגערש","dt":"תרעו","dp":"לאסק","b":"תלמיד ר אהרן קרול מלאסק. חתן ר שמואל ברקנואלד מלאסק. גביר מחכמי לאסק. חברו - ר צבי אריה יהודה מייזלש חיבר לזכרו \"קונטרס זכרון בספר\" ובו מתורתו של ר איטשקה."},{"i":12406,"n":"גרטלר, יצחק צבי מפודוולוציסק","bt":"תר","dt":"תרנב","b":"אב\"ד סטריסוב-תר, פודוולוציסק-תרמד."},{"i":12407,"n":"גרטלר, יצחק צבי מקומרנא","f":"משה","k":"בעל נטע בחורים","bt":"תרם","dt":"תשב","b":"מחרמי קומרנא וממיסדי המזרחי. חיבר \"נטע בחורים\" \"וילקט יוסף\". נספה בשואה. ?? לא באוצר ??"},{"i":12408,"n":"גרטמן-גרטן, אליעזר ליפא מברזן","b":"נכד הרב מבלשביץ."},{"i":12409,"n":"גרטנהויז, אברהם אליעזר ליפא","f":"צבי הירש","dt":"תשמא","b":"הו\"ל ספר \"מים טהורים\" לזקנו."},{"i":12410,"n":"גרטנהויז, אהרן אריה יהודה ליב","f":"אלעזר אליעזר","bt":"תרעד","bp":"מיקוליב","dt":"תשל","b":"תלמיד \"כתר תורה\" בקראקא, זקנו ר צבי הירש מפרוכניק. נסמך מאת: ר משה בלייכר מקראקא. חתן ר אברהם יהושע השל האדמור מקופישטיניץ. רב קהלת \"אנשי וארשא\" בניו יורק, \"זכור לאברהם\"-תש. חיבר ספר הוספות ל\"טעמי המנהגים\" נדפס בניו יורק."},{"i":12411,"n":"גרטנהויז, אלעזר ליפא מארה\"ב","f":"צבי הירש מפרוכניק","k":"בעל אשל הגדולים","bt":"תרנג","bp":"פרוכניק","b":"תלמיד ר יהושע פנחס בומבך מאושפיצין ונסמך ממנו. חתן ר יוסף יחיאל מיכל רדליך אב\"ד מיקולייב. רב במיקוליב, ניו יורק-תרפה בקהילת פרוכניק באמריקה, ור\"מ בישיבת רבי שלמה קלוגר בניו יורק, רב קהלת \"זכור לאברהם\" בניו יורק. ונשיא דגל הרבנים באמריקה. בזיוו\"ש חתן ר אברהם שמחה קלוש ממונקטש. חיבר \"אשל הגדולים\" ניו יורק. פרסם תשובה מר שלמה קלוגר ב\"המסלה\" - נ\"י תרצו. בניו - שמואל דב - נפטר צעיר תשד, ר אהרן יהודה ליב."},{"i":12412,"n":"גרטנהויז, אלעזר ליפא מלנצהוט","b":"רב בלנצהוט לפני מלחמת העולם הראשונה."},{"i":12413,"n":"גרטנהויז, חיים שלמה מרידיק","bt":"תקמ","dt":"תריא","b":"צדיק ומקובל מרידיק שהיה לו הסכם ישכר וזבולון עם ר יצחק מכפר נאוויסעלא. בנו ר יהודה ליב מרידיק."},{"i":12414,"n":"גרטנהויז, צבי הירש מפרוכניק","f":"שמואל דב","bt":"תרל","dt":"תשו","b":"מצאצאי הבעש\"ט, נכד (אבי אמו) - ר צבי אדל בעל \"עץ שתול\" ו\"פרי העץ\". חתן ר יהושע עלאוויטש אב\"ד פרוכניק-תרס, והיה רב שם אחריו. הגיע לניו יורק אחר השואה."},{"i":12415,"n":"גרטנהויז, שמואל מרדכי מרישא","f":"יצחק","bt":"תרנב","bp":"רישא","dt":"תשכד","b":"ברח מהגיוס לצבא לדיסלדורף, חתן ר ישראל וייסברד מצאנז. היגר למונטריאול ולניו יורק, עלה לירושלים-תרפט."},{"i":12416,"n":"גרטנר, אברהם צבי מסיזאוואליע","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":12417,"n":"גרטנר, אליעזר משידלובצא","f":"יהודה מלענשטנא","dt":"תשג","b":"בן האדמור מלענטשנא. רב בשידלובצה."},{"i":12418,"n":"גרטנר, בנימין מיאנוב","b":"רב ביאנוב וגבאי ארץ ישראל. בנו ר פרץ ראב\"ד בסקאלא."},{"i":12419,"n":"גרטנר, יהודה","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":12420,"n":"גרטנר, יהודה מלענטשנא","f":"יחיאל מלענטשנא","k":"אדמור מלענטשנא","dt":"תרפ - כה ניסן","dp":"ייליבסטגרנד","b":"אדמור בלענטשנא, עבר לאלכסנדרובקה. בניו ר שלמה מדומאציבא, ר אליעזר משידלובצא, ר מנחם מתל אביב."},{"i":12421,"n":"גרטנר, יחיאל מלענטשא","f":"יהודה מלענטשא","k":"אדמור מלענטשנא טורנט","dt":"תשל","b":"אדמור מלענטשא בבריסל, עבר לטורונטו."},{"i":12422,"n":"גרטנר, יחיאל מלענטשנא","k":"אדמור מלענטשנא","b":"בן אחותו של ר יצחק איזיק האדמור מלענטשנא. רב בפוטשאשץ, אדמור בלענטשנא על מקום דודו."},{"i":12423,"n":"גרטנר, פרץ מדרוהוביטש","b":"רב בדרוהוביטש, קאטוב. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב."},{"i":12424,"n":"גרטנר, שלמה מדומאציבא","f":"יהודה מלענטשא","b":"נכד האדמור מלענטשנא. רב בדומאציבא."},{"i":12425,"n":"גריבר, אברהם מאיר מקראקא","f":"משה גריובר","bt":"תקסה","dt":"תרמא","b":"דיין בקראקא-תריא אצל ראנ\"ה ינר, בנו ר יהודה ליב רב על מקומו אחריו."},{"i":12426,"n":"גריבר, יהודה מקראקא","f":"משה","bt":"תקס","dt":"תרכו","b":"דיין בקראקא אצל ר משה יעקב דמביצר. בנו ר' יואל על כסאו אחריו."},{"i":12427,"n":"גריבר, יואל מקראקא","f":"יהודה","bt":"תקעח","dt":"תרנו","b":"דיין בקראקא על מקום אביו."},{"i":12428,"n":"גריגו, יהודה","b":"תשובה אליו ממהר\"ם פדובה."},{"i":12429,"n":"גרידל, ראובן מלובלין","b":"תלמיד החוזה מלובלין. דיין בלובלין."},{"i":12430,"n":"גרידץ, דוד טבלי מליסא","f":"מהר\"ם","b":"דיין בליסא-תקך, חתם עם ר צבי הירש ברלין וחבריו על מכתב לר דוד ברלין באה\"ו."},{"i":12431,"n":"גרידץ, מאיר מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":12432,"n":"גריזל, דב בר","dt":"תשג","b":"רב בקרעווא"},{"i":12433,"n":"גריזמן, זאב וולף יעקב מברזאן","f":"שמואל","k":"בעל אוצר נחמד","bt":"תרג","bp":"אולינוב","dt":"תרעג - בערך","b":"חתן רבקה ורנר מרישא ועבר לשם, מחכמי ברזאן. חיבר \"אוצר נחמד\" פרמישלא תרלו."},{"i":12434,"n":"גריזמן, צבי אלימלך מודוביצה","f":"שמואל","bt":"תרא","dt":"תרסו","b":"רב בודוביצה-תרסד."},{"i":12435,"n":"גריזמן, שמואל מודוביצה","b":"רב בודוביצה-תרצז."},{"i":12436,"n":"גריטון, אברהם רהטון","f":"יצחק","b":"המדפיס הראשון בעברית. הדפיס פירוש רש\"י לתורה - ריגיו רלה."},{"i":12437,"n":"גרייבסקי, אלעזר זלמן מאנגליה","f":"מרדכי יוסף","k":"בעל גינת אגוז","bt":"תרג","bp":"מאליאט(=מאלטש)-ליטא","dt":"תרנט","dp":"וילנא - ירושלים","b":"רב בליוורפול, ממלא מקום הרב בקלאצק-תרכח, וארשא, ליברפול-תרלו. עלה לארץ-תרן, נסע לוילנא-תרנט לרפואה ונפטר שם. חיבר גם \"קדיש לעולם\" על מקורות הקדיש. ממיסדי שכונת \"מזכרת משה\" בירושלים. בנו - ר שמעון חיים (תרכז-תשג)."},{"i":12438,"n":"גרייבסקי, יעקב אשר הלוי מירושל","k":"בעל ברית הלוי","bt":"תרכו","bp":"קוסובה","dt":"תשו - יט סיון","b":"עלה לארץ בגיל 16, תלמיד ישיבת תורת חיים בירושלים. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"קול תורה\" - ירושלים תרץ, \"תורת ארץ ישראל\" - ירושלים תרץ. לתולדותיו בהקדמת נכדו לסספר \"ברית הלוי\" ירושלים תשנו, \"ספרים וסופרים\" לרש\"י זוין.","bk":[["ברית הלוי השלם - סוגיות בש\"ס רמב\"ם טור שו\"ע ועוד",""],["ברית הלוי ובו שתי מערכות א. אושר יעקב. ב. דברי אשר.",""],["גיא חזיון - מליצות ופתגמים",""],["שבט הלוי - סימנים",""]]},{"i":12439,"n":"גרייבסקי, פנחס מירושלים","b":"עוזרו של ר יחיאל מיכל פינס במזכירות ביה\"ח ביקור חולים בירושלים, הסטוריון. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":12440,"n":"גרייבסקי, צבי אריה","b":"פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":12441,"n":"גרייבסקי, צבי הירש מסלונים ויר","b":"דיין בסלונים, עלה לירושלים-תרלג. בנו (כנראה) - פנחס-מחבר ספרים וחוקר."},{"i":12442,"n":"גרייבסקי, שמעון חיים","f":"אליעזר זלמן-גנת אגוז","bt":"תרכז","dt":"תשג","b":"תלמידי ישיבת וולוזין. חתן ר שמואל ברמזון מרייאגארד, עלה לירושלים-תרעג, גלה למצרים בזמן מלחה\"ע ה-I, וכיהן כרב הגדודים העבריים בצבא הבריטי. מתורתו ב\"גנת אגוז\" לאביו."},{"i":12443,"n":"גרייוור, אברהם מאיר מקראקא","dt":"תרמא - א ניסן","b":"דיין בקרקא"},{"i":12444,"n":"גרייוור, אלעזר מסלונים","f":"יעקב","k":"בעל משנת דר אליעזר ב","bt":"תקד","dt":"תקצא - י טבת","b":"רב בסלונים."},{"i":12445,"n":"גרייזן רבינוביץ, עמנ'","dt":"תשג","b":"רב בדעמבלין"},{"i":12446,"n":"גריינימן, שמואל מבני ברק","bt":"תרנ","dt":"תשיז","b":"רב פעלים לחזוק היהדות,מרביץ תורה בבני ברק"},{"i":12447,"n":"גריינר, גימפל משטמפן","dt":"תרטז - כד אייר","b":"דיין בשטאמפן"},{"i":12448,"n":"גריליכס, אבנר","f":"צבי","bt":"1822","bp":"וילנא","dt":"1905","b":"תלמיד ישיבות ליטא. עיצב מטבעות ומדליות לממשלת אלכסנדר השלישי וניקולאי השני."},{"i":12449,"n":"גריליכס, אברהם","f":"אבנר","bt":"1852","bp":"וילנא","b":"תלמיד ישיבות ליטא. חרט אומן ובעל תואר חרט ראשי ב\"חצר המטבעות\" הרוסית, כאביו לפניו."},{"i":12450,"n":"גרימן, שמואל דוד מויליצקה","b":"מתורתו ב\"אהל מועד\" - תרפח."},{"i":12451,"n":"גרין, אברהם יהושע השל מסטמר","bp":"ירושלים","b":"הגיע מירושלים לסטמר, והיה מחכמי סטמר. הדפיס חוברת בסטמר ללימוד כתיבת מכתבים - תרצא."},{"i":12452,"n":"גרין, אלברט מארצ'י-הונגריה","dt":"תשד","b":"רב ד\"ר הקהילה המאוחדת בארצ'י. נספה בשואה."},{"i":12453,"n":"גרין, אליהו אהרן מוילקוביסק","f":"חיים מאיר מגרובין","bt":"תרלה","bp":"גרובין","dt":"תשא","dp":"וילקוביסק","b":"אחיו של ר יצחק גרין מספיזישוק. תלמיד זקנו ר שניאור זלמן הירשוביץ מגולדינגן, וישיבת טלז. רבה האחרון של וילקוביסק. מחשובי הרבנים בליטא, פוסק ומראשי אגודת הרבנים בליטא. נספה בשואה."},{"i":12454,"n":"גרין, בנימין ידידיה מזיימל","f":"שלמה מזיימל","b":"רב בזיימל-תרך על מקום אביו. בנו ר שרגא פיבוש."},{"i":12455,"n":"גרין, חיים אהרן דב מפישטיאן","b":"פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":12456,"n":"גרין, חיים מאיר הלוי מגרובין","f":"יוסף","bt":"תרג","b":"חתן ר שניאור זלמן מגולדינגן. רב בגרובין-קורלנד-תרלא על מקום ר זאב וולף רובינזון."},{"i":12457,"n":"גרין, יוסף","b":"רב במוהול-תרע\"ד"},{"i":12458,"n":"גרין, יוסף מלונדון","b":"ר\"מ בישיבת עץ חיים בלונדון-תרע."},{"i":12459,"n":"גרין, יעקב מרדומישל","b":"דיין ברדומישל (ולא פרמישלא)-תרנה. תשובה אליו ב\"בית יצחק\"."},{"i":12460,"n":"גרין, יצחק מוילקוביסק","dt":"תשג","b":"רב בווילקובישק"},{"i":12461,"n":"גרין, יצחק מסאפיזישוק","f":"חיים מאיר מגרובין","dt":"תשג","b":"אחיו של ר אליהו אהרן מוילקוביסק. רבה האחרון של ספיזישיק(=ספיזישוק). נספה בשואה."},{"i":12462,"n":"גרין, מנחם צבי משטמפן","b":"ש\"ץ, ונאמן בשטמפן. חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":12463,"n":"גרין, משה מראגנא","dt":"תרסה - יא ניסן","b":"תלמיד ר אשר אנשל יונגרייז בעל מנחת אשר. מחכמי ראגנא. חתנו - בעל דרכי ישרים (ר יו\"ט ליפא ברוין?)."},{"i":12464,"n":"גרין, עזריאל ממונקטש","dt":"תרע - יא אייר","b":"רב במונקטש. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":12465,"n":"גרין, צבי הירש","dt":"תשג","b":"רב בטילדיעש"},{"i":12466,"n":"גרין, שלמה יצחק מסום","f":"משה דב","bt":"תרלב","b":"נכד-אבי אמו ר יהודה זלקינד מוילנא (מתלמידי הגר\"א). תלמיד ר צבי הירש ואלק מפינסק-אחי חותנו. רב בפדברזנא(=פאדבערעזא)-פלך וילנא-תרנח, סום-פלך חרקוב. נסמך מאת: ר יצחק אלחנן מקובנא, ר אליעזר גורדון מטלז. חיבר פירוש לתורה, על הש\"ס והלכות - בכת\"י."},{"i":12467,"n":"גרין-פרוסטיג, עזריאל ממוסט","f":"שמעון","k":"בעל נחלת עזריאל","b":"נקרא גם בשם - פרוסטיג. אחיו של ר יוסף מטומשוב. תלמיד החוזה מלובלין, והשר שלום ור יצחק מבלז. רב בחוליוב,מוסט-תקצא, ברח בגלל עלילת דם להונגריה, אב\"ד מונקטש-תקצג, היה מחותן עם ר צבי אלימלך מדינוב. חיבר \"נחלת עזריאל\" מונקטש תשג (בשער תרצט). בנו ר יהושע מאיר מרקלניץ (ליד מוסט). פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":12468,"n":"גרין-פרישרמן, יוסף מיריטשוב","f":"שמעון","k":"אדמור מטומשוב","bt":"תקמז","bp":"טומשוב","dt":"תקצט","b":"אחיו של ר עזריאל גרין ממונקטש. חתן הגביר ר אהרן מסטרי. שינה שמו מגרין לפרישרמן. רב בנרול, ירטשוב (ליד טומשוב), רב ואדמור בטומשוב - בהוראת החוזה מלובלין, בנו ר יהושע על מקומו אחריו. היה מעורב במחלוקת כנגד ר בונם מפשיסחא ו מנחם מנדל מקוצק, וגרם לכך שרמ\"מ יעבור מטומשוב לקוצק."},{"i":12469,"n":"גרינבוים, אברהם מהוסאסו","f":"אליעזר","bt":"תקף","bp":"כפר סוטש-ליד לאפוש","dt":"תרנו - ב ניסן","b":"תלמיד ר אשר אנשל יונגרייז בעל מנחת אשר. רב בכפר אורהיי-ליד ביסטריץ. רב בהוסאסו-מחוז טארנאווה מיקה-תרכו. מחדושיו ב\"תל תלפיות\", \"וילקט יוסף\" ועוד. מכתב ממנו בדבר המחלוקת בסיגט בענין פילוג קהל \"ספרדים\" ב\"מלחמת מצוה\"."},{"i":12470,"n":"גרינבוים, אברהם מנאדי-אזאר","b":"אביו של ר מנשה ממאטע-סאלקא."},{"i":12471,"n":"גרינבוים, גרשון הכהן מזבנא","dt":"תש..","b":"רב בפשצלוב, אב\"ד זבנא-תרפז. נספה בשואה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו."},{"i":12472,"n":"גרינבוים, דב בריש מדינוב","f":"ליביש מדינוב","bt":"תרו","bp":"דינוב","dt":"תרפט","b":"ממשפחת הבני\"ש. חסיד צאנז. דחה הצעת רבנות מדינוב. גיסו של ר מרדכי בנק-פיינגולד. עבר לברזיב."},{"i":12473,"n":"גרינבוים, חיים יוסף מבלזנדורף","f":"אברהם מהאסוסא","k":"בעל ספר הארץ הקדושה","bt":"תרלג-ד","bp":"האסוסא","dt":"תרף - כה טבת","b":"מצאצאי (מצד אמו) ר חיים רפפורט מלבוב. תלמיד השב\"ס, ובעל ר חנניה טיטלבוים בעל \"קדושת יום טוב\". רב בהוסאסו(=האסוסא) על מקום אביו-תרנו. רב הקהלה האורטודוכסית בבלאז'(=בלוזנדורף,בלאזענדארף)-תרנז. נסמך מאת: ר קופל רייך מבודפשט. התקרב לציונות והשתתף בביקור בארץ-תרע, ופרסם חוברת בגרמנית והונגרית על רשמיו מהביקור-תרעב. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"תל תלפיות\". ?? לא באוצר - הספר קיים המחבר לא ??"},{"i":12474,"n":"גרינבוים, חיים נחום דוד","b":"רב בפרשדבורז-תר\"ע"},{"i":12475,"n":"גרינבוים, יהודה ליבוש מדינוב","b":"רב בדינוב. בנו - ר בריש מברזיב. תשובה אליו - \"בית יצחק\" תרלב."},{"i":12476,"n":"גרינבוים, יוסף מטעגלאש","k":"הגיבור מטעגלאש","b":"חוכר אצל רוזני דגנפלד בטעגלאש. בכוחו הפיזי הרב מנע פרעות והתנכלויות ביהודים. דמות נערצת בציבור היהודי וכונה \"יוסלה טעגלאשר\". (בחת\"ס ותלמידיו נזכר שהיה שתדלן ומנהיג בטעגלאש.)"},{"i":12477,"n":"גרינבוים, יוסף מנאנאש","k":"בעל הכרמל","b":"מחכמי נאנאש. חיבר \"הכרמל\" סיגט תרס - על שמות נרדפים בכתבי המלבי\"ם."},{"i":12478,"n":"גרינבוים, ירחמיאל","b":"רב בביכאווה-תר\"ע"},{"i":12479,"n":"גרינבוים, מנחם דוד מקונסטנטין","f":"ישכר דב הכהן","bt":"תרא","b":"רב בנאווידוואר-פלך וארשא, קונסטנטין-פלך פיעטרקוב. נסמך מאת: ר יהושע מקוטנא, ר חיים אליעזר וקס מקאליש."},{"i":12480,"n":"גרינבוים, מנשה ממאטע-סאלקא","f":"אברהם מנאדי אזאר","bt":"תריז או תרכא","bp":"נאדי-אזאר","dt":"תש - כא אד\"א","dp":"מאטע-סאלקא","b":"תלמיד השב\"ס, ור עמרם בלום מבערטי-אויפלו, ור משה צבי הרש פוקס מגרוסורדין. חתן ר שלום אולמן מוויצען. רב במאטע-סאלקא-תרמז, ובנו ר שלום על מקומו אחריו."},{"i":12481,"n":"גרינבוים, מרדכי","b":"רב בניישטט,שערפס-תר\"י"},{"i":12482,"n":"גרינבוים, משה הכהן מפשצלוב","b":"ממשתתפי \"אספת חכמים\"-תרעא, \"המפלפל\" - קראקא תרעג."},{"i":12483,"n":"גרינבוים, נתן דוד מפשדבורז'","b":"אב\"ד פשדבורז'-תרצה."},{"i":12484,"n":"גרינבוים, שלום ממאטע-סאלקא","f":"מנשה ממאטע-סאלקא","dt":"תשד","b":"תלמיד הדעת סופר. רב במאטע-סאלקא לצד אביו, ועל מקומו אחריו-תש. נספה בשואה."},{"i":12485,"n":"גרינבלט, אפרים מארה\"ב","k":"בעל רבבות אפרים","b":"רב בממפיס. ?? לא באוצר ??"},{"i":12486,"n":"גרינבלט, יצחק מאלענוויל-ארהב","k":"בעל ויאמר יצחק","b":"רב בוושינגטון, עלענוויל-ארה\"ב. חיבר גם \"הררים התלוים בשערה\" פיעטרקוב תרפט. ?? לא באוצר ??"},{"i":12487,"n":"גרינברג, אברהם מארה\"ב","f":"יוסף","bp":"סלוצק","dt":"תרפט - כו אב","dp":"ניו יורק","b":"גביר בברונסויל-ארה\"ב, סייע בהקמת מוסדות תורה וחסד."},{"i":12488,"n":"גרינברג, אברהם מקזמרק","f":"צבי זאב","bt":"תר-ד","dt":"תרעט - יח טבת","b":"תלמיד הכת\"ס, ור יהודה אסאד, ור אפרים ברוין מטשאבא דודו זקנו. גר בקערעסטעש. רב במישקולץ-תרכט, קזמרק(=קעיזמארק)-תרלד, בנו ר שמחה נתן על מקומו אחריו. חתניו: ר יונתן הורביץ מירושלים, ר יוסף מאיר גליק מקזמרק."},{"i":12489,"n":"גרינברג, אהרן יוסף מפודגורזע","f":"אברהם","bt":"תרעו","b":"תלמיד ר מנדלי רוטנברג בישיבת בובוב. נספה בשואה וכן אחיו ר מרדכי."},{"i":12490,"n":"גרינברג, אהרן ממיהלוביץ","b":"מתורתו ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":12491,"n":"גרינברג, אורי צבי מירושלים","b":"מצאצאי ר אורי השרף מסטרליסק. משורר"},{"i":12492,"n":"גרינברג, אפרים","bt":"1895","bp":"ליובאווה-פלך סובאלק","dt":"1942","dp":"רוסיה","b":"מחבר ועסקן ציוני. פרסם מאמרים בעתוני התקופה. עורך ה\"דאס ווארט\" בקובנא."},{"i":12493,"n":"גרינברג, דוד מקוברין","f":"שמואל גרינברג","k":"בעל סוגה בשושנים","bt":"תרי","b":"רב בפיעסק-מחוז ולקוביסק-תרנה, קוברין(=קאברין)-פלך גרודנא-תרסו. חיבר \"סוגה בשושנים\", שו\"ת - בכת\"י. בנו - ר שלמה-חתן ר אשר ליב בארון מארה\"ב. חתנו - ר יהושע בנימין מפיעסק."},{"i":12494,"n":"גרינברג, זלמן","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":12495,"n":"גרינברג, חיים חייקל","dt":"תשל - כג חשון","b":"דיין בקעניא,עלה לא\"י,רב בתל אביב"},{"i":12496,"n":"גרינברג, חיים מגלינא","f":"יצחק אליעזר","k":"אדמור מגלינא-למברג","bt":"תרלב","b":"מחכמי גלינא, התישב בלמברג כאדמור מגלינא. נספה בשואה. בנו אורי צבי גרינברג."},{"i":12497,"n":"גרינברג, חיים מיכל מניו יורק","k":"בעל אור החיים","b":"מחכמי ניו יורק. חיבר \"אור החיים\" ניו יורק תרעז."},{"i":12498,"n":"גרינברג, חיים מלמברג","f":"יצחק אליעזר מגלינא","k":"אדמור מגלינא-למברג","dt":"תשב","b":"נכד ר יחיאל מיכל מגלינא בעל \"קב ונקי\". חתן ר נחום מבילקמין (סטרליסק). אדמור בלמברג. נספה בשואה."},{"i":12499,"n":"גרינברג, יהושע (רענן)","bp":"טרישקי-ליטא","dt":"1944","dp":"דכאו","b":"מחנך וסופר. קרוב משפחתו של ר ישראל סלנטר, למד ב\"קיבוץ\" של ר יצחק יעקב רבינוביץ בפוניבז. מורה לספרות עברית בגימנסיות בפוניבז, ראסיין, שאוולי. פרסם מאמרים בעתוני המקום ובהם \"אידישע שטימע\", \"הד ליטא\", ועוד. נספה בשואה."},{"i":12500,"n":"גרינברג, יוסף מפרשבורג","dt":"תשד","b":"מלמד בביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה. נספה בשואה."},{"i":12501,"n":"גרינברג, יחיאל יעקב","b":"ר\"מ בביהמ\"ד לרבנים בברלין. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח."},{"i":12502,"n":"גרינברג, יעקב","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":12503,"n":"גרינברג, יעקב חיים מהורודעץ","f":"מרדכי","bt":"תרך","b":"נכד ר נתן מאנטיפליא. ונכד-אבי אמו ר חיים חומסקר. תלמיד ר פנחס מיכאל אנטיפאליע. חתן נכדת ר יהושע זליג מהורודץ(=האראדעץ)-פלך גרודנא, רב בהורודץ-פלך גרודנא-תרסג על מקום חותנו זקנו."},{"i":12504,"n":"גרינברג, יעקב ממייטשאט","dt":"תשג","b":"רב במייטשאט. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":12505,"n":"גרינברג, יעקב משיקגו","k":"בעל פרשת המועדים","b":"רב בשיקגו-תרפט. ?? לא באוצר ??"},{"i":12506,"n":"גרינברג, יצחק איזיק מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":12507,"n":"גרינברג, יצחק אליעזר מגלינא","k":"אדמור מגלינא","dt":"תרעא","b":"הגיע מיאסי לכהן כרב בגלינא-תרסד. חתן ר יחיאל מיכל מושקוביץ (חתנו של ר מאיר מפרמישלן). בנו ר חיים היה אדמור גלינא בלמברג."},{"i":12508,"n":"גרינברג, ישראל פנחס מגורשקוב","b":"פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":12509,"n":"גרינברג, מאיר אשר מקוזמיר","b":"חתן ר יעקב יוסף הורביץ מולאדובקי. רב מטעם בקוזמיר(=נאוי-אלכסנדר)-פלך לובלין-תרע."},{"i":12510,"n":"גרינברג, מאיר מקעזמרק ונ\"י","f":"שמחה נתן מקעזמרק","b":"תלמיד הדעת סופר. רב בליפטא-סנט מיקלוש-תרצז. ניצל מהשואה ואחריה רב בקעזמרק על מקום אביו. עבר לאמריקה וכיהן כרב בניו יורק. פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":12511,"n":"גרינברג, מנחם מנדל מוילאהן","f":"חיים צבי","bt":"תרכא","b":"רב בייאדאווע-פלך וארשא-תרן, ווילאהן-פלך קאליש."},{"i":12512,"n":"גרינברג, מרדכי מנדל מזארמין","b":"רב בזרמין. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":12513,"n":"גרינברג, נחום","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":12514,"n":"גרינברג, נחמן","dt":"תרלה","b":"נכד ר משה שהם מדולינא. בא מדולינא לכהן כרב במיידאן-מרמורוש - תרל, רב בוולאווא, חתן בנו ר מרדכי ימפל על מקומו אחריו."},{"i":12515,"n":"גרינברג, פנחס מרוזניאטוב","b":"רב ברוזניאטוב, אטיניא-תרכב."},{"i":12516,"n":"גרינברג, שלום מהוסיאטין","f":"יעקב","bt":"תרלו","bp":"הוסיאטין","dt":"תרצח","b":"חתן הגביר ר יעקב קופל מגריידינג ועבר לשם. תלמיד ר מאיר ארק בבוצאץ. רב בוינר-נוישטט (ליד וינה), התישב בקשנוב כמלמד. משרידי כתביו - שרובם אבדו - נדפס \"בית יעקב מחצית השקל\" ניו יורק תשיט."},{"i":12517,"n":"גרינברג, שלמה ירמיה מאוסטרלנקה","b":"מו\"צ באוסטרלנקה."},{"i":12518,"n":"גרינברג, שמואל","b":"רב-שנת תר\"ך"},{"i":12519,"n":"גרינברג, שמואל מטשאנד","f":"יצחק מנחם","bt":"תרעה","bp":"מאקאווע","dt":"תשד","b":"תלמיד ר מרדכי וינקלר בעל \"לבושי מרדכי\". חתן ר מרדכי בריסק מטשאנד. דיין בטשאנד-תרצד. הו\"ל ספר חותנו - שו\"ת מהר\"ם בריסק עם הגהות ממנו. נספה בשואה."},{"i":12520,"n":"גרינברג, שמחה נתן מקעזמרק","f":"אברהם מקעזמרק","bt":"תרמד (תרלו)","bp":"קעזמרק","dt":"תשה - ה תשרי","dp":"קראקא","b":"תלמיד השב\"ס, ור בנציון ועזעל מטארדא, ור משה הרש פוקס בגרוסורדין, ועוד. חתן ר שרגא פיבל הרטמן מברגסאס ועבר לשם-תרעג ולימד תורה. רב בטאלדיעש(=טולג'ש)-תרעד. קעזמארק-תרעט לצד אביו ועל מקומו אחריו-תרף. נספה בשואה. נזכר בספרי חכמי דורו. בנו ר מאיר רב בקעזמארק-ברוקלין."},{"i":12521,"n":"גרינברג, שמעון ישראל מסמרגון","b":"תלמיד ר אריה ליב שפירא מקובנא, היגר לבירמינגהם.והתעשר, בעל צדקה."},{"i":12522,"n":"גרינברג-גרינפלד, יעקב מגווזדיץ","b":"מחכמי גוואזדיץ-תרלא, טרנירודה-תרסג. חתן הרב משאץ."},{"i":12523,"n":"גרינברגר, אברהם יצחק הלוי","bp":"סאלאש","b":"תלמיד ר שמואל דוד יונגרייז. מחכמי מאדע, קראלי. נזכר ב\"בית שערים\", \"לבושי מרדכי\". מתורתו ב\"וילקט יוסף\"."},{"i":12524,"n":"גרינברגר, אברהם מצעלדמעלעק","f":"מרדכי","bp":"פאי (אפאלי)","dt":"תשב - כה כסלו","dp":"צעלדמעלק","b":"תלמיד השב\"ס, ור שמעון פולק מבעלניעש. חתן ר אברהם פרגר מטאפלטשן. רב בשארישאפ-תרסה, ממיסדי הקהלה החרדית בצעלדמלק(=צל-דומוק) ורב שם-תרסח. בזיוו\"ש חתן ר יצחק שוורץ מהאלאש. פוסק מפורסם בעניני כשרות. מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד, \"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":12525,"n":"גרינברגר, אהרן ממיהאלביץ","f":"שמחה","k":"בעל דעת סופר","bt":"תקעא","bp":"וואג-ביסטריץ","dt":"תרנג - יח תשרי","dp":"מיהאלביץ","b":"נודע בכינוי \"דער טולצ'בר צדיק\". תלמיד החת\"ס. חתן ר אליעהו טלר מקומוראן, ועבר לשם. רב בטאלטשווא-תרז, רבה הראשון של מיהלביץ(=נאג'י-מיהאי=מיכאלובצה) - למעלה מארבעים שנה, בנו ר שמחה חיים - דיין במיהאלביץ. חיבר \"דעת סופר\". פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":12526,"n":"גרינברגר, יצחק מלייפניק","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":12527,"n":"גרינברגר, משה ממיהאלביץ","f":"שמחה חיים גרינברגר","bt":"תרלב","dt":"תרצד - יב תמוז","b":"דומ\"צ במיהאלביץ-תרעד על מקום אביו, וחתנו ר מנחם מנדל בלז על מקומו אחריו כדיין. פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":12528,"n":"גרינברגר, שמחה בונם מפרשבורג","f":"אברהם מצעלדמעלק","dt":"תשלז - כב סיון","dp":"סקווירא","b":"תלמיד הדעת סופר, ור יואל הלוי פלנר באויהל, ור שמואל גוטליב מפאפא. חתן נכדת ר מנחם צבי קרויס מפרשוב, ובזיוו\"ש חתן ר שמואל פרידמן מסערדאוהל. רב בשארוואר, ניצל מהשואה, ואחריה רב בפרשבורג-תשו, רב קהל חתם סופר בניו יורק."},{"i":12529,"n":"גרינברגר, שמחה חיים ממיהאלביץ","f":"אהרן ממיהאלוביץ","bt":"תרי","dt":"תרע-ג - כט טבת","b":"אב\"ד וראש ישיבה במיהאלוביץ על מקום אביו - אך לא רב ראשי, ובנו ר משה על מקומו אחריו. מחותן עם ר נטע לנדא מאושפיצין"},{"i":12530,"n":"גרינברגר, שמחה ממיהאלביץ - נכד","f":"משה ממיהאלביץ","dt":"תשד","b":"רב במיהאלביץ על מקום אביו. נספה בשואה."},{"i":12531,"n":"גרינגורט, נתן מירושלים","bp":"ביאליסטוק","dp":"ירושלים","b":"רב בירושלים, עלה מביאליסטוק"},{"i":12532,"n":"גרינגלוס, חנוך דוד מלענטשא","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט, \"עמק הלכה\" - וארשא תרפו."},{"i":12533,"n":"גרינגרוס, חיים בער מקרמנצוג","dt":"תרפח","b":"רב בקרמנצוג. חתניו - ר שלמה הרכבי, ר אברהם יעקב גורדון, ר ברוך יעקב זמודזאק, דוד הכהן רפפורט בעל 'צמח דוד', ר דוד יעקב אסבל מסימיאטיץ, ר אלכסנדר זושא סולוב מבריסק, ועוד."},{"i":12534,"n":"גרינהוט אלעזר","bt":"1850","dt":"ג'תתקנא 191","bk":[["לקוטים",""],["סעדיה גאון ופי' לדניאל",""],["פירוש",""]]},{"i":12535,"n":"גרינהוט, אברהם ממארוש-ואשארהי","b":"תלמיד ר שלמה זלמן אולמן בעל \"יריעות שלמה\" במאקאווע. רב במארוש-וואשארהי-תרס בערך - כ-40 שנה."},{"i":12536,"n":"גרינהוט, אליעזר מקראקא","b":"תשובה אליו - \"שם עולם\"-תרלב. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":12537,"n":"גרינהוט, אלעזר הלוי","f":"משה יהודה","bt":"תרי","bp":"כפר גרנד-מחוז טורדה","dt":"תרעג - יב אד\"א","dp":"פתח תקוה","b":"תלמיד ר יצחק אהרן לנדסברג בגרוסורדין, ור אהרן פריד בעל \"אומר לציון\". רב בעניעד (בקשטבא)-תרל, דיין בטימישואר-תרמג, מועמד לרבנות בשימאנדא (נזכר באלגעמיינע יידישע צייטונג)-תרן, עבר לברלין ללמוד בביהמ\"ד לרבנים בברלין. עלה לארץ-תרנג. ההדיר ספרי קדמונים עם תוספות והערות - חלקם עם ר שלמה בובר, ובהם מדרש שיר השירים - ירושלים תרנז, ספר הלקוטים, ועוד. פרסם מאמרים ב\"המאסף\" - ירושלים תרנו."},{"i":12538,"n":"גרינהוט, דוד מפפד\"מ - א","f":"ישראל","dt":"תז - טז אלול","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ-תא, בזמן ר שבתי הורביץ-בנו של השל\"ה."},{"i":12539,"n":"גרינהוט, דוד מפפד\"מ - ב","f":"נתן","k":"בעל טוב רואי","dt":"תפג - כב אד\"ב","dp":"פפד\"מ","b":"אמו ממשפחת גינצבורג. חתן ר שמואל זלהויזר. גדול בחכמה ודקדוק, מקובל, רב בויסבדן, הימארדיגן, פפד\"מ-תעב, אידשטין(=אידסטין) וחזר לפפד\"מ - רב ביהמ\"ד שיסד ר דוד אופנהיים מפרג בפפד\"מ. חיבר גם \"מגדול דוד\", פירוש ל\"פרק שירה\", ועוד. רצה להוציא ספר קבלה של ר חיים ויטאל עם הערות ר מאיר איזנשטט - אך נאסר עליו להפיץ את ספרו בפפד\"מ."},{"i":12540,"n":"גרינהוט, חיים וולף מפרשבורג","b":"מייסד ביה\"ס \"יסודי התורה\" בפרשבורג-תרמה."},{"i":12541,"n":"גרינהוט, נתן מפפד\"מ","b":"מגדולי חכמי פרנקפורט-ת\"ל"},{"i":12542,"n":"גרינהויז, אהרן זליג","b":"בנו או חתנו של ר אברהם יוסף מאוסויעט. בניו - ר נחום מטרוקי, ר אברהם יוסף לוריא מקריסלאוויא."},{"i":12543,"n":"גרינהויז, דובער מהליבקא וחברון","b":"רב בהלובקה,ולהינוב,עלה לחברון"},{"i":12544,"n":"גרינהויז, זלמן ממוסקבה","f":"דובער מהליבקא","b":"מו\"צ במוסקבה. נכדו - ר דובער גורדון מזיטקוביץ."},{"i":12545,"n":"גרינהויז, נחום מסלובודקא וטרוק","f":"אהרן זליג","bt":"תרכו","bp":"וילנא","dt":"תרסז","dp":"טרוקי","b":"נכד ר אברהם יוסף מאוסויעט. חתן ר שלמה הכהן מוילנא בעל \"בנין שלמה\" שהביא ממנו בספרו. רב בטרוקי-פלך וילנא-תרמח. נמנה על חובבי ציון ומראשי ה\"מזרחי\" לצדו של הרב ריינס. פרסם מאמרים בענין ישוב ארץ ישראל, לאחר יסוד הגמנסיה ביפו התאכזב מן הציונות ופרסם מאמר \"טעות לעולם חוזרת\". חיבר חדושי תורה בכת\"י - ואבד. חתנו - ר יצחק סגל מסקולקא-ליטא. נכדו - ר שלמה שוסטר מארה\"ב. אחיו - ר אברהם יוסף לוריא מקריסלאוויא(=קראסלאוויא)."},{"i":12546,"n":"גרינוואלד משה בן עמרם","bt":"1853","dt":"ה'תרע 1910","bk":[["הכנה דרבה",""],["הלל נרצה",""],["הנהגות ישרות",""],["מקוה טהרה",""],["עולת תמיד",""]]},{"i":12547,"n":"גרינוולד, אביגדור מסיגט","f":"יעקב מסיגט","k":"בעל כתר תורה","bp":"סיגט","dt":"תשא - כב כסלו","b":"תלמיד ר יהודה גרינוולד בסטמר. מגיד מישרים ורב ביהמ\"ד בסיגט על מקום אביו."},{"i":12548,"n":"גרינוולד, אברהם אבא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":12549,"n":"גרינוולד, אברהם בצלאל מלאואלאק","f":"יעקב יחיאל יחזקאל ג'","bt":"תרכח","b":"חתן ר אליהו פרנקל מלאואלאק בעל \"אבני אליהו\". רב בלעוועלעק-תרעד על מקום חותנו."},{"i":12550,"n":"גרינוולד, אברהם יוסף מחוסט","f":"משה-ערוגת הבשם","bt":"תרלח","dt":"תרפח - טו טבת","b":"רב במאקעווע(=מאקובה)-תרסו, חוסט-תרע על מקום אביו, אונגוואר-תרפ. הניח חדושים בכת\"י. פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה, \"שערי אורה\" - מיהאלביץ תרץ-תרצד. בנו - ר יהושע."},{"i":12551,"n":"גרינוולד, אליעזר דוד מסטמר","f":"עמרם","k":"בעל קרן לדוד","bt":"תרכז","bp":"טשארנא","dt":"תרפח - א סיון","dp":"סטמר","b":"נכד ר יוסף גרינוולד מטשעטשאוויץ. תלמיד אחיו בעל \"ערוגת הבשם\", וישיבת ה\"חתן סופר\" במטרסדורף. חתן ר יעקב רפפורט מברדיוב ועבר לשם וכיהן כר\"מ בישיבה. ר\"מ בישיבה בחוסט-תרנה אצל אחיו, דיין בדונא-סערדאהאלי(=סערדאוהל)-תרנז, רב וראש ישיבה בצעהלים-הונגריה-תרסז על מקום ר דוד פרידמן ואחיינו ר יעקב יחזקיהו גרינוולד על מקומו אחריו, רב וראש ישיבה באויבר-ווישווה - מאמארוש-תרעב, רב בסטמר-תרפא וראש הישיבה שם - הגדולה ביותר בטרנסילבניה. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב.","bk":[["קרן לדוד [שו\"ת",""],["עה\"ת ומועדים",""],["על הגדש\"פ]",""],["חסדי דוד – הגדה של פסח",""],["מזמור לדוד – תהלים",""],["קרן לדוד – שו\"ת ועה\"ת ודרוש",""],["קרן לדוד",""],["קרן לדוד – שו\"ת ועה\"ת ודרוש, חסדי דוד – הגדה של פסח , מזמור לדוד – תהלים",""]]},{"i":12552,"n":"גרינוולד, אשר אנשיל מאונגואר","k":"בעל מטה אשר","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה, \"הפוסק\" - תל אביב תש-תשיד."},{"i":12553,"n":"גרינוולד, דוד מאונגואר","b":"רב באונגוואר-ת\"ר"},{"i":12554,"n":"גרינוולד, דוד מירושלים","f":"מנחם גרשון גרינולד","dt":"תשה","b":"רב בירושלים. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":12555,"n":"גרינוולד, זאב וולף מלימנוב","b":"חתן ר\"ש אנגל. ר\"מ \"כתר תורה\" בפיעטרקוב ובלימנוב. פרסם מאמרים ב\"הלבנון\" - גורליץ תרפח."},{"i":12556,"n":"גרינוולד, חזקיה מחוסט","dt":"תשד","b":"מרבני חוסט"},{"i":12557,"n":"גרינוולד, יהודה מואיא","f":"חיים מניר-מאדע","k":"בעל יבא חיים","bt":"תרטו או תריז","bp":"ניר-מאדע","dt":"תרצא - ג סיון","b":"תלמיד השב\"ס, ור זכריה שפירא מוראנוב, ור שמואל ארנפלד ממטרסדורף. מחכמי מאזשאני-תרמז. רב בואיא-תרנא כ-40 שנה וראש הישיבה."},{"i":12558,"n":"גרינוולד, יהודה מלוצרן","f":"מנחם משופרון","bp":"פרשבורג","dt":"תשז - ו תשרי","b":"תלמיד השב\"ס. חתן ר נתן רוטשילד מלוצרן. רב בשופרון, קעזמארק, פוטנאק, לוצרן-תרעג. בנו - ר דוד - רב בצ'ילה, דנבר בעל \"אנשי חיל\"."},{"i":12559,"n":"גרינוולד, יהודה מסטמר","f":"עמרם","b":"אחיו של בעל \"קרן לדוד\"."},{"i":12560,"n":"גרינוולד, יהודה מסטמר","f":"יהושע פאלק מברעזאווא","k":"בעל זכרון יהודה","r":"אב\"ד סטמר","bt":"תרה","bp":"ברעזאווא","dt":"תרפ - יט אדר","dp":"סטמר","b":"תלמיד הכת\"ס, ר אהרן דוד דייטש בעל \"גורן דוד\" בג'ארמאט, ר דוד פישר מפישטיאן, ר דוד שיק בעל \"אמרי דוד\". חתן הגביר ר יוסף יוזפא סופר משיראביץ - בנו של החת\"ס ואחיו של הכת\"ס. רב בשיראביץ, סאבאיטש-תרמב, בניהאד-תרמט, שוראן-תרנו, רב וראש ישיבה בסטמר-תרנח - והיה שם מחלוקת כאשר חלק מחברי הקהלה פרשו בגלל בחירת רב \"קיצוני\" ו\"מתנהג בחסידות\" והקימו קהלת סטאטוסקוו. הישיבה בסטמר היתה מהגדולות בהונגריה. חיבר \"זכרון יהודה\", \"שבט מיהודה\" ועוד.","bk":[["זכרון יהודה – שו\"ת",""],["חסדי אבות – אבות",""],["עוללות יהודה - תהילים",""],["שבט מיהודה – עה\"ת",""],["שבט מיהודה – עה\"ת , עוללות יהודה - תהילים, זכרון יהודה – שו\"ת , חסדי אבות – אבות",""]]},{"i":12561,"n":"גרינוולד, יהושע מחוסט","f":"אברהם יוסף מחוסט","k":"בעל חסד יהושע","bt":"תרסט","bp":"חוסט","dt":"תשכט - ו אב","dp":"ניו יורק - ירושלים","b":"נכד בעל \"ערוגת הבשם\". חתן ר יחזקאל פאנט מדעש, ועבר לשם. סייע לגיסו האדמור יעקב אלימלך פאנט בניהול הישיבה, רב באונגוואר-תרפט, חוסט על מקום ר יוסף צבי דושינסקי שעלה לירושלים. ניצל מהשואה, ואחריה עבר לניו יורק וכיהן כרב קהל יראים דחוסט. פרסם מאמרים ב\"עמוד התורה\" - דעש תרצב.","bk":[["חסד יהושע – שו\"ת וחי'",""]]},{"i":12562,"n":"גרינוולד, יהושע מניו יורק","f":"מנחם משופרון","dt":"תשל - כג תשרי","dp":"ניו יורק","b":"תלמיד הדעת סופר, ור שלמה זלמן ברייער מפפדמ. רב במעראנא (איטליה), ניו יורק."},{"i":12563,"n":"גרינוולד, יוסף מיאנוש-האזא","bt":"תקסה - בערך","dt":"תרל - יט אדר","b":"רב ביאנוש-האזא-תקצא, ור אברהם וייס על מקומו אחריו. טולטשווא, טשעטשעוויץ. חתן ר משה נחום רוזנבוים מואשאן. נכדו - ר משה בעל ערוגת הבושם."},{"i":12564,"n":"גרינוולד, יוסף מפאפא","f":"יעקב יחזקיה-ויגד יעק","k":"בעל ויחי יוסף","r":"הרב האדמו\"ר וראש הישיבה בפאפא ואח\"כ בארצות הברית בקהילת פאפא","bt":"תרסג-ה","bp":"ברזוביץ","dt":"תשמד - יג אב","dp":"ניו יורק","b":"חסיד בלז. נכד ר משה מחוסט בעל \"ערוגת הבשם\". תלמיד דודו זקנו וחתנו (נשא את בתו המאומצת) ר אליעזר דוד גרינוולד (ולפי אלפסי חתן דודו זקנו ר יעקב יחזקיה מחוסט). דיין וראש ישיבת \"קרן לדוד\" בסטמר. רב הקהילה החסידית בפאפא על מקום אביו וראש הישיבה - החסידית. גם בהיותו במחנה עבודה עם תלמידיו המשיך ללמד תורה. ניצל מהשואה-איבד את כל משפחתו, ואחריה הקים מחדש את הישיבה בפאפא, עבר לסומבוטהי, עזב עם תלמידיו לאנטורפן-תשז, רב וראש ישיבה בניו יורק-תשיא - וישיבתו היתה מחשובי הישיבות באמריקה, ואדמור-תשיז אחר פטירת רבו האדמור מבלז, ובנו ר יעקב יחזקיה על מקומו אחריו. הו\"ל חיבורי בעל \"קרן לדוד\". חיבר \"ויחי יוסף\", \"קנה בושם\", ועוד. קרובו של ר מאיר גרינוולד מטעטש ואח\"כ בטורונטו. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד.","bk":[["ויחי יוסף",""],["ויען יוסף",""]]},{"i":12565,"n":"גרינוולד, יוסף צבי","f":"יהושע פאלק","b":"אחיו התאום של ר יהודה גרינולד מסטמר. חתנו - ר אברהם חנוך פרידמן מסטמר."},{"i":12566,"n":"גרינוולד, יעקב יחזקיה מסערדנא","f":"יוסף מטשעטשאוויץ","bt":"תקצג","dt":"תרכט - כה תמוז","b":"תלמיד הכת\"ס. חתן ר מנחם אדלר מבאדאנש. רב בסערעדנא."},{"i":12567,"n":"גרינוולד, יעקב יחזקיה מפאפא","f":"משה-ערוגת הבשם","k":"בעל ויגד יעקב","bt":"תרמב","bp":"טשארנא","dt":"תשא - ב אדר","dp":"פאפא","b":"חתן דודו ר ישראל מנחם ברוין מברזוביץ. רב בליקוב-תרסט, צעהלים על מקום דודו ר אליעזר דוד גרינוולד, באנפי-הוניאד ומנהל הישיבה שם, רב הקהילה החסידית שפרשה מהקהילה בפאפא-תרפט וראש ישיבה שם, ובנו ר יוסף על מקומו אחריו. חיבר גם \"צדקה לדרך\", \"אגודת אזוב\" ובנו ר יוסף הוסיף לו \"קלח של אזוב\".","bk":[["אגודת אזוב – הגדה של פסח",""],["ויגד יעקב",""],["משפטיך ליעקב [שו\"ת] (פאפא)",""],["משפטיך ליעקב – שו\"ת",""],["צדה לדרך",""],["צדה לדרך , ויגד יעקב , משפטיך ליעקב – שו\"ת , אגודת אזוב – הגדה של פסח",""]]},{"i":12568,"n":"גרינוולד, יעקב יחזקיה מפאפא ני","f":"יוסף מפאפא נ\"י","k":"אדמור מפאפא בנ\"י","b":"חתן ר מאיר גרינוולד מטעטש בן ר אברהם יוסף. אדמור מפאפא בניו יורק על מקום אביו."},{"i":12569,"n":"גרינוולד, יעקב מזידיטשוב","f":"אברהם","dt":"תקפג","dp":"בריד (ליד ארשיווע)","b":"רבה הראשון של חוסט-תקעב."},{"i":12570,"n":"גרינוולד, יעקב מחוסט","dt":"תקפב - כח אדר","b":"מו\"צ בחוסט"},{"i":12571,"n":"גרינוולד, יעקב ממוהאץ","b":"רב הקהילה הניאולוגית במוהאץ-מחוז בורוניא ודד\"ר ארמין פלאש על מקומו אחריו, מנהל ביה\"ס במקום."},{"i":12572,"n":"גרינוולד, יעקב מנצנענוויטש","f":"יוסף מנאצנענוויטש","k":"בעל בית יעקב","bt":"תר","bp":"נאצנענוויטש","dt":"תרסט - א אדר","b":"תלמיד הכת\"ס, ור אהרן גרינברגר ממיהאלוויץ. חתן ר מנחם א\"ש מאונגוואר. ובזיוו\"ש חתן ר מנחם אדלר מבאדאנאש. מחכמי נאצנעוויטש. בנו ר מאיר מנאצנעוויטש מו\"ל ספר אביו, ונכדו ר אשר מאונגוואר בעל \"קיצור נחלת שבעה\"."},{"i":12573,"n":"גרינוולד, יעקב מסיגט","f":"נפתלי מנאדי באניא","k":"בעל חלק יעקב","bt":"תרי-טו","bp":"חוסט","dt":"תרפח - טו שבט","dp":"סיגט","b":"תלמיד הכת\"ס, ומהרם שיק, ור מרדכי הורביץ משימלויא, ור יקותיאל יהודה טיטלבוים מסיגט. חתן ר אפרים רוזנברג מסיגט ועבר לשם. מגיד מישרים בסיגט ובעל בית מסחר לספרי קדש. בנו ר יקותיאל יהודה בעל \"זכרון לראשונים - לתולדות רבני סיגט. פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח."},{"i":12574,"n":"גרינוולד, יצחק לוי מאורשווא","f":"משה גרינוולד","b":"רב באורשווא-תר\"צ"},{"i":12575,"n":"גרינוולד, יקותיאל יהודה מארה\"ב","f":"יעקב מסיגט","k":"בעל זכרון לראשונים","bt":"תרמט","bp":"סיגט","dt":"תשטו - יט ניסן","b":"תלמיד הדעת סופר ועוד. חתן ר צבי הרש הורביץ מהרמאנשטט. עבר לבודפשט. רב הקהלה החרדית בקולומובוס אוהיו. חיבר ספרים לתולדות הקהלות והרבנים בהונגריה ובהם \"פארי חכמי מדינתנו\" - לקורות רבני הונגריה, קורות עיר פרשבורג, חיבר גם \"אח לצרה\" סט לואיס תרצט, \"זכרון לראשונים\" - לתולדות רבני סיגט, \"לפלגות ישראל בהונגריה\" - על הפילוג עם הניאולוגים. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח. הו\"ל \"אוצר נחמד\" - קולומבוס-אוהיו תשב, \"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר, \"היכל התורה\" - נ\"י תרצג, \"הכוכב\" - מונקטש-נ\"י תרצה, \"הלבנון\" - סטמר תרפח, \"הפוסק\" - תל אביב תש-תשיד, \"שערי ציון\" - ירושלים תרפא."},{"i":12576,"n":"גרינוולד, יקותיאל יהודה מיארע","f":"משה-ערוגת הבושם","k":"בעל זכרון אב צוואה","dt":"תרצד - כד טבת","b":"חתן ר יעקב מאיר הכהן פריד מקאפיש. רב ביארע-תרעא. הו\"ל ספרי אביו, ונזכר בהם. בניו - ר שמואל-חתן בעל לחם שלמה, ר משה מראקש-פאלאטא, ר עמרם צבי מוישעווע, חתניו - ר יושע רוזנברג משאפראן."},{"i":12577,"n":"גרינוולד, ישראל מאיר","f":"משה-ערוגת הבושם","b":"תשובה אליו ב\"ערוגת הבושם\"."},{"i":12578,"n":"גרינוולד, ישראל מנחם מברזוביץ","f":"ראה: ברוין, ישראל מנ"},{"i":12579,"n":"גרינוולד, ישראל מנחם מפאפא נ\"י","f":"יוסף מפאפא נ\"י","k":"אדמור מפאפא בנ\"י","b":"אדמור מפאפא בניו יורק."},{"i":12580,"n":"גרינוולד, לוי יצחק מצעהלים וני","f":"משה-ערוגת הבשם","k":"בעל מגדלות מרקחים","dt":"תשם","b":"חתן ר אברהם יוסף גרינוולד מאונגוואר. רב בצעהלים וראש ישיבה, עם כניסת הנאצים לאוסטריה-1938 (העיר היתה שייכת לאוסטריה) עבר לניו יורק ורכש משק חקלאי כדי לייצר חלב כשר, והקים איטליזים כשרים בהשגחתו, הקים ישיבה בשם \"ערוגת הבושם\". סגן נשיא התאחדות הרבנים באמריקה, ובנו ר יוסף משה על מקומו אחריו כאב\"ד בנ\"י."},{"i":12581,"n":"גרינוולד, מנחם גרשון מבאדראג","f":"דוד","k":"בעל מרגליות טובה","r":"רב בקעמטשע וקרערסטיר","bt":"תקעח-פ","bp":"אונגוואר","dt":"תרל-א - כב תשרי","dp":"באדראג-קרסטור","b":"תלמיד החת\"ס, ור מאיר א\"ש מאונגוואר. חתן ר יוסף צבי וינשטוק ממיהלביץ, ובזיוו\"ש חתן ר יחיאל שרא שטארק מיאנווע. שו\"ב בקעמעטשע ורבה הראשון של הקהלה. רב בבדראג-קרסטור(=קרעסטיר)-תרך. היה ש\"ץ בימים נוראים אצל ר מאיר מפרימישלן.","bk":[["מרגליות טובה – תורה וש\"ס",""]]},{"i":12582,"n":"גרינוולד, מנחם מאדנבורג","bt":"תרי","dt":"תרצא","b":"רב בעדנבורג-הונגריה-תרמה. פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח, \"תל תלפיות\", \"וילקט יוסף\"."},{"i":12583,"n":"גרינוולד, מנחם משופרון","f":"פנחס מצעצע","bt":"תרד","bp":"צעצע","dt":"תרץ - כה תשרי","dp":"שופרון","b":"תלמיד הכת\"ס, ור יונה אריה ליכטר מצעצע. חתן ר דוד ניימן מפרשבורג ועבר לשם-תרל. רב בשופרון. בזיוו\"ש חתן ר יצחק קראמר מנייהייזל (גיסו של חותנו הראשון). חתנו - ר כתריאל בלום מטבריה."},{"i":12584,"n":"גרינוולד, משה מאונגוואר","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":12585,"n":"גרינוולד, משה מהומאנא","dt":"תשד","b":"רב בהומאנא"},{"i":12586,"n":"גרינוולד, משה מוארנוב","dt":"תשד","b":"רב בוארנוב."},{"i":12587,"n":"גרינוולד, משה מחוסט","f":"עמרם מטשארנא","k":"בעל ערוגת הבושם","r":"רב בהומנא, קליינווארדיין, ובסוף ימיו בחוסט","bt":"תריג","bp":"טשארנא","dt":"תרע - ז אב","dp":"חוסט","b":"תלמיד הכת\"ס, וזקנו ר יוסף גרינולד מטשרנוביץ, ור מנחם פרוסטיץ מצעלים. חתן ר אברהם גשטטנר משארקאני. רב בטשארנא-תרל, הומנא-תרמג, קלינורדין-תרמז וראש ישיבה ובגלל הלשנה נאסר עליו להחזיק ישיבה במשך כמה שנים, חוסט-תרנג ובנו ר אברהם יוסף על מקומו אחריו. עוד מבניו - ר ישראל מאיר, ר יעקב חזקיה, ר לוי יצחק.","bk":[["הכנה דרבה - צוואה",""],["הלל נרצה - הגדה של פסח",""],["ערוגת הבושם - שו\"ת ועה\"ת",""],["מקוה טהרה – מקוואות",""],["ערוגת הבושם",""]],"e":"תרי\"ג-תר\"ע","rb":"חוסט"},{"i":12588,"n":"גרינוולד, משה מראקוש פלאטא","f":"יקותיאל יהודה מיארע","dt":"תשד","b":"דומ\"צ בראקוש-פאלאטא"},{"i":12589,"n":"גרינוולד, נחום מטשארנא","f":"עמרם מטשארנא","b":"מחכמי טשארנא. חתנו - ר שמעון הכהן שטרסר מפרשבורג."},{"i":12590,"n":"גרינוולד, עמרם מטשארנא","f":"יוסף מיאנושהאזא","bt":"תקצא","bp":"יאנושהאזא","dt":"תרל - כח ניסן","dp":"פאראד","b":"תלמיד הכת\"ס, ור מאיר א\"ש מאונגוואר. חתן ר שלמה גשטטנר מטשארנא ועבר לשם. רב בטשארנא"},{"i":12591,"n":"גרינוולד, עמרם צבי מוישווה","f":"יקותיאל יהודה מיארע","k":"בעל זכרון עמרם צבי","bt":"תרסז","bp":"קאפיש","dt":"תשיא - כא סיון","dp":"ארה\"ב","b":"נכד בעל \"ערוגת הבשם\" ונכד ר יעקב מאיר פריד האדמור מקאפיש, תלמיד דודו ר אברהם יוסף גרינוולד מאונגוואר ואצל דודו זקנו ר אליעזר דוד גרינוולד מסטמר. חתן ר משה שטיינמץ מאויברווישווה. רב ביארע-תרצד על מקום אביו, דיין באויבר-ווישווה. ניצל מהשואה ואחריה רב במחנה פרנוואלד - ליד האדמור מקלויזנבורג. היגר לארה\"ב-תשט. גיסו ר מרדכי יצחק סאמט הו\"ל את ספרו, אחיו ר דוד חיבר הקדמה לספרו - \"זכרון עמרם צבי\" נ\"י תשלג.","bk":[["זכרון עמרם צבי - על התורה והש\"ס",""]]},{"i":12592,"n":"גרינוולד, פיליפ מבודפשט","b":"מלמד בביהמ\"ד לרבנים בבודפשט. מנהל המוזיאון היהודי. חוקר תולדות יהדות הונגריה, ופרסם מאמרים בתחום."},{"i":12593,"n":"גרינוולד, שמואל מסעליש","f":"יקותיאל יהודה מיארע?","dt":"תשד","b":"חתן בעל לחם שלמה משאמלוי?. רב ביארע, דומ\"צ בסעליש. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":12594,"n":"גרינוולד, שמואל משופרון","f":"מנחם משופרון","bt":"תרלו","bp":"שופרון","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר אלעזר מאייר מטרניץ. שו\"ב בהלברשטט, שופרון. נספה בשואה."},{"i":12595,"n":"גרינולד יהודה","bt":"1849","dt":"ה'תרפ 1920","bk":[["זכרון יהודה חלק א",""],["חסדי אבות",""],["ספר תהלים",""],["צוואת (יודא גרינוואלד)",""],["שארית יהודה",""]]},{"i":12596,"n":"גרינולד יהושע בן אברהם יוסף","bt":"1909","dt":"ה'תשכט 1969","bk":[["חסד יהושע",""],["שו\"ת חסד יהושע",""]]},{"i":12597,"n":"גרינמן, דוד","b":"הו\"ל \"השער\" - בני ברק תשח."},{"i":12598,"n":"גרינמן, חיים שאול","b":"רב בבני ברק"},{"i":12599,"n":"גרינמן, שמואל","bt":"תרמט","dt":"תשיז","b":"חתן ר שמריה יוסף קרליץ, וגיסו של החזון איש. הו\"ל את ספרי גיסו. פרסם מאמרים ב\"היהודי\" - נ\"י תרצו, \"כנסת ישראל\" - וילנא תרץ."},{"i":12600,"n":"גרינמן, שמריה","b":"פרסם מאמרים ב\"שמוש חכמים\" - בני ברק תשז."},{"i":12601,"n":"גרינס, אשר מוילטשין","f":"זאב","bt":"תרלז","b":"נכד ר וולף חריף מלוסק. רב בווילצין(=וילטשין)-תרסב"},{"i":12602,"n":"גרינסטון, יוליוס יהודה הלל","f":"פסח דוד","k":"פילדלפיה","bt":"1873","bp":"מאריאמפול","dt":"1955","b":"תלמיד ר יונתן עליאשברג ממאריאמפול, וישיבות ליטא. היגר לארה\"ב, ולמד בקולג' ניו יורק ובסמינר התיאולוגי היהודי. מנהל בקולג' גרץ בפילדלפיה. רב ומטיף בביהכ\"נ \"מקוה ישראל\" בפילדלפיה על מקום ד\"ר מוראייס. פרסם מחקרים רבים בחכמת ישראל. ומעורכי האנציקלופדיה העברית באנגלית."},{"i":12603,"n":"גרינספלד, אברהם הלוי מפרשבורג","b":"מזכיר קהלת פרשבורג-תרלג-תרצב. בנו ר אברהם."},{"i":12604,"n":"גרינספלד, בנימין זאב מפרשבורג","f":"שלמה אריה מסערדאוהל","b":"נכד ר שלמה אריה גרינספלד מסערדאוהל. חתן ר פרץ זאבל סגל לעווי מפרשבורג."},{"i":12605,"n":"גרינספלד, זלמן ליב מסערד-אהעלי","dt":"תקעו - יט חשון","dp":"סערדאוהל","b":"חתן ר וולף טעבן מפרשבורג, ואחיינו של ר קופל - מנהיג המדינה. רב בסערדאהעלי, קיצע."},{"i":12606,"n":"גרינספלד, יוסף מפרשבורג","k":"בעל פרעסבורגער געטטא","b":"כיהן כרב צבאי בצבא האוסטרי בזמן מלחה\"ע ה-I, וסייע בארגון ההגנה בפרשבורג - בזמן הפרעות בסיומה. אסף חומר מקורות קהלת פרשבורג וחיבר \"פרעסבורגר געטטאבילדער - פרשבורג תרצב."},{"i":12607,"n":"גרינפלד יהודה בן שמעיה","bt":"1837","dt":"ה'תרסז 1907","bk":[["קול יהודא",""]]},{"i":12608,"n":"גרינפלד, אברהם אבא מזאגרוב","bt":"תקפא","dt":"תרמו","b":"אב\"ד זאגראוו(=זאגרוב). נזכר בשו\"ת \"נפש חיה\"."},{"i":12609,"n":"גרינפלד, אהרן מויטקא","b":"רב בוויטקא. שאלה ממנו לר שמואל דוד יונגרייז."},{"i":12610,"n":"גרינפלד, אליעזר","f":"משה יהודה ליב מרימאס","b":"תלמיד ר ישעיה בייערן משארש-פוטוק. אחיו של ר אפרים מרימאסעטש. רשם בכת\"י חדושי רבו ואחיו."},{"i":12611,"n":"גרינפלד, אפרים בנימין מרימאסטש","f":"משה יהודה ליב מרימסש","bt":"תרכד","bp":"פוטנאק","dt":"תשד","dp":"אושוויץ","b":"תלמיד השב\"ס, ור משה סופר מטיסא-פירעד. חתן ר שמעון לפלר מבודפשט ועבר לשם. רב בבודפשט. בזיוו\"ש חתן ר חיים יצחק שוורץ מנעמעש-אטשא. רב ברימאסעטש-תרע על מקום אביו. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":12612,"n":"גרינפלד, ברוך מהונגריה וירושלי","f":"שאול יחזקאל","k":"בעל אהל ברוך","bt":"תרלב","bp":"מיהאלוויץ (=מיכאלוצבה)","dt":"תשטז - יא אייר","dp":"ירושלים","b":"תלמיד בישיבת בעל \"ערוגת הבשם\" בקלינורדין. חברו של ר אליעזר דוד גרינוולד. חתן ר שלמה יוסף וינברגר מסטרופקוב. שו\"ב בשעבעש-תרנד, פוטנאק-תרנח, שו\"ב בהרמאנשטדט-תרסה. היגר לארה\"ב-תרפה, וכיהן כרב בניו יורק, עלה לירושלים-תרצה והתישב בבתי הונגרים. ?? לא באוצר ??"},{"i":12613,"n":"גרינפלד, זלמן ליב מסערד-אהעלי","dt":"תשד","b":"רב בסרדאהעלי"},{"i":12614,"n":"גרינפלד, חיים מלבוב","f":"צבי הירש מלכ'ס","k":"בעל שנות חיים","bt":"תקנח","dt":"תרל","b":"צדיק מחכמי למברג. חיבר \"שנות חיים\" למברג (בשער אוסטרהא) תריא."},{"i":12615,"n":"גרינפלד, חנניה יו\"ט ליפא מעדלי","b":"רב בעדעלין. פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":12616,"n":"גרינפלד, יהודה","b":"תלמיד ישיבת שאפראן. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":12617,"n":"גרינפלד, יהודה מסעמיהלי","k":"בעל זהב שבא","bt":"תקצז","dt":"תרסג-ז - א אדר","b":"תלמיד בעל \"קול אריה\", והדברי חיים מצאנז. עבר אל חותנו בחוסט. רב בסעמיהלי(=סנט מיהאי)-תרמג או תרלג, ובנו ר שמעון על מקומו אחריו. חיבר גם \"קול יהודה\" - נדפס בסוף ספר בנו שו\"ת מהרש\"ג."},{"i":12618,"n":"גרינפלד, יהושע זליג מסנט פעטר","f":"משה יהודה ל' מרימסטש","dt":"תשד - כב סיון","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר שלמה זלמן לוינגר. מחכמי ווארגעדע-תרמח, סנט פעטר ליד בנו ר משה חיים אב\"ד סנט פעטר. נספה בשואה."},{"i":12619,"n":"גרינפלד, יהושע מפרשבורג","dt":"תרלב - כ כסלו","dp":"פרשבורג","b":"תלמיד הכת\"ס, חתן רבו ר ישכר דב בר דייטש ממילכדורף. מחכמי פרשבורג-תרי. הו\"ל \"שפתי רננות\" לרבו-חותנו."},{"i":12620,"n":"גרינפלד, יעקב יהושע ממיהאלביץ","b":"עורך \"קהילת יעקב\" - זבורוב-סלובקיה תרפה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":12621,"n":"גרינפלד, יעקב מגיסינג","f":"אברהם חיים","bt":"תרכו","b":"תלמיד ר משה הירש פוקס מגרוסורדין. חתן ר שמואל רוזנבוים מיערגין. רב בגיסינג-תרע. נסמך מאת: ר אברהם יצחק גליק מטולטשוא, ר פנחס קליין מסוליש."},{"i":12622,"n":"גרינפלד, יעקב מטרנירודה","b":"רב בטרנירודה-תרסג."},{"i":12623,"n":"גרינפלד, יצחק","b":"תשובה אליו בשו\"מ."},{"i":12624,"n":"גרינפלד, ישראל יעקב מזעלוב","bt":"תרכט","dt":"תרצא - ד חשון","b":"חריף ובקי,רב באפאטשנא-תרמ\"ד,זעלוב-תרנ\"א"},{"i":12625,"n":"גרינפלד, מ' יהודה ליב מרימאסעט","dt":"תרע - כה אלול","b":"רב ברימאסעטש"},{"i":12626,"n":"גרינפלד, מאיר מהאדאהאז","k":"בעל נר המאיר","bt":"תריג","dt":"תרמא - כא אלול","b":"מו\"צ בהאדהאז"},{"i":12627,"n":"גרינפלד, מאיר מטעטש וקנדה","b":"נכד בעל \"ערוגת הבושם\". חתן ר משה טיטלבוים. רב בטעטש-תרפח. ניצל מהשואה (לאחר שאיבד את משפחתו) ואחריה רב בטורונטו. הו\"ל ספר זקנו \"ערוגת הבושם\" על המשנה."},{"i":12628,"n":"גרינפלד, מיכאל מפאפא","dt":"תריט - ד שבט","dp":"פאפא","b":"תלמיד החת\"ס. דודו של ר מיכאל הופמן מסעראוהל. מחכמי פאפא-תקפט. ניסה להושיב את ר שמעון בעל \"מכתב סופר\" על כס הרבנות בפאפא, וכן פעל לרשיון רשמי לשנות הבימה בביהכ\"נ - כרצון יראי השם."},{"i":12629,"n":"גרינפלד, מרדכי מטאגלש וינה","f":"אברהם","bt":"תרנו","dt":"תשכג - יח אייר","dp":"וינה - ארץ ישראל","b":"עבר אל חותנו בטאגלש(=טעגלאש) ועבד במפעל הקמח של חותנו ויחד עם זאת הקים ישיבה שנקראה - \"ישיבת הטחנה\". ניצל מהשואה ואחריה רב בנירדהאז(=האדהאז), עלה לארץ-תשטז אל בניו שעלו לפניו. רב הקהלה החרדית בוינה-תשיא."},{"i":12630,"n":"גרינפלד, מרדכי ממטרסדורף","b":"רב במטרסדורף-ת\"ע"},{"i":12631,"n":"גרינפלד, משה חיים מסנט-פעטר","f":"יהושע זליג מסנט-פעטר","k":"בעל חיים ברצונו","bt":"תרמח","bp":"וערדעגע","dt":"תשד - כב סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור מנחם מנדל גליק מקעמטשע, ועוד. חתן ר חיים פריד מסנט-פעטר, ועבר לשם. רבה האחרון של סנט-פעטר על מקום חותנו. מחותן עם ר שמשון נייפלד ממישקולץ. נספה בשואה עם משפחתו. ?? לא באוצר ??"},{"i":12632,"n":"גרינפלד, נצח","b":"תשובה אליו בשו\"מ."},{"i":12633,"n":"גרינפלד, שאול יחזקאל מליטשוק","f":"אברהם שלמה מאויהל","k":"בעל מגן שאול","bt":"תקנג","dt":"תרט - יד אדר","dp":"מיהאלביץ","b":"תלמיד החת\"ס וה\"ישמח משה\". חתן ר צבי מזאוואדקא ועבר לאוהל, מחכמי ליטשיק"},{"i":12634,"n":"גרינפלד, שאול כץ מקראקא","f":"יחזקאל","k":"בעל אשכול ענבים","bt":"תקמט","bp":"לונטשיץ","dt":"תרכו","b":"חתן ר אברהם שעבס, וחתן ר בצלאל הלוי. מחכמי קראקא. חיבר \"אשכול ענבים\" וארשא תקצב."},{"i":12635,"n":"גרינפלד, שלמה ממונקטש","f":"יהודה גרינפלד","dt":"תשד","b":"דומ\"צ במונקאטש"},{"i":12636,"n":"גרינפלד, שמעון מסעמיהאלי","f":"יהודה מסעמיהאלי","k":"בעל שות מהרש\"ג","r":"רב בסמיהאלי","bt":"תרכא","dt":"תרצ - יט שבט","b":"תלמיד המהר\"ם שיק בחוסט, בעל \"קול אריה\". מגדולי הפוסקים בדורו, דומ\"צ במונקאטש-תרנה ומלמד בישיבה, רב בסעמיהאלי(=סט מיהאי)-תרסח על מקום אביו. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. שאלה ממנו לר שמואל דוד ינוגרייז.","bk":[["זהב שבא – עה\"ת",""],["שו\"ת מהרש\"ג",""]]},{"i":12637,"n":"גרינצוייג, אשר זליג מדאלהא","dt":"תשד","b":"רב בדאלהא"},{"i":12638,"n":"גרינצוייג, חיים מלאגמץ","dt":"תשד","b":"דומ\"צ בלאגמץ"},{"i":12639,"n":"גרינצוייג, יחיאל מדאלהא","dt":"תשד","b":"רב בדאלהא"},{"i":12640,"n":"גרינצוייג, משה מליפשא","dt":"תשד","b":"רב באיפשא(=ליפשא). תלמיד בעל \"קדושת יו\"ט\" מסיגט. אב\"ד ליפשא. חתן ר יעקב פרנקפורטר האדמור מקאשוי. נספה בשואה?"},{"i":12641,"n":"גרינצוייג, שלום מדאלהא","f":"אשר זליג גרינצויג","dt":"תשד","b":"דומ\"צ-בדאלהא"},{"i":12642,"n":"גרינקר, נחום","dt":"תשג","b":"רב בגאווראן"},{"i":12643,"n":"גרינשטין, אברהם משטרסבורג","b":"מחכמי שטרסבורג-תקלח, רכש יחד עם מאניש וייל מסכת שבועות מר דוד זינצהיים."},{"i":12644,"n":"גרינשטין, אליהו מיארמוט","b":"גביר ביארמוט. פעל להפרדות הקהלה ביארמוט מקהלת טשאנגר יחד עם ר יצחק ישראל בלוי. והלך לבקש מחילה מרבה של טשאנגר - ר אשר יונגרייז בעל מנחת אשר שברכו באריכות ימים (ונפטר בן למעלה מ-100 שנים), פעל למינוי ר משה נתן לרב ביארמוט ואחריו למינוי ר שמואל דוד לרב ביארמוט אל מקומו אחריו."},{"i":12645,"n":"גרינשטין, אליעזר מדולינא","bt":"תרכא","bp":"בוליחוב","b":"רב בדולינא. תשובות אליו בשו\"ת מהרש\"ם."},{"i":12646,"n":"גרינשטין, זאב מבנדין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":12647,"n":"גרינשטין, פיבוש מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":12648,"n":"גרינשטין, צבי","f":"שמעיה ברגלס","dt":"תשמג","b":"תלמיד רז\"ו גרינולד בקראקא, פרסם בכתבי עת שונים. יסד בית דפוס בקשנוב. ניצל מהשואה. עלה לארץ-תשט והתישב בחיפה. אחיו ר שלמה שבתי."},{"i":12649,"n":"גרינשטין, שלמה שבתי","f":"שמעיה ברגלס","bp":"בוקובסק","b":"חסיד בובוב. תלמיד רד\"ב ויידנפלד מטשבין המשיב לו ב\"דובב מישרים\". חתן ר זלמן צבי שויצר מאמסנא. ניצל מהשואה, בזיוו\"ש חתן ר חיים שפירא מקשנוב. עבר לארה\"ב והתגורר בסן פון-מינסוטה וסייע משם בהדפסת \"כוכב מיעקב\" ו\"דובב מישרים\", עבר לניו יורק. עלה לארץ. אחיו ר צבי."},{"i":12650,"n":"גרינשפן, זוסיא מסטאנוב","f":"יוסף","bt":"תרכ","b":"נכד ר נחמן מקונסטנטין-ווהלין. רב בסטאנוב-פודוליה-תריב."},{"i":12651,"n":"גרינשפן, חיים צבי","dt":"תש..","b":"תלמיד רא\"י הורביץ מפרוביזנא. חתן ר יהושע וידרקר מפשמישל. נספה בשואה."},{"i":12652,"n":"גרינשפן, יהודה מדמביץ","f":"יצחק","k":"בעל חיוכה של תורה","bt":"תרסח","bp":"דמביץ","dt":"תשסד","b":"למד בביהמ\"ד לרבנים בברלין. עלה לירושלים-תרצד. מלמד בבי\"ס מעלה בירושלים. פרסם מאמרים בעתונים. בנו ר יצחק שילת - ר\"מ בישיבת מעלה אדומים. חיבר \"חיוכה של תורה\" ירושלים תשנג."},{"i":12653,"n":"גרינשפן, נחמן שלמה מלידס-אנגלי","k":"בעל מלאכת מחשבת","bt":"תרם","bp":"לכוביץ-פלך מינסק","dt":"תשכא - אלול","b":"תלמיד ישיבת וולוזין, הרידב\"ז בסלוצק, ה\"אבני נזר\" בוארשא, עבר לאנטוורפן, ר\"מ בישיבה בלידס-אנגליה-תרפ, ראש ישיבת עץ חיים בלונדון-תרץ. פרסם מאמרים ב\"אור תורה\" - לונדון תרצד, \"הדביר\" - ירושלים תרעט, \"החיים\" - לונדון תש, \"כנסת ישראל\" - וילנא תרץ, \"סיני\" - ירושלים תרצז, \"שערי ציון\" - ירושלים תרפא, \"תל תלפיות\" - וייצען תרנב-תרעד. חיבר גם \"פלפולה של תורה\"."},{"i":12654,"n":"גריס, יוסף יעקב מקראקא","bt":"תרעב","bp":"דומברובה","dt":"תש..","b":"תלמיד בעל ה\"חזון נחום\". חתן ר שמריל שפירא מקראקא ועבר לגור שם. גיסו של ר יהודה מאיר לוין. לימד בישיבת בובוב. נספה בשואה."},{"i":12655,"n":"גריס, יצחק מלמברג","f":"משה מלמברג","b":"חסיד צורטקוב. נספה בשואה. בנו ר יהושע שסייע לגיסו ר נפתלי רוזנקרנץ בהדפסת \"קול מבשר\"."},{"i":12656,"n":"גריס, מרדכי זאב","b":"תלמיד המהרש\"ק שהשיב לו בטוט\"ד."},{"i":12657,"n":"גריפל, בנימין מנדבורנה","b":"גביר חסיד ויזניץ ואטיניא בנדבורנה. מבניו - ר יצחק איזיק חיים המכונה \"הרבי\"."},{"i":12658,"n":"גריפל, יעקב מקראקא","f":"יצחק איזיק חיים","bp":"קראקא","dt":"תשכב","b":"גר בבוריסלוב. ניצל לבדו מהשואה ועלה לארץ ומיד בשליחות בקושטא כנציג אגו\"י במשלחת ועד ההצלה, ובסיועו נצלו רבים מסלובקיה הונגריה ורומניה. עבר לניו יורק."},{"i":12659,"n":"גריפל, שמואל שמלקא","f":"יצחק איזיק חיים","dt":"תשנט","dp":"ירושלים","b":"היה עצור יח שנה ברוסיה. עלה לארץ-תשכד. חידש את חסידות אטיניא והמשיך את עבודת אחיו בהצלת ילדי ישראל."},{"i":12660,"n":"גריש, יצחק מחברון","b":"רב בחברון בזמן גירוש ספרד, שאלה ממנו לרלב\"ח בענין נוסח התפלה - כנראה בעקבות הגעתם של יהודים ממגורשי ספרד לחברון."},{"i":12661,"n":"גרל, י' י'","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":12662,"n":"גרליך, מרדכי מגבוזדזיץ","b":"שו\"ב בגבוזדזיץ, בן אחיו ר ליבוש על מקומו אחריו."},{"i":12663,"n":"גרליק, הלל","b":"רב בקשרנדק"},{"i":12664,"n":"גרמיזאנו, שלום מקושטא","b":"גביר בקושטא, מתומכי ש\"ץ."},{"i":12665,"n":"גרמיזן - משפחה","b":"משפחת בשלוניקי במקורה מורמייזא."},{"i":12666,"n":"גרמיזן, שבתי משלוניקי וירושלים","k":"בעל אמרי קדוש","dt":"תכא - כה חשון","dp":"ירושלים","b":"רב בשלוניקי, ירושלים-ת', אחיו של ר שמואל. חיבר שו\"ת. תשובות ממנו ב\"משפטי צדק\" לאחיו ר שמואל. כמה מתשובות ר שבתי יוחסו בטעות לאחיו."},{"i":12667,"n":"גרמיזן, שמואל משלוניקי וירושלי","k":"בעל משפט צדק","bt":"שס-ה","bp":"שלוניקי","dt":"תכג-תלה - בערך","dp":"ירושלים","b":"תלמיד ר ישראל בנימין. מחכמי שלוניקי, מוצא משפחתו מגרמייזא-אשכנז. עלה לירושלים לפני שנת תו, והיה אב\"ד בירושלים. בשליחות באירופה-תז, ונשאר לכהן כרב במלטה כעשר שנים. בדרכו לארץ ישראל נשבה על ידי שודדים ובהיותו בשבי ניהל את עניני הדת של קהילת השבויים, נפדה על ידי חברת \"פדיון שבויים\" באיטליה, בהשתדלות ר שמואל אבוהב. רב בירושלים-תה, ומחכמי ישיבת ר משה חאגיז. מתלמידיו ר משה ן חביב בעל \"גט פשוט\". אחיו של ר שבתי מחבר שו\"ת. חיבר \"משפטי צדק\" ירושלים תשה, ועוד רבים בכתב יד."},{"i":12668,"n":"גרמייזא, יהודה ליב מוילנא","f":"דב בר","k":"בעל מאיר נתיב","dt":"תריח - כח אלול","dp":"וילנא","b":"יסד בית ספר לנערות ברוסית בוילנא. חיבר גם \"שירי נעימות\"."},{"i":12669,"n":"גרמר, יהודה הלוי אשכנזי","f":"יעקב אשכנזי","bt":"תצב","dt":"תקנב - כ שבט","b":"מצאצאי ר בצלאל אשכנזי בעל \"שיטה מקובצת\", נכד ר מנחם נחום חסיד. הגיע לוילנא עם אחיו מאמו ר שלמה בן נתן מוילקומיר. תלמיד הגר\"א. דיין בוילנא. לימד שיעור במורה נבוכים, ועליו אמר הגר\"א 'אין בידינו למנוע ללמוד מה שחבר הרמב\"ם ז\"ל'. בנו - ר ישעיה."},{"i":12670,"n":"גרמר, יעקב יוסף הלוי מוילנא","f":"משה יהודה","k":"בעל אש להבה - בכת\"י","dt":"תרל - יג שבט","dp":"וילנא","b":"גביר מחכמי וילנא. חיבר \"נחלת יעקב\", והספד על זקנו ר ישעיה בשם \"אש להבה\" - בכת\"י. נפטר בחיי אביו. בניו תרמו את ירושתם - בית ר ישעיה סגי נהור ל\"חברה תורה\" (שנוסד ע\"י זקנם)."},{"i":12671,"n":"גרמר, יצחק הלוי מפריז","f":"ישעיה מוילנא","bp":"וילנא","b":"מצאצאי ר חיים מוולוזין. תלמיד אוני' ברליין ופריז ובעל תואר ד\"ר לרפואה. ישב בפריז ועבד כעתונאי בעתונים מגרמניה."},{"i":12672,"n":"גרמר, ישעיה סגי נהור מוילנא","f":"יהודה מוילנא","bt":"תקלב","dt":"תרח - טו ניסן","dp":"וילנא","b":"מצאצאי ר בצלאל אשכנזי בעל \"שיטה מקובצת\". מגדולי חכמי וילנא, התעוור-תקע, מאז למד תורה בע\"פ. הקדיש כמה בתים בחצר מייליס ל\"חברה תורה\". משה מונטיפיורי התארח אצלו בהיותו בוילנא. בנו - ר משה יהודה. לתולדותיו \"קריה נאמנה\"."},{"i":12673,"n":"גרמר, משה יהודה מוילנא","f":"ישעיה הלוי מוילנא","dt":"תרלא - יד אדר","dp":"וילנא","b":"גביר מחכמי וילנא. בנו ר יעקב יוסף נפטר בחייו."},{"i":12674,"n":"גרנדשטין, דוד מנאויברודנא","b":"פרסם מאמרים ב\"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו."},{"i":12675,"n":"גרנינר, יעקב משה שמואל","f":"סיני","k":"אדמור מאשלג","bt":"תשג","b":"ר\"מ בישיבות רוזין, בלז, חדושי הרי\"ם. אדמור מאשלג-תשנז על מקום גיסו ר שמואל."},{"i":12676,"n":"גרניק, אברהם","dt":"תש","b":"רב בלינסק"},{"i":12677,"n":"גרניק, יהודה אריה ליבוש מלינסק","f":"עקיבא","k":"ר ליביש ר קיוויס","bt":"תקץ","dt":"תרע","b":"ראב\"ד בלינסק כ-57 שנה. זקנו של ר שלמה דריליך."},{"i":12678,"n":"גרנסהיים, מיכאל מורמייזא","b":"פרנס קהלת ורמייזא, בנו - ר פאלק."},{"i":12679,"n":"גרנסהיים, פאלק מורמייזא","f":"מיכאל"},{"i":12680,"n":"גרנר, יצחק מקלויזנבורג","b":"דיין בקלויזנבורג"},{"i":12681,"n":"גרסטל, אריה ליבוש מיריטשוב","f":"זאב וולף","bt":"תרם","dt":"תש","b":"רב לצד אביו ביריטשוב. מאמר משלו בספר אביו \"חכמת תקופות ומזלות\"."},{"i":12682,"n":"גרסטל, זאב וולף מיריטשוב","f":"שמואל מיריט או מרדכי","k":"בעל חכמת תקופות ומזל","bt":"תריד","bp":"יריטשוב","dt":"תרצג","b":"רב ביריטשוב-תרסח על מקום אביו. היה בקי בחכמת התכונה ובמדעים. השתתף בעבודת מצפה הכוכבים ליד ברלין. עבר ללמברג. חיבר \"חכמת תקופות ומזלות\" למברג תרנז, ועוד. מאמר כנגדו - קמחז\"ה כג אייר תרסו."},{"i":12683,"n":"גרסטל, מאיר מיריטשוב","f":"שמואל","k":"בעל הלכות שחיטה","bt":"תרכה","dt":"תשב","b":"מחכמי שיניבה. מלחין. חיבר ספר על הלכות שחיטה - אבד בשואה. נספה בשואה."},{"i":12684,"n":"גרסטל, מרדכי","dt":"תרסח","b":"רב ביארטשוב"},{"i":12685,"n":"גרסטל, מרדכי מיריטשוב","f":"יוסף","k":"אדמור מיריטשוב","bt":"תקס","dt":"תרי","b":"חתן ר שלום רוזנפלד הגרף מראווה. תלמיד חבר לבעל \"בני יששכר\". ראב\"ד יריטשוב. בנו ר שמואל כיהן אחריו."},{"i":12686,"n":"גרסטל, מרדכי משיניבא","f":"מאיר הי\"ד","k":"בעל שתי רוחות מספרות","bt":"תרנח","bp":"שיניווא-גליציה","dt":"תשך","b":"נכד ר שמואל גרסטל מיריטשוב. תלמיד דודו ר זאב וולף גרסטל מיריטשוב, ונסמך ממנו ומאת: ר אהרן פילץ, ר יצחק קליין בעל \"אהל יצחק\". רב בוינה, יסד את ארגון צעירי המזרחי. נאסר ע\"י הנאצים, הצליח לברוח והגיע לארה\"ב-תש, רב בניו יורק-תשב. חיבר \"שתי רוחות מספרות\" וינה תרפח, \"חורבן יריטשוב\" באידיש. פרסם מאמרים בגרמנית על מנהגי ישראל, ועוד."},{"i":12687,"n":"גרסטל, שמואל מיריטשוב","f":"מרדכי מיריטשוב","k":"אדמור מיריטשוב","bt":"תקצד","dt":"תרסח","b":"רב ואדמור ביריטשוב-תרנב על מקום אביו."},{"i":12688,"n":"גרסטנפלד, אברהם מקרקוביץ","b":"רב בקרקוביץ-תרסד."},{"i":12689,"n":"גרסטנפלד, שמואל מראווה","bt":"תרלג","bp":"ראווה","dt":"תשיח","b":"תלמיד ישיבת קלויזנבורג. עבר לאנגליה וכיהן כרב ומחנך. היגר לארה\"ב-תרעו וכיהן כרב בני יורק וכר\"מ בישיבת רבי יצחק אלחנן."},{"i":12690,"n":"גרף משה בן מנחם","bt":"1650","dt":"ה'תסה 1705","bk":[["זרע קודש מצבתה",""],["מעשה ה’ כי נורא הוא",""],["ע' שמות דמטטרון",""],["צוואות ודרך טובים",""]]},{"i":12691,"n":"גרף, יהודה ליב מפרג","b":"סופר סתם בפרג."},{"i":12692,"n":"גרף, מרדכי מסיאד","b":"רב פעלים לתורה צדקה וחסד,רב בשאד(=סיאד)-תרעב."},{"i":12693,"n":"גרפונקל, ליב","f":"צבי הירש","k":"בעל קובנא היהודית","bt":"1896","bp":"קובנא","b":"עו\"ד ועסקן ציבור בליטא ומראשי הציבור היהודי בליטא. סגן נשיא של \"ועד יהודי ליטא\", חבר עירית קובנא וציר יהודי ליטא בסיים הליטאי. ממיסדי העתון \"אידישע שטימע\" ועורכו. ניצל מהשואה ואחריה כיהן כיו\"ר ארגון הפליטים היהודים. עלה לארץ-1948. חיבר \"קובנא היהודית בחורבנה\"."},{"i":12694,"n":"גרץ, משה מוילקומיר","bt":"תרנה","dt":"תשא - אב","b":"ראש ישיבת ווילקומיר"},{"i":12695,"n":"גרציאנו, אברהם חי ממודנא","b":"מחכמי מודנא, חתם-תקד עם ר מנשה יהושע מצליח, ר משה ליפשיץ, ר יצחק פורמיג'יני."},{"i":12696,"n":"גרציאנו, אברהם יוסף שלמה מאיטל","f":"מרדכי","k":"איש ג\"ר","bt":"שפ-ה","bp":"פיסארו-איטליה","dt":"תמה","b":"נכד ר נתנאל טרבוט, אחיינו של ר נתנאל סגרי בעל \"עפר יעקב\". פוסק, רב במודנא-איטליה-תכו. חיבר הגהות על שו\"ע (נזכרו ע\"י בעל \"זרע אמת\"). קינה שחיבר לזכרו של בעל \"מעבר יבק\" - בראש הספר \"מעבר יבק\". מתשובותיו בספרים \"פחד יצחק\" ו\"עפר יעקב\". חיבר פירוש לטור (מוזכר ב\"זרע אמת\")."},{"i":12697,"n":"גרציאנו, אברהם מאוילונה","b":"גביר באוילונה-שנות ה-ת'."},{"i":12698,"n":"גרשוביץ, יונה","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":12699,"n":"גרשום","k":"בעל ספר השלמן","b":"מגדולי חכמי צרפת שבפרובינצה-ד'תתק\"נ,מגדולי הפוסקים בדורו"},{"i":12700,"n":"גרשום","f":"שלמה","k":"בעל שער השמים","b":"חתן הרמב\"ן?. גדול בתורה בחכמה ובמדעים, מחכמי פרובאנס-שנת מ'."},{"i":12701,"n":"גרשום הגוזר","k":"בעל ספר כללי המילה","b":"מגדולי הראשונים,מוהל מומחה בוירמייזא-ד'תתק\"ג. ?? לא באוצר ??"},{"i":12702,"n":"גרשום הכהן","f":"עקיבא הכהן","b":"גאון וגביר בפרג-רע\"א,בעל הדפוס הראשון בפרג"},{"i":12703,"n":"גרשום מאויבן","b":"מו\"צ באויבן-תל\"ד"},{"i":12704,"n":"גרשום מאור הגולה","k":"גרשום מאור הגולה","bt":"960","bp":"מיץ","dt":"ד'תת - בערך","b":"תלמיד רבנו ליאונתין. מגדולי ראשוני חכמי צרפת ואשכנז, התקין תקנות לדורות. חיבר פירושים, פיוטים.","bk":[["רבינו גרשום","מפרשי ש\"ס - ראשונים"],["רבינו גרשום מאור הגולה","שו\"ת - ראשונים"]]},{"i":12705,"n":"גרשום מאשכנז או צרפת","f":"שלמה","b":"מחכמי אשכנז או צרפת-שנות ה-תת', שאל את הראב\"ן והשיבו. אולי הוא שחיבר סליחת לתענית אסתר \"אשא דעי למרחוק\"."},{"i":12706,"n":"גרשום מבונא","f":"יעקב מבונא","b":"מגדולי חכמי אשכנז הראשונים,מרביץ תורה בבונא-ד'תתק\"ל"},{"i":12707,"n":"גרשום מלובלין ואניקשט","f":"אבלי ר איסרליס מלובל","b":"רב באניקשט. בניו - ר אברהם שלמה מפומפיאן, ר משה. נכדו - ר אברהם אבלי מפוסוואל ווילנא."},{"i":12708,"n":"גרשום משפירא","b":"מגדולי חכמי אשכנז הקדמונים-ד'תת\"ק"},{"i":12709,"n":"גרשון - משפחה","b":"משפחה באה\"ו. וגם משפחה אשכנזית בסופיה-בולגריה - עוד משנת רס."},{"i":12710,"n":"גרשון הכהן מאדא","dt":"תרט","b":"עק\"ה,דומ\"צ באדא"},{"i":12711,"n":"גרשון הכהן מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":12712,"n":"גרשון הלוי מירושלים","f":"בנימין זאב","dt":"תרכה-ח - א טבת","dp":"ירושלים","b":"דיין בירושלים"},{"i":12713,"n":"גרשון הלוי מירושלים","f":"זאב","dt":"תרכה - א טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":12714,"n":"גרשון חריף ממינסק","dp":"מינסק","b":"ראש ישיבה במינסק-תקי בערך על מקום השאגת אריה בזמן כהונת ר יוסף רפפורט כרב העיר, ור השל בעל \"ישועה בראש\" על מקומו אחריו כראש הישיבה, ורב גליל מינסק-תקלח עד תקנג על מקום ר שמואל הכהן מאמדור. בנו - ר נחום מקאפוסט, ונכדו ר דב בער מויטבסק."},{"i":12715,"n":"גרשון יהודה מסופיה וניש","b":"רב בסופיה, נתקבל לרב בבלגרד על מקום הרב מורינו שעלה לארץ-תפט, אך בדרכו נשאר לכהן כרב בניש, ולרב בבלגרד נבחר ר לוי ירושלמי."},{"i":12716,"n":"גרשון מאוסטרהא","b":"מגיד באוסטרהא-קראסניגורא(=צד השני - שכונה באוסטרהא)-תקמז. נזכר בפנקס הח\"ק. חתנו ר בער."},{"i":12717,"n":"גרשון מאוסטרהא","f":"יקר","dt":"תס - ג כסלו","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":12718,"n":"גרשון מאוסטרהא","f":"ראובן מלבוב","bp":"לבוב","dt":"תקי - אחרי","dp":"אוסטרהא","b":"דיין פרנס וגבאי באוסטרהא עם ר שמואל ר יעקב'ס ור מרדכי הלפרין. מבניו: ר שמחה מאוסטרהא, ר ראובן מאוסטרהא."},{"i":12719,"n":"גרשון מאוסטרהא","f":"משלם זלמר מעזירטשר","dt":"תקכח - ו תשרי","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":12720,"n":"גרשון מאיווסקוביץ","f":"ר\"י","b":"רב באיווסקוביץ-תרמז."},{"i":12721,"n":"גרשון מאשכנז וסופיה","b":"מחכמי אשכנז, לאחר הגירוש-רל הגיע לסופיה-בולגריה."},{"i":12722,"n":"גרשון מבודון","f":"יוסף","b":"רב בבודון-שנות ה-ת'."},{"i":12723,"n":"גרשון מברוד","dt":"תקנז - יא ניסן","b":"דרשן,מגיד בברוד"},{"i":12724,"n":"גרשון מגלוגא","b":"רב בגלוגא-תק\"נ"},{"i":12725,"n":"גרשון מואגר-ליטא","dt":"תרסג - יג כסלו","b":"רב בוויגיר(=ואגר)-תרנו על מקום ר שלום דב מאירוביץ. חתנו - ר מנחם מנדל ז\"ק מריגא."},{"i":12726,"n":"גרשון מוילנא","f":"עקיבא","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה."},{"i":12727,"n":"גרשון מוילנא","f":"משה מאנטקליא","dt":"תקנד - כה סיון","dp":"וילנא","b":"מחכמי וילנא בזמן הגר\"א."},{"i":12728,"n":"גרשון מועריש","b":"רב בועריש-תקסד."},{"i":12729,"n":"גרשון מלובלין ואניקשט","f":"אבלי ר איסרליס מלובל","b":"אביו היה פרנס ועד ארבע ארצות. חתן ר יצחק ז\"ק מפוסוואל. רב באניקשט-ליטא. בנו - ר אברהם שלמה מפוסוואל. אחיו של ר שלמה מפוסוואל-זקנו של ר אבלי מפוסוואל. (לפי ליפמן-קובנא - ר גרשון הוא שהיה זקנו של ר אבלי פוסוואלר)."},{"i":12730,"n":"גרשון מלויצק","dt":"תקמח - ח אדר","b":"תלמיד המגיד ממזריטש. הביא מתורת המגיד ונזכרו ב\"יושר דברי אמת\" לר משולם פיבש מזבאריז."},{"i":12731,"n":"גרשון מלמברג","b":"רב בנריוב. תשובה אליו בטוט\"ד."},{"i":12732,"n":"גרשון מלעווא","b":"רב בלעווא-תק\"ס"},{"i":12733,"n":"גרשון ממיץ","b":"מגדולי לותיר-ד'תת\"י"},{"i":12734,"n":"גרשון ממצרים","f":"שלמה","b":"מדפיס במצרים-תק אצל אברהם יתום."},{"i":12735,"n":"גרשון מסופיה","b":"ראש הקהלה ההונגרית בסופיה - בדור שלאחר הגירוש. נזכר בשו\"ת הרא\"ם."},{"i":12736,"n":"גרשון מסופיה וניש","b":"תלמיד ר רפאל בן דוד אשטרוק בסופיה, נתמנה לרב בבלגרד אך בדרכו לשם התקבל לרב בניש ונשאר שם."},{"i":12737,"n":"גרשון מסיציליא","b":"מחכמי סיציליה"},{"i":12738,"n":"גרשון מספרד","b":"מחכמי ספרד, חתן הרמב\"ן"},{"i":12739,"n":"גרשון מפאוויליץ","b":"תלמיד הבעשט. ואולי הוא הנזכר בשבחי הבעשט כ\"הרב בזורנישץ שהיה מגיד מישרים בפאוויליץ\"."},{"i":12740,"n":"גרשון מפוזנא","dt":"תקיח - יג ניסן","b":"רב במאקאווי"},{"i":12741,"n":"גרשון מפומפיאן","f":"בנימין","k":"בעל שמירת המצות","b":"רב בפומפיאן. חיבר \"שמירת המצות\" על מצות הנוהגות בזמן הזה - וילנא תקנט."},{"i":12742,"n":"גרשון מפינטשוב","dt":"תקח - ט ניסן","b":"רב בפינטשוב"},{"i":12743,"n":"גרשון מפרג","f":"נפתלי הירץ","b":"רב בפרג"},{"i":12744,"n":"גרשון מצרפת הפייטן והרופא","f":"חזקיהו","k":"בעל אף חכמתי","b":"רופא ופייטן בצרפת-קעט. חיבר ספר רפואה בשם \"אף חכמתי\" עם פירוש \"ארך אפים\", את הספר חיבר בהיותו אסור בעיר קארדוע. חיבר גם \"אחי יקטן\", \"שבעה עינים\", ועוד."},{"i":12745,"n":"גרשון מקוריסטשוב","b":"תלמיד ר זאב וולף מזיטומיר. שו\"ב בזיטומיר."},{"i":12746,"n":"גרשון מראצקי","f":"זלמן לאנד-רב","b":"רב בראצקי"},{"i":12747,"n":"גרשון מרוזלי","f":"נטע","b":"רב ברוזלי-תק\"מ"},{"i":12748,"n":"גרשון מריטשוואהל","b":"תלמיד המגיד מקוזניץ ובנו ר משה אליקים בריעה שהספידו ב\"באר משה\"."},{"i":12749,"n":"גרשון משקארמילה","f":"אשר","k":"בעל יחוס הצדיקים","b":"הו\"ל \"יחוס הצדיקים\" ובו ציון מקום הצדיקים בכל המקומות שעבר עליהם."},{"i":12750,"n":"גרשון משקלוב","dt":"תרח - כד תשרי","b":"רב בשקלוב"},{"i":12751,"n":"גרשון מתתיהו הלוי","f":"רפאל הלוי","dt":"תנא - י סיון","b":"מחכמי הנובר"},{"i":12752,"n":"גרשון נתן מזולקוא","f":"בצלאל מוכסן מזולקוא","dt":"תצה - ה אייר","b":"גביר בזולקוא, חתם-תנט בענין מדפיסי זולקוא."},{"i":12753,"n":"גרשון סגל יידלש הלוי מירושלים","f":"אליעזר","k":"בעל גלילות ארץ ישראל","bp":"פרג","b":"רב בפרג, עלה לירושלים-שפד, חזר ללובלין. חיבר \"גלילות ארץ ישראל\"-אגרת הקדש באידיש - ונציה שפו, לובלין שצה. בספרו הוא מספר שבשנת שפד נשבה על ידי הטטרים בקרימונה שבאיטליה והובא על ידם לסופיה שם נפדה על יהודי קושטא, עבר לקרים והמשיך לארץ ישראל דרך בבל פרס וסוריה. לפי עדות ר מנשה בן ישראל - הספר נשרף כמעט כולו בידי הישועים בגלל שראו בו סכנה לדתם."},{"i":12754,"n":"גרשון פ\"פ מפרשבורג","b":"גביר מראשי קהלת פרשבורג, חתם-תקסז על כתב הרבנות של החת\"ס, נזכר אצל ר בער פרנק כאחד המסייעים לקהלה לאחר השריפה בשנת תקעא."},{"i":12755,"n":"גרשון קלצקער מוילנא","f":"אליעזר","dt":"תקצא - ו אלול","dp":"וילנא","b":"גביר מחכמי וילנא. חתן נכדת ר יהודה טיקטין בעל \"בער היטב האחרון\"."},{"i":12756,"n":"גרשון שאול מאזמיר","f":"שאול","b":"אחיו של ר יעקב שאול בעל \"קול יעקב\", מתורתו בספר אחיו."},{"i":12757,"n":"גרשון, אברהם"},{"i":12758,"n":"גרשון, ליפא מלמברג","f":"מאיר","b":"מתורתו \"גפן פוריה\"-תרפז."},{"i":12759,"n":"גרשון, שלום מסנוק","b":"סופר בסנוק. תשובה אליו במהרש\"ם."},{"i":12760,"n":"גרשונוביץ, אברהם יצחק מבני ברק","bt":"תרמח","dt":"תשיד","b":"רב בזבינקא-ליד בריסק, עלה לארץ-תרצו וכיהן כר\"מ בישיבת \"תפארת ציון\" בבני ברק-תרצז. בנו - ר יוסף גרשון, חתנו - ר מיכל יהודה לפקוביץ."},{"i":12761,"n":"גרשונוביץ, יהודה אריה מצנסטחוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":12762,"n":"גרשונוביץ, יוסף גרשון","f":"אברהם יצחק מזבידא","bt":"תרעה","dt":"תשנה","b":"תלמיד ישיבות ליטא. חתן ר צבי יהודה אדלשטין מרמת השרון. עלה לארץ-תרצז, ר\"מ בישיבת הנגב.","bk":[["שיעורי רבי ראובן יוסף",""]],"e":"תרע\"ה-תשנ\"ה"},{"i":12763,"n":"גרשונוביץ, משה מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":12764,"n":"גרשונוביץ, ראובן יוסף","dt":"ה'תשנו","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא.","bk":[["חי' רבי ראובן יוסף",""]]},{"i":12765,"n":"גרשונוביצר, גרשון מזביע","b":"רב בזביע. תשובה אליו במהרש\"ם-תרס."},{"i":12766,"n":"גרשוני (גרודנר), יהודה מירושלי","b":"פרסם מאמרים ב\"אורים\" - ירושלים תשז, \"בית מדרש\" - תל אביב תשא, \"כנסת ישראל\" - וילנא תרץ, \"תורת ירושלים\" - ירושלים תרצו, \"תל תלפיות\" - ירושלים תשא."},{"i":12767,"n":"גרשוני יהודה בן גרשון יצחק","bt":"1908","dt":"ה'תשס 2000","bk":[["חוקת הפסח",""],["משפט המלוכה",""]]},{"i":12768,"n":"גרשוני, בן ציון","b":"פרסם מאמרים ב\"שילה\" - ירושלים תשה.","bk":[["נגלות ונסתרות בחיים","הגות והשקפה"],["מהר\"ל מפראג","סיפור חיי המהר\"ל"]]},{"i":12769,"n":"גרשוני, יהודה מארה\"ב","f":"גרשון יצחק","k":"בעל חקת הפסח","bt":"תרע","bp":"גרודנא","b":"תלמיד ר שמעון שקופ, ר ברוך דב ליבוביץ. כונה בשם \"יודל גראדנער\". נסמך מאת: ר חיים עוזר גרודזנסקי, ר אברהם יצחק הכהן קוק, ר איסר זלמן מלצר, ר יצחק הרצוג. ר\"מ בישיבת מרכז הרב בירושלים. חתן בזיוו\"ש ר אליעזר זילבר מסינסינטי. חיבר גם \"משפט המלך\". חבר תנועת המזרחי."},{"i":12770,"n":"גרשוני, צבי (הנרי)","bt":"1844","bp":"וילנא","dt":"1897","b":"רב וסופר. תלמיד ביהמ\"ד לרבנים בוילנא. למד באוניברסית פטרבורג בהמלצת המומר חוולסון, ושם המיר את דתו. חזר בתשובה ופרסם וידוי ב\"המגיד\" בשם \"מודה ועוזב ירוחם\" עם המלצת שניאור זקש. היגר לניו יורק-1869 וכיהן בקהילת \"עמנואל\" הריפומרית בניו יורק, רב באלטלנטה, שיקגו. תרגם ספרים לעברית. ופרסם מאמרים ב\"הפסגה\", ועוד."},{"i":12771,"n":"גרשוני, שמואל מדוינסק","dt":"תרמח - יט תמוז","b":"רב ביעקובשטט(=יאקובשטט), מו\"צ בדוינסק(=דינבורג) ורב מטעם הממשלה."},{"i":12772,"n":"גרשוני, שמואל מרדכי מוילנא","f":"אליהו עקיבא'ס","b":"מחכמי וילנא. אחיו של ר יעקב שבתי, נינו-מצד אמו של ר יעקב מלידא-נכד ר שמואל מפיורדא משידלוב בעל \"בית שמואל\" ור זכריה מנדל בעל באר היטב. החזיק בכתב יחס מצד אמו בחתימת גדולי וילנא ובסופו קיים חתימתם ר חיים מוולוזין."},{"i":12773,"n":"גרשטין, יונה מוילנא","f":"גרשון בן יונה","bt":"תקפח","dt":"תרנב - ה כסלו","dp":"וילנא","b":"תלמיד ביהמ\"ד לרבנים בוילנא (מראשוני התלמידים). עוזר למושל לצד ליב לבנדה. רב מטעם בוילנא על מקום ר אפרים הכהן, וזמן קצר אחר כך פרש מתפקידו ור יהושע שטינברג על מקומו אחריו. משגיח על בית ת\"ת היסו\"ד - (היה קרוב משפחתה של אשת היסו\"ד) על מקום ר יוסף עקיבא קוסובסקי והמקום הפך לבית יתומים גדול בעזרת הגביר ליאון רוזנטל מוילנא ופטרבורג. תרגם יחד עם חברו לבנדה את התנ\"ך לרוסית."},{"i":12774,"n":"גרשטין, יעקב מארה\"ב","k":"בעל לקוטי שושנים","b":"רב בארה\"ב-תרפג."},{"i":12775,"n":"גרשטין-כגן, אלעזר הכהן מירושלי","f":"שלמה אביגדור","dt":"תרצח - ב תשרי","dp":"ירושלים","b":"צדיק מחכמי ירושלים, והחפץ חיים שלח אנשים להתברך ממנו. נהרג עק\"ה ליד הכותל המערבי. אחיהם של ר יהודה ליב כגן מארה\"ב, ר יעקב אריה גרשטין מלאזדי, ר חיים ברוך מסמיאטיש."},{"i":12776,"n":"גרשטין-כגן, חיים ברוך מסמיאטיץ","f":"שלמה אביגדור","dt":"תשג","b":"רב בסמיאטיץ-תרץ. נספה בשואה. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו. אחיהם של ר יהודה ליב כגן מארה\"ב, ר יעקב אריה מלאזדיי הי\"ד, ר אלעזר מירושלים הי\"ד."},{"i":12777,"n":"גרשטין-כגן, יעקב הכהן מלאזדיי","f":"שלמה אביגדור","bt":"תש..","dt":"תשג","b":"נכד(-אבי אמו) ר מאיר יוסף קאטקין מיאנובה בעל \"פנים מאירות\". רבה האחרון של לאזדיי. נספה בשואה. אחיו - ר יהודה ליב קאגאן מארה\"ב."},{"i":12778,"n":"גרשטנפלד, שמואל מנ\"י","f":"ברוך","bt":"תרלד","dt":"תשיח","b":"תלמיד ר דב בר רפפורט בעל \"דרך המלך\". נסמך מאת: ר משה שמואל גלזנר מקלויזנבורג, ר משה פנט מדעש. רב בטרדיגר-סאות ויילס (אוסטרליה או אנגליה?)-תרסא, ר\"מ בישיבת \"ר יצחק אלחנן\" בניו יורק. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"תלפיות\" - נ\"י תשד."},{"i":12779,"n":"גרשיאה, דוד משלוניקי","b":"מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":12780,"n":"גרשינאק, חנוך הניך מאלכסנדר","b":"ר\"מ בישיבת אלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":12781,"n":"גרשם מפרובנס","f":"משלם","k":"בעל ספר שלמון-שלחן","b":"מחכמי פרובנס-ד'תת, חיבר ספר שלמון - ונשלם בידי בנו ר שמואל. נזכר אצל המאירי."},{"i":12782,"n":"גרשנזון, מרדכי מקונסטנטין","k":"אדמור מקונסטנטין","b":"אדמור בקונסטנטין-תרע."},{"i":12783,"n":"גרתי, צבי מפיליפופולי","f":"שמואל","bt":"תרלח","bp":"פיליפופולי","b":"עסקן ציוני, עלה לארץ והתישב בחיפה."},{"i":12784,"n":"גשורי, מ.ש.","b":"פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה, \"בית הכנסת\" - תל אביב תשו."},{"i":12785,"n":"גשטטנר, אהרן אלעזר אלי' משארקנ","f":"יעקב יהודה מטשורנא","b":"רב בשארקאני. חתן אחיו ר שלמה מטשארנא. חתנו - ר גבריאל קוסטליץ משטיינמנגר"},{"i":12786,"n":"גשטטנר, אליעזר מפרשבורג","b":"ראש הקהלה בפרשבורג-תרס-תרעו."},{"i":12787,"n":"גשטטנר, גבריאל משטיינמנגר","f":"שמעון שלמה בנציון","k":"בעל שפתי גבריאל","dt":"תשד - יג אלול","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור בנציון סנידרס מראב, ר שמואל רוזנברג מאונסדורף ועוד. חתן ר מאיר אליעזר הכהן הרטשטיין-רפפורט באויהל בעל \"שלשלת הזהב\", ובזיוו\"ש חתן ר אברהם יוסף גרינולד מחוסט. מחכמי ראב, דיין בשטיינמנגר(=סאמבאט-האלי)-תרצד. נספה בשואה. ?? לא באוצר ??"},{"i":12788,"n":"גשטטנר, נתן מבני ברק","f":"עמרם מנייפעסט","b":"אב\"ד קרית אגודת ישראל בבני ברק."},{"i":12789,"n":"גשטטנר, עמרם מנייפעסט","b":"חתן ר שלמה סופר שרייבר מוינה. ובנו ר נתן גשטטנר מבני ברק."},{"i":12790,"n":"גשטטנר, שמעון שלמה בנציון מראב","f":"אברהם משארקאני","b":"חתניו - ר משה גרינולד מחוסט, ור ישראל מנחם ברוין מברזביץ."},{"i":12791,"n":"גשייד, נחמן מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":12792,"n":"גשלר, נפתלי צבי מהלברשטט","b":"רב בהלברשטט"}];
